let fileElementThreadBtn = null;

function syncFileElementThreadButtonVisibility() {
  const existing = document.getElementById("file-element-thread-btn");
  existing?.remove();
  fileElementThreadBtn = null;
}

function closeFileHistoryModal() {
  fileHistoryModalNode?.classList.add("hidden");
  fileHistoryModalContext = null;
  fileHistoryPreviewWrapNode?.classList.add("hidden");
  if (fileHistoryPreviewContentNode) fileHistoryPreviewContentNode.textContent = "";
}

async function openFileHistoryModal() {
  const context = getFileHistoryRequestContext();
  if (!context || !fileHistoryModalNode) return;
  fileHistoryModalContext = context;
  fileHistoryPreviewWrapNode?.classList.add("hidden");
  if (fileHistoryTitleNode) fileHistoryTitleNode.textContent = "История версий";
  if (fileHistorySubtitleNode) {
    fileHistorySubtitleNode.textContent = context.name || context.file || context.path || "";
  }
  fileHistoryModalNode.classList.remove("hidden");
  await refreshFileHistoryList();
}

async function refreshFileHistoryList() {
  if (!fileHistoryModalContext || !fileHistoryListNode) return;
  fileHistoryListNode.textContent = "Загрузка…";
  try {
    const response = await fetch(
      buildApiUrl("/api/file/history", buildFileHistoryApiParams(fileHistoryModalContext))
    );
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    renderFileHistoryList(data);
  } catch (error) {
    fileHistoryListNode.textContent = `Ошибка: ${error.message}`;
  }
}

function renderFileHistoryList(data) {
  if (!fileHistoryListNode) return;
  fileHistoryListNode.replaceChildren();
  if (data.target && fileHistorySubtitleNode) {
    fileHistorySubtitleNode.textContent = data.target;
  }
  const versions = Array.isArray(data.versions) ? data.versions : [];
  if (versions.length === 0) {
    const empty = document.createElement("p");
    empty.className = "file-history-empty";
    empty.textContent =
      "Пока нет сохранённых версий. Они появятся после первого изменения и сохранения файла.";
    fileHistoryListNode.appendChild(empty);
    return;
  }

  for (const entry of versions) {
    const row = document.createElement("div");
    row.className = "file-history-row";

    const meta = document.createElement("div");
    meta.className = "file-history-row-meta";
    const title = document.createElement("div");
    title.className = "file-history-row-title";
    title.textContent = entry.label || entry.version;
    const size = document.createElement("div");
    size.className = "file-history-row-size";
    size.textContent = entry.size ? `${entry.size} B` : entry.version;
    meta.appendChild(title);
    meta.appendChild(size);

    const actions = document.createElement("div");
    actions.className = "file-history-row-actions";

    const previewBtn = document.createElement("button");
    previewBtn.type = "button";
    previewBtn.className = "save-btn file-history-action-btn";
    previewBtn.textContent = "Просмотр";
    previewBtn.addEventListener("click", () => {
      void previewFileHistoryVersion(entry.version, entry.label || entry.version);
    });

    const restoreBtn = document.createElement("button");
    restoreBtn.type = "button";
    restoreBtn.className = "save-btn file-history-action-btn";
    restoreBtn.textContent = "Восстановить";
    restoreBtn.addEventListener("click", () => {
      void restoreFileHistoryVersion(entry.version, entry.label || entry.version);
    });

    actions.appendChild(previewBtn);
    actions.appendChild(restoreBtn);
    row.appendChild(meta);
    row.appendChild(actions);
    fileHistoryListNode.appendChild(row);
  }
}

async function previewFileHistoryVersion(version, label) {
  if (!fileHistoryModalContext) return;
  try {
    const response = await fetch(
      buildApiUrl("/api/file/history/content", {
        ...buildFileHistoryApiParams(fileHistoryModalContext),
        version
      })
    );
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    if (fileHistoryPreviewTitleNode) fileHistoryPreviewTitleNode.textContent = label || data.label || version;
    if (fileHistoryPreviewContentNode) fileHistoryPreviewContentNode.textContent = data.content || "";
    fileHistoryPreviewWrapNode?.classList.remove("hidden");
  } catch (error) {
    showToast(`Ошибка просмотра версии: ${error.message}`, "error");
  }
}

function applyRestoredHistoryContent(content) {
  const mode = fileHistoryModalContext?.mode;
  if (mode === "system") {
    fileContentInputNode.value = content;
    refreshEditorViewContent();
    commitEditorSaveBaseline();
    return;
  }

  switch (mode) {
    case "description":
      modeContentCache.description = content;
      void applyExternalFileContentUi(content);
      break;
    case "internal":
      modeContentCache.internal = content;
      fileContentInputNode.value = content;
      break;
    case "tabular":
      modeContentCache.tabular = content;
      fileContentInputNode.value = content;
      break;
    case "todo":
      modeContentCache.todo = content;
      fileContentInputNode.value = content;
      break;
    case "configs":
      modeContentCache.configs = content;
      fileContentInputNode.value = content;
      break;
    case "env":
      modeContentCache.env = content;
      fileContentInputNode.value = content;
      break;
    case "external":
      void applyExternalFileContentUi(content);
      break;
    case "media":
      void applyMediaSidecarContentUi(content);
      break;
    default:
      fileContentInputNode.value = content;
      break;
  }
  refreshEditorViewContent();
  commitEditorSaveBaseline();
}

async function restoreFileHistoryVersion(version, label) {
  if (!fileHistoryModalContext) return;
  const confirmed = await askConfirm(`Восстановить версию ${label}? Текущее содержимое будет сохранено в историю.`, {
    okLabel: "Восстановить"
  });
  if (!confirmed) return;

  try {
    const response = await fetch(buildApiUrl("/api/file/history/restore"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...fileHistoryModalContext,
        version
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${response.status}`);
    }
    const data = await response.json();
    applyRestoredHistoryContent(data.content || "");
    showToast("Версия восстановлена", "success");
    await refreshFileHistoryList();
  } catch (error) {
    showToast(`Ошибка восстановления: ${error.message}`, "error");
  }
}

function syncAgentsRegistryDraftPreview(agentPath) {
  if (!agentsRegistryModalNode || agentsRegistryModalNode.classList.contains("hidden")) return;
  const key = normalizeRegistryPathKey(agentPath);
  const index = agentsRegistryDraft.findIndex((item) => normalizeRegistryPathKey(item.path) === key);
  if (index === -1) return;
  const updated = agentsCache.find((item) => normalizeRegistryPathKey(item.path) === key);
  agentsRegistryDraft[index].hasPreview = Boolean(updated?.hasPreview);
  agentsRegistryDraft[index].previewUrl = updated?.previewUrl || null;
  agentsRegistryDraft[index].previewRel = null;
  const row = agentsRegistryListNode?.querySelector(`.agents-registry-row[data-registry-index="${index}"]`);
  if (row) updateRegistryRowPreview(row, agentsRegistryDraft[index]);
}

async function uploadAgentPreviewFile(agentPath, file) {
  if (!agentPath) throw new Error("Workspace не задан");
  if (!isAllowedPreviewFile(file)) throw new Error("Допустимы только JPG, PNG и GIF");

  const data = await readFileAsBase64(file);
  const response = await fetch("/api/agents/preview", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      path: agentPath,
      data,
      fileName: file.name,
      mimeType: file.type
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
  }
  return response.json();
}

async function removeAgentPreviewFile(agentPath) {
  if (!agentPath) throw new Error("Workspace не задан");

  const response = await fetch(`/api/agents/preview?path=${encodeURIComponent(agentPath)}`, {
    method: "DELETE"
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
  }
  return response.json();
}

const AGENT_SLIDER_FOLDER_REF = "awn-storage/assets/slider";
const AGENT_SLIDER_ROTATE_MS = 12000;
let agentSliderCatalog = { folderPath: AGENT_SLIDER_FOLDER_REF, files: [], loadedForAgentId: null };
let agentSliderPlaybackOrder = [];
let agentSliderRotateTimer = null;
let agentSliderIndex = 0;

function shuffleAgentSliderFiles(files) {
  const shuffled = files.slice();
  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
  }
  return shuffled;
}

function rebuildAgentSliderPlaybackOrder({ resetIndex = true } = {}) {
  agentSliderPlaybackOrder = shuffleAgentSliderFiles(agentSliderCatalog.files || []);
  if (resetIndex) {
    agentSliderIndex = agentSliderPlaybackOrder.length
      ? Math.floor(Math.random() * agentSliderPlaybackOrder.length)
      : 0;
    return;
  }
  if (agentSliderIndex >= agentSliderPlaybackOrder.length) {
    agentSliderIndex = 0;
  }
}

function buildAgentSliderMediaApiUrl(mediaFile, agentId = activeAgentId) {
  const relFile = String(mediaFile || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!relFile) return "";
  return buildApiUrl("/api/media/file", { path: MANIFEST_FILE, file: relFile }, agentId);
}

function stopAgentSliderRotation() {
  if (agentSliderRotateTimer) {
    clearInterval(agentSliderRotateTimer);
    agentSliderRotateTimer = null;
  }
}

function restartAgentSliderRotation() {
  stopAgentSliderRotation();
  if (agentSliderPlaybackOrder.length < 2) return;
  agentSliderRotateTimer = setInterval(() => {
    agentSliderIndex = (agentSliderIndex + 1) % agentSliderPlaybackOrder.length;
    if (agentSliderIndex === 0) {
      agentSliderPlaybackOrder = shuffleAgentSliderFiles(agentSliderCatalog.files || []);
    }
    syncAgentPreview();
  }, AGENT_SLIDER_ROTATE_MS);
}

async function refreshAgentSliderCatalog(force = false) {
  const agent = getActiveAgentMeta();
  if (!agent?.path) {
    agentSliderCatalog = { folderPath: AGENT_SLIDER_FOLDER_REF, files: [], loadedForAgentId: null };
    agentSliderPlaybackOrder = [];
    agentSliderIndex = 0;
    stopAgentSliderRotation();
    return agentSliderCatalog;
  }

  if (!force && agentSliderCatalog.loadedForAgentId === agent.id) {
    return agentSliderCatalog;
  }

  try {
    const response = await fetch(buildApiUrl("/api/agents/slider", {}, agent.id));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    agentSliderCatalog = {
      folderPath: String(data.folderPath || AGENT_SLIDER_FOLDER_REF).trim() || AGENT_SLIDER_FOLDER_REF,
      files: Array.isArray(data.files) ? data.files : [],
      loadedForAgentId: agent.id
    };
  } catch {
    agentSliderCatalog = {
      folderPath: AGENT_SLIDER_FOLDER_REF,
      files: [],
      loadedForAgentId: agent.id
    };
  }

  rebuildAgentSliderPlaybackOrder({ resetIndex: true });
  restartAgentSliderRotation();
  return agentSliderCatalog;
}

async function uploadAgentSliderFile(agentPath, file, agentId = activeAgentId) {
  if (!agentPath) throw new Error("Workspace не задан");
  if (!agentId) throw new Error("Workspace не выбран");
  const data = await readFileAsBase64(file);
  const response = await fetch(buildApiUrl("/api/agents/slider", {}, agentId), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      data,
      fileName: file.name,
      mimeType: file.type
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
  }
  return response.json();
}

async function deleteAgentSliderFile(agentPath, fileName, agentId = activeAgentId) {
  if (!agentPath) throw new Error("Workspace не задан");
  const response = await fetch(
    buildApiUrl("/api/agents/slider", { file: fileName }, agentId),
    { method: "DELETE" }
  );
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
  }
  return response.json();
}

function renderAgentSliderModalGrid() {
  if (!agentSliderGridNode) return;
  agentSliderGridNode.replaceChildren();

  const files = agentSliderCatalog.files || [];
  agentSliderEmptyNoteNode?.classList.toggle("hidden", files.length > 0);
  const sliderAgentId = agentSliderCatalog.loadedForAgentId || activeAgentId;

  for (const file of files) {
    const item = document.createElement("article");
    item.className = "agent-slider-grid-item";
    item.setAttribute("role", "listitem");

    const thumbWrap = document.createElement("div");
    thumbWrap.className = "agent-slider-grid-thumb-wrap";

    const img = document.createElement("img");
    img.className = "agent-slider-grid-thumb";
    img.alt = file.name || "Слайд";
    img.loading = "lazy";
    img.decoding = "async";
    img.src = appendMediaThumbToApiUrl(
      appendCacheBuster(buildAgentSliderMediaApiUrl(file.mediaFile, sliderAgentId)),
      MEDIA_THUMB_MAX_GRID
    );
    thumbWrap.appendChild(img);

    const meta = document.createElement("div");
    meta.className = "agent-slider-grid-meta";

    const name = document.createElement("span");
    name.className = "agent-slider-grid-name";
    name.textContent = file.name || "";
    name.title = file.name || "";

    const deleteBtn = document.createElement("button");
    deleteBtn.type = "button";
    deleteBtn.className = "agent-slider-grid-delete-btn";
    deleteBtn.textContent = "Удалить";
    deleteBtn.addEventListener("click", () => {
      void (async () => {
        const agent = getActiveAgentMeta();
        if (!agent?.path) return;
        try {
          await deleteAgentSliderFile(agent.path, file.name, agent.id);
          await refreshAgentSliderCatalog(true);
          renderAgentSliderModalGrid();
          syncAgentPreview();
          showToast("Изображение удалено", "success");
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          showToast(message || "Не удалось удалить", "error");
        }
      })();
    });

    meta.append(name, deleteBtn);
    item.append(thumbWrap, meta);
    agentSliderGridNode.appendChild(item);
  }
}

function openAgentSliderModal() {
  if (!agentSliderModalNode) return;
  const agent = getActiveAgentMeta();
  if (!agent?.path) {
    showToast("Сначала выберите агента", "error");
    return;
  }

  void (async () => {
    await refreshAgentSliderCatalog(true);
    if (agentSliderModalPathNode) {
      const agentLabel = String(agent.name || agent.id || "").trim();
      const folderPath = agentSliderCatalog.folderPath || AGENT_SLIDER_FOLDER_REF;
      agentSliderModalPathNode.textContent = agentLabel
        ? `${agentLabel} · ${folderPath}`
        : folderPath;
    }
    renderAgentSliderModalGrid();
    agentSliderModalNode.classList.remove("hidden");
    document.body.classList.add("modal-open");
  })();
}

function closeAgentSliderModal() {
  if (!agentSliderModalNode) return;
  agentSliderModalNode.classList.add("hidden");
  document.body.classList.remove("modal-open");
}

async function uploadAgentSliderFiles(fileList) {
  const agent = getActiveAgentMeta();
  if (!agent?.path) {
    showToast("Сначала выберите агента", "error");
    return;
  }

  const files = Array.from(fileList || []).filter(Boolean);
  if (!files.length) return;

  agentSliderUploadZoneNode?.classList.add("is-uploading");
  let uploaded = 0;
  const uploadAgentId = agent.id;
  const uploadAgentPath = agent.path;

  try {
    for (const file of files) {
      await uploadAgentSliderFile(uploadAgentPath, file, uploadAgentId);
      uploaded += 1;
    }
    await refreshAgentSliderCatalog(true);
    renderAgentSliderModalGrid();
    syncAgentPreview();
    showToast(uploaded === 1 ? "Изображение добавлено" : `Добавлено изображений: ${uploaded}`, "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message || "Ошибка загрузки", "error");
  } finally {
    agentSliderUploadZoneNode?.classList.remove("is-uploading");
    if (agentSliderFileInputNode) agentSliderFileInputNode.value = "";
  }
}

async function showAgentSliderFolderPath() {
  const folderPath = agentSliderCatalog.folderPath || AGENT_SLIDER_FOLDER_REF;
  try {
    await navigator.clipboard.writeText(folderPath);
    showToast(`Путь скопирован: ${folderPath}`, "success");
  } catch {
    showToast(`Папка: ${folderPath}`, "info");
  }
}

async function refreshAgentPreviewAfterFileChange(agentPath) {
  await loadAgents();
  syncAgentsRegistryDraftPreview(agentPath);
  await refreshAgentSliderCatalog(true);
  syncAgentPreview();
}

function getSelectableAgents() {
  return agentsCache.filter((agent) => agent.active !== false && agent.folderExists !== false);
}

let agentsPickerIsOpen = false;

function getAgentPickerInitials(agent) {
  const name = String(agent?.name || agent?.id || "?").trim();
  const parts = name.split(/\s+/).filter(Boolean);
  if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
  return name.slice(0, 2).toUpperCase();
}

function normalizeAwnEmoji(value) {
  const text = String(value ?? "").trim();
  if (!text) return "";
  if (typeof Intl !== "undefined" && typeof Intl.Segmenter === "function") {
    const segmenter = new Intl.Segmenter("ru", { granularity: "grapheme" });
    const first = [...segmenter.segment(text)][0];
    return first?.segment || text;
  }
  return [...text][0] || text;
}

function resolveAwnEmoji(source) {
  if (!source) return "";
  if (typeof source === "string") return normalizeAwnEmoji(source);
  const raw =
    source["awn-emoji"] ??
    source.awnEmoji ??
    source.awnProps?.["awn-emoji"] ??
    "";
  return normalizeAwnEmoji(raw);
}

function createPreviewFallbackNode({ emoji = "", fallbackText = "?", emojiClass, initialsClass }) {
  const node = document.createElement("span");
  if (emoji) {
    node.className = emojiClass;
    node.textContent = emoji;
    node.setAttribute("aria-hidden", "true");
  } else {
    node.className = initialsClass;
    node.textContent = fallbackText;
  }
  return node;
}

function mountPreviewOrFallback(container, {
  previewUrl = "",
  emoji = "",
  fallbackText = "?",
  emojiClass,
  initialsClass,
  nodePath = "",
  iconClass = ""
}) {
  const mountFallback = () => {
    container.replaceChildren();
    if (emoji) {
      container.appendChild(
        createPreviewFallbackNode({ emoji, fallbackText, emojiClass, initialsClass })
      );
      return;
    }
    if (nodePath) {
      const icon = createNodeCoverFallbackElement({
        nodePath,
        emojiClass,
        iconClass
      });
      container.appendChild(icon);
      return;
    }
    container.appendChild(
      createPreviewFallbackNode({ emoji: "", fallbackText, emojiClass, initialsClass })
    );
  };

  if (previewUrl) {
    const img = document.createElement("img");
    img.alt = "";
    img.draggable = false;
    img.onerror = mountFallback;
    img.src = previewUrl;
    container.replaceChildren();
    container.appendChild(img);
    return;
  }

  mountFallback();
}

function isAgentRegistryActive(agent) {
  return agent?.active !== false;
}

/** Агенты реестра для UI: полный список из awn-agents.json, включая записи без папки на диске. */
function getRegistryAgentsForUi() {
  return agentsCache.filter((agent) => agent.registryEditable !== false && !isPlatformAgent(agent));
}

function getAgentsForLandingGrid() {
  return agentsCache.filter((agent) => agent.folderExists !== false && !isPlatformAgent(agent));
}

function getPlatformAgentForLanding() {
  return agentsCache.find(isPlatformAgent) || null;
}

let globalFocusItemsCache = [];
let agentFocusItemsCache = [];

const LANDING_FOCUS_FILTER_STORAGE_KEY = "agentcms.landingFocusFilter.v1";
const LANDING_FOCUS_SORT_STORAGE_KEY = "agentcms.landingFocusSort.v1";

let landingFocusFilter = { status: "", types: [], category: "", tag: "", owner: "", priority: "" };
let landingFocusSort = { key: "topic", dir: "asc" };

function normalizeLandingFocusTypeFilter(raw) {
  if (Array.isArray(raw)) {
    return [...new Set(raw.map((value) => String(value ?? "").trim()).filter(Boolean))];
  }
  const legacy = String(raw ?? "").trim();
  return legacy ? [legacy] : [];
}

function getLandingFocusSelectedTypes() {
  return normalizeLandingFocusTypeFilter(landingFocusFilter.types);
}

function formatLandingFocusTypeFilterLabel(types = getLandingFocusSelectedTypes()) {
  if (!types.length) return "Все типы";
  if (types.length === 1) return types[0];
  return `${types.length} типов`;
}

function loadLandingFocusUiState() {
  try {
    const filterRaw = readStorageItem(LANDING_FOCUS_FILTER_STORAGE_KEY);
    if (filterRaw) {
      const parsed = JSON.parse(filterRaw);
      const types = normalizeLandingFocusTypeFilter(parsed?.types ?? parsed?.type);
      landingFocusFilter = {
        status: String(parsed?.status ?? "").trim(),
        types,
        category: String(parsed?.category ?? "").trim(),
        tag: String(parsed?.tag ?? "").trim(),
        owner: String(parsed?.owner ?? "").trim(),
        priority: String(parsed?.priority ?? "").trim()
      };
    }
  } catch {
    landingFocusFilter = { status: "", types: [], category: "", tag: "", owner: "", priority: "" };
  }

  try {
    const sortRaw = readStorageItem(LANDING_FOCUS_SORT_STORAGE_KEY);
    if (sortRaw) {
      const parsed = JSON.parse(sortRaw);
      const key = String(parsed?.key ?? "topic").trim();
      const dir = String(parsed?.dir ?? "asc").trim().toLowerCase();
      landingFocusSort = {
        key: key || "topic",
        dir: dir === "desc" ? "desc" : "asc"
      };
    }
  } catch {
    landingFocusSort = { key: "topic", dir: "asc" };
  }
}

function saveLandingFocusUiState() {
  writeStorageItem(LANDING_FOCUS_FILTER_STORAGE_KEY, JSON.stringify(landingFocusFilter));
  writeStorageItem(LANDING_FOCUS_SORT_STORAGE_KEY, JSON.stringify(landingFocusSort));
}

function getFocusItemStatus(item) {
  return String(item?.awnProps?.["awn-status"] ?? "").trim();
}

function getFocusItemType(item) {
  return String(item?.awnType || item?.awnProps?.["awn-type"] || "").trim();
}

function getFocusItemTags(item) {
  const raw = item?.awnProps?.["awn-tags"];
  if (Array.isArray(raw)) return raw.map((tag) => String(tag).trim()).filter(Boolean);
  return String(raw || "")
    .split(",")
    .map((tag) => tag.trim().replace(/^#+/, ""))
    .filter(Boolean);
}

function getFocusItemCatalogRaw(item, key) {
  return String(item?.awnProps?.[key] ?? "").trim();
}

function filterLandingFocusItems(items) {
  const statusFilter = String(landingFocusFilter.status || "").trim();
  const typeFilters = getLandingFocusSelectedTypes();
  const typeFilterSet = typeFilters.length ? new Set(typeFilters) : null;
  const categoryFilter = String(landingFocusFilter.category || "").trim();
  const tagFilter = String(landingFocusFilter.tag || "").trim();
  const ownerFilter = String(landingFocusFilter.owner || "").trim();
  const priorityFilter = String(landingFocusFilter.priority || "").trim();

  return items.filter((item) => {
    if (statusFilter && getFocusItemStatus(item) !== statusFilter) return false;
    if (typeFilterSet && !typeFilterSet.has(getFocusItemType(item))) return false;
    if (categoryFilter && getFocusItemCatalogRaw(item, "awn-category") !== categoryFilter) return false;
    if (ownerFilter && getFocusItemCatalogRaw(item, "awn-owner") !== ownerFilter) return false;
    if (priorityFilter && getFocusItemCatalogRaw(item, "awn-priority") !== priorityFilter) return false;
    if (tagFilter && !getFocusItemTags(item).includes(tagFilter)) return false;
    return true;
  });
}

function getLandingFocusSortValue(item, key) {
  switch (key) {
    case "agent":
      return item.agentName || item.agentId || "";
    case "topic":
      return item.name || item.nodePath || "";
    case "awn-status":
      return getFocusItemStatus(item);
    case "awn-type":
      return getFocusItemType(item);
    case "awn-create":
      return String(item?.awnProps?.["awn-create"] ?? "").trim();
    case "awn-update":
      return String(item?.awnProps?.["awn-update"] ?? "").trim();
    default:
      return item.name || item.nodePath || "";
  }
}

function sortLandingFocusItems(items) {
  const key = landingFocusSort.key || "topic";
  const dir = landingFocusSort.dir === "desc" ? -1 : 1;
  const isDateKey = key === "awn-create" || key === "awn-update";
  return [...items].sort((left, right) => {
    const leftValue = getLandingFocusSortValue(left, key);
    const rightValue = getLandingFocusSortValue(right, key);
    if (isDateKey) {
      const leftTime = Date.parse(leftValue) || 0;
      const rightTime = Date.parse(rightValue) || 0;
      return (leftTime - rightTime) * dir;
    }
    return String(leftValue).localeCompare(String(rightValue), "ru", { sensitivity: "base" }) * dir;
  });
}

function getProcessedLandingFocusItems() {
  return sortLandingFocusItems(filterLandingFocusItems(globalFocusItemsCache));
}

function setLandingFocusTypeFilterOpen(open) {
  if (!appLandingFocusFilterTypePanelNode || !appLandingFocusFilterTypeBtnNode) return;
  const isOpen = Boolean(open);
  appLandingFocusFilterTypePanelNode.classList.toggle("hidden", !isOpen);
  appLandingFocusFilterTypeBtnNode.setAttribute("aria-expanded", isOpen ? "true" : "false");
}

function syncLandingFocusTypeFilterButtonLabel() {
  if (!appLandingFocusFilterTypeBtnNode) return;
  appLandingFocusFilterTypeBtnNode.textContent = formatLandingFocusTypeFilterLabel();
}

function syncLandingFocusFilterTypePanel() {
  if (!appLandingFocusFilterTypePanelNode) return;

  const availableTypes = new Set();
  for (const item of globalFocusItemsCache) {
    const type = getFocusItemType(item);
    if (type) availableTypes.add(type);
  }

  const selected = new Set(getLandingFocusSelectedTypes());
  landingFocusFilter.types = [...selected].filter((type) => availableTypes.has(type));

  appLandingFocusFilterTypePanelNode.replaceChildren();

  const head = document.createElement("div");
  head.className = "agent-focus-type-filter-panel-head";

  const title = document.createElement("span");
  title.className = "agent-focus-type-filter-panel-title";
  title.textContent = "Типы записей";

  const resetBtn = document.createElement("button");
  resetBtn.type = "button";
  resetBtn.className = "agent-focus-type-filter-reset-btn";
  resetBtn.textContent = "Все";
  resetBtn.title = "Показать все типы";
  resetBtn.addEventListener("click", () => {
    landingFocusFilter.types = [];
    saveLandingFocusUiState();
    syncLandingFocusFilterTypePanel();
    syncLandingFocusTypeFilterButtonLabel();
    renderGlobalFocusPanel();
  });

  head.append(title, resetBtn);
  appLandingFocusFilterTypePanelNode.appendChild(head);

  const list = document.createElement("div");
  list.className = "agent-focus-type-filter-panel-list";

  for (const type of [...availableTypes].sort((a, b) => a.localeCompare(b, "ru"))) {
    const label = document.createElement("label");
    label.className = "agent-focus-type-filter-option";

    const input = document.createElement("input");
    input.type = "checkbox";
    input.value = type;
    input.checked = selected.has(type);
    input.addEventListener("change", () => {
      const next = new Set(getLandingFocusSelectedTypes());
      if (input.checked) next.add(type);
      else next.delete(type);
      landingFocusFilter.types = [...next];
      saveLandingFocusUiState();
      syncLandingFocusTypeFilterButtonLabel();
      renderGlobalFocusPanel();
    });

    const text = document.createElement("span");
    text.textContent = type;
    text.title = type;
    label.append(input, text);
    list.appendChild(label);
  }

  if (!availableTypes.size) {
    const empty = document.createElement("p");
    empty.className = "agent-focus-type-filter-empty";
    empty.textContent = "Нет типов в списке";
    list.appendChild(empty);
  }

  appLandingFocusFilterTypePanelNode.appendChild(list);
  syncLandingFocusTypeFilterButtonLabel();
}

function syncLandingFocusCatalogFilterOptions() {
  const specs = [
    { node: appLandingFocusFilterCategoryNode, key: "awn-category", filterKey: "category" },
    { node: appLandingFocusFilterTagNode, key: "awn-tags", filterKey: "tag", tags: true },
    { node: appLandingFocusFilterOwnerNode, key: "awn-owner", filterKey: "owner" },
    { node: appLandingFocusFilterPriorityNode, key: "awn-priority", filterKey: "priority" }
  ];

  for (const spec of specs) {
    if (!spec.node) continue;
    const current = String(landingFocusFilter[spec.filterKey] || "").trim();
    const values = new Map();

    for (const item of globalFocusItemsCache) {
      if (spec.tags) {
        for (const tag of getFocusItemTags(item)) {
          if (!tag) continue;
          const label = getFocusPropDisplayValue(item, "awn-tags")
            .split(",")
            .map((part) => part.trim())
            .find((part) => part.includes(tag) || part === tag);
          values.set(tag, label || tag);
        }
        continue;
      }
      const raw = getFocusItemCatalogRaw(item, spec.key);
      if (!raw) continue;
      values.set(raw, getFocusPropDisplayValue(item, spec.key) || raw);
    }

    spec.node.replaceChildren();
    const allOption = document.createElement("option");
    allOption.value = "";
    allOption.textContent = "Все";
    spec.node.appendChild(allOption);

    for (const [value, label] of [...values.entries()].sort((a, b) =>
      String(a[1]).localeCompare(String(b[1]), "ru")
    )) {
      const option = document.createElement("option");
      option.value = value;
      option.textContent = label === value ? label : `${label} (${value})`;
      if (value === current) option.selected = true;
      spec.node.appendChild(option);
    }

    if (current && !values.has(current)) {
      const legacy = document.createElement("option");
      legacy.value = current;
      legacy.textContent = current;
      legacy.selected = true;
      spec.node.appendChild(legacy);
    } else {
      spec.node.value = current;
    }
  }
}

function setLandingFocusFiltersOpen(open) {
  if (!appLandingFocusToolbarNode || !appLandingFocusFiltersBtnNode) return;
  const isOpen = Boolean(open);
  appLandingFocusToolbarNode.classList.toggle("is-open", isOpen);
  appLandingFocusToolbarNode.classList.toggle("hidden", !isOpen);
  appLandingFocusFiltersBtnNode.setAttribute("aria-expanded", isOpen ? "true" : "false");
  appLandingFocusFiltersBtnNode.classList.toggle("is-active", isOpen);
}

function syncLandingFocusToolbarUi() {
  if (!appLandingFocusToolbarNode) return;

  const hasItems = globalFocusItemsCache.length > 0;
  appLandingFocusFiltersBtnNode?.classList.toggle("hidden", !hasItems);
  if (!hasItems) {
    setLandingFocusFiltersOpen(false);
  }

  if (appLandingFocusFilterStatusNode) {
    appLandingFocusFilterStatusNode.value = landingFocusFilter.status || "";
  }
  syncLandingFocusCatalogFilterOptions();
  syncLandingFocusFilterTypePanel();
  if (appLandingFocusSortNode) {
    appLandingFocusSortNode.value = landingFocusSort.key || "topic";
  }
  if (appLandingFocusSortDirNode) {
    appLandingFocusSortDirNode.textContent = landingFocusSort.dir === "asc" ? "↑" : "↓";
  }

  const processed = getProcessedLandingFocusItems();
  const total = globalFocusItemsCache.length;
  const shown = processed.length;
  if (appLandingFocusFilterCountNode) {
    appLandingFocusFilterCountNode.textContent =
      shown === total ? `${total} записей` : `${shown} из ${total}`;
  }
  if (appLandingFocusCountNode) {
    appLandingFocusCountNode.textContent = total
      ? shown === total
        ? String(total)
        : `${shown}/${total}`
      : "";
    appLandingFocusCountNode.classList.toggle("hidden", total === 0);
  }
}

function bindLandingFocusToolbar() {
  if (!appLandingFocusToolbarNode || appLandingFocusToolbarNode.dataset.bound === "1") return;
  appLandingFocusToolbarNode.dataset.bound = "1";

  loadLandingFocusUiState();

  appLandingFocusFiltersBtnNode?.addEventListener("click", () => {
    const willOpen = !appLandingFocusToolbarNode.classList.contains("is-open");
    setLandingFocusFiltersOpen(willOpen);
  });

  appLandingFocusFilterStatusNode?.addEventListener("change", () => {
    landingFocusFilter.status = appLandingFocusFilterStatusNode.value || "";
    saveLandingFocusUiState();
    renderGlobalFocusPanel();
  });

  for (const [node, key] of [
    [appLandingFocusFilterCategoryNode, "category"],
    [appLandingFocusFilterTagNode, "tag"],
    [appLandingFocusFilterOwnerNode, "owner"],
    [appLandingFocusFilterPriorityNode, "priority"]
  ]) {
    node?.addEventListener("change", () => {
      landingFocusFilter[key] = node.value || "";
      saveLandingFocusUiState();
      renderGlobalFocusPanel();
    });
  }

  appLandingFocusFilterTypeBtnNode?.addEventListener("click", (event) => {
    event.stopPropagation();
    const willOpen = appLandingFocusFilterTypePanelNode?.classList.contains("hidden");
    document.querySelectorAll(".agent-focus-type-filter-panel").forEach((node) => {
      if (node !== appLandingFocusFilterTypePanelNode) node.classList.add("hidden");
    });
    setLandingFocusTypeFilterOpen(willOpen);
  });

  if (!document.body.dataset.landingFocusTypeFilterBound) {
    document.body.dataset.landingFocusTypeFilterBound = "1";
    document.addEventListener("click", (event) => {
      if (!appLandingFocusFilterTypeWrapNode?.contains(event.target)) {
        setLandingFocusTypeFilterOpen(false);
      }
    });
  }

  appLandingFocusSortNode?.addEventListener("change", () => {
    landingFocusSort.key = appLandingFocusSortNode.value || "topic";
    saveLandingFocusUiState();
    renderGlobalFocusPanel();
  });

  appLandingFocusSortDirNode?.addEventListener("click", () => {
    landingFocusSort.dir = landingFocusSort.dir === "asc" ? "desc" : "asc";
    if (appLandingFocusSortDirNode) {
      appLandingFocusSortDirNode.textContent = landingFocusSort.dir === "asc" ? "↑" : "↓";
    }
    saveLandingFocusUiState();
    renderGlobalFocusPanel();
  });
}

const FOCUS_AWN_KEYS = [
  "awn-status",
  "awn-description",
  "awn-category",
  "awn-owner",
  "awn-priority",
  "awn-tags",
  "awn-color",
  "awn-version",
  "awn-type",
  "awn-create",
  "awn-update"
];

function formatFocusPropLabel(key) {
  const meta = PROPS_FIELD_META[key];
  if (meta?.label) return meta.label;
  return String(key || "").replace(/^awn-/, "").replace(/-/g, " ");
}

function formatFocusPropValue(key, value) {
  const text = String(value ?? "").trim();
  if (!text) return "";
  if (key === "awn-color" && /^#[0-9a-f]{3,8}$/i.test(text)) {
    return text;
  }
  return text;
}

function getFocusPropDisplayValue(focusItem, key) {
  const fromCatalog = focusItem?.catalogDisplay?.[key];
  if (fromCatalog) return String(fromCatalog).trim();
  return formatFocusPropValue(key, focusItem?.awnProps?.[key] ?? "");
}

function appendFocusPropRows(propsNode, focusItem, keys = FOCUS_AWN_KEYS) {
  const awnProps = focusItem?.awnProps && typeof focusItem.awnProps === "object" ? focusItem.awnProps : {};
  for (const key of keys) {
    const value = getFocusPropDisplayValue(focusItem, key);
    if (!value) continue;

    const row = document.createElement("div");
    row.className = "agent-focus-prop";

    const dt = document.createElement("dt");
    dt.className = "agent-focus-prop-key";
    dt.textContent = formatFocusPropLabel(key);

    const dd = document.createElement("dd");
    dd.className = "agent-focus-prop-value";
    if (key === "awn-color") {
      const swatchHex =
        String(focusItem?.catalogDisplay?.["awn-color-hex"] || "").trim() ||
        (/^#[0-9a-f]{3,8}$/i.test(String(focusItem?.awnProps?.[key] || "").trim())
          ? String(focusItem.awnProps[key]).trim()
          : "");
      const swatch = document.createElement("span");
      swatch.className = "agent-focus-prop-color";
      if (swatchHex) swatch.style.backgroundColor = swatchHex;
      swatch.setAttribute("aria-hidden", "true");
      dd.append(swatch, document.createTextNode(value));
    } else {
      dd.textContent = value;
    }

    row.append(dt, dd);
    propsNode.appendChild(row);
  }
}

function isFocusItemActive(focusItem) {
  if (activeSystemFile || !activePath || !focusItem?.nodePath) return false;
  return (
    normalizeMenuNodePath(getResolvedNodePath(activePath)) ===
    normalizeMenuNodePath(focusItem.nodePath)
  );
}

function syncFocusPanelActiveState() {
  const resolvedActive = normalizeMenuNodePath(getResolvedNodePath(activePath || ""));

  for (const chip of document.querySelectorAll(".agent-focus-chip[data-focus-path]")) {
    const isActive =
      !activeSystemFile &&
      Boolean(resolvedActive) &&
      normalizeMenuNodePath(chip.dataset.focusPath || "") === resolvedActive;
    chip.classList.toggle("is-active", isActive);
    chip.setAttribute("aria-current", isActive ? "page" : "false");
  }

  for (const item of document.querySelectorAll(
    ".agent-focus-item[data-focus-path], .app-landing-focus-tile[data-focus-path], .app-landing-orbit-twig[data-focus-path], .app-landing-hub-twig[data-focus-path], .app-landing-flow-card[data-focus-path]"
  )) {
    const isActive =
      !activeSystemFile &&
      Boolean(resolvedActive) &&
      normalizeMenuNodePath(item.dataset.focusPath || "") === resolvedActive;
    item.classList.toggle("is-active", isActive);
  }
}

function appendDisabledRegistryAgentDot(parent) {
  const statusDot = document.createElement("span");
  statusDot.className = "app-landing-agent-dot is-disabled";
  statusDot.setAttribute("aria-hidden", "true");
  parent.appendChild(statusDot);
}

function createFocusItem(focusItem, variant = "landing") {
  const agent =
    agentsCache.find((entry) => entry.id === focusItem.agentId) || {
      id: focusItem.agentId,
      name: focusItem.agentName,
      path: focusItem.agentPath
    };
  const registryActive = focusItem.agentActive !== false && isAgentRegistryActive(agent);
  const label = focusItem.name || focusItem.agentName || focusItem.agentId;
  const nodePath = String(focusItem.nodePath || "").trim();
  const awnProps = focusItem.awnProps && typeof focusItem.awnProps === "object" ? focusItem.awnProps : {};

  if (variant === "sidebar") {
    const row = document.createElement("div");
    row.className = "agent-focus-chip-row";
    row.setAttribute("role", "listitem");
    if (nodePath) row.dataset.focusPath = nodePath;

    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "agent-focus-chip";
    if (isFocusItemActive(focusItem)) {
      chip.classList.add("is-active");
      chip.setAttribute("aria-current", "page");
    }
    if (!registryActive) chip.classList.add("is-registry-off");
    chip.title = nodePath || label;
    chip.setAttribute("aria-label", registryActive ? `Открыть ${label}` : `${label} — агент неактивен`);

    const nameNode = document.createElement("span");
    nameNode.className = "agent-focus-chip-name";
    nameNode.textContent = label;

    if (!registryActive) appendDisabledRegistryAgentDot(chip);
    chip.append(nameNode);
    chip.addEventListener("click", () => {
      void openFocusItem(focusItem);
    });

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "agent-focus-chip-remove";
    removeBtn.title = "Убрать из фокуса";
    removeBtn.setAttribute("aria-label", `Убрать ${label} из фокуса`);
    removeBtn.textContent = "×";
    removeBtn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      void removeNodeFromFocus(focusItem);
    });

    row.append(chip, removeBtn);
    return row;
  }

  const item = document.createElement("article");
  item.className = "agent-focus-item";
  item.setAttribute("role", "listitem");
  if (nodePath) item.dataset.focusPath = nodePath;
  if (isFocusItemActive(focusItem)) item.classList.add("is-active");

  const head = document.createElement("button");
  head.type = "button";
  head.className = "agent-focus-item-head";
  if (!registryActive) head.classList.add("is-registry-off");
  head.title = registryActive ? `Открыть ${label}` : `${label} — агент неактивен`;
  head.setAttribute(
    "aria-label",
    registryActive ? `Открыть ${label}` : `${label} — агент неактивен`
  );

  const media = document.createElement("span");
  media.className = "agent-focus-item-media";
  const nodeEmoji = resolveAwnEmoji(awnProps);
  const agentEmoji = resolveAwnEmoji(agent.awnProps);
  const previewUrl = resolveFocusPreviewUrl(focusItem.nodePreviewUrl, focusItem.agentId);
  mountPreviewOrFallback(media, {
    previewUrl,
    emoji: nodeEmoji || agentEmoji,
    fallbackText: getAgentPickerInitials({ name: label, id: focusItem.agentId }),
    emojiClass: "agent-focus-item-emoji",
    initialsClass: "agent-focus-item-fallback",
    nodePath,
    iconClass: "node-cover-icon--in-focus-media"
  });

  const titleWrap = document.createElement("span");
  titleWrap.className = "agent-focus-item-title-wrap";

  const nameRow = document.createElement("span");
  nameRow.className = "agent-focus-item-name-row";

  const nameNode = document.createElement("span");
  nameNode.className = "agent-focus-item-name";
  nameNode.textContent = label;

  const metaNode = document.createElement("span");
  metaNode.className = "agent-focus-item-meta";
  metaNode.textContent = nodePath || focusItem.awnType || "workspace";

  if (!registryActive) appendDisabledRegistryAgentDot(nameRow);
  nameRow.append(nameNode);
  titleWrap.append(nameRow, metaNode);
  head.append(media, titleWrap);
  head.addEventListener("click", () => {
    void openFocusItem(focusItem);
  });

  const props = document.createElement("dl");
  props.className = "agent-focus-props";
  appendFocusPropRows(props, focusItem);

  if (props.childElementCount > 0) {
    item.append(head, props);
  } else {
    item.append(head);
  }
  return item;
}

async function openFocusItem(focusItem) {
  const agent = agentsCache.find((entry) => entry.id === focusItem?.agentId);
  if (!agent || !isAgentRegistryActive(agent)) {
    showToast("Агент выключен — включите в реестре (⚙)", "error");
    return;
  }

  const nodePath = String(focusItem?.nodePath || "").trim();
  const label = focusItem?.name || getLabelFromPath(nodePath) || agent.name || agent.id;

  try {
    if (activeAgentId !== agent.id) {
      await switchActiveAgent(agent.id);
    } else if (!appLandingPaneNode?.classList.contains("hidden")) {
      hideAppLandingView();
      showHomeView();
    }
    if (nodePath && nodePath !== "_registration.md") {
      await openNodeFromMenu(label, nodePath);
    } else {
      showAgentHomeView();
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message ? `Не удалось открыть: ${message}` : "Не удалось открыть", "error");
  }
}

function resolveFocusPreviewUrl(rawUrl, agentId) {
  const url = String(rawUrl || "").trim();
  if (!url) return null;
  if (url.startsWith("/api/agents/workspace-preview")) {
    return appendCacheBuster(url);
  }
  return appendCacheBuster(appendAgentToApiUrl(url, agentId));
}

function createFocusThumbCell(previewUrl, fallbackText, sizeClass = "", emoji = "", nodePath = "") {
  const media = document.createElement("span");
  media.className = `agent-focus-table-thumb${sizeClass ? ` ${sizeClass}` : ""}`;
  mountPreviewOrFallback(media, {
    previewUrl,
    emoji,
    fallbackText,
    emojiClass: "agent-focus-table-emoji",
    initialsClass: "agent-focus-table-fallback",
    nodePath,
    iconClass: "node-cover-icon--in-focus-table"
  });
  return media;
}

function createFocusTableEntityCell(thumb, title, sub = "") {
  const wrap = document.createElement("div");
  wrap.className = "agent-focus-table-entity";

  const copy = document.createElement("div");
  copy.className = "agent-focus-table-entity-copy";

  const titleNode = document.createElement("span");
  titleNode.className = "agent-focus-table-entity-title";
  titleNode.textContent = title;
  copy.appendChild(titleNode);

  if (sub) {
    const subNode = document.createElement("span");
    subNode.className = "agent-focus-table-entity-sub";
    subNode.textContent = sub;
    copy.appendChild(subNode);
  }

  wrap.append(thumb, copy);
  return wrap;
}

function createFocusTableValueCell(key, value, focusItem = null) {
  const td = document.createElement("td");
  td.className = "agent-focus-table-value";
  td.dataset.field = key;

  if (key === "awn-color" && value) {
    const swatchHex =
      String(focusItem?.catalogDisplay?.["awn-color-hex"] || "").trim() ||
      (/^#[0-9a-f]{3,8}$/i.test(String(focusItem?.awnProps?.["awn-color"] || "").trim())
        ? String(focusItem.awnProps["awn-color"]).trim()
        : "");
    const swatch = document.createElement("span");
    swatch.className = "agent-focus-prop-color";
    if (swatchHex) swatch.style.backgroundColor = swatchHex;
    swatch.setAttribute("aria-hidden", "true");
    const text = document.createElement("span");
    text.className = "agent-focus-table-value-text";
    text.textContent = value;
    td.append(swatch, text);
    return td;
  }

  td.textContent = value || "—";
  return td;
}

function getLandingFocusTableColumns(items) {
  const propCols = FOCUS_AWN_KEYS.filter((key) =>
    items.some((item) => getFocusPropDisplayValue(item, key))
  );
  return ["agent", "topic", ...propCols];
}

function getLandingFocusColumnLabel(columnId) {
  if (columnId === "agent") return "Агент";
  if (columnId === "topic") return "Тема";
  return formatFocusPropLabel(columnId);
}

function createLandingFocusTableRow(focusItem, columns) {
  const agent =
    agentsCache.find((entry) => entry.id === focusItem.agentId) || {
      id: focusItem.agentId,
      name: focusItem.agentName,
      path: focusItem.agentPath
    };
  const registryActive = focusItem.agentActive !== false && isAgentRegistryActive(agent);
  const label = focusItem.name || focusItem.agentName || focusItem.agentId;
  const nodePath = String(focusItem.nodePath || "").trim();
  const awnProps = focusItem.awnProps && typeof focusItem.awnProps === "object" ? focusItem.awnProps : {};

  const row = document.createElement("tr");
  row.className = "agent-focus-table-row";
  if (!registryActive) row.classList.add("is-registry-off");
  row.tabIndex = 0;
  row.title = registryActive ? `Открыть ${label}` : `${label} — агент неактивен`;

  const open = () => {
    void openFocusItem(focusItem);
  };
  row.addEventListener("click", open);
  row.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      open();
    }
  });

  for (const columnId of columns) {
    const td = document.createElement("td");
    td.className = "agent-focus-table-cell";
    td.dataset.column = columnId;

    if (columnId === "agent") {
      const agentPreviewUrl =
        resolveFocusPreviewUrl(focusItem.agentPreviewUrl, focusItem.agentId) ||
        getRegistryAgentPreviewUrl(agent);
      const thumb = createFocusThumbCell(
        agentPreviewUrl,
        getAgentPickerInitials({ name: focusItem.agentName, id: focusItem.agentId }),
        "",
        resolveAwnEmoji(agent.awnProps)
      );
      td.appendChild(
        createFocusTableEntityCell(
          thumb,
          focusItem.agentName || focusItem.agentId,
          focusItem.agentId
        )
      );
    } else if (columnId === "topic") {
      const nodePreviewUrl = resolveFocusPreviewUrl(focusItem.nodePreviewUrl, focusItem.agentId);
      const thumb = createFocusThumbCell(
        nodePreviewUrl,
        getAgentPickerInitials({ name: label, id: focusItem.agentId }),
        "",
        resolveAwnEmoji(awnProps),
        nodePath
      );
      td.appendChild(createFocusTableEntityCell(thumb, label, nodePath));
    } else {
      const value = getFocusPropDisplayValue(focusItem, columnId);
      row.appendChild(createFocusTableValueCell(columnId, value, focusItem));
      continue;
    }

    row.appendChild(td);
  }

  return row;
}

function createLandingFocusTile(focusItem) {
  const agent =
    agentsCache.find((entry) => entry.id === focusItem.agentId) || {
      id: focusItem.agentId,
      name: focusItem.agentName,
      path: focusItem.agentPath
    };
  const registryActive = focusItem.agentActive !== false && isAgentRegistryActive(agent);
  const label = focusItem.name || focusItem.agentName || focusItem.agentId;
  const agentLabel = agent.name || focusItem.agentName || focusItem.agentId;
  const nodePath = String(focusItem.nodePath || "").trim();
  const awnProps = focusItem.awnProps && typeof focusItem.awnProps === "object" ? focusItem.awnProps : {};
  const status = getFocusPropDisplayValue(focusItem, "awn-status");

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "app-landing-focus-tile";
  btn.setAttribute("role", "listitem");
  if (nodePath) btn.dataset.focusPath = nodePath;
  if (isFocusItemActive(focusItem)) btn.classList.add("is-active");
  if (!registryActive) btn.classList.add("is-registry-off");
  btn.title = registryActive ? `Открыть ${label}` : `${label} — агент неактивен`;
  btn.setAttribute(
    "aria-label",
    registryActive ? `Открыть ${label}` : `${label} — агент неактивен`
  );

  const media = document.createElement("span");
  media.className = "app-landing-focus-tile-media";
  const nodeEmoji = resolveAwnEmoji(awnProps);
  const agentEmoji = resolveAwnEmoji(agent.awnProps);
  const previewUrl = resolveFocusPreviewUrl(focusItem.nodePreviewUrl, focusItem.agentId);
  mountPreviewOrFallback(media, {
    previewUrl,
    emoji: nodeEmoji || agentEmoji,
    fallbackText: getAgentPickerInitials({ name: label, id: focusItem.agentId }),
    emojiClass: "app-landing-focus-tile-emoji",
    initialsClass: "app-landing-focus-tile-fallback",
    nodePath,
    iconClass: "node-cover-icon--in-focus-tile"
  });

  const copy = document.createElement("span");
  copy.className = "app-landing-focus-tile-copy";

  const titleNode = document.createElement("span");
  titleNode.className = "app-landing-focus-tile-title";
  titleNode.textContent = label;

  const metaNode = document.createElement("span");
  metaNode.className = "app-landing-focus-tile-meta";
  metaNode.textContent = agentLabel;

  copy.append(titleNode, metaNode);

  if (status) {
    const statusNode = document.createElement("span");
    statusNode.className = "app-landing-focus-tile-status";
    statusNode.textContent = status;
    copy.appendChild(statusNode);
  }

  btn.append(media, copy);
  btn.addEventListener("click", () => {
    void openFocusItem(focusItem);
  });
  return btn;
}

function renderLandingFocusGrid(items) {
  if (!appLandingFocusNode || !appLandingFocusListNode) return;

  appLandingFocusListNode.replaceChildren();

  if (!globalFocusItemsCache.length) {
    appLandingFocusNode.classList.add("hidden");
    setLandingFocusFiltersOpen(false);
    return;
  }

  appLandingFocusNode.classList.remove("hidden");

  if (!items.length) {
    const empty = document.createElement("p");
    empty.className = "app-landing-focus-empty";
    empty.textContent = "Нет записей по выбранным фильтрам";
    appLandingFocusListNode.appendChild(empty);
    return;
  }

  for (const focusItem of items) {
    appLandingFocusListNode.appendChild(createLandingFocusTile(focusItem));
  }
  syncFocusPanelActiveState();
}

function renderGlobalFocusPanel() {
  syncLandingFocusToolbarUi();
  const processed = getProcessedLandingFocusItems();
  if (getLandingAgentsView() === "hub") {
    renderAppLandingHub(processed);
    return;
  }
  if (getLandingAgentsView() === "orbit") {
    setLandingOrbitFocusCache(processed);
    return;
  }
  if (getLandingAgentsView() === "grid") {
    renderAppLandingList(processed);
    return;
  }
  if (getLandingAgentsView() === "flow") {
    renderAppLandingFlow(processed);
    return;
  }
  renderLandingFocusGrid(processed);
}

function renderSidebarFocusPanel(panelNode, listNode, items) {
  if (!panelNode || !listNode) return;
  listNode.replaceChildren();
  if (!activeAgentId) {
    panelNode.classList.add("hidden");
    syncSidebarFocusCount();
    return;
  }
  panelNode.classList.remove("hidden");
  if (!items.length) {
    const empty = document.createElement("p");
    empty.className = "agent-focus-empty";
    empty.textContent = "Нет записей с awn-main: true — отметьте тему в свойствах (⭐ Фокус).";
    listNode.appendChild(empty);
    syncSidebarFocusCount();
    syncSidebarFocusAccordionUi();
    return;
  }
  for (const focusItem of items) {
    listNode.appendChild(createFocusItem(focusItem, "sidebar"));
  }
  syncSidebarFocusCount();
  syncSidebarFocusAccordionUi();
}

function renderFocusPanel(panelNode, listNode, items, variant) {
  if (!panelNode || !listNode) return;
  if (variant === "sidebar") {
    renderSidebarFocusPanel(panelNode, listNode, items);
    return;
  }
  listNode.replaceChildren();
  if (!items.length) {
    panelNode.classList.add("hidden");
    return;
  }
  panelNode.classList.remove("hidden");
  for (const focusItem of items) {
    listNode.appendChild(createFocusItem(focusItem, variant));
  }
}

function renderAgentFocusPanels() {
  renderFocusPanel(homeFocusNode, homeFocusListNode, agentFocusItemsCache, "home");
  renderFocusPanel(sidebarFocusNode, sidebarFocusListNode, agentFocusItemsCache, "sidebar");
  syncSidebarFocusCount();
  updateNodeOverviewHeroActionStates();
}

async function loadGlobalFocusItems() {
  try {
    const response = await fetch("/api/agents/focus");
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    globalFocusItemsCache = Array.isArray(data.items) ? data.items : [];
  } catch {
    globalFocusItemsCache = [];
  }
  renderGlobalFocusPanel();
}

async function loadAgentFocusItems(agentId = activeAgentId) {
  if (!agentId) {
    agentFocusItemsCache = [];
    renderAgentFocusPanels();
    return;
  }
  try {
    const response = await fetch(`/api/agents/focus?agent=${encodeURIComponent(agentId)}`);
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    agentFocusItemsCache = Array.isArray(data.items) ? data.items : [];
  } catch {
    agentFocusItemsCache = [];
  }
  renderAgentFocusPanels();
}

async function refreshAllFocusPanels() {
  await Promise.all([loadGlobalFocusItems(), loadAgentFocusItems(activeAgentId)]);
}

function getAgentsForPickerGrid() {
  return [...agentsCache].sort((a, b) => {
    const aOn = isAgentRegistryActive(a) ? 1 : 0;
    const bOn = isAgentRegistryActive(b) ? 1 : 0;
    if (aOn !== bOn) return bOn - aOn;
    return String(a.name || a.id).localeCompare(String(b.name || b.id), "ru");
  });
}

function createAgentPickerAgentButton(agent, avatarSize = 42) {
  const btn = document.createElement("button");
  btn.type = "button";
  const registryActive = isAgentRegistryActive(agent);
  const isCurrent = agent.id === activeAgentId;
  btn.className = "agents-picker-agent-btn";
  if (isCurrent) btn.classList.add("is-active");
  if (!registryActive) btn.classList.add("is-registry-off");

  const statusLabel = registryActive ? "вкл" : "выкл";
  const titleParts = [agent.name || agent.id, registryActive ? "активен в реестре" : "выключен в реестре"];
  if (isCurrent) titleParts.push("текущий");
  btn.title = titleParts.join(" · ");
  btn.setAttribute(
    "aria-label",
    `${agent.name || agent.id}, ${registryActive ? "активен" : "неактивен"}${isCurrent ? ", текущий" : ""}`
  );
  btn.style.setProperty("--picker-avatar-size", `${avatarSize}px`);

  const previewUrl = getRegistryAgentPreviewUrl(agent);
  if (previewUrl) {
    const img = document.createElement("img");
    img.className = "agents-picker-avatar";
    img.alt = "";
    img.draggable = false;
    img.onerror = () => {
      img.replaceWith(createAgentPickerFallback(agent, avatarSize));
    };
    img.src = previewUrl;
    btn.appendChild(img);
  } else {
    btn.appendChild(createAgentPickerFallback(agent, avatarSize));
  }

  const nameNode = document.createElement("span");
  nameNode.className = "agents-picker-name";
  nameNode.textContent = agent.name || agent.id;
  btn.appendChild(nameNode);

  const statusNode = document.createElement("span");
  statusNode.className = `agents-picker-registry-status ${
    registryActive ? "agents-picker-registry-status--on" : "agents-picker-registry-status--off"
  }`;
  statusNode.textContent = `${registryActive ? "●" : "○"} ${statusLabel}`;
  btn.appendChild(statusNode);

  if (agent.default) {
    const badge = document.createElement("span");
    badge.className = "agents-picker-default-badge";
    badge.title = "Агент по умолчанию";
    badge.setAttribute("aria-hidden", "true");
    btn.appendChild(badge);
  }

  btn.addEventListener("click", () => {
    if (!registryActive) {
      showToast("Агент выключен — включите в реестре (⚙)", "error");
      return;
    }
    selectAgentOption(agent.id);
    closeAgentsPickerPopover();
  });

  return btn;
}

function createAgentPickerFallback(agent, avatarSize) {
  const emoji = resolveAwnEmoji(agent);
  const fallback = document.createElement("span");
  fallback.className = emoji ? "agents-picker-avatar-emoji" : "agents-picker-avatar-fallback";
  fallback.style.setProperty("--picker-avatar-size", `${avatarSize}px`);
  fallback.textContent = emoji || getAgentPickerInitials(agent);
  if (emoji) fallback.setAttribute("aria-hidden", "true");
  return fallback;
}

function renderAgentsPickerGrid() {
  if (!agentsPickerStageNode) return;

  agentsPickerStageNode.className = "agents-picker-stage agents-picker-stage--grid";
  agentsPickerStageNode.replaceChildren();

  const agents = getAgentsForPickerGrid();
  if (agents.length === 0) {
    const empty = document.createElement("p");
    empty.className = "agents-picker-empty";
    empty.textContent = "Нет агентов в реестре";
    agentsPickerStageNode.appendChild(empty);
    return;
  }

  const grid = document.createElement("div");
  grid.className = "agents-picker-grid";
  for (const agent of agents) {
    grid.appendChild(createAgentPickerAgentButton(agent));
  }
  agentsPickerStageNode.appendChild(grid);
}

function syncAgentsPickerButtonState() {
  if (!agentsPickerBtn) return;
  agentsPickerBtn.classList.toggle("is-active", agentsPickerIsOpen);
  agentsPickerBtn.setAttribute("aria-expanded", agentsPickerIsOpen ? "true" : "false");
}

function resetAgentsPickerPopoverPosition() {
  if (!agentsPickerPopoverNode) return;
  for (const prop of ["top", "left", "width", "maxHeight"]) {
    agentsPickerPopoverNode.style.removeProperty(prop);
  }
}

function positionAgentsPickerPopover() {
  const popover = agentsPickerPopoverNode;
  const anchor = document.querySelector(".sidebar-agent-controls");
  if (!popover || !anchor || popover.classList.contains("hidden")) return;

  const rect = anchor.getBoundingClientRect();
  const width = Math.min(300, Math.max(Math.round(rect.width), 240));
  const left = Math.max(12, Math.round(rect.left));
  const top = Math.round(rect.bottom + 6);
  const maxHeight = Math.max(160, window.innerHeight - top - 12);

  popover.style.top = `${top}px`;
  popover.style.left = `${left}px`;
  popover.style.width = `${width}px`;
  popover.style.maxHeight = `${maxHeight}px`;
}

function closeAgentsPickerPopover() {
  agentsPickerPopoverNode?.classList.add("hidden");
  agentsPickerIsOpen = false;
  syncAgentsPickerButtonState();
  resetAgentsPickerPopoverPosition();
}

function openAgentsPickerPopover() {
  if (!agentsPickerPopoverNode) return;
  if (agentsPickerIsOpen) {
    closeAgentsPickerPopover();
    return;
  }
  closeMenuSettingsPopover();
  agentsPickerIsOpen = true;
  renderAgentsPickerGrid();
  agentsPickerPopoverNode.classList.remove("hidden");
  syncAgentsPickerButtonState();
  positionAgentsPickerPopover();
}

function refreshAgentsPickerIfOpen() {
  if (!agentsPickerIsOpen) return;
  renderAgentsPickerGrid();
}

function getActiveAgentLabel() {
  return getActiveAgentMeta()?.name || "";
}

function formatAgentSelectLabel(agent, groupTitle = "") {
  const registryActive = isAgentRegistryActive(agent);
  const name = agent.name || agent.id;
  let label = registryActive ? name : `${name} (выкл.)`;
  if (isPlatformAgent(agent)) {
    label = `${name} — глобальные справочники`;
  }
  const prefix = String(groupTitle || "").trim();
  return prefix ? `${prefix} | ${label}` : label;
}

function createAgentSelectOption(agent, groupTitle = "") {
  const option = document.createElement("option");
  option.value = agent.id;
  option.textContent = formatAgentSelectLabel(agent, groupTitle);
  option.disabled = !isAgentRegistryActive(agent);
  return option;
}

function renderAgentSelectGrouped(agents) {
  const platformAgents = agents.filter(isPlatformAgent);
  const workspaceAgents = agents.filter((agent) => !isPlatformAgent(agent));
  const { orchestrator } = splitLandingOrchestratorAgent(workspaceAgents);
  const { grouped, ungrouped } = buildLandingGroupsLayout(workspaceAgents, landingAgentsGroupsCache);

  for (const agent of platformAgents) {
    agentSelectNode.appendChild(createAgentSelectOption(agent, "Платформа"));
  }

  if (orchestrator) {
    agentSelectNode.appendChild(createAgentSelectOption(orchestrator, "Оркестратор"));
  }

  for (const group of grouped) {
    const groupTitle = group.title || group.id;
    for (const agent of group.agents || []) {
      agentSelectNode.appendChild(createAgentSelectOption(agent, groupTitle));
    }
  }

  for (const agent of ungrouped) {
    agentSelectNode.appendChild(createAgentSelectOption(agent));
  }
}

function renderAgentSelectFlat(agents) {
  for (const agent of agents) {
    agentSelectNode.appendChild(createAgentSelectOption(agent));
  }
}

function renderAgentSelect() {
  if (!agentSelectNode) return;

  const agents = getRegistryAgentsForUi();
  const selectableAgents = getSelectableAgents();
  const previousValue = agentSelectNode.value;
  agentSelectNode.innerHTML = "";

  const placeholderOption = document.createElement("option");
  placeholderOption.value = "";
  placeholderOption.textContent = "— агент —";
  agentSelectNode.appendChild(placeholderOption);

  if (agents.length === 0) {
    placeholderOption.textContent = "Нет агентов";
    placeholderOption.disabled = true;
    agentSelectNode.disabled = true;
    syncAgentPreview();
    return;
  }

  if (landingAgentsGroupsCache.length > 0) {
    renderAgentSelectGrouped(agents);
  } else {
    renderAgentSelectFlat(agents);
  }

  agentSelectNode.disabled = false;
  const nextValue =
    activeAgentId && selectableAgents.some((agent) => agent.id === activeAgentId)
      ? activeAgentId
      : previousValue && selectableAgents.some((agent) => agent.id === previousValue)
        ? previousValue
        : "";
  agentSelectNode.value = nextValue;
  void refreshAgentSliderCatalog(true).then(() => syncAgentPreview());
  refreshAgentsPickerIfOpen();
}

function showMenuNoAgentPlaceholder() {
  for (const pane of menuAgentPanes.values()) {
    pane.classList.add("hidden");
  }
  if (!menuNode) return;

  let placeholder = document.getElementById("menu-no-agent-placeholder");
  if (!placeholder) {
    placeholder = document.createElement("div");
    placeholder.id = "menu-no-agent-placeholder";
    placeholder.className = "menu-no-agent-placeholder";
    menuNode.appendChild(placeholder);
  }
  placeholder.textContent = "Выберите агента на главной";
  placeholder.classList.remove("hidden");
}

function hideMenuNoAgentPlaceholder() {
  document.getElementById("menu-no-agent-placeholder")?.classList.add("hidden");
}

function openCreateAgentFromLanding() {
  openAppLandingCreateModal();
}

function openAppLandingCreateModal() {
  if (!appLandingCreateModalNode) return;
  if (appLandingCreateNameInputNode) {
    appLandingCreateNameInputNode.value = "";
  }
  if (appLandingCreateDescriptionInputNode) {
    appLandingCreateDescriptionInputNode.value = "";
  }
  if (appLandingCreatePathInputNode) {
    appLandingCreatePathInputNode.value = "./workspaces/";
  }
  clearCreateAgentFormValidation(getCreateAgentFormFields("app-landing").fieldNodes);
  resetCreateAgentPathAutoSync("app-landing");
  appLandingCreateModalNode.classList.remove("hidden");
  window.setTimeout(() => appLandingCreateNameInputNode?.focus(), 0);
}

function closeAppLandingCreateModal() {
  appLandingCreateModalNode?.classList.add("hidden");
  if (appLandingCreateSubmitBtn) {
    appLandingCreateSubmitBtn.disabled = false;
    appLandingCreateSubmitBtn.textContent = "Создать";
  }
}

function isAgentPathInRegistry(pathValue) {
  const key = normalizeRegistryPathKey(pathValue);
  return agentsCache.some((agent) => normalizeRegistryPathKey(agent.path) === key);
}

async function appendCreatedAgentToRegistry(discovered) {
  const key = normalizeRegistryPathKey(discovered.path);
  const base = getRegistryAgentsForUi();
  if (base.some((agent) => normalizeRegistryPathKey(agent.path) === key)) {
    return false;
  }

  const agents = [
    ...base.map(({ path, environment, default: isDefault, orchestrator: isOrchestrator, active, name, comment }) => ({
      path,
      environment: environment || "local",
      default: Boolean(isDefault),
      orchestrator: Boolean(isOrchestrator),
      active: active !== false,
      name: name ?? "",
      comment: comment ?? ""
    })),
    {
      path: discovered.path,
      environment: "local",
      default: base.length === 0,
      active: true,
      name: discovered.name ?? "",
      comment: discovered.comment ?? ""
    }
  ];

  const response = await fetch("/api/agents/registry", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ agents })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
  }

  await loadAgents();
  return true;
}

async function submitAppLandingCreate() {
  if (!appLandingCreateSubmitBtn || !appLandingCreatePathInputNode) return;

  const workspacePath = normalizeCreateAgentWorkspacePath(appLandingCreatePathInputNode.value.trim());
  appLandingCreatePathInputNode.value = workspacePath;
  const agentName = appLandingCreateNameInputNode?.value.trim() || "";
  const agentDescription = appLandingCreateDescriptionInputNode?.value.trim() || "";
  const validationError = validateCreateAgentForm({
    name: agentName,
    description: agentDescription,
    path: workspacePath,
    checkRegistry: true
  });
  if (validationError) {
    applyCreateAgentFormValidation("app-landing", validationError);
    return;
  }

  appLandingCreateSubmitBtn.disabled = true;
  appLandingCreateSubmitBtn.textContent = "Создаю...";

  try {
    const response = await fetch("/api/agents/create", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path: workspacePath,
        name: agentName || undefined,
        comment: agentDescription || undefined
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
    }

    const data = await response.json();
    if (!data.agent) throw new Error("Сервер не вернул данные агента");

    const added = await appendCreatedAgentToRegistry(data.agent);
    if (!added) {
      showToast("Агент создан, но уже есть в реестре", "error");
      return;
    }

    closeAppLandingCreateModal();
    renderAppLandingAgents();
    renderLandingSearchAgents();
    showToast("Агент создан", "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message ? `Ошибка создания: ${message}` : "Ошибка создания", "error");
  } finally {
    appLandingCreateSubmitBtn.disabled = false;
    appLandingCreateSubmitBtn.textContent = "Создать";
  }
}

async function runPlatformCatalogMigration(preset = "") {
  try {
    const url = preset
      ? `/api/platform/catalogs/migrate?preset=${encodeURIComponent(preset)}`
      : "/api/platform/catalogs/migrate";
    const response = await fetch(url, { method: "POST" });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`);
    if (preset) {
      showToast(`${preset}: +${data.addedCount || 0}, всего ${data.total || 0}`, "success");
    } else {
      const parts = Object.entries(data.results || {})
        .filter(([, result]) => result?.addedCount)
        .map(([key, result]) => `${key} +${result.addedCount}`);
      showToast(parts.length ? parts.join(" · ") : "Новых значений не найдено", "success");
    }
    if (activeAgentId) await loadAgentCatalogs(activeAgentId);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message ? `Миграция: ${message}` : "Ошибка миграции", "error");
  }
}

async function runPlatformTagsMigration() {
  return runPlatformCatalogMigration("tags");
}

async function openPlatformIndexItem(relativePath) {
  const platform = getPlatformAgentForLanding();
  if (!platform) return;
  const normalized = String(relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return;
  selectAgentOption(platform.id);
  await openNodeFromMenu(getLabelFromPath(normalized), normalized);
}

async function renderAppLandingPlatformSection() {
  if (!appLandingPlatformNode) return;
  appLandingPlatformNode.replaceChildren();
  const platform = getPlatformAgentForLanding();
  if (!platform) {
    appLandingPlatformNode.classList.add("hidden");
    return;
  }
  appLandingPlatformNode.classList.remove("hidden");

  const head = document.createElement("header");
  head.className = "app-landing-platform-head";
  const title = document.createElement("h3");
  title.id = "app-landing-platform-title";
  title.className = "app-landing-platform-title";
  title.textContent = "Платформа";
  const lead = document.createElement("p");
  lead.className = "app-landing-platform-lead";
  lead.textContent = "Глобальные справочники и конфигурация платформы";
  head.append(title, lead);

  const actions = document.createElement("div");
  actions.className = "app-landing-platform-actions";
  const openBtn = document.createElement("button");
  openBtn.type = "button";
  openBtn.className = "app-landing-platform-open-btn";
  openBtn.textContent = "Открыть справочники";
  openBtn.addEventListener("click", () => selectAgentOption(platform.id));
  const migrateBtn = document.createElement("button");
  migrateBtn.type = "button";
  migrateBtn.className = "app-landing-platform-migrate-btn";
  migrateBtn.textContent = "Собрать справочники";
  migrateBtn.title = "Добавить в global CSV значения из frontmatter всех workspace";
  migrateBtn.addEventListener("click", () => void runPlatformCatalogMigration());
  actions.append(openBtn, migrateBtn);
  appLandingPlatformNode.append(head, actions);

  try {
    const response = await fetch("/api/platform/index");
    if (!response.ok) return;
    const index = await response.json();
    const sections = Array.isArray(index?.sections) ? index.sections : [];
    if (!sections.length) return;

    const grid = document.createElement("div");
    grid.className = "app-landing-platform-sections";

    for (const section of sections) {
      const items = Array.isArray(section.items) ? section.items : [];
      if (!items.length) continue;

      const block = document.createElement("section");
      block.className = "app-landing-platform-section";

      const sectionTitle = document.createElement("h4");
      sectionTitle.className = "app-landing-platform-section-title";
      sectionTitle.textContent =
        section.title === "Catalogs" ? "Справочники" : section.title || "Раздел";
      block.appendChild(sectionTitle);

      const list = document.createElement("div");
      list.className = "app-landing-platform-section-items";

      for (const item of items) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "app-landing-platform-link";
        btn.textContent = item.label || item.path || "—";
        btn.title = item.path || "";
        btn.addEventListener("click", () => void openPlatformIndexItem(item.path));
        list.appendChild(btn);
      }

      block.appendChild(list);
      grid.appendChild(block);
    }

    appLandingPlatformNode.appendChild(grid);
  } catch {
    // index optional
  }
}

function createAppLandingAgentTile(agent) {
  const registryActive = isAgentRegistryActive(agent);
  const isOrchestrator = agent.orchestrator === true;
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "app-landing-agent-tile";
  if (!registryActive) btn.classList.add("is-registry-off");
  if (isOrchestrator) btn.classList.add("is-orchestrator");
  const label = agent.name || agent.id;
  btn.title = registryActive
    ? `Открыть ${label}`
    : `${label} — неактивен, включите в реестре`;
  btn.setAttribute(
    "aria-label",
    registryActive ? `Открыть агента ${label}` : `Агент ${label} неактивен`
  );

  const media = document.createElement("div");
  media.className = "app-landing-agent-tile-media";
  mountPreviewOrFallback(media, {
    previewUrl: getRegistryAgentPreviewUrl(agent),
    emoji: resolveAwnEmoji(agent),
    fallbackText: getAgentPickerInitials(agent),
    emojiClass: "app-landing-agent-tile-emoji",
    initialsClass: "app-landing-agent-tile-fallback"
  });

  const nameNode = document.createElement("span");
  nameNode.className = "app-landing-agent-tile-name";
  nameNode.textContent = label;

  btn.append(media, nameNode);
  btn.addEventListener("click", () => {
    if (!registryActive) {
      showToast("Агент выключен — включите в реестре (⚙)", "error");
      return;
    }
    selectAgentOption(agent.id);
  });
  return btn;
}

function createAppLandingAgentCard(agent) {
  const registryActive = isAgentRegistryActive(agent);
  const isOrchestrator = agent.orchestrator === true;
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "app-landing-agent-card";
  if (!registryActive) btn.classList.add("is-registry-off");
  if (isOrchestrator) btn.classList.add("is-orchestrator");
  const label = agent.name || agent.id;
  btn.title = registryActive
    ? `Открыть ${label}`
    : `${label} — неактивен, включите в реестре`;
  btn.setAttribute(
    "aria-label",
    registryActive ? `Открыть агента ${label}` : `Агент ${label} неактивен`
  );

  const media = document.createElement("div");
  media.className = "app-landing-agent-card-media";

  mountPreviewOrFallback(media, {
    previewUrl: getRegistryAgentPreviewUrl(agent),
    emoji: resolveAwnEmoji(agent),
    fallbackText: getAgentPickerInitials(agent),
    emojiClass: "app-landing-agent-card-emoji",
    initialsClass: "app-landing-agent-card-fallback"
  });

  const body = document.createElement("div");
  body.className = "app-landing-agent-card-body";

  const nameRow = document.createElement("div");
  nameRow.className = "app-landing-agent-card-name-row";

  const nameNode = document.createElement("span");
  nameNode.className = "app-landing-agent-card-name";
  nameNode.textContent = label;
  if (!registryActive) appendDisabledRegistryAgentDot(nameRow);
  nameRow.append(nameNode);

  if (isOrchestrator) {
    const orchestratorBadge = document.createElement("span");
    orchestratorBadge.className = "app-landing-agent-orchestrator-badge";
    orchestratorBadge.textContent = "Оркестратор";
    orchestratorBadge.setAttribute("aria-hidden", "true");
    nameRow.appendChild(orchestratorBadge);
  }

  const idNode = document.createElement("span");
  idNode.className = "app-landing-agent-card-id";
  idNode.textContent = agent.id;

  const pathNode = document.createElement("span");
  pathNode.className = "app-landing-agent-card-path";
  pathNode.textContent = agent.path || "";

  body.append(nameRow, idNode, pathNode);
  btn.append(media, body);
  btn.addEventListener("click", () => {
    if (!registryActive) {
      showToast("Агент выключен — включите в реестре (⚙)", "error");
      return;
    }
    selectAgentOption(agent.id);
  });
  return btn;
}

function isOrchestratorAgent(agent) {
  return agent?.orchestrator === true;
}

function splitLandingOrchestratorAgent(agents) {
  const orchestrator = agents.find(isOrchestratorAgent) || null;
  const rest = orchestrator ? agents.filter((agent) => !isOrchestratorAgent(agent)) : agents;
  return { orchestrator, rest };
}

function renderAppLandingOrchestratorSection(agent) {
  const section = document.createElement("section");
  section.className =
    "app-landing-group-section app-landing-orchestrator-section is-display-only is-readonly";

  const head = document.createElement("header");
  head.className = "app-landing-group-head app-landing-orchestrator-head";

  const titleNode = document.createElement("h3");
  titleNode.className = "app-landing-group-title-badge app-landing-orchestrator-title-badge";
  titleNode.textContent = "Оркестратор";
  head.appendChild(titleNode);

  const grid = document.createElement("div");
  grid.className = "app-landing-group-agents app-landing-orchestrator-agents is-tile-grid";

  const wrap = document.createElement("div");
  wrap.className = "app-landing-group-agent-wrap app-landing-orchestrator-agent-wrap";
  wrap.appendChild(createAppLandingAgentTile(agent));
  grid.appendChild(wrap);

  section.append(head, grid);
  return section;
}

let landingAgentsGroupsCache = [];
let landingAgentsUngroupedCache = {
  id: "__ungrouped__",
  title: "Без группы",
  background: null,
  backgroundUrl: null,
  appearance: "light"
};
let landingGroupBackgroundModalGroupId = null;

const LANDING_UNGROUPED_GROUP_ID = "__ungrouped__";

function mapLandingUngroupedFromApi(ungrouped) {
  return {
    id: LANDING_UNGROUPED_GROUP_ID,
    title: "Без группы",
    background: ungrouped?.background || null,
    backgroundUrl: ungrouped?.backgroundUrl || null,
    appearance: normalizeLandingGroupAppearance(ungrouped?.appearance)
  };
}

function getLandingGroupMeta(groupId) {
  if (groupId === LANDING_UNGROUPED_GROUP_ID) return landingAgentsUngroupedCache;
  return landingAgentsGroupsCache.find((item) => item.id === groupId) || null;
}

function applyLandingGroupMetaBackground(groupId, saved) {
  const target = getLandingGroupMeta(groupId);
  if (!target) return null;
  target.background = saved?.background || null;
  target.backgroundUrl = saved?.backgroundUrl || null;
  return target;
}

function getLandingGroupBackgroundModalGroup() {
  if (!landingGroupBackgroundModalGroupId) return null;
  return getLandingGroupMeta(landingGroupBackgroundModalGroupId);
}

function renderLandingGroupBackgroundModalUi(group = getLandingGroupBackgroundModalGroup()) {
  if (!appLandingGroupBgZoneNode) return;
  const hasImage = Boolean(group?.backgroundUrl);
  appLandingGroupBgImageNode?.classList.toggle("hidden", !hasImage);
  appLandingGroupBgPlaceholderNode?.classList.toggle("hidden", hasImage);
  appLandingGroupBgActionsNode?.classList.toggle("hidden", !hasImage);
  appLandingGroupBgZoneNode.classList.toggle("has-image", hasImage);
  appLandingGroupBgZoneNode.title = hasImage ? "Нажмите, чтобы заменить фон" : "Загрузить фон группы";

  if (hasImage && appLandingGroupBgImageNode) {
    appLandingGroupBgImageNode.onerror = () => {
      renderLandingGroupBackgroundModalUi({ ...(group || {}), backgroundUrl: null });
    };
    appLandingGroupBgImageNode.src = appendCacheBuster(group.backgroundUrl);
  } else {
    appLandingGroupBgImageNode?.removeAttribute("src");
  }
}

function refreshLandingGroupBackgroundBtn(groupId) {
  const section = appLandingGroupsContentNode?.querySelector(
    `.app-landing-group-section[data-group-id="${CSS.escape(String(groupId))}"]`
  );
  const btn = section?.querySelector(".app-landing-group-bg-open-btn");
  const group = getLandingGroupMeta(groupId);
  if (!section || !group) return;

  if (group.backgroundUrl) {
    applyLandingGroupSectionBackground(section, group);
    if (!section.querySelector(".app-landing-group-appearance-btn")) {
      const head = section.querySelector(".app-landing-group-head");
      const bgBtn = head?.querySelector(".app-landing-group-bg-open-btn");
      if (head && bgBtn) {
        head.insertBefore(createLandingGroupAppearanceBtn(group), bgBtn.nextSibling);
      }
    }
  } else {
    applyLandingGroupSectionBackground(section, group);
    section.querySelector(".app-landing-group-appearance-btn")?.remove();
  }

  if (btn) {
    const hasBg = Boolean(group.backgroundUrl);
    btn.textContent = hasBg ? "Фон ✓" : "Фон";
    btn.title = hasBg ? "Изменить фон группы" : "Загрузить фон группы";
  }
}

function openLandingGroupBackgroundModal(group) {
  if (!appLandingGroupBgModalNode || !group?.id) return;
  landingGroupBackgroundModalGroupId = group.id;
  const fresh = getLandingGroupBackgroundModalGroup() || group;
  if (appLandingGroupBgModalTitleNode) {
    const label = fresh.id === LANDING_UNGROUPED_GROUP_ID ? fresh.title : `«${fresh.title || fresh.id}»`;
    appLandingGroupBgModalTitleNode.textContent = `Фон ${fresh.id === LANDING_UNGROUPED_GROUP_ID ? "секции" : "группы"} ${label}`;
  }
  renderLandingGroupBackgroundModalUi(fresh);
  appLandingGroupBgModalNode.classList.remove("hidden");
}

function closeLandingGroupBackgroundModal() {
  landingGroupBackgroundModalGroupId = null;
  appLandingGroupBgModalNode?.classList.add("hidden");
  appLandingGroupBgZoneNode?.classList.remove("is-uploading", "drag-over");
}

async function handleLandingGroupBackgroundUpload(file) {
  const group = getLandingGroupBackgroundModalGroup();
  if (!file || !group?.id) return;
  if (!isAllowedPreviewFile(file)) {
    showToast("Допустимы только JPG, PNG и GIF", "error");
    return;
  }

  appLandingGroupBgZoneNode?.classList.add("is-uploading");
  try {
    const saved = await uploadLandingGroupBackground(group.id, file);
    const target = applyLandingGroupMetaBackground(group.id, saved);
    renderLandingGroupBackgroundModalUi(target || group);
    refreshLandingGroupBackgroundBtn(group.id);
    refreshLandingAgentsListIfVisible();
    showToast("Фон группы сохранён", "success");
  } catch (error) {
    showToast(`Не удалось загрузить фон: ${error.message}`, "error");
  } finally {
    appLandingGroupBgZoneNode?.classList.remove("is-uploading");
  }
}

async function pasteLandingGroupBackgroundFromClipboard() {
  try {
    const file = await readPreviewFileFromClipboard();
    if (!file) {
      showToast("В буфере нет изображения", "error");
      return;
    }
    await handleLandingGroupBackgroundUpload(file);
  } catch (error) {
    const message =
      error?.name === "NotAllowedError"
        ? "Нет доступа к буферу обмена. Разрешите доступ в браузере."
        : error?.message || "Не удалось вставить изображение";
    showToast(message, "error");
  }
}

async function removeLandingGroupBackgroundFromModal() {
  const group = getLandingGroupBackgroundModalGroup();
  if (!group?.id) return;

  appLandingGroupBgZoneNode?.classList.add("is-uploading");
  try {
    await removeLandingGroupBackground(group.id);
    const target = applyLandingGroupMetaBackground(group.id, { background: null, backgroundUrl: null });
    renderLandingGroupBackgroundModalUi(target || group);
    refreshLandingGroupBackgroundBtn(group.id);
    refreshLandingAgentsListIfVisible();
    showToast("Фон удалён", "success");
  } catch (error) {
    showToast(`Не удалось удалить фон: ${error.message}`, "error");
  } finally {
    appLandingGroupBgZoneNode?.classList.remove("is-uploading");
  }
}

function createLandingGroupBackgroundBtn(group) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "app-landing-group-bg-open-btn";
  const hasBg = Boolean(group.backgroundUrl);
  btn.textContent = hasBg ? "Фон ✓" : "Фон";
  btn.title = hasBg ? "Изменить фон группы" : "Загрузить фон группы";
  btn.addEventListener("click", (event) => {
    event.stopPropagation();
    openLandingGroupBackgroundModal(group);
  });
  return btn;
}

function setupLandingGroupBackgroundModal() {
  if (!appLandingGroupBgModalNode || appLandingGroupBgModalNode.dataset.bound === "1") return;
  appLandingGroupBgModalNode.dataset.bound = "1";

  appLandingGroupBgZoneNode?.addEventListener("click", (event) => {
    if (event.target.closest(".preview-action-paste")) return;
    appLandingGroupBgFileInputNode?.click();
  });

  appLandingGroupBgZoneNode?.addEventListener("keydown", (event) => {
    if (event.target.closest(".preview-action-paste")) return;
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      appLandingGroupBgFileInputNode?.click();
    }
  });

  appLandingGroupBgFileInputNode?.addEventListener("change", () => {
    const file = appLandingGroupBgFileInputNode.files?.[0];
    appLandingGroupBgFileInputNode.value = "";
    if (file) void handleLandingGroupBackgroundUpload(file);
  });

  appLandingGroupBgZoneNode?.addEventListener("dragover", (event) => {
    event.preventDefault();
    appLandingGroupBgZoneNode.classList.add("drag-over");
  });
  appLandingGroupBgZoneNode?.addEventListener("dragleave", () => {
    appLandingGroupBgZoneNode.classList.remove("drag-over");
  });
  appLandingGroupBgZoneNode?.addEventListener("drop", (event) => {
    event.preventDefault();
    appLandingGroupBgZoneNode.classList.remove("drag-over");
    const file = event.dataTransfer?.files?.[0];
    if (file) void handleLandingGroupBackgroundUpload(file);
  });

  appLandingGroupBgPasteBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    event.preventDefault();
    void pasteLandingGroupBackgroundFromClipboard();
  });
  appLandingGroupBgPasteActionsBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    event.preventDefault();
    void pasteLandingGroupBackgroundFromClipboard();
  });
  appLandingGroupBgReplaceBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    appLandingGroupBgFileInputNode?.click();
  });
  appLandingGroupBgRemoveBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    void removeLandingGroupBackgroundFromModal();
  });
  appLandingGroupBgCloseBtn?.addEventListener("click", closeLandingGroupBackgroundModal);
  appLandingGroupBgModalNode.addEventListener("click", (event) => {
    if (event.target === appLandingGroupBgModalNode) closeLandingGroupBackgroundModal();
  });
}

function slugifyLandingGroupId(raw, fallbackIndex = 0) {
  const cleaned = String(raw || "")
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}_-]+/gu, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "");
  return cleaned || `group-${fallbackIndex + 1}`;
}

function normalizeLandingGroupAppearance(value) {
  return value === "dark" ? "dark" : "light";
}

function mapLandingGroupFromApi(group) {
  return {
    id: String(group?.id || ""),
    title: String(group?.title || group?.id || "").trim(),
    agentIds: Array.isArray(group?.agentIds) ? [...group.agentIds] : [],
    background: group?.background || null,
    backgroundUrl: group?.backgroundUrl || null,
    appearance: normalizeLandingGroupAppearance(group?.appearance)
  };
}

async function loadLandingAgentsGroups() {
  const response = await fetch("/api/agents/groups");
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || `HTTP ${response.status}`);
  }
  const data = await response.json();
  landingAgentsGroupsCache = Array.isArray(data.groups) ? data.groups.map(mapLandingGroupFromApi) : [];
  landingAgentsUngroupedCache = mapLandingUngroupedFromApi(data.ungrouped);
  return landingAgentsGroupsCache;
}

async function saveLandingAgentsGroups() {
  const response = await fetch("/api/agents/groups", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      groups: landingAgentsGroupsCache,
      ungrouped: {
        background: landingAgentsUngroupedCache.background,
        appearance: landingAgentsUngroupedCache.appearance
      }
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || errorData.details || `HTTP ${response.status}`);
  }
  const data = await response.json();
  landingAgentsGroupsCache = Array.isArray(data.groups) ? data.groups.map(mapLandingGroupFromApi) : [];
  landingAgentsUngroupedCache = mapLandingUngroupedFromApi(data.ungrouped);
  return landingAgentsGroupsCache;
}


async function uploadLandingGroupBackground(groupId, file) {
  if (!groupId) throw new Error("Группа не задана");
  if (!isAllowedPreviewFile(file)) {
    throw new Error("Допустимы только JPG, PNG и GIF");
  }
  const data = await readFileAsBase64(file);
  const response = await fetch("/api/agents/groups/background", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      groupId,
      data,
      fileName: file.name,
      mimeType: file.type
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.details || errorData.error || `HTTP ${response.status}`);
  }
  return response.json();
}

async function removeLandingGroupBackground(groupId) {
  const response = await fetch(`/api/agents/groups/background?groupId=${encodeURIComponent(groupId)}`, {
    method: "DELETE"
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.details || errorData.error || `HTTP ${response.status}`);
  }
  return response.json();
}

function openAppLandingGroupCreateModal() {
  if (!appLandingGroupCreateModalNode) return;
  if (appLandingGroupCreateNameInputNode) appLandingGroupCreateNameInputNode.value = "";
  appLandingGroupCreateModalNode.classList.remove("hidden");
  window.setTimeout(() => appLandingGroupCreateNameInputNode?.focus(), 0);
}

function closeAppLandingGroupCreateModal() {
  appLandingGroupCreateModalNode?.classList.add("hidden");
  if (appLandingGroupCreateSubmitBtn) {
    appLandingGroupCreateSubmitBtn.disabled = false;
    appLandingGroupCreateSubmitBtn.textContent = "Создать";
  }
}

async function submitAppLandingGroupCreate() {
  if (!appLandingGroupCreateSubmitBtn || !appLandingGroupCreateNameInputNode) return;
  const trimmed = String(appLandingGroupCreateNameInputNode.value || "").trim();
  if (!trimmed) {
    showToast("Укажите название группы", "error");
    appLandingGroupCreateNameInputNode.focus();
    return;
  }

  appLandingGroupCreateSubmitBtn.disabled = true;
  appLandingGroupCreateSubmitBtn.textContent = "Создание…";

  try {
    if (!landingAgentsGroupsCache.length) {
      await loadLandingAgentsGroups().catch(() => {});
    }

    const baseId = slugifyLandingGroupId(trimmed, landingAgentsGroupsCache.length);
    let id = baseId;
    let suffix = 2;
    while (landingAgentsGroupsCache.some((group) => group.id === id)) {
      id = `${baseId}-${suffix}`;
      suffix += 1;
    }

    landingAgentsGroupsCache.push({
      id,
      title: trimmed,
      agentIds: [],
      background: null,
      backgroundUrl: null,
      appearance: "light"
    });
    await saveLandingAgentsGroups();
    closeAppLandingGroupCreateModal();
    setLandingAgentsView("settings");
    afterLandingGroupsChanged();
    showToast("Группа создана", "success");
  } catch (error) {
    await loadLandingAgentsGroups().catch(() => {});
    showToast(`Не удалось создать группу: ${error.message}`, "error");
  } finally {
    appLandingGroupCreateSubmitBtn.disabled = false;
    appLandingGroupCreateSubmitBtn.textContent = "Создать";
  }
}

function getAssignedLandingAgentGroupMap(groups = landingAgentsGroupsCache) {
  const assigned = new Map();
  for (const group of groups) {
    for (const agentId of group.agentIds || []) {
      assigned.set(agentId, group.id);
    }
  }
  return assigned;
}

function buildLandingGroupsLayout(agents, groups = landingAgentsGroupsCache) {
  const layoutAgents = agents.filter((agent) => !isOrchestratorAgent(agent));
  const agentById = new Map(layoutAgents.map((agent) => [agent.id, agent]));
  const assigned = getAssignedLandingAgentGroupMap(groups);
  const grouped = groups.map((group) => ({
    ...group,
    agents: (group.agentIds || [])
      .map((agentId) => agentById.get(agentId))
      .filter((agent) => agent && !isOrchestratorAgent(agent))
  }));
  const ungrouped = layoutAgents.filter((agent) => !assigned.has(agent.id));
  return { grouped, ungrouped };
}

function createLandingGroupAddSelect(group) {
  const wrap = document.createElement("div");
  wrap.className = "app-landing-group-add-wrap";

  const select = document.createElement("select");
  select.className = "app-landing-group-add-select";
  select.setAttribute("aria-label", `Добавить агента в группу ${group.title}`);

  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = "+ Добавить агента";
  select.appendChild(placeholder);

  const assigned = getAssignedLandingAgentGroupMap();
  const addable = getAgentsForLandingGrid().filter((agent) => {
    if (isOrchestratorAgent(agent)) return false;
    if ((group.agentIds || []).includes(agent.id)) return false;
    const currentGroupId = assigned.get(agent.id);
    return !currentGroupId;
  });

  for (const agent of addable) {
    const option = document.createElement("option");
    option.value = agent.id;
    option.textContent = agent.name || agent.id;
    select.appendChild(option);
  }

  if (addable.length === 0) {
    select.disabled = true;
    placeholder.textContent = "Нет доступных агентов";
  }

  select.addEventListener("change", () => {
    const agentId = String(select.value || "").trim();
    if (!agentId) return;
    void (async () => {
      const target = landingAgentsGroupsCache.find((item) => item.id === group.id);
      if (!target) return;
      if (!target.agentIds.includes(agentId)) {
        for (const item of landingAgentsGroupsCache) {
          item.agentIds = (item.agentIds || []).filter((id) => id !== agentId);
        }
        target.agentIds.push(agentId);
      }
      try {
        await saveLandingAgentsGroups();
        afterLandingGroupsChanged();
        showToast("Агент добавлен в группу", "success");
      } catch (error) {
        showToast(`Не удалось сохранить группы: ${error.message}`, "error");
        await loadLandingAgentsGroups().catch(() => {});
        afterLandingGroupsChanged();
      }
    })();
  });

  wrap.appendChild(select);
  return wrap;
}

function createLandingGroupAppearanceBtn(group) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "app-landing-group-appearance-btn";

  const syncBtn = (appearance) => {
    const isDark = appearance === "dark";
    btn.textContent = isDark ? "☀ Светлый фон" : "🌙 Тёмный фон";
    btn.title = isDark
      ? "Переключить на светлое оформление (для ярких изображений)"
      : "Переключить на оформление для тёмного фонового изображения";
  };

  syncBtn(normalizeLandingGroupAppearance(group.appearance));

  btn.addEventListener("click", (event) => {
    event.stopPropagation();
    void (async () => {
      const target = getLandingGroupMeta(group.id);
      if (!target) return;
      const next = normalizeLandingGroupAppearance(target.appearance) === "dark" ? "light" : "dark";
      target.appearance = next;
      try {
        await saveLandingAgentsGroups();
        const section = appLandingGroupsContentNode?.querySelector(
          `.app-landing-group-section[data-group-id="${CSS.escape(String(group.id))}"]`
        );
        if (section) applyLandingGroupSectionBackground(section, target);
        syncBtn(next);
        refreshLandingAgentsListIfVisible();
        showToast("Оформление группы сохранено", "success");
      } catch (error) {
        showToast(`Не удалось сохранить оформление: ${error.message}`, "error");
        await loadLandingAgentsGroups().catch(() => {});
        afterLandingGroupsChanged();
      }
    })();
  });

  return btn;
}

function applyLandingGroupSectionBackground(section, group) {
  if (section?.classList.contains("is-display-only")) {
    section.classList.remove(
      "has-background",
      "is-group-appearance-light",
      "is-group-appearance-dark"
    );
    section.style.removeProperty("--group-bg-image");
    return;
  }
  if (!section || !group?.backgroundUrl) {
    section?.classList.remove(
      "has-background",
      "is-group-appearance-light",
      "is-group-appearance-dark"
    );
    section?.style.removeProperty("--group-bg-image");
    return;
  }

  const appearance = normalizeLandingGroupAppearance(group.appearance);
  section.classList.add("has-background");
  section.classList.toggle("is-group-appearance-light", appearance === "light");
  section.classList.toggle("is-group-appearance-dark", appearance === "dark");
  section.style.setProperty("--group-bg-image", `url("${appendCacheBuster(group.backgroundUrl)}")`);
}

function renderAppLandingGroupSection(group, { editable = true } = {}) {
  const isUngrouped = group.id === LANDING_UNGROUPED_GROUP_ID;
  const isReadonly = !editable || group.readonly === true || isUngrouped;
  const section = document.createElement("section");
  section.className = "app-landing-group-section";
  if (isReadonly) section.classList.add("is-readonly");
  else section.classList.add("app-landing-group-section--sortable");
  if (!editable) {
    section.classList.add("is-display-only");
  }
  section.dataset.groupId = group.id;
  applyLandingGroupSectionBackground(section, group);

  const head = document.createElement("header");
  head.className = "app-landing-group-head";

  if (!isReadonly) {
    const sortHandle = document.createElement("button");
    sortHandle.type = "button";
    sortHandle.className = "menu-sort-handle app-landing-group-sort-handle";
    sortHandle.draggable = true;
    sortHandle.title = "Перетащить для сортировки";
    sortHandle.setAttribute("aria-label", "Перетащить для сортировки");
    sortHandle.textContent = "⠿";
    sortHandle.addEventListener("mousedown", (event) => event.stopPropagation());
    head.appendChild(sortHandle);
  }

  if (isReadonly) {
    const titleNode = document.createElement("h3");
    titleNode.className = editable ? "app-landing-group-title-input" : "app-landing-group-title-badge";
    if (editable) {
      titleNode.style.border = "0";
      titleNode.style.background = "transparent";
      titleNode.style.padding = "0";
    }
    titleNode.textContent = group.title || "Без группы";
    head.appendChild(titleNode);
  } else {
    const titleInput = document.createElement("input");
    titleInput.type = "text";
    titleInput.className = "app-landing-group-title-input";
    titleInput.value = group.title || group.id;
    titleInput.setAttribute("aria-label", "Название группы");
    titleInput.addEventListener("change", () => {
      void (async () => {
        const target = landingAgentsGroupsCache.find((item) => item.id === group.id);
        if (!target) return;
        const nextTitle = String(titleInput.value || "").trim();
        if (!nextTitle) {
          titleInput.value = target.title;
          return;
        }
        target.title = nextTitle;
        try {
          await saveLandingAgentsGroups();
          showToast("Группа сохранена", "success");
        } catch (error) {
          showToast(`Не удалось сохранить группы: ${error.message}`, "error");
          titleInput.value = target.title;
        }
      })();
    });
    head.appendChild(titleInput);
  }

  if (editable) {
    const countNode = document.createElement("span");
    countNode.className = "app-landing-group-count";
    countNode.textContent = `${group.agents.length} агентов`;
    head.appendChild(countNode);
  }

  if (!isReadonly) {
    head.appendChild(createLandingGroupAddSelect(group));
  }

  if (editable && (!isReadonly || isUngrouped)) {
    head.appendChild(createLandingGroupBackgroundBtn(group));
    if (group.backgroundUrl) {
      head.appendChild(createLandingGroupAppearanceBtn(group));
    }
  }

  if (!isReadonly) {
    const deleteBtn = document.createElement("button");
    deleteBtn.type = "button";
    deleteBtn.className = "app-landing-group-delete-btn";
    deleteBtn.textContent = "Удалить";
    deleteBtn.addEventListener("click", () => {
      void (async () => {
        landingAgentsGroupsCache = landingAgentsGroupsCache.filter((item) => item.id !== group.id);
        try {
          await removeLandingGroupBackground(group.id).catch(() => {});
          await saveLandingAgentsGroups();
          afterLandingGroupsChanged();
          showToast("Группа удалена", "success");
        } catch (error) {
          showToast(`Не удалось сохранить группы: ${error.message}`, "error");
          await loadLandingAgentsGroups().catch(() => {});
          afterLandingGroupsChanged();
        }
      })();
    });
    head.appendChild(deleteBtn);
  }

  const grid = document.createElement("div");
  grid.className = "app-landing-group-agents";
  if (!isReadonly) grid.dataset.groupId = group.id;
  if (!editable) grid.classList.add("is-tile-grid");

  if (!group.agents.length) {
    const empty = document.createElement("p");
    empty.className = "app-landing-group-empty";
    empty.textContent = isReadonly
      ? "Все агенты распределены по группам."
      : "В группе пока нет агентов — выберите их в списке «Добавить агента».";
    grid.appendChild(empty);
  } else {
    for (const agent of group.agents) {
      const wrap = document.createElement("div");
      wrap.className = "app-landing-group-agent-wrap";
      if (!isReadonly) {
        wrap.classList.add("app-landing-group-agent-wrap--sortable");
        wrap.dataset.agentId = agent.id;

        const sortHandle = document.createElement("button");
        sortHandle.type = "button";
        sortHandle.className = "menu-sort-handle app-landing-group-agent-sort-handle";
        sortHandle.draggable = true;
        sortHandle.title = "Перетащить для сортировки";
        sortHandle.setAttribute("aria-label", "Перетащить для сортировки");
        sortHandle.textContent = "⠿";
        sortHandle.addEventListener("mousedown", (event) => event.stopPropagation());
        wrap.appendChild(sortHandle);
      }

      if (!isReadonly) {
        const removeBtn = document.createElement("button");
        removeBtn.type = "button";
        removeBtn.className = "app-landing-group-agent-remove";
        removeBtn.title = "Убрать из группы";
        removeBtn.setAttribute("aria-label", `Убрать ${agent.name || agent.id} из группы`);
        removeBtn.textContent = "×";
        removeBtn.addEventListener("click", (event) => {
          event.stopPropagation();
          void (async () => {
            const target = landingAgentsGroupsCache.find((item) => item.id === group.id);
            if (!target) return;
            target.agentIds = (target.agentIds || []).filter((id) => id !== agent.id);
            try {
              await saveLandingAgentsGroups();
              afterLandingGroupsChanged();
            } catch (error) {
              showToast(`Не удалось сохранить группы: ${error.message}`, "error");
              await loadLandingAgentsGroups().catch(() => {});
              afterLandingGroupsChanged();
            }
          })();
        });
        wrap.appendChild(removeBtn);
      }

      wrap.appendChild(!editable ? createAppLandingAgentTile(agent) : createAppLandingAgentCard(agent));
      grid.appendChild(wrap);
    }
  }

  section.append(head, grid);
  return section;
}

let landingGroupsSortDragSection = null;
let landingGroupAgentsSortDragWrap = null;

function collectLandingGroupsSortOrder() {
  if (!appLandingGroupsContentNode) return [];
  return Array.from(
    appLandingGroupsContentNode.querySelectorAll(".app-landing-group-section--sortable")
  )
    .map((section) => section.dataset.groupId)
    .filter(Boolean);
}

async function persistLandingGroupsSortOrder() {
  const order = collectLandingGroupsSortOrder();
  if (!order.length) return;

  const byId = new Map(landingAgentsGroupsCache.map((group) => [group.id, group]));
  const reordered = order.map((id) => byId.get(id)).filter(Boolean);
  for (const group of landingAgentsGroupsCache) {
    if (!reordered.some((item) => item.id === group.id)) reordered.push(group);
  }

  landingAgentsGroupsCache = reordered;
  try {
    await saveLandingAgentsGroups();
    showToast("Порядок групп сохранён", "success");
  } catch (error) {
    showToast(`Не удалось сохранить порядок: ${error.message}`, "error");
    await loadLandingAgentsGroups().catch(() => {});
    afterLandingGroupsChanged();
  }
}

function collectLandingGroupAgentsSortOrder(grid) {
  if (!grid) return [];
  return Array.from(grid.querySelectorAll(".app-landing-group-agent-wrap--sortable"))
    .map((wrap) => wrap.dataset.agentId)
    .filter(Boolean);
}

async function persistLandingGroupAgentsSortOrder(groupId, grid) {
  const order = collectLandingGroupAgentsSortOrder(grid);
  if (!groupId || !order.length) return;

  const target = landingAgentsGroupsCache.find((item) => item.id === groupId);
  if (!target) return;

  const existing = Array.isArray(target.agentIds) ? target.agentIds : [];
  const reordered = order.filter((id) => existing.includes(id));
  for (const id of existing) {
    if (!reordered.includes(id)) reordered.push(id);
  }
  target.agentIds = reordered;

  try {
    await saveLandingAgentsGroups();
    showToast("Порядок агентов сохранён", "success");
  } catch (error) {
    showToast(`Не удалось сохранить порядок: ${error.message}`, "error");
    await loadLandingAgentsGroups().catch(() => {});
    afterLandingGroupsChanged();
  }
}

function getLandingGroupAgentsSortGrid(wrap) {
  return wrap?.closest(".app-landing-group-agents[data-group-id]") || null;
}

function shouldInsertLandingGroupAgentBefore(targetWrap, event) {
  const rect = targetWrap.getBoundingClientRect();
  const offsetY = event.clientY - rect.top;
  const offsetX = event.clientX - rect.left;
  return offsetY < rect.height * 0.5 || (offsetY <= rect.height * 0.75 && offsetX < rect.width * 0.5);
}

function setupLandingGroupsSortDragDrop() {
  const container = appLandingGroupsContentNode;
  if (!container || container.dataset.sortBound === "1") return;
  container.dataset.sortBound = "1";

  container.addEventListener("dragstart", (event) => {
    const agentHandle = event.target.closest(".app-landing-group-agent-sort-handle");
    if (agentHandle) {
      const wrap = agentHandle.closest(".app-landing-group-agent-wrap--sortable");
      if (!wrap) {
        event.preventDefault();
        return;
      }
      landingGroupAgentsSortDragWrap = wrap;
      wrap.classList.add("is-dragging");
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", wrap.dataset.agentId || "");
      return;
    }

    const handle = event.target.closest(".app-landing-group-sort-handle");
    if (!handle) return;
    const section = handle.closest(".app-landing-group-section--sortable");
    if (!section) {
      event.preventDefault();
      return;
    }
    landingGroupsSortDragSection = section;
    section.classList.add("is-dragging");
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("text/plain", section.dataset.groupId || "");
  });

  container.addEventListener("dragover", (event) => {
    if (landingGroupAgentsSortDragWrap) {
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      const targetWrap = event.target.closest(".app-landing-group-agent-wrap--sortable");
      if (!targetWrap || targetWrap === landingGroupAgentsSortDragWrap) return;

      const dragGrid = getLandingGroupAgentsSortGrid(landingGroupAgentsSortDragWrap);
      const targetGrid = getLandingGroupAgentsSortGrid(targetWrap);
      if (!dragGrid || dragGrid !== targetGrid) return;

      const insertBefore = shouldInsertLandingGroupAgentBefore(targetWrap, event);
      if (insertBefore) dragGrid.insertBefore(landingGroupAgentsSortDragWrap, targetWrap);
      else dragGrid.insertBefore(landingGroupAgentsSortDragWrap, targetWrap.nextSibling);
      return;
    }

    if (!landingGroupsSortDragSection) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    const targetSection = event.target.closest(".app-landing-group-section--sortable");
    if (!targetSection || targetSection === landingGroupsSortDragSection) return;

    const rect = targetSection.getBoundingClientRect();
    const insertBefore = event.clientY < rect.top + rect.height / 2;
    if (insertBefore) container.insertBefore(landingGroupsSortDragSection, targetSection);
    else container.insertBefore(landingGroupsSortDragSection, targetSection.nextSibling);
  });

  container.addEventListener("drop", (event) => {
    event.preventDefault();
    if (landingGroupAgentsSortDragWrap) {
      const grid = getLandingGroupAgentsSortGrid(landingGroupAgentsSortDragWrap);
      const groupId = grid?.dataset.groupId || "";
      landingGroupAgentsSortDragWrap.classList.remove("is-dragging");
      landingGroupAgentsSortDragWrap = null;
      if (grid && groupId) void persistLandingGroupAgentsSortOrder(groupId, grid);
      return;
    }

    if (!landingGroupsSortDragSection) return;
    landingGroupsSortDragSection.classList.remove("is-dragging");
    landingGroupsSortDragSection = null;
    void persistLandingGroupsSortOrder();
  });

  container.addEventListener("dragend", () => {
    if (landingGroupAgentsSortDragWrap) {
      landingGroupAgentsSortDragWrap.classList.remove("is-dragging");
      landingGroupAgentsSortDragWrap = null;
    }
    if (landingGroupsSortDragSection) {
      landingGroupsSortDragSection.classList.remove("is-dragging");
      landingGroupsSortDragSection = null;
    }
  });
}

async function renderAppLandingGroups() {
  if (!appLandingGroupsContentNode) return;

  appLandingGroupsContentNode.replaceChildren();
  const loading = document.createElement("p");
  loading.className = "app-landing-groups-loading";
  loading.textContent = "Загрузка групп…";
  appLandingGroupsContentNode.appendChild(loading);

  try {
    await loadLandingAgentsGroups();
    appLandingGroupsContentNode.replaceChildren();

    const agents = getAgentsForLandingGrid();
    const { grouped, ungrouped } = buildLandingGroupsLayout(agents, landingAgentsGroupsCache);

    if (!grouped.length) {
      const empty = document.createElement("p");
      empty.className = "app-landing-group-empty";
      empty.textContent = "Групп пока нет. Нажмите «Создать группу», чтобы разложить агентов по категориям.";
      appLandingGroupsContentNode.appendChild(empty);
    } else {
      for (const group of grouped) {
        appLandingGroupsContentNode.appendChild(renderAppLandingGroupSection(group, { editable: true }));
      }
    }

    if (ungrouped.length || landingAgentsUngroupedCache.backgroundUrl) {
      appLandingGroupsContentNode.appendChild(
        renderAppLandingGroupSection(
          {
            ...landingAgentsUngroupedCache,
            agents: ungrouped,
            agentIds: ungrouped.map((agent) => agent.id),
            readonly: true
          },
          { editable: true }
        )
      );
    }

    if (landingGroupBackgroundModalGroupId) {
      const modalGroup = getLandingGroupMeta(landingGroupBackgroundModalGroupId);
      if (modalGroup) {
        if (appLandingGroupBgModalTitleNode) {
          const label =
            modalGroup.id === LANDING_UNGROUPED_GROUP_ID
              ? modalGroup.title
              : `«${modalGroup.title || modalGroup.id}»`;
          appLandingGroupBgModalTitleNode.textContent = `Фон ${
            modalGroup.id === LANDING_UNGROUPED_GROUP_ID ? "секции" : "группы"
          } ${label}`;
        }
        renderLandingGroupBackgroundModalUi(modalGroup);
      } else {
        closeLandingGroupBackgroundModal();
      }
    }
  } catch (error) {
    appLandingGroupsContentNode.replaceChildren();
    const errorNode = document.createElement("p");
    errorNode.className = "app-landing-groups-error";
    errorNode.textContent = `Не удалось загрузить группы: ${error.message}`;
    appLandingGroupsContentNode.appendChild(errorNode);
  }
}

function isAgentsSettingsViewActive() {
  return getLandingAgentsView() === "settings";
}

function openAgentsSettingsView() {
  if (getLandingAgentsView() === "settings") {
    setLandingAgentsView("hub");
  } else {
    setLandingAgentsView("settings");
  }
}

function refreshLandingAgentsListIfVisible() {
  const view = getLandingAgentsView();
  if (view === "hub" || view === "grid" || view === "orbit" || view === "flow") {
    void renderAppLandingAgents();
  }
}

function afterLandingGroupsChanged() {
  if (isAgentsSettingsViewActive()) {
    void renderAppLandingGroups();
  }
  refreshLandingAgentsListIfVisible();
  renderAgentSelect();
}

function hashAgentIdForOrbit(id) {
  let hash = 2166136261;
  for (let i = 0; i < id.length; i += 1) {
    hash ^= id.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function getLandingAgentsView() {
  try {
    const saved = localStorage.getItem(LANDING_AGENTS_VIEW_KEY);
    if (saved === "hub") return "hub";
    if (saved === "settings" || saved === "groups") return "settings";
    if (saved === "grid") return "grid";
    if (saved === "flow") return "flow";
    if (saved === "orbit") return "orbit";
  } catch {
    // ignore
  }
  return "orbit";
}

function setLandingAgentsView(view) {
  const next =
    view === "settings" || view === "groups"
      ? "settings"
      : view === "grid"
        ? "grid"
        : view === "hub"
          ? "hub"
          : view === "flow"
            ? "flow"
            : "orbit";
  localStorage.setItem(LANDING_AGENTS_VIEW_KEY, next);
  syncLandingAgentsViewUi();
}

function getOrbitBubbleLayout(index, total, agentId) {
  const hash = hashAgentIdForOrbit(String(agentId || index));
  const golden = 2.399963229728653;
  const t = index + 1;
  const radius = 24 + (t / Math.max(total, 1)) * 24 + (hash % 12);
  const angle = t * golden + (hash % 360) * (Math.PI / 180) * 0.08;
  const x = 50 + Math.cos(angle) * radius * (0.92 + (hash % 7) * 0.015);
  const y = 48 + Math.sin(angle) * radius * 0.72;
  return {
    x: Math.min(90, Math.max(8, x)),
    y: Math.min(88, Math.max(10, y)),
    size: 58 + (hash % 28),
    duration: 7 + (hash % 6),
    delay: ((hash % 50) / 10).toFixed(1),
    floatX: 10 + (hash % 18),
    floatY: 12 + (hash % 16)
  };
}

function syncLandingAgentsViewUi() {
  const view = getLandingAgentsView();
  const isHub = view === "hub";
  const isOrbit = view === "orbit";
  const isSettings = view === "settings";
  const isGrid = view === "grid";
  const isFlow = view === "flow";
  const isCanvasView = isHub || isOrbit || isFlow;

  appLandingPaneNode?.classList.toggle("is-screensaver", isCanvasView);
  appLandingPaneNode?.classList.toggle("app-landing-pane--hub", isHub);
  appLandingPaneNode?.classList.toggle("app-landing-pane--grid", isGrid);
  appLandingPaneNode?.classList.toggle("app-landing-pane--flow", isFlow);

  appLandingHubNode?.classList.toggle("hidden", !isHub);
  appLandingHubNode?.setAttribute("aria-hidden", isHub ? "false" : "true");
  appLandingOrbitNode?.classList.toggle("hidden", !isOrbit);
  appLandingOrbitNode?.setAttribute("aria-hidden", isOrbit ? "false" : "true");
  appLandingFlowNode?.classList.toggle("hidden", !isFlow);
  appLandingFlowNode?.setAttribute("aria-hidden", isFlow ? "false" : "true");

  appLandingAgentsNode?.classList.toggle("hidden", !isGrid);
  appLandingFocusNode?.classList.add("hidden");
  appLandingAttentionNode?.classList.toggle("hidden", !(isHub || isOrbit || isFlow));

  appLandingGroupsNode?.classList.toggle("hidden", !isSettings);
  appLandingGroupsNode?.setAttribute("aria-hidden", isSettings ? "false" : "true");

  if (appLandingSettingsBtn) {
    appLandingSettingsBtn.textContent = isSettings ? "← Назад" : "Группы";
  }

  appLandingViewGridBtn?.classList.toggle("is-active", isGrid);
  appLandingViewOrbitBtn?.classList.toggle("is-active", isOrbit);
  appLandingViewHubBtn?.classList.toggle("is-active", isHub);
  appLandingViewFlowBtn?.classList.toggle("is-active", isFlow);
  appLandingViewGridBtn?.setAttribute("aria-selected", isGrid ? "true" : "false");
  appLandingViewOrbitBtn?.setAttribute("aria-selected", isOrbit ? "true" : "false");
  appLandingViewHubBtn?.setAttribute("aria-selected", isHub ? "true" : "false");
  appLandingViewFlowBtn?.setAttribute("aria-selected", isFlow ? "true" : "false");
  appLandingSettingsBtn?.classList.toggle("is-active", isSettings);
  appLandingFocusFiltersBtnNode?.classList.toggle("hidden", true);

  if (isSettings) {
    void renderAppLandingGroups();
  }
  if (isHub) {
    renderAppLandingHub(getProcessedLandingFocusItems());
  }
  if (isOrbit) {
    renderAppLandingOrbit();
  }
  if (isGrid) {
    renderAppLandingList(getProcessedLandingFocusItems());
  }
  if (isFlow) {
    renderAppLandingFlow(getProcessedLandingFocusItems());
  }
  if (isHub || isOrbit || isFlow) {
    renderAppLandingAttention(buildMockAgentAttentionShares(getAgentsForLandingGrid()));
  } else {
    appLandingAttentionNode?.classList.add("hidden");
  }

  syncLandingBgUi();
}

const HUB_FOCUS_TWIG_LIMIT = 8;

function groupFocusItemsByAgent(items = []) {
  const byAgent = new Map();
  for (const item of items) {
    const agentId = String(item?.agentId || "").trim();
    if (!agentId) continue;
    if (!byAgent.has(agentId)) byAgent.set(agentId, []);
    byAgent.get(agentId).push(item);
  }
  return byAgent;
}

function createAppLandingHubTwig(focusItem) {
  const agent =
    agentsCache.find((entry) => entry.id === focusItem.agentId) || {
      id: focusItem.agentId,
      name: focusItem.agentName
    };
  const registryActive = focusItem.agentActive !== false && isAgentRegistryActive(agent);
  const label = focusItem.name || getLabelFromPath(focusItem.nodePath) || focusItem.agentName || "Тема";
  const nodePath = String(focusItem.nodePath || "").trim();
  const status = getFocusPropDisplayValue(focusItem, "awn-status");

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "app-landing-hub-twig";
  if (nodePath) btn.dataset.focusPath = nodePath;
  if (isFocusItemActive(focusItem)) btn.classList.add("is-active");
  if (!registryActive) btn.classList.add("is-registry-off");
  btn.title = nodePath || label;
  btn.setAttribute(
    "aria-label",
    registryActive ? `Открыть ${label}` : `${label} — агент неактивен`
  );

  const dot = document.createElement("span");
  dot.className = "app-landing-hub-twig-dot";
  dot.setAttribute("aria-hidden", "true");

  const text = document.createElement("span");
  text.className = "app-landing-hub-twig-label";
  text.textContent = label;

  btn.append(dot, text);
  if (status) {
    const statusNode = document.createElement("span");
    statusNode.className = "app-landing-hub-twig-status";
    statusNode.textContent = status;
    btn.appendChild(statusNode);
  }

  btn.addEventListener("click", (event) => {
    event.stopPropagation();
    void openFocusItem(focusItem);
  });
  return btn;
}

function createAppLandingHubRow(agent, focusItems = [], options = {}) {
  const isList = options.variant === "list";
  const registryActive = isAgentRegistryActive(agent);
  const isOrchestrator = agent.orchestrator === true;
  const label = agent.name || agent.id;

  const row = document.createElement("article");
  row.className = "app-landing-hub-row";
  if (isList) row.classList.add("app-landing-hub-row--list");
  if (!registryActive) row.classList.add("is-registry-off");
  if (isOrchestrator) row.classList.add("is-orchestrator");
  row.setAttribute("role", "listitem");
  row.dataset.agentId = agent.id;

  const agentBtn = document.createElement("button");
  agentBtn.type = "button";
  agentBtn.className = "app-landing-hub-agent";
  agentBtn.title = registryActive
    ? `Открыть workspace ${label}`
    : `${label} — неактивен, включите в реестре`;

  const node = document.createElement("span");
  node.className = "app-landing-hub-node";
  mountPreviewOrFallback(node, {
    previewUrl: getRegistryAgentPreviewUrl(agent),
    emoji: resolveAwnEmoji(agent),
    fallbackText: getAgentPickerInitials(agent),
    emojiClass: "app-landing-hub-node-emoji",
    initialsClass: "app-landing-hub-node-initials"
  });

  const copy = document.createElement("span");
  copy.className = "app-landing-hub-agent-copy";
  const nameNode = document.createElement("span");
  nameNode.className = "app-landing-hub-agent-name";
  nameNode.textContent = label;
  const hintNode = document.createElement("span");
  hintNode.className = "app-landing-hub-agent-hint";
  hintNode.textContent = isOrchestrator ? "Оркестратор" : "Workspace";
  copy.append(nameNode, hintNode);
  agentBtn.append(node, copy);
  agentBtn.addEventListener("click", () => {
    if (!registryActive) {
      showToast("Агент выключен — включите в реестре (⚙)", "error");
      return;
    }
    selectAgentOption(agent.id);
  });

  const branches = document.createElement("div");
  branches.className = "app-landing-hub-branches";

  if (focusItems.length) {
    const twigs = document.createElement("div");
    twigs.className = `app-landing-hub-twigs${isList ? " app-landing-hub-twigs--list" : ""}`;
    twigs.setAttribute("role", "list");
    twigs.setAttribute("aria-label", `Темы фокуса — ${label}`);

    const limit = isList ? 16 : HUB_FOCUS_TWIG_LIMIT;
    const shown = focusItems.slice(0, limit);
    for (const focusItem of shown) {
      twigs.appendChild(createAppLandingHubTwig(focusItem));
    }

    const overflow = focusItems.length - shown.length;
    if (overflow > 0) {
      const more = document.createElement("span");
      more.className = "app-landing-hub-more";
      more.textContent = `+${overflow}`;
      more.title = `Ещё ${overflow} тем у ${label}`;
      twigs.appendChild(more);
    }

    if (!isList) {
      const stem = document.createElement("span");
      stem.className = "app-landing-hub-stem";
      stem.setAttribute("aria-hidden", "true");
      branches.append(stem, twigs);
    } else {
      branches.appendChild(twigs);
    }
  } else {
    const empty = document.createElement("span");
    empty.className = "app-landing-hub-empty";
    empty.textContent = "Нет тем фокуса";
    branches.appendChild(empty);
  }

  row.append(agentBtn, branches);
  return row;
}

function appendAppLandingHubAgents(container, agents, focusByAgent, options = {}) {
  for (const agent of agents) {
    container.appendChild(createAppLandingHubRow(agent, focusByAgent.get(agent.id) || [], options));
  }
}

function renderAppLandingHub(focusItems = getProcessedLandingFocusItems()) {
  if (!appLandingHubNode) return;
  if (getLandingAgentsView() !== "hub") return;

  appLandingHubNode.replaceChildren();
  const focusByAgent = groupFocusItemsByAgent(focusItems);
  const agents = getAgentsForLandingGrid();

  if (!agents.length) {
    const empty = document.createElement("p");
    empty.className = "app-landing-hub-page-empty";
    empty.textContent = "Нет агентов. Нажмите «+ Агент» или откройте реестр (⚙).";
    appLandingHubNode.appendChild(empty);
    syncFocusPanelActiveState();
    return;
  }

  const { orchestrator, rest } = splitLandingOrchestratorAgent(agents);

  if (orchestrator) {
    const orchSection = document.createElement("section");
    orchSection.className = "app-landing-hub-section app-landing-hub-section--orchestrator";
    orchSection.appendChild(createAppLandingHubRow(orchestrator, focusByAgent.get(orchestrator.id) || []));
    appLandingHubNode.appendChild(orchSection);
  }

  if (landingAgentsGroupsCache.length > 0) {
    const { grouped, ungrouped } = buildLandingGroupsLayout(rest, landingAgentsGroupsCache);

    for (const group of grouped) {
      const section = document.createElement("section");
      section.className = "app-landing-hub-section";
      const title = document.createElement("h3");
      title.className = "app-landing-hub-section-title";
      title.textContent = group.name || "Группа";
      section.appendChild(title);
      appendAppLandingHubAgents(section, group.agents, focusByAgent);
      appLandingHubNode.appendChild(section);
    }

    if (ungrouped.length) {
      const section = document.createElement("section");
      section.className = "app-landing-hub-section";
      const title = document.createElement("h3");
      title.className = "app-landing-hub-section-title";
      title.textContent = landingAgentsUngroupedCache.name || "Без группы";
      section.appendChild(title);
      appendAppLandingHubAgents(section, ungrouped, focusByAgent);
      appLandingHubNode.appendChild(section);
    }
  } else {
    appendAppLandingHubAgents(appLandingHubNode, rest, focusByAgent);
  }

  syncFocusPanelActiveState();
}

function renderAppLandingList(focusItems = getProcessedLandingFocusItems()) {
  if (!appLandingAgentsNode) return;
  if (getLandingAgentsView() !== "grid") return;

  appLandingAgentsNode.replaceChildren();
  appLandingAgentsNode.className = "app-landing-agents app-landing-agents--list app-landing-grid-panel";
  const focusByAgent = groupFocusItemsByAgent(focusItems);
  const agents = getAgentsForLandingGrid();

  if (!agents.length) {
    const empty = document.createElement("p");
    empty.className = "app-landing-list-empty";
    empty.textContent = "Нет агентов. Нажмите «+» или откройте реестр (⚙).";
    appLandingAgentsNode.appendChild(empty);
    return;
  }

  const { orchestrator, rest } = splitLandingOrchestratorAgent(agents);
  if (orchestrator) {
    appLandingAgentsNode.appendChild(
      createAppLandingHubRow(orchestrator, focusByAgent.get(orchestrator.id) || [], { variant: "list" })
    );
  }
  appendAppLandingHubAgents(appLandingAgentsNode, rest, focusByAgent, { variant: "list" });
  syncFocusPanelActiveState();
}

function createAppLandingFlowCard(focusItem) {
  const agent =
    agentsCache.find((entry) => entry.id === focusItem.agentId) || {
      id: focusItem.agentId,
      name: focusItem.agentName,
      path: focusItem.agentPath
    };
  const registryActive = focusItem.agentActive !== false && isAgentRegistryActive(agent);
  const label = focusItem.name || getLabelFromPath(focusItem.nodePath) || focusItem.agentName || "Тема";
  const agentLabel = agent.name || focusItem.agentName || focusItem.agentId;
  const nodePath = String(focusItem.nodePath || "").trim();
  const awnProps = focusItem.awnProps && typeof focusItem.awnProps === "object" ? focusItem.awnProps : {};
  const status = getFocusPropDisplayValue(focusItem, "awn-status");
  const typeLabel = getFocusPropDisplayValue(focusItem, "awn-type") || getFocusItemType(focusItem);

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "app-landing-flow-card";
  btn.setAttribute("role", "listitem");
  btn.dataset.agentId = focusItem.agentId;
  if (nodePath) btn.dataset.focusPath = nodePath;
  if (isFocusItemActive(focusItem)) btn.classList.add("is-active");
  if (!registryActive) btn.classList.add("is-registry-off");
  btn.title = registryActive ? `Открыть ${label}` : `${label} — агент неактивен`;
  btn.setAttribute(
    "aria-label",
    registryActive ? `Открыть ${label}` : `${label} — агент неактивен`
  );

  const media = document.createElement("span");
  media.className = "app-landing-flow-card-media";
  const nodeEmoji = resolveAwnEmoji(awnProps);
  const agentEmoji = resolveAwnEmoji(agent.awnProps);
  const previewUrl = resolveFocusPreviewUrl(focusItem.nodePreviewUrl, focusItem.agentId);
  mountPreviewOrFallback(media, {
    previewUrl,
    emoji: nodeEmoji || agentEmoji,
    fallbackText: getAgentPickerInitials({ name: label, id: focusItem.agentId }),
    emojiClass: "app-landing-flow-card-emoji",
    initialsClass: "app-landing-flow-card-fallback",
    nodePath,
    iconClass: "node-cover-icon--in-flow-card"
  });

  const body = document.createElement("span");
  body.className = "app-landing-flow-card-body";

  const titleNode = document.createElement("span");
  titleNode.className = "app-landing-flow-card-title";
  titleNode.textContent = label;

  const meta = document.createElement("span");
  meta.className = "app-landing-flow-card-meta";

  const agentChip = document.createElement("span");
  agentChip.className = "app-landing-flow-card-agent";
  const agentAvatar = document.createElement("span");
  agentAvatar.className = "app-landing-flow-card-agent-avatar";
  mountPreviewOrFallback(agentAvatar, {
    previewUrl: getRegistryAgentPreviewUrl(agent),
    emoji: resolveAwnEmoji(agent),
    fallbackText: getAgentPickerInitials(agent),
    emojiClass: "app-landing-flow-card-agent-emoji",
    initialsClass: "app-landing-flow-card-agent-initials"
  });
  const agentName = document.createElement("span");
  agentName.className = "app-landing-flow-card-agent-name";
  agentName.textContent = agentLabel;
  agentChip.append(agentAvatar, agentName);

  meta.appendChild(agentChip);

  if (status || typeLabel) {
    const tags = document.createElement("span");
    tags.className = "app-landing-flow-card-tags";
    if (status) {
      const statusTag = document.createElement("span");
      statusTag.className = "app-landing-flow-card-tag app-landing-flow-card-tag--status";
      statusTag.textContent = status;
      tags.appendChild(statusTag);
    }
    if (typeLabel) {
      const typeTag = document.createElement("span");
      typeTag.className = "app-landing-flow-card-tag app-landing-flow-card-tag--type";
      typeTag.textContent = typeLabel;
      tags.appendChild(typeTag);
    }
    meta.appendChild(tags);
  }

  body.append(titleNode, meta);
  btn.append(media, body);
  btn.addEventListener("click", () => {
    void openFocusItem(focusItem);
  });
  return btn;
}

function renderAppLandingFlow(focusItems = getProcessedLandingFocusItems()) {
  if (!appLandingFlowGridNode) return;
  if (getLandingAgentsView() !== "flow") return;

  appLandingFlowGridNode.replaceChildren();
  const agents = getAgentsForLandingGrid();

  if (!agents.length) {
    const empty = document.createElement("p");
    empty.className = "app-landing-flow-empty";
    empty.textContent = "Нет агентов. Нажмите «+» или откройте реестр (⚙).";
    appLandingFlowGridNode.appendChild(empty);
    syncFocusPanelActiveState();
    return;
  }

  if (!focusItems.length) {
    const empty = document.createElement("div");
    empty.className = "app-landing-flow-empty-wrap";

    const lead = document.createElement("p");
    lead.className = "app-landing-flow-empty";
    lead.textContent = "Пока нет тем в фокусе.";

    const hint = document.createElement("p");
    hint.className = "app-landing-flow-empty-hint";
    hint.textContent = "Отметьте тему звёздочкой (awn-main: true) — она появится здесь и на других видах.";

    empty.append(lead, hint);
    appLandingFlowGridNode.appendChild(empty);
    syncFocusPanelActiveState();
    return;
  }

  for (const focusItem of focusItems) {
    appLandingFlowGridNode.appendChild(createAppLandingFlowCard(focusItem));
  }
  syncFocusPanelActiveState();
}

const ORBIT_LINK_CENTER = { x: 50, y: 48 };

function createAppLandingOrbitBubble(agent, index, total, share) {
  const registryActive = isAgentRegistryActive(agent);
  const isOrchestrator = agent.orchestrator === true;
  const label = agent.name || agent.id;
  const layout = getOrbitBubbleLayout(index, total, agent.id);

  const item = document.createElement("div");
  item.className = "app-landing-orbit-item";
  if (isOrchestrator) item.classList.add("app-landing-orbit-item--orchestrator");
  item.setAttribute("role", "listitem");
  item.dataset.agentId = agent.id;
  item.style.setProperty("--orbit-x", `${layout.x}%`);
  item.style.setProperty("--orbit-y", `${layout.y}%`);
  item.style.setProperty("--orbit-size", `${layout.size}px`);
  item.style.setProperty("--orbit-duration", `${layout.duration}s`);
  item.style.setProperty("--orbit-delay", `${layout.delay}s`);
  item.style.setProperty("--orbit-float-x", `${layout.floatX}px`);
  item.style.setProperty("--orbit-float-y", `${layout.floatY}px`);
  if (share?.color) item.style.setProperty("--orbit-attention-color", share.color);

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = `app-landing-orbit-bubble${registryActive ? " is-active" : " is-inactive"}${
    isOrchestrator ? " is-orchestrator" : ""
  }`;
  btn.title = registryActive
    ? isOrchestrator
      ? `Оркестратор · ${label}`
      : `Открыть ${label}`
    : `${label} — неактивен`;
  btn.setAttribute(
    "aria-label",
    registryActive
      ? isOrchestrator
        ? `Оркестратор ${label}`
        : `Открыть агента ${label}`
      : `Агент ${label} неактивен`
  );

  const avatar = document.createElement("span");
  avatar.className = "app-landing-orbit-bubble-avatar";

  mountPreviewOrFallback(avatar, {
    previewUrl: getRegistryAgentPreviewUrl(agent),
    emoji: resolveAwnEmoji(agent),
    fallbackText: getAgentPickerInitials(agent),
    emojiClass: "app-landing-orbit-bubble-emoji",
    initialsClass: "app-landing-orbit-bubble-initials"
  });

  btn.append(avatar);

  if (isOrchestrator) {
    const badge = document.createElement("span");
    badge.className = "app-landing-orbit-orchestrator-badge";
    badge.textContent = "Оркестратор";
    badge.setAttribute("aria-hidden", "true");
    btn.appendChild(badge);
  }

  const nameNode = document.createElement("span");
  nameNode.className = "app-landing-orbit-bubble-label";
  if (isOrchestrator) nameNode.classList.add("is-orchestrator");
  nameNode.textContent = label;

  btn.addEventListener("click", () => {
    if (!registryActive) {
      showToast("Агент выключен — включите в реестре (⚙)", "error");
      return;
    }
    selectAgentOption(agent.id);
  });

  const children = [btn, nameNode];

  if (share) {
    const attentionWrap = document.createElement("div");
    attentionWrap.className = "app-landing-orbit-bubble-attention";
    attentionWrap.setAttribute("aria-hidden", "true");

    const track = document.createElement("div");
    track.className = "app-landing-orbit-attention-track app-landing-orbit-bubble-attention-track";

    const fill = document.createElement("span");
    fill.className = "app-landing-orbit-attention-fill";
    fill.style.width = `${share.percent}%`;
    fill.style.backgroundColor = share.color;

    track.appendChild(fill);
    attentionWrap.appendChild(track);
    children.push(attentionWrap);
  }

  item.append(...children);
  bindOrbitAttentionHover(item, agent.id);
  bindOrbitItemFocusHover(item, agent, index);
  return item;
}

function renderAppLandingOrbitLinks(agents) {
  if (!appLandingOrbitLinksNode) return;
  appLandingOrbitLinksNode.replaceChildren();

  if (!Array.isArray(agents) || agents.length === 0) return;

  const svgNs = "http://www.w3.org/2000/svg";
  for (let index = 0; index < agents.length; index += 1) {
    const agent = agents[index];
    const layout = getOrbitBubbleLayout(index, agents.length, agent.id);
    const registryActive = isAgentRegistryActive(agent);

    const line = document.createElementNS(svgNs, "line");
    line.setAttribute("x1", String(ORBIT_LINK_CENTER.x));
    line.setAttribute("y1", String(ORBIT_LINK_CENTER.y));
    line.setAttribute("x2", String(layout.x));
    line.setAttribute("y2", String(layout.y));
    line.classList.add("app-landing-orbit-link");
    if (registryActive) line.classList.add("is-active");
    line.style.animationDelay = `${layout.delay}s`;
    appLandingOrbitLinksNode.appendChild(line);
  }
}

function renderAppLandingOrbit() {
  if (!appLandingOrbitBubblesNode) return;
  appLandingOrbitBubblesNode.replaceChildren();
  clearOrbitAttentionHighlight();

  const agents = getAgentsForLandingGrid();
  if (agents.length === 0) {
    const empty = document.createElement("p");
    empty.className = "app-landing-orbit-empty";
    empty.textContent = "Нет агентов. Нажмите «+» или откройте реестр.";
    appLandingOrbitBubblesNode.appendChild(empty);
    renderAppLandingAttention([]);
    return;
  }

  const shares = buildMockAgentAttentionShares(agents);
  const shareByAgentId = new Map(shares.map((share) => [share.agent.id, share]));

  agents.forEach((agent, index) => {
    appLandingOrbitBubblesNode.appendChild(
      createAppLandingOrbitBubble(agent, index, agents.length, shareByAgentId.get(agent.id))
    );
  });

  renderAppLandingOrbitLinks(agents);
  renderAppLandingAttention(buildMockAgentAttentionShares(agents));
  setLandingOrbitFocusCache(getProcessedLandingFocusItems());
}

const ORBIT_FOCUS_TWIG_LIMIT = 8;
let landingOrbitFocusByAgent = new Map();
let landingOrbitFocusHoverAgentId = null;
let landingOrbitFocusHideTimer = null;

function setLandingOrbitFocusCache(items = []) {
  landingOrbitFocusByAgent = groupFocusItemsByAgent(items);
  if (landingOrbitFocusHoverAgentId) {
    const agents = getAgentsForLandingGrid();
    const agentIndex = agents.findIndex((agent) => agent.id === landingOrbitFocusHoverAgentId);
    if (agentIndex >= 0) {
      paintOrbitAgentFocusGraph(landingOrbitFocusHoverAgentId, agentIndex);
      return;
    }
  }
  clearOrbitAgentFocusDisplay();
}

function clearOrbitAgentFocusDisplay() {
  landingOrbitFocusHoverAgentId = null;
  appLandingOrbitTwigsNode?.replaceChildren();
  appLandingOrbitFocusLinksNode?.replaceChildren();
  appLandingOrbitTwigsNode?.classList.remove("is-visible");
  appLandingOrbitFocusLinksNode?.classList.remove("is-visible");
}

function cancelOrbitAgentFocusHide() {
  if (landingOrbitFocusHideTimer) {
    clearTimeout(landingOrbitFocusHideTimer);
    landingOrbitFocusHideTimer = null;
  }
}

function scheduleOrbitAgentFocusHide() {
  cancelOrbitAgentFocusHide();
  landingOrbitFocusHideTimer = window.setTimeout(() => {
    clearOrbitAgentFocusDisplay();
  }, 160);
}

function getOrbitGraphTwigLayout(focusIndex, focusTotal, agentLayout, focusItem) {
  const hash = hashAgentIdForOrbit(String(focusItem?.nodePath || focusItem?.agentId || focusIndex));
  const count = Math.max(focusTotal, 1);
  const baseAngle = (hash % 360) * (Math.PI / 180);
  const ring = Math.floor(focusIndex / 6);
  const slot = focusIndex % 6;
  const angle = baseAngle + (slot / 6) * Math.PI * 2 + ring * 0.45;
  const dist = 11 + ring * 5 + (hash % 4);
  return {
    x: Math.min(96, Math.max(4, agentLayout.x + Math.cos(angle) * dist)),
    y: Math.min(92, Math.max(6, agentLayout.y + Math.sin(angle) * dist * 0.78))
  };
}

function paintOrbitAgentFocusGraph(agentId, agentIndex) {
  if (!appLandingOrbitTwigsNode || !appLandingOrbitFocusLinksNode) return;
  if (getLandingAgentsView() !== "orbit") return;

  const agentFocusItems = landingOrbitFocusByAgent.get(agentId) || [];
  landingOrbitFocusHoverAgentId = agentId;
  appLandingOrbitTwigsNode.replaceChildren();
  appLandingOrbitFocusLinksNode.replaceChildren();

  if (!agentFocusItems.length) {
    appLandingOrbitTwigsNode.classList.remove("is-visible");
    appLandingOrbitFocusLinksNode.classList.remove("is-visible");
    return;
  }

  const agents = getAgentsForLandingGrid();
  const agent = agents.find((entry) => entry.id === agentId);
  const agentLayout = getOrbitBubbleLayout(agentIndex, agents.length, agentId);
  const shown = agentFocusItems.slice(0, ORBIT_FOCUS_TWIG_LIMIT);
  const svgNs = "http://www.w3.org/2000/svg";

  shown.forEach((focusItem, focusIndex) => {
    const twigLayout = getOrbitGraphTwigLayout(focusIndex, shown.length, agentLayout, focusItem);
    const label = focusItem.name || getLabelFromPath(focusItem.nodePath) || focusItem.agentName || "Тема";
    const nodePath = String(focusItem.nodePath || "").trim();

    const line = document.createElementNS(svgNs, "line");
    line.setAttribute("x1", String(agentLayout.x));
    line.setAttribute("y1", String(agentLayout.y));
    line.setAttribute("x2", String(twigLayout.x));
    line.setAttribute("y2", String(twigLayout.y));
    line.classList.add("app-landing-orbit-focus-link");
    if (nodePath) line.dataset.focusPath = nodePath;
    appLandingOrbitFocusLinksNode.appendChild(line);

    const twig = document.createElement("button");
    twig.type = "button";
    twig.className = "app-landing-orbit-twig";
    twig.setAttribute("role", "listitem");
    twig.style.setProperty("--twig-x", `${twigLayout.x}%`);
    twig.style.setProperty("--twig-y", `${twigLayout.y}%`);
    if (nodePath) twig.dataset.focusPath = nodePath;
    if (isFocusItemActive(focusItem)) twig.classList.add("is-active");
    twig.textContent = label;
    twig.title = nodePath || label;
    twig.addEventListener("click", (event) => {
      event.stopPropagation();
      void openFocusItem(focusItem);
    });
    twig.addEventListener("mouseenter", cancelOrbitAgentFocusHide);
    twig.addEventListener("mouseleave", scheduleOrbitAgentFocusHide);
    appLandingOrbitTwigsNode.appendChild(twig);
  });

  appLandingOrbitTwigsNode.classList.add("is-visible");
  appLandingOrbitFocusLinksNode.classList.add("is-visible");
  syncFocusPanelActiveState();
}

function bindOrbitItemFocusHover(item, agent, agentIndex) {
  if (!item || !agent?.id) return;
  item.addEventListener("mouseenter", () => {
    cancelOrbitAgentFocusHide();
    paintOrbitAgentFocusGraph(agent.id, agentIndex);
  });
  item.addEventListener("mouseleave", scheduleOrbitAgentFocusHide);
  item.addEventListener("focusin", () => {
    cancelOrbitAgentFocusHide();
    paintOrbitAgentFocusGraph(agent.id, agentIndex);
  });
  item.addEventListener("focusout", (event) => {
    if (!item.contains(event.relatedTarget)) scheduleOrbitAgentFocusHide();
  });
}

function renderAppLandingOrbitFocus(items = []) {
  setLandingOrbitFocusCache(items);
}

const ORBIT_ATTENTION_PALETTE = [
  "#818cf8",
  "#fbbf24",
  "#34d399",
  "#f472b6",
  "#22d3ee",
  "#c084fc",
  "#fb7185",
  "#a3e635"
];

function getOrbitAttentionColor(agentId) {
  return ORBIT_ATTENTION_PALETTE[hashAgentIdForOrbit(String(agentId || "")) % ORBIT_ATTENTION_PALETTE.length];
}

function buildMockAgentAttentionShares(agents) {
  if (!Array.isArray(agents) || !agents.length) return [];

  const weighted = agents.map((agent) => ({
    agent,
    weight: 14 + (hashAgentIdForOrbit(agent.id) % 86)
  }));
  const totalWeight = weighted.reduce((sum, item) => sum + item.weight, 0);
  const shares = weighted.map((item) => ({
    agent: item.agent,
    percent: totalWeight ? Math.round((item.weight / totalWeight) * 100) : 0,
    color: getOrbitAttentionColor(item.agent.id)
  }));

  const drift = 100 - shares.reduce((sum, item) => sum + item.percent, 0);
  if (drift && shares.length) shares[0].percent += drift;

  return shares.sort((a, b) => b.percent - a.percent);
}

function bindOrbitAttentionHover(node, agentId) {
  if (!node || !agentId) return;

  node.addEventListener("mouseenter", () => {
    setOrbitAttentionHighlight(agentId);
  });
  node.addEventListener("mouseleave", () => {
    setOrbitAttentionHighlight(null);
  });
  node.addEventListener("focusin", () => {
    setOrbitAttentionHighlight(agentId);
  });
  node.addEventListener("focusout", (event) => {
    if (!node.contains(event.relatedTarget)) {
      setOrbitAttentionHighlight(null);
    }
  });
}

function setOrbitAttentionHighlight(agentId) {
  const hasHighlight = Boolean(agentId);

  appLandingOrbitBubblesNode
    ?.querySelectorAll(".app-landing-orbit-item[data-agent-id]")
    .forEach((item) => {
      const isMatch = item.dataset.agentId === agentId;
      item.classList.toggle("is-attention-highlighted", hasHighlight && isMatch);
      item.classList.toggle("is-attention-dimmed", hasHighlight && !isMatch);
    });

  appLandingOrbitAttentionNode
    ?.querySelectorAll(".app-landing-orbit-attention-stack-segment[data-agent-id]")
    .forEach((segment) => {
      const isMatch = segment.dataset.agentId === agentId;
      segment.classList.toggle("is-highlighted", hasHighlight && isMatch);
      segment.classList.toggle("is-dimmed", hasHighlight && !isMatch);
    });

  appLandingAttentionNode
    ?.querySelectorAll(".app-landing-orbit-attention-stack-segment[data-agent-id]")
    .forEach((segment) => {
      const isMatch = segment.dataset.agentId === agentId;
      segment.classList.toggle("is-highlighted", hasHighlight && isMatch);
      segment.classList.toggle("is-dimmed", hasHighlight && !isMatch);
    });

  appLandingFlowGridNode
    ?.querySelectorAll(".app-landing-flow-card[data-agent-id]")
    .forEach((card) => {
      const isMatch = card.dataset.agentId === agentId;
      card.classList.toggle("is-attention-highlighted", hasHighlight && isMatch);
      card.classList.toggle("is-attention-dimmed", hasHighlight && !isMatch);
    });
}

function clearOrbitAttentionHighlight() {
  setOrbitAttentionHighlight(null);
}

function renderAppLandingAttention(shares) {
  const target = appLandingAttentionNode || appLandingOrbitAttentionNode;
  if (!target) return;
  target.replaceChildren();
  clearOrbitAttentionHighlight();

  if (!Array.isArray(shares) || !shares.length) {
    target.classList.add("hidden");
    return;
  }

  target.classList.remove("hidden");

  const stackedBar = document.createElement("div");
  stackedBar.className = "app-landing-orbit-attention-stack";
  stackedBar.setAttribute("role", "img");
  stackedBar.setAttribute(
    "aria-label",
    shares.map((item) => `${item.agent.name || item.agent.id}: ${item.percent}%`).join(", ")
  );

  for (const item of shares) {
    if (item.percent <= 0) continue;

    const segment = document.createElement("button");
    segment.type = "button";
    segment.className = "app-landing-orbit-attention-stack-segment";
    segment.dataset.agentId = item.agent.id;
    segment.style.width = `${item.percent}%`;
    segment.style.setProperty("--orbit-attention-color", item.color);
    segment.style.backgroundColor = item.color;
    segment.title = `${item.agent.name || item.agent.id} — ${item.percent}%`;
    segment.setAttribute("aria-label", segment.title);
    bindOrbitAttentionHover(segment, item.agent.id);
    stackedBar.appendChild(segment);
  }

  target.append(stackedBar);
}

function renderAppLandingOrbitAttention(shares) {
  renderAppLandingAttention(shares);
}

async function renderAppLandingAgents() {
  await renderAppLandingPlatformSection();
  if (!appLandingAgentsNode) return;
  appLandingAgentsNode.replaceChildren();

  const agents = getAgentsForLandingGrid();
  if (agents.length === 0) {
    appLandingAgentsNode.classList.remove("is-grouped-layout");
    const empty = document.createElement("p");
    empty.className = "app-landing-empty";
    empty.textContent = "Нет агентов. Нажмите «+ Добавить агента» или «Реестр».";
    appLandingAgentsNode.appendChild(empty);
  } else {
    try {
      await loadLandingAgentsGroups();
    } catch {
      landingAgentsGroupsCache = [];
    }

    const agents = getAgentsForLandingGrid();
    const { orchestrator, rest } = splitLandingOrchestratorAgent(agents);

    if (orchestrator) {
      appLandingAgentsNode.appendChild(renderAppLandingOrchestratorSection(orchestrator));
    }

    const hasGroups = landingAgentsGroupsCache.length > 0;

    if (hasGroups) {
      appLandingAgentsNode.classList.add("is-grouped-layout");
      const { grouped, ungrouped } = buildLandingGroupsLayout(rest, landingAgentsGroupsCache);

      for (const group of grouped) {
        appLandingAgentsNode.appendChild(renderAppLandingGroupSection(group, { editable: false }));
      }

      if (ungrouped.length || landingAgentsUngroupedCache.backgroundUrl) {
        appLandingAgentsNode.appendChild(
          renderAppLandingGroupSection(
            {
              ...landingAgentsUngroupedCache,
              agents: ungrouped,
              agentIds: ungrouped.map((agent) => agent.id),
              readonly: true
            },
            { editable: false }
          )
        );
      }
    } else {
      appLandingAgentsNode.classList.remove("is-grouped-layout");
      for (const agent of rest) {
        const item = document.createElement("div");
        item.className = "app-landing-agent-item";
        item.setAttribute("role", "listitem");
        item.appendChild(createAppLandingAgentTile(agent));
        appLandingAgentsNode.appendChild(item);
      }
    }
  }

  renderAppLandingOrbit();
  renderAppLandingHub(getProcessedLandingFocusItems());
  void loadGlobalFocusItems();
  syncLandingAgentsViewUi();
  renderAgentSelect();
}

function setAppLandingHint(message = "", { alert = false } = {}) {
  if (!appLandingHintNode) return;
  const text = String(message || "").trim();
  appLandingHintNode.textContent = text;
  appLandingHintNode.classList.toggle("hidden", !text);
  appLandingHintNode.classList.toggle("is-alert", Boolean(text && alert));
}

function selectAgentOption(agentId) {
  if (!agentId || agentId === activeAgentId) return;
  if (agentSelectNode) agentSelectNode.value = agentId;
  switchActiveAgent(agentId).catch((error) => {
    showHomeView(`Ошибка переключения агента: ${error.message}`);
    renderAgentSelect();
  });
}

async function switchActiveAgent(nextAgentId) {
  if (!nextAgentId || nextAgentId === activeAgentId) return;
  if (!agentsCache.some((agent) => agent.id === nextAgentId)) return;

  setMenuLoading(true);
  try {
    saveCollapsedFoldersByAgent();
    closeCreateNodeModal();
    activeAgentId = nextAgentId;
    localStorage.setItem(ACTIVE_AGENT_STORAGE_KEY, activeAgentId);
    workspaceNotificationsEvents = [];
    workspaceNotificationsLatestId = 0;
    workspaceNotificationsTruncated = false;
    workspaceNotificationsFileLines = 0;
    workspaceNotificationsInitialLoadDone = false;
    workspaceNotificationsAnnouncedUpToId = 0;
    loadWorkspaceNotificationsSeenId(nextAgentId);
    void refreshWorkspaceNotifications(false);
    resetLiveSyncSession(nextAgentId);
    invalidateMarkdownLinkIndexCache();
    invalidateTypeCatalogCache(nextAgentId);
    hideAppLandingView();
    syncWorkspaceNotificationsAvailability();
    hideMenuNoAgentPlaceholder();
    syncAppRouteToUrl({ replace: true });
    activateMenuAgentPane(activeAgentId);
    activePath = null;
    activeLabel = null;
    clearActiveSystemFile();
    clearMediaSidecarEditor();
    resetGitWorkspaceViewToDefault();

    const cachedMenu = menuCacheByAgent.get(activeAgentId);
    const cachedPane = menuAgentPanes.get(activeAgentId);
    const hasCachedView = Boolean(cachedMenu && cachedPane && cachedPane.childElementCount > 0);
    if (hasCachedView) {
      currentMenuData = cachedMenu;
    }

    showHomeView();
    renderAgentSelect();
    applyMenuTreeSettingsUi();
    applyAgentGraphSettingsUi();
    closeMenuSettingsPopover();
    setMenuLoading(true, `Загрузка: ${getActiveAgentLabel() || nextAgentId}`);

    if (hasCachedView) {
      activateMenuAgentPane(activeAgentId);
      updateActiveButton();
      await refreshAgentSliderCatalog(true);
      syncAgentPreview();
    }

    await Promise.all([loadSystemFiles(), loadAwnTypes(activeAgentId), loadAgentCatalogs(activeAgentId)]);

    if (hasCachedView) {
      renderSystemFiles(systemFilesCache);
    } else {
      await refreshMenu({ agentId: activeAgentId });
    }

    if (isAgentWorkspaceCanvasVisible()) {
      applyAgentWorkspaceCanvasUi();
    }
    await loadAgentFocusItems(activeAgentId);
    updateDocumentTitle();
    updateBreadcrumbsForActiveMode();
  } finally {
    setMenuLoading(false);
  }
}

function setMenuLoading(isLoading, message = "Загрузка...") {
  if (!menuLoadingNode) return;
  if (menuLoadingTextNode) {
    menuLoadingTextNode.textContent = message;
  }
  menuLoadingNode.classList.toggle("hidden", !isLoading);
  menuLoadingNode.setAttribute("aria-busy", isLoading ? "true" : "false");
  menuNode?.classList.toggle("is-loading", isLoading);
  if (agentSelectNode) agentSelectNode.disabled = isLoading;
  if (agentsManageBtn) agentsManageBtn.disabled = isLoading;
  if (agentsPickerBtn) agentsPickerBtn.disabled = isLoading;
  if (isLoading) closeAgentsPickerPopover();
  syncMenuRefreshButtonState();
  if (menuCollapseAllBtn) menuCollapseAllBtn.disabled = isLoading;
  if (menuPinBranchBtn) menuPinBranchBtn.disabled = isLoading;
  if (menuSettingsBtn) menuSettingsBtn.disabled = isLoading;
}

function syncMenuRefreshButtonState() {
  if (!menuRefreshBtn) return;
  const menuBusy = Boolean(menuLoadingNode && !menuLoadingNode.classList.contains("hidden"));
  menuRefreshBtn.disabled = menuBusy || menuRefreshInFlight;
}

function ensureMenuAgentPane(agentId = activeAgentId) {
  const id = agentId || activeAgentId || "main";
  let pane = menuAgentPanes.get(id);
  if (!pane) {
    pane = document.createElement("div");
    pane.className = "menu-agent-pane hidden";
    pane.dataset.agentId = id;
    menuNode.appendChild(pane);
    menuAgentPanes.set(id, pane);
  }
  return pane;
}

function activateMenuAgentPane(agentId = activeAgentId) {
  for (const [id, pane] of menuAgentPanes.entries()) {
    pane.classList.toggle("hidden", id !== agentId);
  }
  const pane = ensureMenuAgentPane(agentId);
  pane.classList.remove("hidden");
}

function getMenuQueryRoot() {
  return menuAgentPanes.get(activeAgentId) || menuNode;
}

function invalidateMenuAgentCache(agentId = activeAgentId) {
  menuCacheByAgent.delete(agentId);
  menuRuntimeFlagsByAgent.delete(agentId);
}

function openAgentsRegistryModal() {
  agentsRegistryDraft = getRegistryAgentsForUi().map((agent) => ({
      id: agent.id,
      path: agent.path,
      environment: normalizeAgentEnvironmentDraft(agent.environment),
      name: agent.name || agent.id,
      comment: agent.comment || "",
      default: Boolean(agent.default),
      orchestrator: Boolean(agent.orchestrator),
      active: agent.active !== false,
      manifestFound: Boolean(agent.manifestFound),
      folderExists: agent.folderExists !== false,
      hasPreview: Boolean(agent.hasPreview),
      previewUrl: agent.previewUrl || null,
      previewRel: agent.previewRel || null,
      awnProps: agent.awnProps && typeof agent.awnProps === "object" ? { ...agent.awnProps } : {}
    }));
  renderAgentsRegistryList();
  agentsRegistryModalNode?.classList.remove("hidden");
  void refreshAgentsRegistryPreviewMeta();
}

async function refreshAgentsRegistryPreviewMeta() {
  if (!agentsRegistryModalNode || agentsRegistryModalNode.classList.contains("hidden")) return;
  try {
    const response = await fetch("/api/agents");
    if (!response.ok) return;
    const data = await response.json();
    const freshAgents = Array.isArray(data.agents) ? data.agents : [];
    agentsCache = freshAgents;
    freshAgents.forEach((agent) => syncAgentsRegistryDraftPreview(agent.path));
  } catch {
    // keep cached preview state
  }
}

function countActiveAgentsRegistryDraft() {
  return agentsRegistryDraft.filter((agent) => agent.active !== false).length;
}

function toggleAgentsRegistryDraftActive(index) {
  const agent = agentsRegistryDraft[index];
  if (!agent) return;

  const isActive = agent.active !== false;
  if (isActive && countActiveAgentsRegistryDraft() <= 1) {
    showToast("Нужен хотя бы один активный агент", "error");
    return;
  }

  agent.active = !isActive;
  if (!agent.active && agent.default) {
    agent.default = false;
    const replacement = agentsRegistryDraft.find((item, itemIndex) => itemIndex !== index && item.active !== false);
    if (replacement) replacement.default = true;
  }
  renderAgentsRegistryList();
}

function closeAgentsRegistryModal() {
  agentsRegistryModalNode?.classList.add("hidden");
  agentsRegistryDraft = [];
  agentsRegistryListNode.innerHTML = "";
  if (agentsRegistryPathValidateTimer) {
    clearTimeout(agentsRegistryPathValidateTimer);
    agentsRegistryPathValidateTimer = null;
  }
}

function normalizeRegistryPathKey(rawPath) {
  return String(rawPath || "")
    .trim()
    .replace(/\\/g, "/")
    .replace(/\/+$/, "");
}

function getWorkspaceFolderNameFromPath(rawPath) {
  const trimmed = String(rawPath || "").trim().replace(/[\\/]+$/, "");
  if (!trimmed) return "";
  return trimmed.split(/[\\/]/).filter(Boolean).pop() || "";
}

const CREATE_AGENT_NAME_MAX_LENGTH = 120;
const CREATE_AGENT_DESCRIPTION_MAX_LENGTH = 2000;
const CREATE_AGENT_ID_FOLDER_RE = /^[a-z0-9][a-z0-9_-]*$/;
const CREATE_AGENT_WORKSPACE_PATH_PREFIX = "./workspaces/";
const createAgentPathAutoSyncState = new Map();

function slugifyAgentFolderSegment(raw) {
  const text = String(raw || "").trim();
  if (!text) return "";
  return sanitizeSlugValue(transliterateDisplayToSlug(text) || text) || "";
}

function normalizeAgentFolderName(rawFolderName) {
  return slugifyAgentFolderSegment(rawFolderName);
}

function getCreateAgentIdFromPath(rawPath) {
  const folderName = getWorkspaceFolderNameFromPath(normalizeCreateAgentWorkspacePath(rawPath));
  return folderName ? folderName.toLowerCase() : "";
}

function isAgentIdInRegistry(agentId) {
  const id = String(agentId || "").trim().toLowerCase();
  if (!id) return false;
  return agentsCache.some((agent) => String(agent.id || "").trim().toLowerCase() === id);
}

function isAgentIdAlreadyInDraft(agentId) {
  const id = String(agentId || "").trim().toLowerCase();
  if (!id) return false;
  return agentsRegistryDraft.some((item) => {
    const itemId = String(item.id || getWorkspaceFolderNameFromPath(item.path) || "")
      .trim()
      .toLowerCase();
    return itemId === id;
  });
}

function normalizeCreateAgentWorkspacePath(rawPath) {
  const trimmed = String(rawPath || "").trim().replace(/[\\/]+$/, "");
  if (!trimmed) return trimmed;
  const folderName = getWorkspaceFolderNameFromPath(trimmed);
  if (!folderName) return trimmed;
  const normalizedFolder = normalizeAgentFolderName(folderName);
  if (!normalizedFolder || normalizedFolder === folderName) return trimmed;
  const parent = trimmed.slice(0, Math.max(0, trimmed.length - folderName.length)).replace(/[\\/]+$/, "");
  if (!parent) return normalizedFolder;
  const sep = trimmed.includes("\\") ? "\\" : "/";
  return `${parent}${sep}${normalizedFolder}`;
}

function getCreateAgentNameError(rawName) {
  const name = String(rawName || "").trim();
  if (!name) return "Укажите название агента";
  if (name.length > CREATE_AGENT_NAME_MAX_LENGTH) {
    return `Название агента: не более ${CREATE_AGENT_NAME_MAX_LENGTH} символов`;
  }
  return null;
}

function getCreateAgentDescriptionError(rawDescription) {
  const description = String(rawDescription || "");
  if (description.length > CREATE_AGENT_DESCRIPTION_MAX_LENGTH) {
    return `Описание агента: не более ${CREATE_AGENT_DESCRIPTION_MAX_LENGTH} символов`;
  }
  return null;
}

function getCreateAgentWorkspacePathError(rawPath) {
  const trimmedPath = String(rawPath || "").trim();
  if (!trimmedPath) return "Укажите путь workspace";

  const normalizedPath = normalizeCreateAgentWorkspacePath(trimmedPath);
  const folderName = getWorkspaceFolderNameFromPath(normalizedPath);
  if (!folderName) return "Укажите путь workspace";
  if (folderName === "workspaces" || folderName === "Workspaces") {
    return "Укажите ID агента в имени последней папки (например ./workspaces/my-project)";
  }
  if (!CREATE_AGENT_ID_FOLDER_RE.test(folderName)) {
    return "ID агента (имя папки): латиница, цифры, дефис и подчёркивание";
  }
  return null;
}

function getCreateAgentFormFields(prefix) {
  const nameInput = document.getElementById(`${prefix}-create-name-input`);
  const descriptionInput = document.getElementById(`${prefix}-create-description-input`);
  const pathInput = document.getElementById(`${prefix}-create-path-input`);
  return {
    nameInput,
    descriptionInput,
    pathInput,
    nameField: nameInput?.closest(".agents-registry-create-field") || null,
    descriptionField: descriptionInput?.closest(".agents-registry-create-field") || null,
    pathField: pathInput?.closest(".agents-registry-create-path-field") || null,
    fieldNodes: [
      nameInput?.closest(".agents-registry-create-field"),
      descriptionInput?.closest(".agents-registry-create-field"),
      pathInput?.closest(".agents-registry-create-path-field")
    ].filter(Boolean)
  };
}

function clearCreateAgentFormValidation(fieldNodes) {
  for (const fieldNode of fieldNodes || []) {
    fieldNode.classList.remove("is-invalid");
    fieldNode.querySelector(".agents-registry-create-error")?.remove();
  }
}

function showCreateAgentFieldError(fieldNode, message) {
  if (!fieldNode) return;
  fieldNode.classList.add("is-invalid");
  let errorNode = fieldNode.querySelector(".agents-registry-create-error");
  if (!errorNode) {
    errorNode = document.createElement("div");
    errorNode.className = "agents-registry-create-error";
    errorNode.setAttribute("role", "alert");
    fieldNode.appendChild(errorNode);
  }
  errorNode.textContent = message;
}

function validateCreateAgentForm({ name, description, path, checkRegistry = false, checkDraft = false }) {
  const nameError = getCreateAgentNameError(name);
  if (nameError) return { field: "name", message: nameError };

  const descriptionError = getCreateAgentDescriptionError(description);
  if (descriptionError) return { field: "description", message: descriptionError };

  const pathError = getCreateAgentWorkspacePathError(path);
  if (pathError) return { field: "path", message: pathError };

  const normalizedPath = normalizeCreateAgentWorkspacePath(path);
  const agentId = getCreateAgentIdFromPath(normalizedPath);
  if (isAgentIdInRegistry(agentId)) {
    return { field: "path", message: `Агент с ID «${agentId}» уже есть в реестре` };
  }
  if (checkDraft && isAgentIdAlreadyInDraft(agentId)) {
    return { field: "path", message: `Агент с ID «${agentId}» уже в списке` };
  }

  if (checkRegistry && isAgentPathInRegistry(normalizedPath)) {
    return { field: "path", message: "Агент с таким путём уже в реестре" };
  }
  if (checkDraft && isAgentPathAlreadyInDraft(normalizedPath)) {
    return { field: "path", message: "Этот агент уже в списке" };
  }

  return null;
}

function applyCreateAgentFormValidation(prefix, validationError) {
  const fields = getCreateAgentFormFields(prefix);
  clearCreateAgentFormValidation(fields.fieldNodes);
  if (!validationError) return fields;

  const fieldMap = {
    name: fields.nameField,
    description: fields.descriptionField,
    path: fields.pathField
  };
  const inputMap = {
    name: fields.nameInput,
    description: fields.descriptionInput,
    path: fields.pathInput
  };
  const fieldNode = fieldMap[validationError.field];
  showCreateAgentFieldError(fieldNode, validationError.message);
  showToast(validationError.message, "error");
  inputMap[validationError.field]?.focus();
  return fields;
}

function bindCreateAgentFormValidation(prefix) {
  const fields = getCreateAgentFormFields(prefix);
  for (const fieldNode of fields.fieldNodes) {
    fieldNode?.addEventListener("input", () => {
      fieldNode.classList.remove("is-invalid");
      fieldNode.querySelector(".agents-registry-create-error")?.remove();
    });
  }
}

function resetCreateAgentPathAutoSync(prefix) {
  createAgentPathAutoSyncState.set(prefix, true);
}

function getCreateAgentPathParent(rawPath) {
  const trimmed = String(rawPath || "").trim().replace(/[\\/]+$/, "");
  if (!trimmed) return CREATE_AGENT_WORKSPACE_PATH_PREFIX.replace(/\/$/, "");
  const folderName = getWorkspaceFolderNameFromPath(trimmed);
  if (!folderName || trimmed === folderName) return trimmed;
  return trimmed.slice(0, Math.max(0, trimmed.length - folderName.length)).replace(/[\\/]+$/, "");
}

function buildCreateAgentWorkspacePath(parentPath, folderName) {
  const parent = String(parentPath || "").trim().replace(/[\\/]+$/, "");
  const folder = String(folderName || "").trim();
  if (!folder) return parent ? `${parent}/` : CREATE_AGENT_WORKSPACE_PATH_PREFIX;
  const sep = parent.includes("\\") ? "\\" : "/";
  return `${parent}${sep}${folder}`;
}

function syncCreateAgentPathFromName(prefix) {
  if (!createAgentPathAutoSyncState.get(prefix)) return;
  const { nameInput, pathInput } = getCreateAgentFormFields(prefix);
  if (!pathInput) return;
  const folderName = normalizeAgentFolderName(nameInput?.value || "");
  const parentPath = getCreateAgentPathParent(pathInput.value);
  pathInput.value = buildCreateAgentWorkspacePath(parentPath, folderName);
}

function bindCreateAgentPathAutoSync(prefix) {
  const { nameInput, pathInput } = getCreateAgentFormFields(prefix);
  if (!nameInput || !pathInput) return;

  resetCreateAgentPathAutoSync(prefix);

  nameInput.addEventListener("input", () => {
    syncCreateAgentPathFromName(prefix);
  });
  pathInput.addEventListener("input", () => {
    createAgentPathAutoSyncState.set(prefix, false);
  });
  pathInput.addEventListener("blur", () => {
    const normalized = normalizeCreateAgentWorkspacePath(pathInput.value.trim());
    if (normalized && normalized !== pathInput.value.trim()) {
      pathInput.value = normalized;
    }
  });
}

function buildRegistryPathResultMap(results) {
  const byPath = new Map();
  if (!Array.isArray(results)) return byPath;
  for (const result of results) {
    const inputKey = normalizeRegistryPathKey(result?.path);
    if (inputKey) byPath.set(inputKey, result);
    const absoluteKey = normalizeRegistryPathKey(result?.absolute);
    if (absoluteKey) byPath.set(absoluteKey, result);
  }
  return byPath;
}

function findRegistryPathValidationResult(pathValue, byPath) {
  const key = normalizeRegistryPathKey(pathValue);
  if (!key) return null;
  if (byPath.has(key)) return byPath.get(key);
  return null;
}

function updateAgentsRegistryPathStatusNode(node, result) {
  if (!node) return;
  if (result?.status === "checking") {
    node.dataset.state = "checking";
    node.title = "Проверка…";
    syncRegistryRowActions(node.closest(".agents-registry-row"), "checking");
    return;
  }
  if (!result?.valid) {
    node.dataset.state = "invalid";
    node.title = result?.absolute
      ? `${result.error || "Некорректный путь"}\n${result.absolute}`
      : result?.error || "Некорректный путь";
    syncRegistryRowActions(node.closest(".agents-registry-row"), "invalid");
    return;
  }
  if (result.manifestFound) {
    node.dataset.state = "manifest";
    node.title = result.absolute ? `manifest.md (awn.page.ws) найден:\n${result.absolute}` : "manifest.md (awn.page.ws) найден";
    syncRegistryRowActions(node.closest(".agents-registry-row"), "manifest");
    return;
  }
  if (result.exists) {
    node.dataset.state = "missing";
    node.title = result.absolute
      ? `Папка есть, но нет manifest.md (awn.page.ws):\n${result.absolute}`
      : "Папка есть, но нет manifest.md (awn.page.ws)";
    syncRegistryRowActions(node.closest(".agents-registry-row"), "missing");
    return;
  }
  node.dataset.state = "missing";
  node.title = result.absolute ? `Папка не найдена:\n${result.absolute}` : "Папка не найдена";
  syncRegistryRowActions(node.closest(".agents-registry-row"), "missing");
}

function syncRegistryRowActions(row, pathState) {
  if (!row) return;
  row.classList.toggle("is-missing-folder", pathState === "missing");
  const activeBtn = row.querySelector(".agents-registry-active-btn");
  const deleteBtn = row.querySelector(".agents-registry-delete-btn");
  const isMissing = pathState === "missing";

  if (activeBtn) activeBtn.hidden = isMissing;
  if (deleteBtn) {
    deleteBtn.hidden = !isMissing;
    deleteBtn.disabled = agentsRegistryDraft.length <= 1;
    deleteBtn.title =
      agentsRegistryDraft.length <= 1
        ? "Нужен хотя бы один агент"
        : "Удалить из списка (без манифеста)";
  }
}

async function removeAgentsRegistryDraftRow(index) {
  if (agentsRegistryDraft.length <= 1) {
    showToast("Нужен хотя бы один агент", "error");
    return;
  }

  const agent = agentsRegistryDraft[index];
  if (!agent) return;

  const label = String(agent.name || agent.id || agent.path || "агента").trim();
  const confirmed = await askConfirm(
    `Удалить «${label}» из списка? Запись исчезнет после «Сохранить». Папка на диске не удаляется.`
  );
  if (!confirmed) return;

  const wasDefault = Boolean(agent.default);
  const wasActive = agent.active !== false;
  agentsRegistryDraft.splice(index, 1);

  if (wasDefault) {
    const replacement =
      agentsRegistryDraft.find((item) => item.active !== false) || agentsRegistryDraft[0];
    if (replacement) replacement.default = true;
  }
  if (wasActive && countActiveAgentsRegistryDraft() === 0 && agentsRegistryDraft[0]) {
    agentsRegistryDraft[0].active = true;
  }

  renderAgentsRegistryList();
}

function applyManifestToRegistryDraft(index, result) {
  if (!agentsRegistryDraft[index] || !result?.manifestFound || !result?.manifest) return;
  const manifest = result.manifest;
  agentsRegistryDraft[index].manifestFound = true;
  agentsRegistryDraft[index].name = manifest.name || agentsRegistryDraft[index].name;
  agentsRegistryDraft[index].comment = manifest.comment || "";
  if (manifest.awnProps && typeof manifest.awnProps === "object") {
    agentsRegistryDraft[index].awnProps = { ...manifest.awnProps };
  }
}

function getRegistryAgentPreviewUrl(agent) {
  if (!agent?.path) return null;
  if (
    agent.previewUrl?.startsWith("/api/preview/image") ||
    agent.previewUrl?.startsWith("/api/media/file")
  ) {
    if (!agent.hasPreview) return null;
    return appendMediaThumbToApiUrl(
      appendCacheBuster(appendAgentToApiUrl(agent.previewUrl, agent.id)),
      MEDIA_THUMB_MAX_AVATAR
    );
  }
  if (agent.hasPreview || agent.previewUrl?.startsWith("/api/agents/workspace-preview")) {
    const url = agent.previewUrl?.startsWith("/api/agents/workspace-preview")
      ? agent.previewUrl
      : `/api/agents/workspace-preview?path=${encodeURIComponent(agent.path)}`;
    return appendMediaThumbToApiUrl(
      appendCacheBuster(appendAgentToApiUrl(url, agent.id)),
      MEDIA_THUMB_MAX_AVATAR
    );
  }
  return null;
}

function updateRegistryRowPreview(row, agent) {
  const previewSlot = row.querySelector(".agents-registry-preview-slot");
  if (!previewSlot) return;

  const previewUrl = getRegistryAgentPreviewUrl(agent);
  const hasImage = Boolean(previewUrl);
  const emoji = resolveAwnEmoji(agent);
  const placeholder = previewSlot.querySelector(".agents-registry-preview-placeholder");

  previewSlot.classList.toggle("has-image", hasImage);
  previewSlot.classList.toggle("has-emoji", !hasImage && Boolean(emoji));
  previewSlot.title = hasImage ? "Нажмите, чтобы заменить аватар" : "Загрузить аватар";

  let emojiNode = previewSlot.querySelector(".agents-registry-preview-emoji");
  if (!hasImage && emoji) {
    if (!emojiNode) {
      emojiNode = document.createElement("span");
      emojiNode.className = "agents-registry-preview-emoji";
      emojiNode.setAttribute("aria-hidden", "true");
      previewSlot.insertBefore(emojiNode, placeholder);
    }
    emojiNode.textContent = emoji;
    placeholder?.classList.add("hidden");
  } else {
    emojiNode?.remove();
    placeholder?.classList.remove("hidden");
  }

  let img = previewSlot.querySelector(".agents-registry-preview-thumb");
  if (hasImage) {
    if (!img) {
      img = document.createElement("img");
      img.className = "agents-registry-preview-thumb";
      img.alt = "";
      img.draggable = false;
      previewSlot.insertBefore(img, placeholder);
    }
    img.onerror = () => {
      img.remove();
      previewSlot.classList.remove("has-image");
      updateRegistryRowPreview(row, agent);
    };
    img.src = previewUrl;
  } else if (img) {
    img.remove();
  }
}

function bindRegistryPreviewSlot(row, agent, index) {
  const previewSlot = row.querySelector(".agents-registry-preview-slot");
  if (!previewSlot || previewSlot.dataset.bound === "1") return;
  previewSlot.dataset.bound = "1";

  const fileInput = previewSlot.querySelector(".agents-registry-preview-file-input");
  const removeBtn = previewSlot.querySelector(".agents-registry-preview-remove-btn");

  previewSlot.addEventListener("click", () => {
    fileInput?.click();
  });
  previewSlot.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      fileInput?.click();
    }
  });

  fileInput?.addEventListener("click", (event) => {
    event.stopPropagation();
  });
  fileInput?.addEventListener("change", () => {
    const file = fileInput.files?.[0];
    if (file) void uploadAgentsRegistryPreview(index, file, row);
    fileInput.value = "";
  });

  removeBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    void removeAgentsRegistryPreview(index, row);
  });
}

async function uploadAgentsRegistryPreview(index, file, row) {
  const agent = agentsRegistryDraft[index];
  if (!agent?.path) {
    showToast("Workspace не задан", "error");
    return;
  }

  const previewSlot = row.querySelector(".agents-registry-preview-slot");
  previewSlot?.classList.add("is-uploading");

  try {
    const payload = await uploadAgentPreviewFile(agent.path, file);
    agentsRegistryDraft[index].hasPreview = Boolean(payload.hasPreview);
    agentsRegistryDraft[index].previewUrl = payload.previewUrl || null;
    agentsRegistryDraft[index].previewRel = null;
    updateRegistryRowPreview(row, agentsRegistryDraft[index]);
    await refreshAgentPreviewAfterFileChange(agent.path);
    showToast("Аватар сохранён", "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message ? `Ошибка загрузки: ${message}` : "Ошибка загрузки", "error");
  } finally {
    previewSlot?.classList.remove("is-uploading");
  }
}

async function removeAgentsRegistryPreview(index, row) {
  const agent = agentsRegistryDraft[index];
  if (!agent?.path || !agent.hasPreview) return;

  const previewSlot = row.querySelector(".agents-registry-preview-slot");
  previewSlot?.classList.add("is-uploading");

  try {
    await removeAgentPreviewFile(agent.path);
    agentsRegistryDraft[index].previewRel = null;
    agentsRegistryDraft[index].hasPreview = false;
    agentsRegistryDraft[index].previewUrl = null;
    updateRegistryRowPreview(row, agentsRegistryDraft[index]);
    await refreshAgentPreviewAfterFileChange(agent.path);
    showToast("Аватар удалён", "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message ? `Ошибка удаления: ${message}` : "Ошибка удаления", "error");
  } finally {
    previewSlot?.classList.remove("is-uploading");
  }
}

function syncRegistryRowMetaFromDraft() {
  if (!agentsRegistryListNode) return;
  agentsRegistryDraft.forEach((agent, index) => {
    const row = agentsRegistryListNode.querySelector(`.agents-registry-row[data-registry-index="${index}"]`);
    if (!row) return;
    const nameNode = row.querySelector("[data-agent-name]");
    const commentNode = row.querySelector("[data-agent-comment]");
    const pathNode = row.querySelector("[data-agent-path]");
    if (nameNode && nameNode.value !== (agent.name || "")) {
      nameNode.value = agent.name || "";
    }
    if (commentNode && commentNode.value !== (agent.comment || "")) {
      commentNode.value = agent.comment || "";
    }
    if (pathNode && pathNode.value !== (agent.path || "")) {
      pathNode.value = agent.path || "";
      pathNode.title = agent.path || "";
    }
    updateRegistryRowPreview(row, agent);
  });
}

function applyAgentsRegistryPathValidationResults(results, pathsSnapshot = null) {
  if (!agentsRegistryListNode || !Array.isArray(results)) return;
  const byPath = buildRegistryPathResultMap(results);
  const snapshot =
    Array.isArray(pathsSnapshot) && pathsSnapshot.length > 0
      ? pathsSnapshot
      : agentsRegistryDraft.map((agent) => normalizeRegistryPathKey(agent.path));

  agentsRegistryDraft.forEach((agent, index) => {
    const expectedPath = snapshot[index];
    const currentPath = normalizeRegistryPathKey(agent.path);
    if (expectedPath && currentPath !== expectedPath) return;

    const result = findRegistryPathValidationResult(agent.path, byPath);
    const statusNode = agentsRegistryListNode.querySelector(
      `.agents-registry-row[data-registry-index="${index}"] .agents-registry-path-dot`
    );
    if (!statusNode) return;
    if (result) {
      agentsRegistryDraft[index].folderExists = result.exists !== false;
      applyManifestToRegistryDraft(index, result);
      updateAgentsRegistryPathStatusNode(statusNode, result);
      return;
    }
    updateAgentsRegistryPathStatusNode(statusNode, { status: "checking" });
  });

  syncRegistryRowMetaFromDraft();
}

function markAgentsRegistryPathStatusesChecking() {
  if (!agentsRegistryListNode) return;
  for (const node of agentsRegistryListNode.querySelectorAll(".agents-registry-row .agents-registry-path-dot")) {
    updateAgentsRegistryPathStatusNode(node, { status: "checking" });
  }
}

function scheduleAgentsRegistryPathValidation() {
  if (agentsRegistryPathValidateTimer) {
    clearTimeout(agentsRegistryPathValidateTimer);
  }
  agentsRegistryPathValidateTimer = window.setTimeout(() => {
    agentsRegistryPathValidateTimer = null;
    void refreshAgentsRegistryPathStatuses();
  }, 350);
}

async function refreshAgentsRegistryPathStatuses() {
  if (!agentsRegistryListNode || agentsRegistryDraft.length === 0) return;
  const requestId = ++agentsRegistryPathValidateRequestId;
  const pathsSnapshot = agentsRegistryDraft.map((agent) => normalizeRegistryPathKey(agent.path));
  markAgentsRegistryPathStatusesChecking();
  try {
    const response = await fetch("/api/agents/validate-paths", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ paths: agentsRegistryDraft.map((agent) => agent.path) })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.details || errorData.error || `HTTP ${response.status}`);
    }
    const data = await response.json();
    if (requestId !== agentsRegistryPathValidateRequestId) return;
    applyAgentsRegistryPathValidationResults(data.results, pathsSnapshot);
  } catch (error) {
    if (requestId !== agentsRegistryPathValidateRequestId) return;
    for (const row of agentsRegistryListNode.querySelectorAll(".agents-registry-row")) {
      const statusNode = row.querySelector(".agents-registry-path-dot");
      updateAgentsRegistryPathStatusNode(statusNode, {
        valid: false,
        error: `Ошибка проверки: ${error.message}`
      });
    }
  }
}

function moveAgentsRegistryDraftRow(fromIndex, toIndex) {
  if (fromIndex === toIndex) return;
  if (fromIndex < 0 || toIndex < 0) return;
  if (fromIndex >= agentsRegistryDraft.length || toIndex >= agentsRegistryDraft.length) return;
  const [item] = agentsRegistryDraft.splice(fromIndex, 1);
  agentsRegistryDraft.splice(toIndex, 0, item);
  renderAgentsRegistryList();
}

function sortAgentsRegistryDraft(field) {
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  agentsRegistryDraft.sort((left, right) => {
    if (field === "default") {
      return Number(Boolean(right.default)) - Number(Boolean(left.default));
    }
    return collator.compare(String(left[field] || ""), String(right[field] || ""));
  });
  renderAgentsRegistryList();
}

function renderAgentsRegistryList() {
  if (!agentsRegistryListNode) return;
  agentsRegistryListNode.innerHTML = "";

  agentsRegistryDraft.forEach((agent, index) => {
    const row = document.createElement("div");
    row.className = "agents-registry-row";
    if (agent.active === false) row.classList.add("is-inactive");
    if (agent.orchestrator) row.classList.add("is-orchestrator");
    row.dataset.registryIndex = String(index);

    const mainRow = document.createElement("div");
    mainRow.className = "agents-registry-row-main";

    const orderWrap = document.createElement("div");
    orderWrap.className = "agents-registry-order";
    const upBtn = document.createElement("button");
    upBtn.type = "button";
    upBtn.className = "agents-registry-order-btn";
    upBtn.textContent = "↑";
    upBtn.title = "Выше";
    upBtn.disabled = index === 0;
    upBtn.addEventListener("click", () => moveAgentsRegistryDraftRow(index, index - 1));
    const downBtn = document.createElement("button");
    downBtn.type = "button";
    downBtn.className = "agents-registry-order-btn";
    downBtn.textContent = "↓";
    downBtn.title = "Ниже";
    downBtn.disabled = index === agentsRegistryDraft.length - 1;
    downBtn.addEventListener("click", () => moveAgentsRegistryDraftRow(index, index + 1));
    orderWrap.append(upBtn, downBtn);

    const nameField = document.createElement("label");
    nameField.className = "agents-registry-field agents-registry-name-field";
    nameField.innerHTML = "<span>Название</span>";
    const nameInput = document.createElement("input");
    nameInput.type = "text";
    nameInput.className = "agents-registry-name-input";
    nameInput.dataset.agentName = "1";
    nameInput.placeholder = "Название";
    nameInput.value = agent.name || "";
    nameInput.addEventListener("input", () => {
      agentsRegistryDraft[index].name = nameInput.value;
    });
    nameField.appendChild(nameInput);

    const pathField = document.createElement("label");
    pathField.className = "agents-registry-field agents-registry-path-field";
    const pathLabelRow = document.createElement("span");
    pathLabelRow.className = "agents-registry-path-label";
    const pathStatusNode = document.createElement("span");
    pathStatusNode.className = "agents-registry-path-dot";
    pathStatusNode.dataset.state = "checking";
    pathStatusNode.title = "Проверка…";
    pathStatusNode.setAttribute("aria-label", "Статус manifest.md (awn.page.ws)");
    const pathLabelText = document.createElement("span");
    pathLabelText.textContent = "Workspace";
    pathLabelRow.append(pathStatusNode, pathLabelText);
    const pathInput = document.createElement("input");
    pathInput.type = "text";
    pathInput.className = "agents-registry-path-input";
    pathInput.dataset.agentPath = "1";
    pathInput.value = agent.path || "";
    pathInput.title = agent.path || "";
    pathInput.disabled = true;
    pathInput.setAttribute("aria-disabled", "true");
    pathField.append(pathLabelRow, pathInput);

    const orchestratorWrap = document.createElement("div");
    orchestratorWrap.className = "agents-registry-field agents-registry-orchestrator-field";
    const orchestratorTitle = document.createElement("span");
    orchestratorTitle.textContent = "Оркестратор";
    const orchestratorLabel = document.createElement("label");
    orchestratorLabel.className = "agents-registry-orchestrator";
    orchestratorLabel.title = "Главный агент — координирует остальные workspace";
    const orchestratorInput = document.createElement("input");
    orchestratorInput.type = "radio";
    orchestratorInput.name = "agents-registry-orchestrator";
    orchestratorInput.checked = Boolean(agent.orchestrator);
    orchestratorInput.setAttribute("aria-label", "Главный агент");
    orchestratorInput.addEventListener("change", () => {
      if (!orchestratorInput.checked) return;
      setAgentsRegistryDraftOrchestrator(index);
    });
    orchestratorLabel.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      setAgentsRegistryDraftOrchestrator(index);
    });
    const orchestratorText = document.createElement("span");
    orchestratorText.textContent = "Главный агент";
    orchestratorText.setAttribute("aria-hidden", "true");
    orchestratorLabel.append(orchestratorInput, orchestratorText);
    orchestratorWrap.append(orchestratorTitle, orchestratorLabel);

    const commentInput = document.createElement("textarea");
    commentInput.className = "agents-registry-comment-input";
    commentInput.dataset.agentComment = "1";
    commentInput.rows = 1;
    commentInput.placeholder = "Описание";
    commentInput.value = agent.comment || "";
    commentInput.addEventListener("input", () => {
      agentsRegistryDraft[index].comment = commentInput.value;
    });

    const commentField = document.createElement("label");
    commentField.className = "agents-registry-field agents-registry-comment-field";
    commentField.innerHTML = "<span>Описание</span>";
    commentField.appendChild(commentInput);

    const environmentField = document.createElement("label");
    environmentField.className = "agents-registry-field agents-registry-environment-field";
    environmentField.innerHTML = "<span>Среда</span>";
    const environmentSelect = document.createElement("select");
    environmentSelect.className = "agents-registry-select";
    for (const option of AGENT_ENVIRONMENT_OPTIONS) {
      const optionNode = document.createElement("option");
      optionNode.value = option.value;
      optionNode.textContent = option.label;
      environmentSelect.appendChild(optionNode);
    }
    environmentSelect.value = normalizeAgentEnvironmentDraft(agent.environment);
    environmentSelect.addEventListener("change", () => {
      agentsRegistryDraft[index].environment = environmentSelect.value;
    });
    environmentField.appendChild(environmentSelect);

    const defaultWrap = document.createElement("div");
    defaultWrap.className = "agents-registry-field agents-registry-default-field";
    const defaultTitle = document.createElement("span");
    defaultTitle.textContent = "Def.";
    const defaultLabel = document.createElement("label");
    defaultLabel.className = "agents-registry-default";
    defaultLabel.title = "По умолчанию";
    const defaultInput = document.createElement("input");
    defaultInput.type = "radio";
    defaultInput.name = "agents-registry-default";
    defaultInput.checked = Boolean(agent.default) && agent.active !== false;
    defaultInput.disabled = agent.active === false;
    defaultInput.setAttribute("aria-label", "По умолчанию");
    defaultInput.addEventListener("change", () => {
      if (!defaultInput.checked || agent.active === false) return;
      for (const item of agentsRegistryDraft) item.default = false;
      agentsRegistryDraft[index].default = true;
      renderAgentsRegistryList();
    });
    const defaultText = document.createElement("span");
    defaultText.setAttribute("aria-hidden", "true");
    defaultLabel.append(defaultInput, defaultText);
    defaultWrap.append(defaultTitle, defaultLabel);

    const actionsWrap = document.createElement("div");
    actionsWrap.className = "agents-registry-row-actions";

    const activeBtn = document.createElement("button");
    activeBtn.type = "button";
    activeBtn.className = "agents-registry-active-btn";
    activeBtn.title = agent.active !== false ? "Активен — отключить" : "Неактивен — включить";
    activeBtn.setAttribute("aria-pressed", agent.active !== false ? "true" : "false");
    activeBtn.setAttribute("aria-label", agent.active !== false ? "Активен" : "Неактивен");
    activeBtn.textContent = agent.active !== false ? "●" : "○";
    activeBtn.hidden = true;
    activeBtn.addEventListener("click", () => {
      toggleAgentsRegistryDraftActive(index);
    });

    const deleteBtn = document.createElement("button");
    deleteBtn.type = "button";
    deleteBtn.className = "agents-registry-delete-btn";
    deleteBtn.textContent = "✕";
    deleteBtn.title = "Удалить из списка (без манифеста)";
    deleteBtn.setAttribute("aria-label", "Удалить из списка");
    deleteBtn.hidden = true;
    deleteBtn.disabled = agentsRegistryDraft.length <= 1;
    deleteBtn.addEventListener("click", () => {
      void removeAgentsRegistryDraftRow(index);
    });

    actionsWrap.append(activeBtn, deleteBtn);

    mainRow.append(orderWrap, nameField, commentField, environmentField, defaultWrap, actionsWrap);

    const detailsRow = document.createElement("div");
    detailsRow.className = "agents-registry-details-row";
    detailsRow.dataset.layout = "content-path";
    detailsRow.append(pathField, orchestratorWrap);

    const rowContent = document.createElement("div");
    rowContent.className = "agents-registry-row-content";
    rowContent.append(mainRow, detailsRow);

    const previewSlot = document.createElement("div");
    previewSlot.className = "agents-registry-preview-slot";
    previewSlot.tabIndex = 0;
    previewSlot.setAttribute("role", "button");
    previewSlot.setAttribute("aria-label", "Загрузить аватар");

    const previewFileInput = document.createElement("input");
    previewFileInput.type = "file";
    previewFileInput.className = "agents-registry-preview-file-input";
    previewFileInput.accept = "image/jpeg,image/png,image/gif";

    const previewPlaceholder = document.createElement("span");
    previewPlaceholder.className = "agents-registry-preview-placeholder";
    previewPlaceholder.innerHTML =
      '<span class="agents-registry-preview-placeholder-icon" aria-hidden="true">+</span><span class="agents-registry-preview-placeholder-text">JPG, PNG, GIF</span>';

    const previewRemoveBtn = document.createElement("button");
    previewRemoveBtn.type = "button";
    previewRemoveBtn.className = "agents-registry-preview-remove-btn";
    previewRemoveBtn.title = "Удалить аватар";
    previewRemoveBtn.setAttribute("aria-label", "Удалить аватар");
    previewRemoveBtn.textContent = "×";

    previewSlot.append(previewFileInput, previewPlaceholder, previewRemoveBtn);

    const rowBody = document.createElement("div");
    rowBody.className = "agents-registry-row-body";
    rowBody.append(previewSlot, rowContent);

    row.append(rowBody);
    bindRegistryPreviewSlot(row, agent, index);
    updateRegistryRowPreview(row, agent);
    agentsRegistryListNode.appendChild(row);
  });

  void refreshAgentsRegistryPathStatuses();
}

function addAgentsRegistryDraftRow() {
  openAgentDiscoverModal();
}

function openAgentsRegistryCreateModal() {
  if (!agentsRegistryCreateModalNode) return;
  if (agentsRegistryCreateNameInputNode) {
    agentsRegistryCreateNameInputNode.value = "";
  }
  if (agentsRegistryCreateDescriptionInputNode) {
    agentsRegistryCreateDescriptionInputNode.value = "";
  }
  if (agentsRegistryCreatePathInputNode) {
    agentsRegistryCreatePathInputNode.value = "./workspaces/";
  }
  clearCreateAgentFormValidation(getCreateAgentFormFields("agents-registry").fieldNodes);
  resetCreateAgentPathAutoSync("agents-registry");
  agentsRegistryCreateModalNode.classList.remove("hidden");
  window.setTimeout(() => agentsRegistryCreateNameInputNode?.focus(), 0);
}

function closeAgentsRegistryCreateModal() {
  agentsRegistryCreateModalNode?.classList.add("hidden");
  if (agentsRegistryCreateSubmitBtn) {
    agentsRegistryCreateSubmitBtn.disabled = false;
    agentsRegistryCreateSubmitBtn.textContent = "Создать";
  }
}

async function submitAgentsRegistryCreate() {
  if (!agentsRegistryCreateSubmitBtn || !agentsRegistryCreatePathInputNode) return;

  const workspacePath = normalizeCreateAgentWorkspacePath(agentsRegistryCreatePathInputNode.value.trim());
  agentsRegistryCreatePathInputNode.value = workspacePath;
  const agentName = agentsRegistryCreateNameInputNode?.value.trim() || "";
  const agentDescription = agentsRegistryCreateDescriptionInputNode?.value.trim() || "";
  const validationError = validateCreateAgentForm({
    name: agentName,
    description: agentDescription,
    path: workspacePath,
    checkDraft: true
  });
  if (validationError) {
    applyCreateAgentFormValidation("agents-registry", validationError);
    return;
  }

  agentsRegistryCreateSubmitBtn.disabled = true;
  agentsRegistryCreateSubmitBtn.textContent = "Создаю...";

  try {
    const response = await fetch("/api/agents/create", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path: workspacePath,
        name: agentName || undefined,
        comment: agentDescription || undefined
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
    }

    const data = await response.json();
    if (!applyDiscoverAgentToDraft(data.agent)) return;

    closeAgentsRegistryCreateModal();
    renderAgentsRegistryList();
    showToast("Агент создан — сохраните список", "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message ? `Ошибка создания: ${message}` : "Ошибка создания", "error");
  } finally {
    agentsRegistryCreateSubmitBtn.disabled = false;
    agentsRegistryCreateSubmitBtn.textContent = "Создать";
  }
}

function isAgentPathAlreadyInDraft(pathValue) {
  const key = normalizeRegistryPathKey(pathValue);
  return agentsRegistryDraft.some((item) => normalizeRegistryPathKey(item.path) === key);
}

function setAgentsRegistryDraftOrchestrator(index) {
  if (index < 0 || index >= agentsRegistryDraft.length) return;
  for (const item of agentsRegistryDraft) item.orchestrator = false;
  agentsRegistryDraft[index].orchestrator = true;
  renderAgentsRegistryList();
}

function syncAgentsRegistryOrchestratorFromForm() {
  if (!agentsRegistryListNode) return;
  let selectedIndex = -1;
  agentsRegistryDraft.forEach((agent, index) => {
    const row = agentsRegistryListNode.querySelector(
      `.agents-registry-row[data-registry-index="${index}"]`
    );
    const input = row?.querySelector('input[name="agents-registry-orchestrator"]');
    if (input?.checked) selectedIndex = index;
  });
  agentsRegistryDraft.forEach((agent, index) => {
    agent.orchestrator = index === selectedIndex;
  });
}

function applyDiscoverAgentToDraft(discovered) {
  const entry = {
    id: discovered.id,
    path: discovered.path,
    environment: "local",
    name: getDiscoverAgentDisplayName(discovered),
    comment: getDiscoverAgentDisplayComment(discovered),
    manifestFound: true,
    hasPreview: Boolean(
      discovered.hasPreview || discovered.previewRel || discovered.manifest?.preview
    ),
    previewUrl: null,
    previewRel: discovered.previewRel || discovered.manifest?.preview || null,
    active: true,
    default: agentsRegistryDraft.length === 0,
    orchestrator: false
  };

  if (isAgentPathAlreadyInDraft(entry.path)) {
    showToast("Этот агент уже в списке", "error");
    return false;
  }
  agentsRegistryDraft.push(entry);
  return true;
}

async function loadAgentDiscoverResults() {
  if (!agentsRegistryDiscoverListNode) return;
  agentsRegistryDiscoverListNode.innerHTML = `<div class="agents-registry-discover-status">Сканирование workspace с manifest.md (awn.page.ws)…</div>`;
  try {
    const response = await fetch("/api/agents/discover", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ maxDepth: 6 })
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    renderAgentDiscoverResults(Array.isArray(data.agents) ? data.agents : []);
  } catch (error) {
    agentsRegistryDiscoverListNode.innerHTML = `<div class="agents-registry-discover-status">Ошибка: ${escapeHtml(error.message)}</div>`;
  }
}

function getDiscoverAgentDisplayName(item) {
  return String(item?.manifest?.name || item?.name || item?.id || "Agent").trim() || "Agent";
}

function getDiscoverAgentDisplayComment(item) {
  return String(item?.manifest?.comment ?? item?.comment ?? "").trim();
}

function renderAgentDiscoverResults(items) {
  if (!agentsRegistryDiscoverListNode) return;
  agentsRegistryDiscoverListNode.innerHTML = "";
  if (items.length === 0) {
    agentsRegistryDiscoverListNode.innerHTML = `<div class="agents-registry-discover-status">Папки agent-* с manifest.md (awn.page.ws) не найдены</div>`;
    return;
  }

  for (const item of items) {
    const displayName = getDiscoverAgentDisplayName(item);
    const displayComment = getDiscoverAgentDisplayComment(item);
    const row = document.createElement("button");
    row.type = "button";
    row.className = "agents-registry-discover-item";

    const previewSlot = document.createElement("div");
    previewSlot.className = "agents-registry-preview-slot agents-registry-discover-preview";

    const previewHint =
      item.previewRel || item.manifest?.preview || item.hasPreview ? displayName.charAt(0).toUpperCase() : "+";
    const previewFallback = document.createElement("span");
    previewFallback.className = "agents-registry-discover-preview-fallback";
    previewFallback.textContent = previewHint;
    previewSlot.appendChild(previewFallback);

    if (item.path && (item.hasPreview || item.previewRel || item.manifest?.preview)) {
      const img = document.createElement("img");
      img.className = "agents-registry-preview-thumb";
      img.alt = displayName;
      img.draggable = false;
      img.src = appendCacheBuster(`/api/agents/workspace-preview?path=${encodeURIComponent(item.path)}`);
      img.onload = () => {
        previewSlot.classList.add("has-image");
        previewFallback.remove();
      };
      img.onerror = () => img.remove();
      previewSlot.appendChild(img);
    }

    const meta = document.createElement("div");
    meta.className = "agents-registry-discover-meta";
    meta.innerHTML = `
      <div class="agents-registry-discover-name">${escapeHtml(displayName)}</div>
      <div class="agents-registry-discover-path">${escapeHtml(item.path || "")}</div>
      ${displayComment ? `<div class="agents-registry-discover-comment">${escapeHtml(displayComment)}</div>` : ""}
    `;

    row.append(previewSlot, meta);
    row.addEventListener("click", () => {
      if (!applyDiscoverAgentToDraft(item)) return;
      closeAgentDiscoverModal();
      renderAgentsRegistryList();
      showToast("Агент добавлен", "success");
    });
    agentsRegistryDiscoverListNode.appendChild(row);
  }
}

function openAgentDiscoverModal() {
  agentsRegistryDiscoverModalNode?.classList.remove("hidden");
  void loadAgentDiscoverResults();
}

function closeAgentDiscoverModal() {
  agentsRegistryDiscoverModalNode?.classList.add("hidden");
  if (agentsRegistryDiscoverListNode) agentsRegistryDiscoverListNode.innerHTML = "";
}

async function saveAgentsRegistryDraft() {
  if (!agentsRegistrySaveBtn) return;
  syncAgentsRegistryOrchestratorFromForm();
  agentsRegistrySaveBtn.disabled = true;
  agentsRegistrySaveBtn.textContent = "Сохраняю...";

  try {
    const response = await fetch("/api/agents/registry", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        agents: agentsRegistryDraft.map(
          ({ path, environment, default: isDefault, orchestrator: isOrchestrator, active, name, comment }) => ({
            path,
            environment,
            default: isDefault,
            orchestrator: Boolean(isOrchestrator),
            active: active !== false,
            name: name ?? "",
            comment: comment ?? ""
          })
        )
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
    }

    const data = await response.json();
    await loadAgents();
    const wasOnLanding = appRootNode?.classList.contains("app-landing-view");
    const previousAgentId = activeAgentId;
    if (
      !wasOnLanding &&
      activeAgentId &&
      (!agentsCache.some((agent) => agent.id === activeAgentId) ||
        !getSelectableAgents().some((agent) => agent.id === activeAgentId))
    ) {
      activeAgentId = data.defaultAgentId || getSelectableAgents()[0]?.id || agentsCache[0]?.id || "main";
      localStorage.setItem(ACTIVE_AGENT_STORAGE_KEY, activeAgentId);
      syncAgentToUrl(activeAgentId);
    }
    renderAgentSelect();
    syncAgentPreview();
    closeAgentsRegistryModal();

    if (wasOnLanding) {
      renderAppLandingAgents();
      renderLandingSearchAgents();
    } else if (previousAgentId !== activeAgentId) {
      activePath = null;
      activeLabel = null;
      clearActiveSystemFile();
      clearMediaSidecarEditor();
      showAgentHomeView();
      await loadSystemFiles();
    }
    if (!wasOnLanding && activeAgentId) {
      await refreshMenu();
    }
    showToast("Список агентов сохранён", "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message ? `Ошибка сохранения агентов: ${message}` : "Ошибка сохранения агентов", "error");
  } finally {
    agentsRegistrySaveBtn.disabled = false;
    agentsRegistrySaveBtn.textContent = "Сохранить";
  }
}

