function renderDataHubAllItemsPanelLoading(container) {
  renderDataHubPanelEmptyState(container, {
    icon: "📋",
    message: "Сканирование awn-storage…",
    variant: "loading"
  });
}

function loadDataHubAllItemsPanel(container) {
  renderDataHubAllItemsPanelLoading(container);
  return fetchStorageRootScan()
    .then((scan) => {
      if (isDataHubAllSlotsPanelStale()) return;
      renderDataHubAllItemsPanel(container, scan);
    })
    .catch(() => {
      if (isDataHubAllSlotsPanelStale()) return;
      renderDataHubPanelEmptyState(container, {
        icon: "⚠",
        message: "Не удалось просканировать awn-storage",
        variant: "error"
      });
    });
}

function invalidateStorageRootScanCache(manifestPath = getActiveNodeApiPath()) {
  if (manifestPath) storageRootScanCache.delete(manifestPath);
  if (!manifestPath || manifestPath === getActiveNodeApiPath()) {
    activeStorageRootScan = null;
    const slotTree = getStorageSlotTreeNode();
    if (slotTree) delete slotTree.dataset.storageScanManifest;
  }
}

async function fetchStorageRootScan(manifestPath = getActiveNodeApiPath(), { force = false } = {}) {
  if (!manifestPath) {
    return { exists: false, folders: [], looseFiles: [], bundleSlots: {}, totalEntries: 0, storageRoot: "" };
  }
  if (!force) {
    const cached = storageRootScanCache.get(manifestPath);
    if (cached) {
      activeStorageRootScan = cached;
      return cached;
    }
    const inflight = storageRootScanInflight.get(manifestPath);
    if (inflight) return inflight;
  }

  const promise = (async () => {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), STORAGE_ROOT_SCAN_TIMEOUT_MS);
    try {
      const response = await fetch(buildApiUrl("/api/storage/scan", { path: manifestPath }), {
        signal: controller.signal
      });
      if (!response.ok) throw new Error(`Storage scan failed (${response.status})`);
      const data = await response.json();
      storageRootScanCache.set(manifestPath, data);
      activeStorageRootScan = data;
      return data;
    } finally {
      clearTimeout(timeoutId);
      storageRootScanInflight.delete(manifestPath);
    }
  })();

  if (!force) storageRootScanInflight.set(manifestPath, promise);
  return promise;
}

function getStorageFolderNamesForSlotKey(slotKey) {
  const namesByKey = {
    memory: ["main", "content", "memory"],
    inbox: ["inbox"],
    note: ["notes", "note", "quick-notes"],
    references: ["references"],
    artefacts: ["artefacts"],
    assets: ["assets"],
    repository: ["repository"],
    media: ["media"],
    scripts: ["scripts"],
    thread: ["thread"],
    temp: ["temp"],
    volume: ["volume"],
    history: ["history"],
    comments: ["comments"]
  };
  return namesByKey[slotKey] || [];
}

const HIDDEN_STORAGE_SLOT_TREE_KEYS = new Set(["quick-notes"]);

function findScanFolderForSlotKey(slotKey, folders = []) {
  const names = new Set(getStorageFolderNamesForSlotKey(slotKey).map((name) => name.toLowerCase()));
  if (!names.size) return null;
  const matched = folders.filter((folder) => {
    const canonical = String(folder.canonical || folder.name || "").toLowerCase();
    const name = String(folder.name || "").toLowerCase();
    return names.has(canonical) || names.has(name);
  });
  if (!matched.length) return null;
  if (matched.length === 1) return matched[0];
  return {
    name: matched.map((folder) => folder.name).join("+"),
    canonical: matched[0].canonical || matched[0].name,
    entryCount: matched.reduce((sum, folder) => sum + (Number(folder.entryCount) || 0), 0),
    subfolderCount: matched.reduce((sum, folder) => sum + (Number(folder.subfolderCount) || 0), 0),
    slotKey,
    matched: true
  };
}

function applyRepositoryStorageSlotTreeCount(container, count) {
  const btn = container?.querySelector('.storage-slot-tree-item[data-storage-slot="repository"]');
  if (!btn) return;
  const label = btn.querySelector(".media-section-tree-label")?.textContent?.trim() || "Репозитории";
  const normalized = Number(count) || 0;
  const badge = btn.querySelector(".media-section-tree-count");
  if (badge) {
    badge.textContent = normalized > 0 ? String(normalized) : "";
    badge.dataset.baseCount = String(normalized);
  }
  btn.title = getRepositorySlotCounterTitle(label, normalized);
}

function refreshRepositoryStorageSlotTreeCount(container, manifestPath = getActiveNodeApiPath()) {
  if (!container || !manifestPath) return;
  void fetchFolderViewSummary(manifestPath, "repository").then((summary) => {
    if (!container.isConnected) return;
    if (
      container.dataset.storageScanManifest &&
      container.dataset.storageScanManifest !== String(manifestPath)
    ) {
      return;
    }
    applyRepositoryStorageSlotTreeCount(container, summary.subfolders);
  });
}

function markScanFoldersConsumedForSlotKey(consumed, slotKey, folders = []) {
  const names = new Set(getStorageFolderNamesForSlotKey(slotKey).map((name) => name.toLowerCase()));
  for (const folder of folders) {
    const canonical = String(folder.canonical || folder.name || "").toLowerCase();
    const name = String(folder.name || "").toLowerCase();
    if (names.has(canonical) || names.has(name)) {
      markScanFolderConsumed(consumed, folder);
    }
  }
}

function markScanFolderConsumed(consumed, folder) {
  if (!folder) return;
  consumed.add(String(folder.canonical || folder.name).toLowerCase());
  consumed.add(String(folder.name).toLowerCase());
}

function buildStorageSlotTreeModel(scan = {}) {
  const folders = scan.exists ? scan.folders || [] : [];
  const bundleSlots = scan.bundleSlots || {};
  const consumed = new Set();
  const entries = [];
  const enabledSpecs = DATA_STORAGE_SLOT_SPECS.filter((spec) => !spec.disabled);
  const folderSpecs = enabledSpecs.filter(
    (spec) => getStorageSlotTreeGroup(spec) === STORAGE_SLOT_TREE_GROUP_FOLDER
  );
  const filesSpecs = enabledSpecs.filter(
    (spec) => getStorageSlotTreeGroup(spec) === STORAGE_SLOT_TREE_GROUP_FILES
  );
  const singleFileSpecs = enabledSpecs.filter(
    (spec) => getStorageSlotTreeGroup(spec) === STORAGE_SLOT_TREE_GROUP_SINGLE_FILE
  );

  for (const spec of folderSpecs) {
    const folder = findScanFolderForSlotKey(spec.key, folders);
    markScanFoldersConsumedForSlotKey(consumed, spec.key, folders);
    entries.push({ kind: "slot", spec, folder });
  }

  if (filesSpecs.length > 0) {
    entries.push({
      kind: "group-label",
      id: "files-slots",
      label: STORAGE_SLOT_TREE_GROUP_LABELS[STORAGE_SLOT_TREE_GROUP_FILES]
    });
    for (const spec of filesSpecs) {
      const folder = findScanFolderForSlotKey(spec.key, folders);
      markScanFoldersConsumedForSlotKey(consumed, spec.key, folders);
      entries.push({ kind: "slot", spec, folder });
    }
  }

  if (singleFileSpecs.length > 0) {
    entries.push({
      kind: "group-label",
      id: "single-file-slots",
      label: STORAGE_SLOT_TREE_GROUP_LABELS[STORAGE_SLOT_TREE_GROUP_SINGLE_FILE]
    });
    for (const spec of singleFileSpecs) {
      entries.push({
        kind: "slot",
        spec,
        folder: null,
        bundleSlot: bundleSlots[spec.key] || null
      });
    }
  }

  const metaSpecs = STORAGE_SLOT_TREE_META_ORDER.map((key) =>
    DATA_STORAGE_SLOT_SPECS.find((spec) => spec.key === key)
  ).filter(Boolean);
  if (metaSpecs.length > 0) {
    entries.push({ kind: "divider", id: "meta-slots" });
    entries.push({
      kind: "group-label",
      id: "meta-slots",
      label: STORAGE_SLOT_TREE_GROUP_LABELS[STORAGE_SLOT_TREE_GROUP_META]
    });
    for (const spec of metaSpecs) {
      const folder = findScanFolderForSlotKey(spec.key, folders);
      markScanFoldersConsumedForSlotKey(consumed, spec.key, folders);
      entries.push({ kind: "slot", spec, folder });
    }
  }

  const communicationSpecs = STORAGE_SLOT_TREE_COMMUNICATION_ORDER.map((key) =>
    DATA_STORAGE_SLOT_SPECS.find((spec) => spec.key === key)
  ).filter(Boolean);
  if (communicationSpecs.length > 0) {
    entries.push({ kind: "divider", id: "communication-slots" });
    entries.push({
      kind: "group-label",
      id: "communication-slots",
      label: STORAGE_SLOT_TREE_GROUP_LABELS[STORAGE_SLOT_TREE_GROUP_COMMUNICATION]
    });
    for (const spec of communicationSpecs) {
      const folder = findScanFolderForSlotKey(spec.key, folders);
      markScanFoldersConsumedForSlotKey(consumed, spec.key, folders);
      entries.push({ kind: "slot", spec, folder });
    }
  }

  const sharedMounts = Array.isArray(scan.sharedMounts) ? scan.sharedMounts : [];
  if (sharedMounts.length > 0 && !isActiveSharedThemeStorageContext(scan)) {
    entries.push({ kind: "divider", id: "shared-mounts" });
    entries.push({
      kind: "group-label",
      id: "shared-mounts",
      label: STORAGE_SLOT_TREE_GROUP_LABELS[STORAGE_SLOT_TREE_GROUP_SHARED]
    });
    for (const mount of sharedMounts) {
      entries.push({ kind: "shared-mount", mount });
    }
  }

  const disabledSpecs = DATA_STORAGE_SLOT_SPECS.filter(
    (spec) =>
      spec.disabled &&
      !HIDDEN_STORAGE_SLOT_TREE_KEYS.has(spec.key) &&
      !STORAGE_SLOT_TREE_SPECIAL_BLOCK_KEYS.has(spec.key)
  );
  if (disabledSpecs.length > 0) {
    entries.push({ kind: "divider", id: "disabled-slots" });
    for (const spec of disabledSpecs) {
      const folder = findScanFolderForSlotKey(spec.key, folders);
      markScanFoldersConsumedForSlotKey(consumed, spec.key, folders);
      entries.push({ kind: "slot", spec, folder });
    }
  }

  const orphans = sortStorageScanFolders(
    folders.filter((folder) => {
      const canonical = String(folder.canonical || folder.name).toLowerCase();
      const name = String(folder.name).toLowerCase();
      return !consumed.has(canonical) && !consumed.has(name);
    })
  );

  if (orphans.length > 0) {
    entries.push({ kind: "divider", id: "orphan-folders" });
    for (const folder of orphans) {
      entries.push({ kind: "orphan", folder });
    }
  }

  return entries;
}

function sortStorageScanFolders(folders = []) {
  const slotOrder = DATA_STORAGE_SLOT_SPECS.map((spec) => spec.key);
  return [...folders].sort((a, b) => {
    if (a.matched !== b.matched) return a.matched ? -1 : 1;
    const indexA = a.slotKey ? slotOrder.indexOf(a.slotKey) : Number.MAX_SAFE_INTEGER;
    const indexB = b.slotKey ? slotOrder.indexOf(b.slotKey) : Number.MAX_SAFE_INTEGER;
    if (indexA !== indexB) return indexA - indexB;
    return String(a.name || "").localeCompare(String(b.name || ""), "ru");
  });
}

function getStorageScanFolderSpec(folder) {
  if (!folder?.slotKey) return null;
  return DATA_STORAGE_SLOT_SPECS.find((spec) => spec.key === folder.slotKey) || null;
}

function setActiveDataStorageAllItems() {
  activeDataStorageAllItems = true;
  syncStorageSlotTreeActiveState(getStorageSlotTreeNode());
  syncListViewHead();
  renderListViewContent();
  syncAppRouteToUrl({ replace: true });
}

function shouldUseDataHubListShell(mode = activeContentMode) {
  if (!getDataStorageSlotForMode(mode)) return false;
  if (mode === NODE_THREAD_MODE) return false;
  if (mode === "internal" || mode === "todo") return true;
  if (mode === "external" && isExternalFileEditing()) return false;
  if (mode === "media" && isMediaAssetEditing()) return false;
  if (mode === "tabular" && isTabularSourceEditing()) return false;
  return true;
}

function isBundleSingleFileSlotMode(mode = activeContentMode) {
  const spec = getDataStorageSlotForMode(mode);
  return (
    spec?.sectionKind === "bundle" && spec?.treeGroup === STORAGE_SLOT_TREE_GROUP_SINGLE_FILE
  );
}

function isDataHubBundleSlotShellMode(mode = activeContentMode) {
  return isBundleSingleFileSlotMode(mode) && shouldUseDataHubListShell(mode);
}

function isDataHubBundlePreviewActive(mode = activeContentMode) {
  return isDataHubBundleSlotShellMode(mode) && dataHubBundleEntryView === MEMORY_ENTRY_VIEW_OVERVIEW;
}

function resetDataHubBundleEntryView(mode = activeContentMode) {
  if (isBundleSingleFileSlotMode(mode)) {
    dataHubBundleEntryView = MEMORY_ENTRY_VIEW_OVERVIEW;
  }
}

function isDataHubBundleEditorMode(mode = activeContentMode) {
  return isDataHubBundleSlotShellMode(mode) && dataHubBundleEntryView === MEMORY_ENTRY_VIEW_LIST;
}

async function ensureDataHubBundleEditorContent(mode = activeContentMode) {
  if (!activePath) return;
  const apiPath = getActiveNodeApiPath();
  if (!apiPath) return;

  fileContentInputNode.readOnly = false;

  if (mode === "internal") {
    const response = await fetch(buildApiUrl("/api/memory/internal", { path: apiPath }));
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    modeContentCache.internal = data.content || "";
    fileContentInputNode.value = modeContentCache.internal;
    return;
  }

  if (mode === "todo") {
    const response = await fetch(buildApiUrl("/api/todo", { path: apiPath }));
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    modeContentCache.todo = data.content || "";
    fileContentInputNode.value = modeContentCache.todo;
    return;
  }

  if (mode === "tabular") {
    const response = await fetch(buildApiUrl("/api/memory/tabular", { path: apiPath }));
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    modeContentCache.tabular = data.content || "";
    tabularDataCache = {
      columns: Array.isArray(data.columns) ? data.columns : [],
      rows: Array.isArray(data.rows) ? data.rows : [],
      rowCount: data.rowCount || 0
    };
    fileContentInputNode.value = data.content || "";
  }
}

function activateDataHubBundleEditorUi(mode = activeContentMode) {
  if (!isDataHubBundleEditorMode(mode)) return;
  if (mode === "tabular") {
    setEditorViewMode("source", { skipRouteSync: true });
  } else if (isWysiwygEditorEnabled()) {
    setEditorViewMode("wysiwyg", { skipRouteSync: true });
  } else {
    setEditorViewMode("source", { skipRouteSync: true });
  }
  refreshEditorViewContent();
  syncDataHubBundleEditorPlacement();
  applyModeUi();
  syncSaveButtonLamp();
}

function finishDataHubBundleEditorOpen(mode = activeContentMode) {
  if (!isDataHubBundleEditorMode(mode)) return;
  void ensureDataHubBundleEditorContent(mode)
    .catch(() => {
      fileContentInputNode.value = "";
      fileContentInputNode.readOnly = false;
    })
    .finally(() => activateDataHubBundleEditorUi(mode));
}

function openDataHubBundleSlotEditor(mode = activeContentMode) {
  const spec = getDataStorageSlotForMode(mode);
  const memoryKind = getEntryOverviewMemoryKindForSlot(spec);
  if (memoryKind) {
    applyDataHubBundleEntryViewChange(memoryKind, MEMORY_ENTRY_VIEW_LIST);
  } else {
    dataHubBundleEntryView = MEMORY_ENTRY_VIEW_LIST;
    renderListViewContent();
    syncNodeMemoryEntryViewSelect();
    finishDataHubBundleEditorOpen(mode);
  }
}

function syncDataHubBundleEditorPlacement() {
  if (!editorSurfaceNode) return;

  const panelBody = getDataHubPanelBodyNode();
  const editMode = isDataHubBundleEditorMode();

  if (editMode && panelBody) {
    if (!dataHubBundleEditorRestoreParent) {
      dataHubBundleEditorRestoreParent = editorSurfaceNode.parentElement;
    }
    if (editorSurfaceNode.parentElement !== panelBody) {
      panelBody.appendChild(editorSurfaceNode);
    }
    editorSurfaceNode.classList.add("data-hub-bundle-editor-surface");
    return;
  }

  if (dataHubBundleEditorRestoreParent && editorSurfaceNode.parentElement !== dataHubBundleEditorRestoreParent) {
    dataHubBundleEditorRestoreParent.appendChild(editorSurfaceNode);
  }
  editorSurfaceNode.classList.remove("data-hub-bundle-editor-surface");
}

async function renderDataHubBundleSlotPanel(container, mode = activeContentMode) {
  if (!container) return;
  container.replaceChildren();

  const spec = getDataStorageSlotForMode(mode);
  if (!spec) return;

  if (isDataHubBundleEditorMode(mode)) {
    syncDataHubBundleEditorPlacement();
    return;
  }

  syncDataHubBundleEditorPlacement();

  if (mode === "tabular") {
    if (!isDataHubBundlePreviewActive(mode)) {
      return;
    }
    const { columns, rows } = tabularDataCache;
    if (!columns.length && !rows.length) {
      renderDataHubPanelEmptyState(container, {
        icon: spec.icon || "📄",
        message: "Файл ещё не создан. Создайте содержимое, чтобы оно появилось в этом слоте.",
        path: spec.bundleFile || "",
        variant: "missing",
        actionLabel: "Создать",
        onAction: () => openDataHubBundleSlotEditor(mode)
      });
      return;
    }
    const wrap = document.createElement("div");
    wrap.className = "data-hub-bundle-preview";
    const body = document.createElement("div");
    body.className = "data-hub-bundle-preview-body data-hub-bundle-tabular-preview";
    wrap.appendChild(body);
    container.appendChild(wrap);
    renderTabularTableView(body);
    return;
  }

  if (!isDataHubBundlePreviewActive(mode)) {
    renderDataHubPanelEmptyState(container, {
      icon: spec.icon || "📄",
      message: "Переключите вид на «Просмотр», чтобы увидеть содержимое.",
      path: spec.bundleFile || "",
      variant: "muted"
    });
    return;
  }

  const memoryKind = getEntryOverviewMemoryKindForSlot(spec);
  if (!memoryKind) return;

  renderDataHubPanelEmptyState(container, {
    icon: spec.icon || "📄",
    message: "Загрузка…",
    variant: "loading"
  });

  try {
    const text = await fetchBundleMemoryTextContent(memoryKind);
    if (activeContentMode !== mode || !isDataHubBundlePreviewActive(mode)) {
      return;
    }

    container.replaceChildren();
    const meaningful =
      memoryKind === "todo"
        ? getBundleMemoryMeaningfulBody(text)
        : stripAwnDescCallouts(splitFrontmatter(String(text)).body).trim();

    if (!String(meaningful || "").trim()) {
      renderDataHubPanelEmptyState(container, {
        icon: spec.icon || "📄",
        message: "Файл ещё не создан. Создайте содержимое, чтобы оно появилось в этом слоте.",
        path: spec.bundleFile || "",
        variant: "missing",
        actionLabel: "Создать",
        onAction: () => openDataHubBundleSlotEditor(mode)
      });
      return;
    }

    const wrap = document.createElement("div");
    wrap.className = "data-hub-bundle-preview";

    const preview = document.createElement("div");
    preview.className =
      "data-hub-bundle-preview-body file-content-preview node-navigation-preview";
    const nodePath = getResolvedNodePath(activePath);
    if (memoryKind === "todo") {
      setMarkdownPreviewHtml(preview, text, { nodePath });
    } else {
      setMarkdownPreviewHtml(preview, meaningful, { nodePath });
    }
    enhanceMarkdownPreviewImages(preview);
    wrap.appendChild(preview);
    container.appendChild(wrap);
  } catch (error) {
    if (activeContentMode !== mode) return;
    container.replaceChildren();
    renderDataHubPanelEmptyState(container, {
      icon: "⚠",
      message: `Не удалось загрузить файл: ${error.message}`,
      variant: "error"
    });
  }
}

function getStorageSlotTreeNode() {
  return listViewContentNode?.querySelector(".data-hub-list-view-wrap .storage-slot-tree") || null;
}

function refreshStorageSlotTree() {
  invalidateStorageRootScanCache();
  void renderStorageSlotTree(getStorageSlotTreeNode(), { force: true });
}

function getDataHubPanelNode() {
  return listViewContentNode?.querySelector(".data-hub-list-view-wrap .data-hub-panel") || null;
}

function ensureDataHubPanelBody(panel) {
  if (!panel) return null;
  let panelBody = panel.querySelector(":scope > .data-hub-panel-body");
  if (panelBody) return panelBody;
  panelBody = document.createElement("div");
  panelBody.className = "data-hub-panel-body";
  const toMove = [...panel.childNodes].filter(
    (node) => !(node.nodeType === Node.ELEMENT_NODE && node.classList?.contains("list-view-head")),
  );
  for (const node of toMove) {
    panelBody.appendChild(node);
  }
  panel.appendChild(panelBody);
  return panelBody;
}

function getDataHubPanelBodyNode() {
  const panel = getDataHubPanelNode();
  return panel ? ensureDataHubPanelBody(panel) : null;
}

function syncDataHubPanelHeadPlacement() {
  const useDataHub =
    shouldUseDataHubListShell() &&
    listViewBlockNode &&
    !listViewBlockNode.classList.contains("hidden");
  const head = listViewBlockNode?.querySelector(":scope > .list-view-head");
  if (!head) return;
  head.classList.toggle("hidden", useDataHub);
}

function shouldRenderStorageSlotTree(container, manifestPath = getActiveNodeApiPath()) {
  if (!container) return false;
  if (container.querySelector(":scope > .storage-slot-tree-loading")) return false;
  const renderedFor = String(container.dataset.storageScanManifest || "");
  const nextPath = String(manifestPath || "");
  return !container.querySelector(":scope > .storage-slot-tree-list") || renderedFor !== nextPath;
}

function ensureDataHubShell() {
  let wrap = listViewContentNode.querySelector(".data-hub-list-view-wrap");
  if (wrap) {
    ensureDataHubPanelBody(wrap.querySelector(".data-hub-panel"));
    const slotTree = wrap.querySelector(".storage-slot-tree");
    if (shouldRenderStorageSlotTree(slotTree)) {
      void renderStorageSlotTree(slotTree);
    } else {
      syncStorageSlotTreeActiveState(slotTree);
    }
    syncStorageSectionsPanelUi();
    syncDataHubPanelHeadPlacement();
    return wrap;
  }
  listViewContentNode.innerHTML = "";
  wrap = document.createElement("div");
  wrap.className = "data-hub-list-view-wrap";

  const split = document.createElement("div");
  split.className = "data-hub-list-view-split";

  const slotTree = document.createElement("nav");
  slotTree.className = "storage-slot-tree";
  slotTree.setAttribute("aria-label", "Слоты storage");
  split.appendChild(slotTree);

  const panel = document.createElement("div");
  panel.className = "data-hub-panel";
  const panelBody = document.createElement("div");
  panelBody.className = "data-hub-panel-body";
  panel.appendChild(panelBody);
  split.appendChild(panel);

  wrap.appendChild(split);
  listViewContentNode.appendChild(wrap);
  void renderStorageSlotTree(slotTree);
  syncStorageSectionsPanelUi();
  syncDataHubPanelHeadPlacement();
  return wrap;
}

function getListViewMountRoot(mode = activeContentMode) {
  if (shouldUseDataHubListShell(mode)) {
    ensureDataHubShell();
    syncDataHubPanelHeadPlacement();
    return getDataHubPanelBodyNode() || listViewContentNode;
  }
  syncDataHubPanelHeadPlacement();
  return listViewContentNode;
}

function getRepositoryStorageSlotScanCount(folder) {
  const subfolders = Number(folder?.subfolderCount);
  if (Number.isFinite(subfolders) && subfolders >= 0) return subfolders;
  return Number(folder?.entryCount) || 0;
}

function getDataStorageSlotCountForScan(spec, folder, bundleSlot = null) {
  if (isStorageSlotCountOnly(spec)) {
    return Number(folder?.entryCount) || 0;
  }
  if (spec?.treeGroup === STORAGE_SLOT_TREE_GROUP_SINGLE_FILE) {
    const count = Number(bundleSlot?.entryCount) || 0;
    return count > 0 ? count : null;
  }
  if (spec?.key === "repository") {
    const count = getRepositoryStorageSlotScanCount(folder);
    return count > 0 ? count : null;
  }
  const entryCount = Number(folder?.entryCount);
  return entryCount > 0 ? entryCount : null;
}

function getRepositorySlotCounterTitle(label, count) {
  if (count <= 0) return `${label}: пусто`;
  const mod10 = count % 10;
  const mod100 = count % 100;
  let noun = "репозиториев";
  if (mod10 === 1 && mod100 !== 11) noun = "репозиторий";
  else if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) noun = "репозитория";
  return `${label}: ${count} ${noun}`;
}

function setActiveDataStorageSlotFromOverview(spec) {
  if (!spec || spec.disabled || isStorageSlotCountOnly(spec)) return;
  const memoryKind = getEntryOverviewMemoryKindForSlot(spec);
  if (memoryKind && supportsDataEntryOverview(spec.key)) {
    if (isBundleEntryOverviewMemoryKind(memoryKind)) {
      if (
        activeContentMode === NODE_ENTRY_OVERVIEW_MODE &&
        activeEntryOverviewContext?.memoryKind === memoryKind &&
        !isEntryOverviewMemoryTocRoot(activeEntryOverviewContext)
      ) {
        return;
      }
      openEntryOverviewBundleSlotFromNavigation(memoryKind);
      return;
    }
    if (
      activeEntryOverviewContext?.memoryKind === memoryKind &&
      isEntryOverviewMemoryTocRoot(activeEntryOverviewContext)
    ) {
      return;
    }
    openEntryOverviewMemoryTocFromNavigation(memoryKind);
    return;
  }
  setActiveDataStorageSlot(spec);
}

function setActiveDataStorageSlot(spec) {
  if (!spec || spec.disabled || isStorageSlotCountOnly(spec)) return;
  activeDataStorageAllItems = false;
  if (spec.sectionKind === "bundle") {
    dataHubBundleEntryView = MEMORY_ENTRY_VIEW_OVERVIEW;
  }
  if (spec.key === "thread") clearActiveThreadScope();
  const targetMode = spec.modes.has(activeContentMode) ? activeContentMode : spec.defaultMode;
  if (activeContentMode === targetMode) {
    syncStorageSlotTreeActiveState(getStorageSlotTreeNode());
    renderListViewContent();
    applyModeUi();
    syncAppRouteToUrl({ replace: true });
    return;
  }
  setContentMode(targetMode);
}

function setActiveDataMemoryModeFromOverview(mode) {
  if (!DATA_MEMORY_MODE_SPECS.some((item) => item.mode === mode)) return;
  if (mode === "external" && supportsDataEntryOverview("memory")) {
    if (
      activeEntryOverviewContext?.memoryKind === "external" &&
      isEntryOverviewMemoryTocRoot(activeEntryOverviewContext)
    ) {
      return;
    }
    openEntryOverviewMemoryTocFromNavigation("external");
    return;
  }
  setActiveDataMemoryMode(mode);
}

function setActiveDataMemoryMode(mode) {
  if (!DATA_MEMORY_MODE_SPECS.some((item) => item.mode === mode)) return;
  activeDataStorageAllItems = false;
  if (activeContentMode === mode) {
    syncStorageSlotTreeActiveState(getStorageSlotTreeNode());
    renderListViewContent();
    applyModeUi();
    syncAppRouteToUrl({ replace: true });
    return;
  }
  setContentMode(mode);
}

function isStorageScanFolderDisabled(folder, spec = null) {
  if (spec) return Boolean(spec.disabled);
  if (!folder?.matched) return true;
  const folderSpec = getStorageScanFolderSpec(folder);
  return Boolean(folderSpec?.disabled);
}

function appendStorageSlotTreeItem(
  list,
  { spec = null, folder = null, bundleSlot = null },
  {
    activeSlot,
    sectionFilterActive,
    allItemsActive = false,
    useEntryOverviewNavigation = false,
    activeSlotKey = null
  } = {}
) {
  const slotKey = spec?.key || folder?.slotKey || null;
  const isOrphan = !spec && Boolean(folder);
  const isCountOnly = isStorageSlotCountOnly(spec);
  const disabled = isCountOnly ? false : isStorageScanFolderDisabled(folder, spec);
  const isMemorySlot = slotKey === "memory";
  const label = spec?.label || folder?.name || "";
  const icon = spec?.icon || "📁";
  const isActive =
    !isCountOnly &&
    !disabled &&
    !allItemsActive &&
    (isMemorySlot
      ? useEntryOverviewNavigation
        ? activeSlotKey === "memory"
        : isDataStorageSlotActive("memory") && activeContentMode === "external"
      : useEntryOverviewNavigation
        ? activeSlotKey === slotKey
        : activeSlot?.key === slotKey);
  const count = isCountOnly
    ? getDataStorageSlotCountForScan(spec, folder, bundleSlot)
    : disabled
      ? folder?.entryCount > 0
        ? folder.entryCount
        : null
      : spec
        ? getDataStorageSlotCountForScan(spec, folder, bundleSlot)
        : folder?.entryCount > 0
          ? folder.entryCount
          : null;
  const btn = appendMediaSectionTreeItem(list, {
    icon,
    label,
    count: isCountOnly ? count : count > 0 ? count : null,
    isActive: isActive && !sectionFilterActive,
    onClick:
      isCountOnly || disabled
        ? () => {}
        : () => {
          if (!spec) return;
          if (useEntryOverviewNavigation) {
            if (isMemorySlot) {
              setActiveDataMemoryModeFromOverview("external");
              return;
            }
            setActiveDataStorageSlotFromOverview(spec);
            return;
          }
          if (isMemorySlot) {
            setActiveDataMemoryMode("external");
            return;
          }
          setActiveDataStorageSlot(spec);
        }
  });
  btn.dataset.storageSlot = slotKey || folder?.name || "";
  if (isOrphan) btn.dataset.storageOrphan = folder.name;
  btn.classList.add("storage-slot-tree-item");
  if (isCountOnly) {
    btn.classList.add("storage-slot-tree-item--count-only");
    btn.setAttribute("aria-disabled", "true");
    btn.title = `${label} · ${count} файл(ов)`;
  } else if (disabled) {
    btn.disabled = true;
    btn.classList.add("is-disabled");
    if (isOrphan) btn.title = "Папка не сопоставлена ни с одним слотом";
    else if (spec?.disabled) btn.title = "Скоро";
  }
  const badge = btn.querySelector(".media-section-tree-count");
  if (badge && count !== null) badge.dataset.baseCount = String(count);
  if (spec?.key === "repository" && count !== null) {
    btn.title = getRepositorySlotCounterTitle(label, count);
  }

  if (
    !disabled &&
    !isCountOnly &&
    slotKey &&
    slotKey !== "thread" &&
    getTopicSchemaTargetForStorageSlot(slotKey)
  ) {
    const row = btn.closest(".media-section-tree-row");
    row?.appendChild(createStorageSlotSchemaButton(slotKey));
  }

  const sharedMount = findSharedMountForSlotKey(slotKey);
  if (sharedMount && !isCountOnly && !isActiveSharedThemeStorageContext()) {
    const sharedRow = btn.closest(".media-section-tree-row");
    sharedRow?.appendChild(createStorageSlotSharedOpenButton(sharedMount));
  }
}

function appendSharedMountTreeItem(list, mount, { activeSlotKey = null, sectionFilterActive = false } = {}) {
  if (!mount) return null;
  const slotKey = mount.slotKey || mount.themeSlug || "";
  const count = Number(mount.entryCount) || 0;
  const isActive = !sectionFilterActive && activeSlotKey === slotKey && isActiveSharedThemeStorageContext();
  const btn = appendMediaSectionTreeItem(list, {
    icon: "📦",
    label: mount.label || mount.themeSlug || "shared",
    count: count > 0 ? count : 0,
    isActive,
    onClick: () => {
      void openSharedStorageMount(mount);
    }
  });
  btn.dataset.storageSlot = slotKey;
  btn.dataset.storageSharedMount = mount.themeSlug || slotKey;
  btn.classList.add("storage-slot-tree-item", "storage-slot-tree-item--shared-mount");
  btn.title = `Общее · ${mount.label || mount.themeSlug}. Файлы доступны всем темам.`;
  const badge = btn.querySelector(".media-section-tree-count");
  if (badge) badge.dataset.baseCount = String(count);
  return btn;
}

function syncStorageSlotTreeActiveState(container, { useEntryOverviewNavigation = false } = {}) {
  if (!container) return;
  const list = container.querySelector(":scope > .storage-slot-tree-list");
  if (!list) return;

  const activeSlotKey = useEntryOverviewNavigation
    ? getDataStorageSlotKeyForEntryView()
    : getDataStorageSlotForMode()?.key || null;
  const activeSlot = activeSlotKey
    ? DATA_STORAGE_SLOT_SPECS.find((spec) => spec.key === activeSlotKey) || null
    : getDataStorageSlotForMode();
  const sectionFilterActive = useEntryOverviewNavigation ? false : isStorageSectionFilterActive();
  const allItemsActive = useEntryOverviewNavigation ? false : activeDataStorageAllItems;

  const allBtn = list.querySelector('[data-storage-slot="all"]');
  if (allBtn) allBtn.classList.toggle("is-active", allItemsActive);

  list.querySelectorAll(".storage-slot-tree-item[data-storage-slot]").forEach((btn) => {
    const slotKey = btn.dataset.storageSlot;
    if (!slotKey || slotKey === "all") return;
    if (btn.classList.contains("storage-slot-tree-item--count-only")) {
      btn.classList.remove("is-active");
      return;
    }
    if (btn.classList.contains("storage-slot-tree-item--shared-mount")) {
      const isActive =
        !allItemsActive &&
        isActiveSharedThemeStorageContext() &&
        (activeSlotKey === slotKey || btn.dataset.storageSharedMount === activeStorageRootScan?.sharedContext?.themeSlug);
      btn.classList.toggle("is-active", isActive && !sectionFilterActive);
      return;
    }
    const disabled = btn.disabled || btn.classList.contains("is-disabled");
    const isMemorySlot = slotKey === "memory";
    let isActive = false;
    if (!disabled && !allItemsActive) {
      if (isMemorySlot) {
        isActive = useEntryOverviewNavigation
          ? activeSlotKey === "memory"
          : isDataStorageSlotActive("memory") && activeContentMode === "external";
      } else {
        isActive = useEntryOverviewNavigation
          ? activeSlotKey === slotKey
          : activeSlot?.key === slotKey;
      }
    }
    btn.classList.toggle("is-active", isActive && !sectionFilterActive);
  });
}

function updateStorageSlotTreeCounts(container, scan = {}) {
  const list = container?.querySelector(":scope > .storage-slot-tree-list");
  if (!list) return;

  const allCount = Number(scan.totalEntries) || 0;
  const allBtn = list.querySelector('[data-storage-slot="all"]');
  const allBadge = allBtn?.querySelector(".media-section-tree-count");
  if (allBadge) {
    allBadge.textContent = allCount > 0 ? String(allCount) : "";
    allBadge.dataset.baseCount = String(allCount);
  }

  const folders = scan.exists ? scan.folders || [] : [];
  const bundleSlots = scan.bundleSlots || {};
  list.querySelectorAll(".storage-slot-tree-item[data-storage-slot]").forEach((btn) => {
    const slotKey = btn.dataset.storageSlot;
    if (!slotKey || slotKey === "all") return;
    const spec = DATA_STORAGE_SLOT_SPECS.find((item) => item.key === slotKey);
    const sharedMount = btn.dataset.storageSharedMount
      ? (scan?.sharedMounts || []).find(
          (mount) =>
            mount?.themeSlug === btn.dataset.storageSharedMount || mount?.slotKey === slotKey
        ) || null
      : null;
    const folder = findScanFolderForSlotKey(slotKey, folders);
    const count = sharedMount
      ? Number(sharedMount.entryCount) || 0
      : spec
        ? getDataStorageSlotCountForScan(spec, folder, bundleSlots[slotKey] || null)
        : folder?.entryCount > 0
          ? folder.entryCount
          : null;
    const badge = btn.querySelector(".media-section-tree-count");
    if (!badge) return;
    if (isStorageSlotCountOnly(spec)) {
      badge.textContent = String(Number(count) || 0);
      badge.dataset.baseCount = String(Number(count) || 0);
      return;
    }
    if (count !== null && count > 0) {
      badge.textContent = String(count);
      badge.dataset.baseCount = String(count);
    } else {
      badge.textContent = "";
      delete badge.dataset.baseCount;
    }
    if (spec?.key === "repository" && count !== null) {
      const label = btn.querySelector(".media-section-tree-label")?.textContent?.trim() || spec.label;
      btn.title = getRepositorySlotCounterTitle(label, count);
    }
  });

  refreshRepositoryStorageSlotTreeCount(
    container,
    container.dataset.storageScanManifest || getActiveNodeApiPath()
  );
}

function renderStorageSlotTreeContent(
  container,
  scan,
  { useEntryOverviewNavigation = false, manifestPath = "" } = {}
) {
  container.replaceChildren();
  container.dataset.storageScanManifest = String(manifestPath || "");

  const list = document.createElement("div");
  list.className = "media-section-tree-list storage-slot-tree-list";
  list.setAttribute("role", "tree");
  container.appendChild(list);

  const activeSlotKey = useEntryOverviewNavigation
    ? getDataStorageSlotKeyForEntryView()
    : getDataStorageSlotForMode()?.key || null;
  const activeSlot = activeSlotKey
    ? DATA_STORAGE_SLOT_SPECS.find((spec) => spec.key === activeSlotKey) || null
    : getDataStorageSlotForMode();
  const sectionFilterActive = useEntryOverviewNavigation ? false : isStorageSectionFilterActive();
  const allItemsActive = useEntryOverviewNavigation ? false : activeDataStorageAllItems;
  const allCount = Number(scan.totalEntries) || 0;
  const treeItemOptions = {
    activeSlot,
    sectionFilterActive,
    allItemsActive,
    useEntryOverviewNavigation,
    activeSlotKey
  };

  const allBtn = appendMediaSectionTreeItem(list, {
    icon: "📋",
    label: DATA_HUB_ALL_SLOTS_LABEL,
    count: allCount > 0 ? allCount : null,
    isActive: allItemsActive,
    onClick: () => setActiveDataStorageAllItems()
  });
  allBtn.dataset.storageSlot = "all";
  allBtn.classList.add("storage-slot-tree-item", "storage-slot-tree-item--all");

  const divider = document.createElement("div");
  divider.className = "media-section-tree-divider storage-slot-tree-divider";
  divider.setAttribute("role", "presentation");
  list.appendChild(divider);

  const entries = buildStorageSlotTreeModel(scan);
  if (!scan.exists && entries.length === 0) {
    const empty = document.createElement("div");
    empty.className = "media-section-tree-empty storage-slot-tree-empty";
    empty.textContent = "Папка awn-storage не найдена";
    list.appendChild(empty);
  } else {
    for (const entry of entries) {
      if (entry.kind === "divider") {
        const entryDivider = document.createElement("div");
        entryDivider.className = "media-section-tree-divider storage-slot-tree-divider";
        entryDivider.setAttribute("role", "presentation");
        list.appendChild(entryDivider);
        continue;
      }
      if (entry.kind === "group-label") {
        const groupLabel = document.createElement("div");
        groupLabel.className = "media-section-tree-group-label storage-slot-tree-group-label";
        groupLabel.textContent = entry.label || "";
        groupLabel.setAttribute("role", "presentation");
        list.appendChild(groupLabel);
        continue;
      }
      if (entry.kind === "slot") {
        appendStorageSlotTreeItem(
          list,
          { spec: entry.spec, folder: entry.folder, bundleSlot: entry.bundleSlot || null },
          treeItemOptions
        );
        continue;
      }
      if (entry.kind === "shared-mount") {
        appendSharedMountTreeItem(list, entry.mount, treeItemOptions);
        continue;
      }
      if (entry.kind === "orphan") {
        appendStorageSlotTreeItem(
          list,
          { folder: entry.folder },
          treeItemOptions
        );
      }
    }
  }
  ensureStorageTreePolicyFooter(container, activeContentMode);
  if (!useEntryOverviewNavigation) syncListViewHead();
  syncDataHubPanelChrome(getDataHubPanelBodyNode(), scan);
  refreshRepositoryStorageSlotTreeCount(container, manifestPath);
}

async function renderStorageSlotTree(container, options = {}) {
  if (!container) return;
  const useEntryOverviewNavigation = Boolean(options.useEntryOverviewNavigation);
  const manifestPath = options.manifestPath || getActiveNodeApiPath();
  const force = Boolean(options.force);
  const connectedAtStart = container.isConnected;
  const token = (container._storageSlotTreeRenderSeq = (container._storageSlotTreeRenderSeq || 0) + 1);

  const hasList = Boolean(container.querySelector(":scope > .storage-slot-tree-list"));
  const manifestKey = String(manifestPath || "");
  const cachedScan = !force ? storageRootScanCache.get(manifestPath) : null;

  if (cachedScan && hasList && container.dataset.storageScanManifest === manifestKey) {
    syncStorageSlotTreeActiveState(container, { useEntryOverviewNavigation });
    updateStorageSlotTreeCounts(container, cachedScan);
    return;
  }

  if (cachedScan && !hasList) {
    renderStorageSlotTreeContent(container, cachedScan, { useEntryOverviewNavigation, manifestPath });
    return;
  }

  if (!hasList) {
    container.replaceChildren();
    const loading = document.createElement("div");
    loading.className = "media-section-tree-loading storage-slot-tree-loading";
    loading.textContent = "Сканирование awn-storage…";
    container.appendChild(loading);
  }

  let scan = { exists: false, folders: [], looseFiles: [], bundleSlots: {}, totalEntries: 0 };
  let scanError = null;
  try {
    if (manifestPath) scan = await fetchStorageRootScan(manifestPath, { force });
  } catch (error) {
    scanError = error;
    scan = { exists: false, folders: [], looseFiles: [], bundleSlots: {}, totalEntries: 0 };
  }
  if (token !== container._storageSlotTreeRenderSeq) return;
  if (connectedAtStart && !container.isConnected) return;

  if (scanError) {
    if (!hasList) {
      container.replaceChildren();
      const err = document.createElement("div");
      err.className = "media-section-tree-empty storage-slot-tree-empty";
      err.textContent =
        scanError.name === "AbortError"
          ? "Сканирование awn-storage заняло слишком много времени"
          : "Не удалось просканировать awn-storage";
      container.appendChild(err);
    }
    return;
  }

  renderStorageSlotTreeContent(container, scan, { useEntryOverviewNavigation, manifestPath });
}

function loadStorageSectionsPanelVisible() {
  const raw = readStorageItem(STORAGE_SECTIONS_PANEL_VISIBLE_KEY);
  if (raw === "0" || raw === "false") return false;
  return true;
}

let storageSectionsPanelVisible = loadStorageSectionsPanelVisible();

function isStorageSectionsPanelVisible() {
  return storageSectionsPanelVisible;
}

function isFlatStorageSectionMode(mode = activeContentMode) {
  return FLAT_STORAGE_SECTION_MODES.has(mode);
}

function getActiveFlatStorageSectionFolder(mode = activeContentMode) {
  return isFlatStorageSectionMode(mode) ? activeFlatStorageSectionFolder[mode] : null;
}

function isStorageSectionFilterActive() {
  if (!isStorageSectionsPanelVisible()) return false;
  if (activeExternalSectionFolder || activeMediaSectionFolder) return true;
  return isFlatStorageSectionMode() && Boolean(getActiveFlatStorageSectionFolder());
}

function syncStorageSectionsPanelUi() {
  const visible = isStorageSectionsPanelVisible();
  if (storageSectionsPanelToggleNode) {
    storageSectionsPanelToggleNode.checked = visible;
  }
  for (const wrap of listViewContentNode.querySelectorAll(".media-list-view-wrap")) {
    wrap.classList.toggle("is-sections-panel-hidden", !visible);
  }
}

function setStorageSectionsPanelVisible(visible, { rerender = true, skipRouteSync = false } = {}) {
  const next = Boolean(visible);
  if (next === storageSectionsPanelVisible) {
    syncStorageSectionsPanelUi();
    return;
  }
  storageSectionsPanelVisible = next;
  try {
    localStorage.setItem(STORAGE_SECTIONS_PANEL_VISIBLE_KEY, next ? "1" : "0");
  } catch {
    // ignore quota / private mode
  }
  if (!next) {
    activeMediaSectionFolder = null;
    activeExternalSectionFolder = null;
    for (const mode of FLAT_STORAGE_SECTION_MODES) {
      activeFlatStorageSectionFolder[mode] = null;
    }
  }
  syncStorageSectionsPanelUi();
  if (rerender) {
    if (isMediaLibraryContentMode() && !isMediaAssetEditing()) {
      rerenderMediaListViewBody();
    } else if (activeContentMode === "external" && !isExternalFileEditing()) {
      rerenderExternalListViewBody();
    } else if (isFlatStorageSectionMode() && isFlatStorageListMode()) {
      rerenderFlatStorageListViewBody(activeContentMode);
    } else {
      renderListViewContent();
    }
  }
  if (!skipRouteSync) {
    syncAppRouteToUrl({ replace: true });
  }
}
