function createMenuRuntimeBadges(source, agentId = activeAgentId) {
  const resolved = resolveMenuRuntimeSource(source, agentId);
  const hasContextAlways = Boolean(resolved?.runtimeLoadAlways);
  const hasCron = Boolean(resolved?.runtimeCron);
  const hasHeartbeat = Boolean(resolved?.runtimeHeartbeat);
  const hasCommands = Boolean(resolved?.runtimeCommands);
  const hasCustomSchema = Boolean(resolved?.hasCustomSchema);
  if (!hasContextAlways && !hasCron && !hasHeartbeat && !hasCommands && !hasCustomSchema) return null;

  const wrap = document.createElement("span");
  wrap.className = "menu-runtime-badges";

  if (hasContextAlways) {
    const badge = document.createElement("span");
    badge.className = "menu-runtime-badge menu-runtime-badge--context";
    badge.appendChild(createContextAlwaysRuntimeMarkerSvg());
    badge.title = "Всегда в контексте";
    badge.setAttribute("aria-label", "Всегда в контексте");
    wrap.appendChild(badge);
  }

  if (hasCron) {
    const badge = document.createElement("span");
    badge.className = "menu-runtime-badge menu-runtime-badge--cron";
    if (resolved?.runtimeCronSelf === false) badge.classList.add("menu-runtime-badge--descendant");
    badge.appendChild(createCronRuntimeMarkerSvg());
    const title = resolveMenuRuntimeBadgeTitle("cron", resolved);
    badge.title = title;
    badge.setAttribute("aria-label", title);
    wrap.appendChild(badge);
  }

  if (hasHeartbeat) {
    const badge = document.createElement("span");
    badge.className = "menu-runtime-badge menu-runtime-badge--heartbeat";
    if (resolved?.runtimeHeartbeatSelf === false) {
      badge.classList.add("menu-runtime-badge--descendant");
    }
    badge.appendChild(createHeartbeatRuntimeMarkerSvg());
    const title = resolveMenuRuntimeBadgeTitle("heartbeat", resolved);
    badge.title = title;
    badge.setAttribute("aria-label", title);
    wrap.appendChild(badge);
  }

  if (hasCommands) {
    const badge = document.createElement("span");
    badge.className = "menu-runtime-badge menu-runtime-badge--commands";
    badge.appendChild(createCommandsRuntimeMarkerSvg());
    badge.title = "Выполнение команд";
    badge.setAttribute("aria-label", "Выполнение команд");
    wrap.appendChild(badge);
  }

  if (hasCustomSchema) {
    const badge = document.createElement("span");
    badge.className = "menu-runtime-badge menu-runtime-badge--schema";
    if (resolved?.hasCustomSchemaSelf === false) badge.classList.add("menu-runtime-badge--descendant");
    badge.appendChild(createSchemaMenuMarkerSvg());
    badge.title =
      resolved?.hasCustomSchemaSelf === false ? "Схема полей в дочерних узлах" : "Схема полей задана";
    badge.setAttribute("aria-label", badge.title);
    wrap.appendChild(badge);
  }

  return wrap;
}

