function appendMemorySectionTreeNodes(list, nodes, config, depth = 0) {
  for (const section of nodes) {
    const counts = config.countFn(section.folderPath);
    const btn = appendMediaSectionTreeItem(list, {
      icon: "📁",
      label: section.label,
      count: formatMemorySectionTreeCount(counts),
      depth,
      isActive: config.isActive(section.folderPath),
      isEmpty: counts.total === 0,
      onClick: () => config.onSelect(section.folderPath),
      sectionFolder: section.folderPath,
      readmeExists: config.readmeExists(section.folderPath),
      onSectionReadmeEdit: (readmePath) => config.onReadmeEdit(readmePath, section.folderPath),
      sectionStorageMode: config.storageMode || null,
      sectionExternalMode: config.externalMode || null,
      sectionMediaMode: config.mediaMode || null
    });
    if (config.datasetKey) btn.dataset[config.datasetKey] = section.folderPath;
    if (section.children.length) {
      appendMemorySectionTreeNodes(list, section.children, config, depth + 1);
    }
  }
}

function getMediaUserSections() {
  return mapMemorySectionFolderPaths(collectMediaSectionFolderPaths());
}

function hasMediaUserSections() {
  return getMediaUserSections().length > 0;
}

function hasExternalUserSections() {
  return getExternalUserSections().length > 0;
}

function isSectionReadmePath(filePath) {
  const base = String(filePath || "").split("/").pop() || "";
  return isAreaManifestFileName(base);
}

function isSectionReadmeSegmentName(segment) {
  const normalized = String(segment || "").trim().toLowerCase();
  return normalized === MANIFEST_FILE.toLowerCase() || normalized === "manifest";
}

function isBreadcrumbStorageInfrastructureSegment(part) {
  const lower = String(part || "").trim().toLowerCase();
  if (!lower) return false;
  if (lower === STORAGE_ROOT_FOLDER.toLowerCase()) return true;
  return (
    lower === BUNDLE_CONTENT_FILE.toLowerCase() ||
    lower === BUNDLE_TABULAR_FILE.toLowerCase() ||
    lower === BUNDLE_TODO_FILE.toLowerCase() ||
    lower === BUNDLE_CONFIG_FILE.toLowerCase() ||
    lower === ".env"
  );
}

function isMemorySectionInfrastructureFolderPath(folderPath) {
  const normalized = String(folderPath || "").replace(/\\/g, "/").replace(/\/$/, "").trim();
  if (!normalized) return false;
  const parts = normalized.split("/").filter(Boolean);
  if (!parts.length) return false;

  if (parts[0].toLowerCase() === STORAGE_ROOT_FOLDER.toLowerCase()) return true;
  if (parts[0].toLowerCase() === STORAGE_SUBFOLDER_ASSETS.toLowerCase()) return true;

  const root = parts[0].toLowerCase();
  if (
    parts.length === 1 &&
    (root === PREVIEW_ASSETS_SUBDIR.toLowerCase() ||
      root === PASTED_ASSETS_SUBDIR.toLowerCase() ||
      root === ATTACHMENTS_ASSETS_SUBDIR.toLowerCase())
  ) {
    return true;
  }

  return false;
}

function isMemorySectionInfrastructureFilePath(filePath) {
  const normalized = String(filePath || "").replace(/\\/g, "/").replace(/\/$/, "").trim();
  if (!normalized) return false;
  const parts = normalized.split("/").filter(Boolean);
  if (parts.length <= 1) {
    return isMemorySectionInfrastructureFolderPath(parts[0] || "");
  }
  let built = "";
  for (let i = 0; i < parts.length - 1; i += 1) {
    built = built ? `${built}/${parts[i]}` : parts[i];
    if (isMemorySectionInfrastructureFolderPath(built)) return true;
  }
  return false;
}

function addMemorySectionFolderPath(folderPaths, folderPath) {
  const normalized = String(folderPath || "").replace(/\\/g, "/").replace(/\/$/, "").trim();
  if (!normalized || isMemorySectionInfrastructureFolderPath(normalized)) return;
  folderPaths.add(normalized);
}

function getMemorySectionDisplayLabel(folderPath) {
  const folderKey = String(folderPath || "").replace(/\\/g, "/").replace(/\/$/, "");
  if (!folderKey) return "";
  const segment = folderKey.split("/").pop() || folderKey;
  const readmePath = getSectionReadmeRelPath(folderKey);

  const externalReadme = externalFilesCache.find(
    (file) => String(file.relativePath || "").replace(/\\/g, "/") === readmePath
  );
  if (externalReadme) {
    const props = Array.isArray(externalReadme.props) ? externalReadme.props : [];
    const awnName = getPropsEntryValueByKey(props, "awn-name");
    if (awnName) return resolveNodeDisplayName(awnName, segment);
    const title = String(externalReadme.title || "").trim();
    if (title && title.toLowerCase() !== "manifest") return title;
    return resolveNodeDisplayName(awnName, segment);
  }

  const manifest = mediaSectionManifests.find(
    (item) => String(item.path || "").replace(/\\/g, "/") === readmePath
  );
  if (manifest) {
    const displayName = String(manifest.displayName || "").trim();
    if (displayName) return displayName;
    return segment;
  }

  return segment;
}

function getMemoryContentRelativePath(parts, endIndex) {
  const contentIndex = parts.findIndex(
    (part, index) => index <= endIndex && part === STORAGE_SUBFOLDER_CONTENT
  );
  const assetsIndex = parts.findIndex(
    (part, index) => index <= endIndex && part === STORAGE_SUBFOLDER_MEDIA
  );
  const rootIndex = contentIndex >= 0 ? contentIndex : assetsIndex;
  if (rootIndex < 0 || endIndex <= rootIndex) return "";
  return parts.slice(rootIndex + 1, endIndex + 1).join("/");
}

function buildMemoryContentLabelMap() {
  const map = new Map();
  for (const item of externalFilesCache) {
    const path = String(item.relativePath || "").replace(/\\/g, "/");
    if (!path) continue;
    if (isSectionReadmePath(path)) {
      const folderKey = path.slice(0, path.length - AREA_MANIFEST_FILE.length).replace(/\/$/, "");
      if (folderKey) map.set(folderKey, getMemorySectionDisplayLabel(folderKey));
      continue;
    }
    const slug = String(item.name || path.split("/").pop() || "").replace(/\.md$/i, "");
    const props = Array.isArray(item.props) ? item.props : [];
    const awnName = getPropsEntryValueByKey(props, "awn-name");
    const title = String(item.title || "").trim();
    map.set(path, title || resolveNodeDisplayName(awnName, slug));
  }

  for (const manifest of mediaSectionManifests) {
    const path = String(manifest.path || "").replace(/\\/g, "/");
    if (!path) continue;
    const folderKey = path.slice(0, path.length - AREA_MANIFEST_FILE.length).replace(/\/$/, "");
    if (folderKey) map.set(folderKey, getMemorySectionDisplayLabel(folderKey));
  }

  for (const groupItems of Object.values(mediaFilesCache)) {
    if (!Array.isArray(groupItems)) continue;
    for (const item of groupItems) {
      if (item.isFolder) continue;
      const path = String(item.path || "").replace(/\\/g, "/");
      if (!path) continue;
      if (isSectionReadmePath(path)) continue;
      if (!path.toLowerCase().endsWith(".md")) continue;
      const slug = String(item.name || path.split("/").pop() || "").replace(/\.md$/i, "");
      const title = String(item.displayName || "").trim();
      if (title) map.set(path, title);
      else map.set(path, slug);
    }
  }

  return map;
}

let menuDisplayLabelMapCache = null;
let menuDisplayLabelMapAgentId = "";

function buildMenuDisplayLabelMap(menu = currentMenuData) {
  const map = new Map();
  if (!menu) return map;

  function registerManifestLabel(manifestPath, title) {
    const trimmedTitle = String(title || "").trim();
    if (!trimmedTitle || !manifestPath) return;
    const folderPath = stripVaultPrefixFromRelPath(
      stripAgentContentPrefixFromRelPath(getFolderPathFromManifest(manifestPath) || "")
    );
    if (folderPath) map.set(folderPath, trimmedTitle);
    const displayPath = stripVaultPrefixFromRelPath(getNodeDisplayPath(manifestPath));
    if (displayPath && displayPath !== folderPath) map.set(displayPath, trimmedTitle);
  }

  function walk(node) {
    if (!node || typeof node !== "object") return;
    if (node.indexPath) {
      registerManifestLabel(node.indexPath, node.title);
    }
    for (const section of node.sections || []) {
      const folderPath = stripVaultPrefixFromRelPath(section.folderPath || "");
      if (folderPath && section.title) {
        map.set(folderPath, section.title);
      }
      if (section.indexPath) {
        registerManifestLabel(section.indexPath, section.title);
      }
      walk(section);
    }
    for (const item of [...(node.items || []), ...getMenuRepoServiceItems(node)]) {
      if (!item?.path) continue;
      const normalizedPath = normalizeMenuNodePath(item.path);
      const displayPath = stripVaultPrefixFromRelPath(getNodeDisplayPath(item.path));
      if (item.label) {
        if (normalizedPath) map.set(normalizedPath, item.label);
        if (displayPath) map.set(displayPath, item.label);
      }
    }
  }

  walk({ title: getAgentTreeTitle(), ...menu });
  if (menu.serviceTree) walk({ title: "", ...menu.serviceTree });
  if (menu.containerTree) walk({ title: "", ...menu.containerTree });
  return map;
}

function getMenuDisplayLabelMap() {
  const agentId = activeAgentId || "";
  if (!menuDisplayLabelMapCache || menuDisplayLabelMapAgentId !== agentId) {
    const menu = menuCacheByAgent.get(agentId) || currentMenuData;
    menuDisplayLabelMapCache = buildMenuDisplayLabelMap(menu);
    menuDisplayLabelMapAgentId = agentId;
  }
  return menuDisplayLabelMapCache;
}

function invalidateMenuDisplayLabelMap() {
  menuDisplayLabelMapCache = null;
  menuDisplayLabelMapAgentId = "";
}

const MEMORY_SUBFOLDER_BREADCRUMB_LABELS = {
  [STORAGE_SUBFOLDER_CONTENT]: "Память",
  [STORAGE_SUBFOLDER_MEDIA]: "Медиа"
};

function getBreadcrumbSegmentDisplayLabel(segmentIndex, parts) {
  const segment = parts[segmentIndex];
  const cumulativePath = parts.slice(0, segmentIndex + 1).join("/");
  const menuKey = stripAgentContentPrefixFromRelPath(cumulativePath);
  const menuMap = getMenuDisplayLabelMap();
  const memoryMap = buildMemoryContentLabelMap();
  const isLast = segmentIndex === parts.length - 1;

  if (MEMORY_SUBFOLDER_BREADCRUMB_LABELS[segment]) {
    return MEMORY_SUBFOLDER_BREADCRUMB_LABELS[segment];
  }

  const memoryRel = getMemoryContentRelativePath(parts, segmentIndex);
  if (memoryRel) {
    if (memoryMap.has(memoryRel)) return memoryMap.get(memoryRel);
    if (!/\.md$/i.test(memoryRel)) {
      const sectionLabel = getMemorySectionDisplayLabel(memoryRel);
      if (sectionLabel) return sectionLabel;
    }
  }

  if (segmentIndex > 0 && parts[segmentIndex - 1] === STORAGE_ROOT_FOLDER) {
    const containerParts = parts.slice(0, segmentIndex - 1);
    const topicDisplay = containerParts.length
      ? `${containerParts.join("/")}/${segment}`
      : segment;
    const topicKey = stripAgentContentPrefixFromRelPath(topicDisplay);
    if (menuMap.has(topicKey)) return menuMap.get(topicKey);
    if (menuMap.has(topicDisplay)) return menuMap.get(topicDisplay);
  }

  if (menuMap.has(menuKey)) return menuMap.get(menuKey);

  const manifestPath = getBreadcrumbManifestPathForSegmentIndex(segmentIndex, parts);
  if (manifestPath) {
    const resolved = resolveMenuEntryLabel(manifestPath);
    const slug = getLabelFromPath(manifestPath);
    if (resolved && resolved !== slug) return resolved;
  }

  const entry = resolveMenuEntryByDisplayPath(menuKey);
  if (entry?.label) {
    const slug = entry.path ? getLabelFromPath(entry.path) : segment;
    if (entry.label !== slug) return entry.label;
  }

  if (isLast) {
    const activeDisplayPath = stripAgentContentPrefixFromRelPath(
      getNodeDisplayPath(getResolvedNodePath(activePath))
    );
    if (activeDisplayPath === menuKey) {
      const manifestTitle = getNodeDisplayTitleForActiveManifest();
      if (manifestTitle) return manifestTitle;
      if (activeLabel) return activeLabel;
    }
    if (activeContentMode === "external" && activeExternalFilePath) {
      const filePath = String(activeExternalFilePath).replace(/\\/g, "/");
      if (memoryMap.has(filePath)) return memoryMap.get(filePath);
    }
    if (isMediaLibraryContentMode()) {
      const filePath = String(activeMediaMarkdownPath || activeMediaSidecarSourcePath || "")
        .replace(/\\/g, "/");
      if (filePath && memoryMap.has(filePath)) return memoryMap.get(filePath);
    }
  }

  return segment;
}

function getSectionReadmeRelPath(sectionFolder) {
  const folder = String(sectionFolder || "").replace(/\\/g, "/").replace(/\/$/, "");
  return folder ? `${folder}/${AREA_MANIFEST_FILE}` : AREA_MANIFEST_FILE;
}

function resolveSectionReadmeSeedNames(sectionFolder) {
  const folderKey = String(sectionFolder || "").replace(/\\/g, "/").replace(/\/$/, "");
  const folderSlug = folderKey.split("/").filter(Boolean).pop() || "Раздел";
  const displayLabel = getMemorySectionDisplayLabel(folderKey) || folderSlug;
  return { folderSlug, displayLabel };
}

function buildSectionReadmeFrontmatterLines(displayName, awnType, folderSlug) {
  const segment =
    String(folderSlug || "").trim() || String(displayName || "Раздел").trim() || "Раздел";
  const awnName = normalizeAwnNameForStorage(displayName, segment);
  const lines = [];
  if (awnType) lines.push(`awn-type: ${awnType}`);
  if (awnName) lines.push(`awn-name: ${formatYamlScalar(awnName)}`);
  return lines;
}

function buildSectionReadmeContent(displayName, awnType = "awn.record.category", folderSlug = "") {
  const lines = buildSectionReadmeFrontmatterLines(displayName, awnType, folderSlug);
  if (!lines.length) return `\n> Описание раздела.\n`;
  return `---\n${lines.join("\n")}\n---\n\n> Описание раздела.\n`;
}

async function buildSectionReadmeContentWithSchema(
  title,
  awnType = "awn.record.category",
  nodePath = activePath,
  contentPath = "",
  folderSlug = ""
) {
  if (!awnType) return buildSectionReadmeContent(title, null, folderSlug);
  const safeTitle = String(title || "Раздел").trim() || "Раздел";
  const manifestPath = getTopicSchemaManifestPath(nodePath);
  const schemaTarget = resolveAwnSchemaTargetForType(awnType, resolveSchemaSlotKeyForContext());
  if (!manifestPath || !schemaTarget) {
    return buildSectionReadmeContent(safeTitle, awnType, folderSlug);
  }
  try {
    if (!awnTypesCache?.types) await loadAwnTypes(activeAgentId);
    const normalizedContentPath = String(contentPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
    const cache = await loadTopicSchemaForManifest(
      manifestPath,
      normalizedContentPath ? { contentPath: normalizedContentPath } : {}
    );
    const mergedType = cache?.merged?.[schemaTarget];
    if (!mergedType?.fields || !Object.keys(mergedType.fields).length) {
      return buildSectionReadmeContent(safeTitle, awnType, folderSlug);
    }
    let entries = applyTypeSchemaToEntries(
      [{ key: "awn-type", kind: "string", value: awnType }],
      awnType
    );
    const storedAwnName = normalizeAwnNameForStorage(
      safeTitle,
      String(folderSlug || "").trim() || safeTitle
    );
    const nameIndex = entries.findIndex((entry) => normalizePropsKey(entry.key) === "awn-name");
    if (storedAwnName) {
      if (nameIndex >= 0) entries[nameIndex] = { ...entries[nameIndex], value: storedAwnName };
      else entries.unshift({ key: "awn-name", kind: "string", value: storedAwnName });
    } else if (nameIndex >= 0) {
      entries.splice(nameIndex, 1);
    }
    return `---\n${stringifyPropsYaml(entries)}\n---\n\n> Описание раздела.\n`;
  } catch {
    return buildSectionReadmeContent(safeTitle, awnType, folderSlug);
  }
}

function externalSectionReadmeExists(sectionFolder) {
  const readmePath = getSectionReadmeRelPath(sectionFolder);
  return externalFilesCache.some((file) => file.relativePath === readmePath);
}

function mediaSectionReadmeExists(sectionFolder) {
  const readmePath = getSectionReadmeRelPath(sectionFolder);
  return mediaSectionManifests.some(
    (item) => String(item.path || "").replace(/\\/g, "/") === readmePath
  );
}

function splitSectionReadmeItems(items, sectionFolder) {
  const readmePath = getSectionReadmeRelPath(sectionFolder);
  return {
    readmePath,
    readmeItem: items.find((item) => item.path === readmePath) || null,
    items: items.filter((item) => item.path !== readmePath)
  };
}

function createSectionReadmeSettingsButton(sectionFolder, { exists, onEdit }) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "node-settings-btn media-section-tree-settings-btn";
  btn.textContent = "⚙";
  btn.title = exists
    ? `Редактировать ${AREA_MANIFEST_FILE}`
    : `Создать ${AREA_MANIFEST_FILE}`;
  btn.setAttribute("aria-label", btn.title);
  btn.classList.toggle("is-missing", !exists);
  btn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    onEdit(getSectionReadmeRelPath(sectionFolder));
  });
  return btn;
}

function appendSectionReadmeOffer(
  container,
  sectionFolder,
  { categoryType = "awn.record.category", onCreate }
) {
  const card = document.createElement("article");
  card.className =
    "workspace-system-notice workspace-system-notice--info workspace-system-notice--offer section-readme-card section-readme-card--offer";

  const title = document.createElement("h5");
  title.className = "workspace-system-notice-title section-readme-card-title";
  title.textContent = "Описание раздела";

  const hint = document.createElement("p");
  hint.className = "workspace-system-notice-message section-readme-card-hint";
  hint.textContent =
    "Файл с описанием ещё не создан. Добавьте описание каталога — это необязательно, но помогает задать имя и свойства раздела.";

  const actions = document.createElement("div");
  actions.className = "workspace-system-notice-actions";

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className =
    "workspace-system-notice-action workspace-system-notice-action--accent section-readme-card-btn";
  btn.textContent = "Создать описание раздела";
  btn.addEventListener("click", () => onCreate(getSectionReadmeRelPath(sectionFolder)));

  actions.appendChild(btn);
  card.append(title, hint, actions);
  container.prepend(wrapWorkspaceSystemNoticeContent(card, "info"));
}

function getMediaSectionFileCounts(sectionFolder) {
  const normalizedSection = String(sectionFolder || "").replace(/\\/g, "/").replace(/\/$/, "");
  let direct = 0;
  let total = 0;
  for (const groupItems of Object.values(mediaFilesCache)) {
    if (!Array.isArray(groupItems)) continue;
    for (const item of groupItems) {
      if (!isMediaContentFileItem(item)) continue;
      const path = String(item.path || "").replace(/\\/g, "/");
      if (!normalizedSection) {
        total += 1;
        continue;
      }
      const prefix = `${normalizedSection}/`;
      if (!path.startsWith(prefix)) continue;
      total += 1;
      const remainder = path.slice(prefix.length);
      if (remainder && !remainder.includes("/")) direct += 1;
    }
  }
  return { direct, total };
}

function countMediaFilesInSection(sectionFolder) {
  return getMediaSectionFileCounts(sectionFolder).total;
}

function pruneActiveMediaSectionFolder() {
  if (!activeMediaSectionFolder) return;
  const folders = Array.isArray(mediaFilesCache.Folders) ? mediaFilesCache.Folders : [];
  if (!folders.length) return;
  const exists = getMediaUserSections().some((section) => section.folderPath === activeMediaSectionFolder);
  if (!exists) activeMediaSectionFolder = null;
}

function getMediaItemsForSection(sectionFolder, viewMode = mediaViewMode) {
  if (!sectionFolder) return [];
  const prefix = `${sectionFolder}/`;
  const groupName = MEDIA_VIEW_GROUPS[viewMode];
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  const items = [];

  for (const groupItems of Object.values(mediaFilesCache)) {
    if (!Array.isArray(groupItems)) continue;
    for (const item of groupItems) {
      if (!isMediaContentFileItem(item)) continue;
      const path = String(item.path || "").replace(/\\/g, "/");
      if (!path.startsWith(prefix)) continue;
      const remainder = path.slice(prefix.length);
      if (!remainder || remainder.includes("/")) continue;
      if (groupName && item.group !== groupName) continue;
      items.push(item);
    }
  }

  return items.sort((a, b) => collator.compare(a.path || a.name || "", b.path || b.name || ""));
}

function formatMediaViewSelectLabel(mode) {
  const node = getMediaViewSelectNodeMeta(mode);
  if (!node?.label) return "";
  const prefix = node.icon ? `${node.icon} ` : "";
  const count = getMediaViewOptionCount(mode);
  const label = `${prefix}${node.label}`;
  return count === null ? label : `${label} (${count})`;
}

function syncMediaViewSelectOptions() {
  if (!mediaViewSelectNode) return;
  const currentValue = getEffectiveMediaViewMode();
  for (const option of mediaViewSelectNode.options) {
    if (option.disabled || option.value === "sep") continue;
    const label = formatMediaViewSelectLabel(option.value);
    if (label) option.textContent = label;
  }
  if ([...mediaViewSelectNode.options].some((option) => option.value === currentValue)) {
    mediaViewSelectNode.value = currentValue;
  }
}

function rerenderMediaListViewBody() {
  if (activeContentMode !== "media" || isMediaAssetEditing()) return;
  syncMediaSectionTreeFromCaches();
  const body = listViewContentNode.querySelector(".media-list-view-body");
  if (body) {
    body.innerHTML = "";
    renderMediaListViewBody(body);
    return;
  }
  renderListViewContent();
}

function setActiveMediaSectionFolder(folderName, { rerender = true, skipRouteSync = false } = {}) {
  const next = folderName ? String(folderName).replace(/\\/g, "/").replace(/\/$/, "").trim() : null;
  if (next === activeMediaSectionFolder) {
    syncMediaSectionTreeActiveState();
    syncMediaViewSelectOptions();
    if (mediaViewSelectNode) mediaViewSelectNode.value = getEffectiveMediaViewMode();
    return;
  }
  activeMediaSectionFolder = next;
  if (activeMediaSectionFolder && mediaViewMode === "dashboard") {
    mediaViewMode = "all";
    saveStoredMediaViewMode(mediaViewMode);
  }
  syncMediaSectionTreeActiveState();
  syncMediaViewSelectOptions();
  if (mediaViewSelectNode) mediaViewSelectNode.value = getEffectiveMediaViewMode();
  if (rerender) rerenderMediaListViewBody();
  updateBreadcrumbsForActiveMode();
  if (!skipRouteSync) syncAppRouteToUrl({ push: true });
}

function setMediaViewMode(mode, { rerender = true, skipRouteSync = false, clearSection = false } = {}) {
  if (!mode || mode === "sep") return;

  const clearsSection = clearSection || mode === "dashboard";
  const unchanged =
    mode === mediaViewMode && (!clearsSection || !activeMediaSectionFolder);
  if (unchanged) {
    syncMediaSectionTreeActiveState();
    syncMediaViewSelectOptions();
    if (mediaViewSelectNode) mediaViewSelectNode.value = getEffectiveMediaViewMode();
    return;
  }

  mediaViewMode = mode;
  saveStoredMediaViewMode(mode);
  if (clearsSection) activeMediaSectionFolder = null;
  if (mediaViewSelectNode) mediaViewSelectNode.value = getEffectiveMediaViewMode();
  syncMediaSectionTreeActiveState();
  syncMediaViewSelectOptions();
  if (rerender) rerenderMediaListViewBody();
  updateBreadcrumbsForActiveMode();
  if (!skipRouteSync) syncAppRouteToUrl({ push: true });
}

function getMediaSectionTreeNode() {
  const wrap = listViewContentNode.querySelector(
    ".media-list-view-wrap:not(.external-list-view-wrap):not(.flat-storage-list-view-wrap)"
  );
  return wrap?.querySelector(".media-section-tree") || null;
}

function syncMediaSectionTreeActiveState() {
  const tree = getMediaSectionTreeNode();
  if (!tree) return;
  for (const btn of tree.querySelectorAll(".media-section-tree-item[data-media-view]")) {
    const view = btn.dataset.mediaView;
    if (view === "all") {
      btn.classList.toggle("is-active", mediaViewMode === "all" && !activeMediaSectionFolder);
    }
  }
  for (const btn of tree.querySelectorAll(".media-section-tree-item[data-media-section]")) {
    btn.classList.toggle("is-active", btn.dataset.mediaSection === activeMediaSectionFolder);
  }
}

function isMemorySectionUnregistered(sectionFolder, readmeExists) {
  return Boolean(sectionFolder) && !readmeExists;
}

function getMemorySectionUnregisteredTitle(sectionFolder, { context = "tree" } = {}) {
  const segment = String(sectionFolder || "").split("/").filter(Boolean).pop() || "раздел";
  if (context === "navigation") {
    return `Раздел «${segment}» без ${AREA_MANIFEST_FILE} — откройте каталог или создайте описание раздела`;
  }
  return `Папка «${segment}» без ${AREA_MANIFEST_FILE} — нажмите ⚙, чтобы создать описание раздела`;
}

const MEMORY_FILE_DRAG_MIME = "application/x-yamlcms-memory-file";
const MEMORY_SECTION_DRAG_SELECTOR =
  ".media-section-tree-item[data-external-section], .media-section-tree-item[data-media-section]";
let memorySectionSortDragRow = null;
let memorySectionMoveDragBtn = null;
let memorySectionMoveDropTargetBtn = null;
let memoryFileDragPayload = null;

function createMemoryFileDragHandle() {
  const handle = document.createElement("button");
  handle.type = "button";
  handle.className = "memory-file-drag-handle menu-sort-handle";
  handle.draggable = true;
  handle.textContent = "⠿";
  handle.title = "Перетащите в раздел";
  handle.setAttribute("aria-label", "Перетащите в раздел");
  handle.addEventListener("mousedown", (event) => event.stopPropagation());
  handle.addEventListener("click", (event) => event.stopPropagation());
  return handle;
}

function createMemorySectionSortHandle() {
  const handle = document.createElement("button");
  handle.type = "button";
  handle.className = "memory-section-sort-handle menu-sort-handle";
  handle.draggable = true;
  handle.textContent = "⠿";
  handle.title = "Перетащить для сортировки";
  handle.setAttribute("aria-label", "Перетащить для сортировки");
  handle.addEventListener("mousedown", (event) => event.stopPropagation());
  handle.addEventListener("click", (event) => event.stopPropagation());
  return handle;
}

function getMemorySectionFolderPathFromRow(row) {
  const btn = row?.querySelector(MEMORY_SECTION_DRAG_SELECTOR);
  return btn?.dataset.externalSection || btn?.dataset.mediaSection || "";
}

function getMemorySectionParentPath(folderPath) {
  const parts = String(folderPath || "").split("/").filter(Boolean);
  parts.pop();
  return parts.join("/");
}

function getMemorySectionDepth(folderPath) {
  return String(folderPath || "").split("/").filter(Boolean).length;
}

function isMemorySectionDirectChild(folderPath, parentPath) {
  const parts = String(folderPath || "").split("/").filter(Boolean);
  const parentParts = String(parentPath || "").split("/").filter(Boolean);
  return parts.length === parentParts.length + 1 && getMemorySectionParentPath(folderPath) === parentPath;
}

function getMemorySectionSortBlockRows(row) {
  const folderPath = getMemorySectionFolderPathFromRow(row);
  if (!folderPath) return [row];
  const depth = getMemorySectionDepth(folderPath);
  const rows = [row];
  let next = row.nextElementSibling;
  while (next?.classList.contains("memory-section-sort-row")) {
    const nextPath = getMemorySectionFolderPathFromRow(next);
    if (!nextPath || getMemorySectionDepth(nextPath) <= depth) break;
    rows.push(next);
    next = next.nextElementSibling;
  }
  return rows;
}

function insertMemorySectionSortBlock(list, blockRows, targetRow, insertBefore) {
  const fragment = document.createDocumentFragment();
  for (const blockRow of blockRows) fragment.appendChild(blockRow);
  if (insertBefore) list.insertBefore(fragment, targetRow);
  else {
    const targetBlock = getMemorySectionSortBlockRows(targetRow);
    const after = targetBlock[targetBlock.length - 1]?.nextSibling || null;
    list.insertBefore(fragment, after);
  }
}

function collectMemorySectionSortOrder(list, parentPath) {
  const order = [];
  for (const row of list.querySelectorAll(".memory-section-sort-row")) {
    const folderPath = getMemorySectionFolderPathFromRow(row);
    if (!folderPath || !isMemorySectionDirectChild(folderPath, parentPath)) continue;
    const key = folderPath.split("/").filter(Boolean).pop();
    if (key) order.push(key);
  }
  return order;
}

function getMemorySectionSortScope(tree) {
  if (tree?.classList.contains("external-section-tree")) {
    return { type: "external", folder: "" };
  }
  if (tree?.classList.contains("flat-storage-section-tree")) return null;
  if (tree?.classList.contains("media-section-tree")) {
    const folder = isMediaLibraryContentMode() ? getMediaLibraryStorageSubfolder() : STORAGE_SUBFOLDER_MEDIA;
    return {
      type: "media",
      folder: folder === STORAGE_SUBFOLDER_MEDIA ? "" : folder
    };
  }
  return null;
}

async function persistMemorySectionSortOrder(list, parentPath, scope) {
  const apiBase = getMemorySectionApiBase(scope);
  if (!apiBase) {
    showToast("Не удалось определить область сортировки", "error");
    return;
  }
  const order = collectMemorySectionSortOrder(list, parentPath);
  if (!order.length) {
    showToast("Не удалось определить порядок разделов", "error");
    return;
  }
  const body = { path: getActiveNodeApiPath(), parent: parentPath || "", order };
  if (scope.type === "storage" || (scope.type === "media" && scope.folder)) body.folder = scope.folder;
  try {
    const response = await fetch(buildApiUrl(`${apiBase}/sort`), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body)
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `HTTP ${response.status}`);
    }
    await refreshMemorySectionViews({
      externalMode: scope.type === "external",
      mediaMode: scope.type === "media",
      storageMode: scope.type === "storage" ? activeContentMode : null
    });
  } catch (error) {
    showToast(`Не удалось сохранить порядок: ${error.message}`, "error");
    if (scope.type === "external") await refreshExternalMemoryCaches().catch(() => {});
    else if (scope.type === "media") await refreshMediaCache().catch(() => {});
    if (scope.type === "external") {
      ensureExternalSectionTree(list.closest(".external-section-tree"));
    } else if (scope.type === "media") {
      ensureMediaSectionTree(list.closest(".media-section-tree"));
    }
  }
}

function clearMemorySectionMoveDropTarget() {
  if (!memorySectionMoveDropTargetBtn) return;
  memorySectionMoveDropTargetBtn.classList.remove("is-memory-section-move-drop-target");
  memorySectionMoveDropTargetBtn = null;
}

function setMemorySectionMoveDropTarget(btn) {
  if (memorySectionMoveDropTargetBtn === btn) return;
  clearMemorySectionMoveDropTarget();
  if (!btn) return;
  memorySectionMoveDropTargetBtn = btn;
  btn.classList.add("is-memory-section-move-drop-target");
}

function resolveMemorySectionDragMove(sourceSection, targetSection) {
  const source = String(sourceSection || "").replace(/\\/g, "/").replace(/\/$/, "").trim();
  const target = String(targetSection || "").replace(/\\/g, "/").replace(/\/$/, "").trim();
  if (!source || !target || source === target) return null;
  if (source.startsWith(`${target}/`) || target.startsWith(`${source}/`)) return null;
  if (getMemorySectionParentPath(source) === target) return null;
  return { source, target, parentPath: target };
}

function buildMemoryFileMoveTargetPath(filePath, targetSectionFolder) {
  const normalized = String(filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const fileName = normalized.split("/").filter(Boolean).pop() || normalized;
  const section = String(targetSectionFolder || "").replace(/\\/g, "/").replace(/\/$/, "").trim();
  return section ? `${section}/${fileName}` : fileName;
}

function getMemoryFileParentPath(filePath) {
  const parts = String(filePath || "").replace(/\\/g, "/").split("/").filter(Boolean);
  parts.pop();
  return parts.join("/");
}

function decorateMemorySectionSortRows(tree) {
  if (!tree) return;
  const scope = getMemorySectionSortScope(tree);
  if (!scope) return;
  tree.querySelectorAll(".memory-section-sort-handle").forEach((handle) => handle.remove());
  tree.querySelectorAll(".memory-section-sort-row").forEach((row) => {
    row.classList.remove("memory-section-sort-row", "is-dragging");
    delete row.dataset.sortSection;
  });
  tree.querySelectorAll(MEMORY_SECTION_DRAG_SELECTOR).forEach((btn) => {
    const folderPath = btn.dataset.externalSection || btn.dataset.mediaSection;
    if (!folderPath) return;
    const row = btn.closest(".media-section-tree-row");
    if (!row) return;
    row.classList.add("memory-section-sort-row");
    row.dataset.sortSection = folderPath;
    if (!row.querySelector(".memory-section-sort-handle")) {
      row.insertBefore(createMemorySectionSortHandle(), btn);
    }
    btn.draggable = true;
    if (!btn.dataset.sectionMoveHint) {
      btn.dataset.sectionMoveHint = "1";
      const hint = "Перетащите на другой раздел для перемещения";
      btn.title = btn.title ? `${btn.title}. ${hint}` : hint;
    }
  });
}

async function moveExternalFileToSection(filePath, targetSectionFolder) {
  const nextPath = buildMemoryFileMoveTargetPath(filePath, targetSectionFolder);
  if (nextPath === filePath) return;
  const data = await moveExternalMemoryRecord(filePath, {
    targetPath: getActiveNodeApiPath(),
    targetFile: nextPath
  });
  notifyMarkdownLinkRewrite(data.linkRewrite);
  await refreshExternalMemoryCaches();
  if (activeExternalFilePath === filePath) {
    activeExternalFilePath = data.file;
    await openExternalFile(data.file);
  } else {
    rerenderExternalListViewBody();
  }
  showToast("Перемещено", "success");
}

async function moveMediaFileToSection(filePath, targetSectionFolder) {
  const nextPath = buildMemoryFileMoveTargetPath(filePath, targetSectionFolder);
  if (nextPath === filePath) return;
  const data = await moveMediaStorageRecord(filePath, {
    targetPath: getActiveNodeApiPath(),
    targetFile: nextPath
  });
  notifyMarkdownLinkRewrite(data.linkRewrite);
  await refreshMediaCache();
  if (activeMediaSidecarSourcePath === filePath) {
    await openMediaAsset(data.file);
  } else {
    rerenderMediaListViewBody();
    renderMediaListViewBody(listViewContentNode?.querySelector(".media-list-view-body"));
  }
  showToast("Перемещено", "success");
}

function setupMemoryListDragDrop() {
  const root = listViewContentNode;
  if (!root || root.dataset.memoryDragBound === "1") return;
  root.dataset.memoryDragBound = "1";

  root.addEventListener("dragstart", (event) => {
    const sectionHandle = event.target.closest(".memory-section-sort-handle");
    if (sectionHandle) {
      const row = sectionHandle.closest(".memory-section-sort-row");
      if (!row) {
        event.preventDefault();
        return;
      }
      memorySectionSortDragRow = row;
      row.classList.add("is-dragging");
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", row.dataset.sortSection || "");
      return;
    }

    const fileHandle = event.target.closest(".memory-file-drag-handle");
    if (!fileHandle) return;
    const payloadHost =
      fileHandle.closest(".external-table-row") ||
      fileHandle.closest(".external-list-item") ||
      fileHandle.closest(".media-file-item");
    const filePath = payloadHost?.dataset.memoryFilePath;
    const scope = payloadHost?.dataset.memoryFileScope;
    if (!filePath || !scope) {
      event.preventDefault();
      return;
    }
    memoryFileDragPayload = { filePath, scope };
    payloadHost?.classList.add("is-dragging-memory-file");
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData(
      MEMORY_FILE_DRAG_MIME,
      JSON.stringify({ filePath, scope })
    );
    event.dataTransfer.setData("text/plain", filePath);
  });

  root.addEventListener("dragstart", (event) => {
    if (event.target.closest(".memory-section-sort-handle")) return;
    const sectionBtn = event.target.closest(MEMORY_SECTION_DRAG_SELECTOR);
    if (!sectionBtn) return;
    const folderPath = sectionBtn.dataset.externalSection || sectionBtn.dataset.mediaSection;
    if (!folderPath) return;
    memorySectionMoveDragBtn = sectionBtn;
    sectionBtn.classList.add("is-dragging-memory-section");
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData(
      MEMORY_FILE_DRAG_MIME,
      JSON.stringify({ kind: "section", folderPath, externalMode: Boolean(sectionBtn.dataset.externalSection), mediaMode: Boolean(sectionBtn.dataset.mediaSection) })
    );
    event.dataTransfer.setData("text/plain", folderPath);
  }, true);

  root.addEventListener("dragover", (event) => {
    if (memorySectionSortDragRow) {
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      const targetRow = event.target.closest(".memory-section-sort-row");
      if (!targetRow || targetRow === memorySectionSortDragRow) return;
      const dragPath = getMemorySectionFolderPathFromRow(memorySectionSortDragRow);
      const targetPath = getMemorySectionFolderPathFromRow(targetRow);
      if (!dragPath || !targetPath) return;
      if (getMemorySectionParentPath(dragPath) !== getMemorySectionParentPath(targetPath)) return;
      const list = targetRow.parentElement;
      if (!list) return;
      const blockRows = getMemorySectionSortBlockRows(memorySectionSortDragRow);
      if (blockRows.includes(targetRow)) return;
      const rect = targetRow.getBoundingClientRect();
      insertMemorySectionSortBlock(list, blockRows, targetRow, event.clientY < rect.top + rect.height / 2);
      return;
    }

    if (memorySectionMoveDragBtn) {
      const targetBtn = event.target.closest(MEMORY_SECTION_DRAG_SELECTOR);
      if (!targetBtn || targetBtn === memorySectionMoveDragBtn) {
        clearMemorySectionMoveDropTarget();
        return;
      }
      const move = resolveMemorySectionDragMove(
        memorySectionMoveDragBtn.dataset.externalSection || memorySectionMoveDragBtn.dataset.mediaSection,
        targetBtn.dataset.externalSection || targetBtn.dataset.mediaSection
      );
      if (!move) {
        clearMemorySectionMoveDropTarget();
        return;
      }
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      setMemorySectionMoveDropTarget(targetBtn);
      return;
    }

    if (!memoryFileDragPayload) return;
    const targetBtn = event.target.closest(MEMORY_SECTION_DRAG_SELECTOR);
    if (!targetBtn) return;
    const targetSection = targetBtn.dataset.externalSection || targetBtn.dataset.mediaSection || "";
    const { filePath, scope } = memoryFileDragPayload;
    const sameScope =
      (scope === "external" && targetBtn.dataset.externalSection != null) ||
      (scope === "media" && targetBtn.dataset.mediaSection != null);
    if (!sameScope) return;
    if (getMemoryFileParentPath(filePath) === targetSection) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    setMemorySectionMoveDropTarget(targetBtn);
  });

  root.addEventListener("dragleave", (event) => {
    if (root.contains(event.relatedTarget)) return;
    clearMemorySectionMoveDropTarget();
  });

  root.addEventListener("drop", async (event) => {
    if (memorySectionSortDragRow) {
      event.preventDefault();
      const row = memorySectionSortDragRow;
      const list = row.closest(".media-section-tree-list");
      const tree = list?.closest(".media-section-tree");
      const scope = getMemorySectionSortScope(tree);
      const parentPath = getMemorySectionParentPath(getMemorySectionFolderPathFromRow(row));
      row.classList.remove("is-dragging");
      memorySectionSortDragRow = null;
      if (!list || !scope) return;
      await persistMemorySectionSortOrder(list, parentPath, scope);
      return;
    }

    if (memorySectionMoveDragBtn) {
      const targetBtn = event.target.closest(MEMORY_SECTION_DRAG_SELECTOR);
      clearMemorySectionMoveDropTarget();
      if (!targetBtn || targetBtn === memorySectionMoveDragBtn) return;
      const move = resolveMemorySectionDragMove(
        memorySectionMoveDragBtn.dataset.externalSection || memorySectionMoveDragBtn.dataset.mediaSection,
        targetBtn.dataset.externalSection || targetBtn.dataset.mediaSection
      );
      if (!move) return;
      event.preventDefault();
      event.stopPropagation();
      const sourceLabel =
        getMemorySectionDisplayLabel(move.source) || move.source.split("/").pop() || move.source;
      const targetLabel =
        getMemorySectionDisplayLabel(move.target) || move.target.split("/").pop() || move.target;
      const confirmed = await askConfirm(
        `Переместить «${sourceLabel}» в «${targetLabel}»?`,
        { okLabel: "Подтвердить" }
      );
      if (!confirmed) return;
      const state = {
        sectionFolder: move.source,
        externalMode: Boolean(memorySectionMoveDragBtn.dataset.externalSection),
        mediaMode: Boolean(memorySectionMoveDragBtn.dataset.mediaSection),
        label: sourceLabel
      };
      try {
        const data = await moveMemorySectionApi(move.source, move.parentPath, state);
        await refreshMemorySectionViews(state);
        if (state.externalMode && data.sectionPath) activeExternalSectionFolder = data.sectionPath;
        else if (state.mediaMode && data.sectionPath) activeMediaSectionFolder = data.sectionPath;
        refreshStorageSlotTree();
        showToast("Раздел перемещён", "success");
      } catch (error) {
        showToast(`Ошибка перемещения: ${error.message}`, "error");
      }
      return;
    }

    if (!memoryFileDragPayload) return;
    const targetBtn = event.target.closest(MEMORY_SECTION_DRAG_SELECTOR);
    clearMemorySectionMoveDropTarget();
    if (!targetBtn) return;
    const targetSection = targetBtn.dataset.externalSection ?? targetBtn.dataset.mediaSection ?? "";
    const { filePath, scope } = memoryFileDragPayload;
    const sameScope =
      (scope === "external" && targetBtn.dataset.externalSection != null) ||
      (scope === "media" && targetBtn.dataset.mediaSection != null);
    if (!sameScope || getMemoryFileParentPath(filePath) === targetSection) return;
    event.preventDefault();
    event.stopPropagation();
    const fileLabel = getExternalListItemDisplayTitle({ path: filePath, title: filePath.split("/").pop() });
    const sectionLabel =
      getMemorySectionDisplayLabel(targetSection) || targetSection.split("/").pop() || "корень";
    const confirmed = await askConfirm(
      `Переместить «${fileLabel}» в «${sectionLabel}»?`,
      { okLabel: "Подтвердить" }
    );
    if (!confirmed) return;
    try {
      if (scope === "external") await moveExternalFileToSection(filePath, targetSection);
      else if (scope === "media") await moveMediaFileToSection(filePath, targetSection);
    } catch (error) {
      showToast(`Ошибка перемещения: ${error.message}`, "error");
    }
  });

  root.addEventListener("dragend", () => {
    if (memorySectionSortDragRow) {
      memorySectionSortDragRow.classList.remove("is-dragging");
      memorySectionSortDragRow = null;
    }
    if (memorySectionMoveDragBtn) {
      memorySectionMoveDragBtn.classList.remove("is-dragging-memory-section");
      memorySectionMoveDragBtn = null;
    }
    if (memoryFileDragPayload) {
      root.querySelector(".is-dragging-memory-file")?.classList.remove("is-dragging-memory-file");
      memoryFileDragPayload = null;
    }
    clearMemorySectionMoveDropTarget();
  });
}

function appendMemorySectionTreeLabel(parent, label, { isUnregistered = false, description = "" } = {}) {
  const labelNode = document.createElement("span");
  labelNode.className = "media-section-tree-label";
  if (isUnregistered) labelNode.classList.add("media-section-tree-label--unregistered");
  const titleText = normalizeYamlDisplayString(String(label || "").trim());
  const descText = normalizeYamlDisplayString(String(description || "").trim());
  if (descText) {
    labelNode.append(document.createTextNode(titleText + " "));
    const descNode = document.createElement("span");
    descNode.className = "nav-book-toc-description-text";
    descNode.textContent = `(${descText})`;
    labelNode.appendChild(descNode);
  } else {
    labelNode.textContent = titleText;
  }
  parent.appendChild(labelNode);
  return labelNode;
}

function appendMediaSectionTreeItem(
  list,
  {
    icon,
    label,
    count = null,
    isActive = false,
    isEmpty = false,
    depth = 0,
    onClick,
    sectionFolder = null,
    readmeExists = false,
    onSectionReadmeEdit = null,
    sectionStorageMode = null,
    sectionExternalMode = null,
    sectionMediaMode = null
  }
) {
  const isUnregistered = isMemorySectionUnregistered(sectionFolder, readmeExists);
  const row = document.createElement("div");
  row.className = "media-section-tree-row";
  if (depth > 0) {
    row.classList.add("is-nested");
    row.style.paddingLeft = `${8 + depth * 14}px`;
  }
  if (isUnregistered) row.classList.add("media-section-tree-row--unregistered");

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "media-section-tree-item";
  btn.setAttribute("role", "treeitem");
  btn.title = isUnregistered ? getMemorySectionUnregisteredTitle(sectionFolder) : label;
  btn.classList.toggle("is-active", isActive);
  btn.classList.toggle("is-empty", isEmpty);
  btn.classList.toggle("media-section-tree-item--unregistered", isUnregistered);
  if (depth > 0) btn.classList.add("is-nested");

  const iconNode = document.createElement("span");
  iconNode.className = "media-section-tree-icon";
  iconNode.setAttribute("aria-hidden", "true");
  iconNode.textContent = icon;

  btn.appendChild(iconNode);
  appendMemorySectionTreeLabel(btn, label, { isUnregistered });

  if (count !== null) {
    const badge = document.createElement("span");
    badge.className = "media-section-tree-count";
    badge.textContent = String(count);
    btn.appendChild(badge);
  }

  btn.addEventListener("click", onClick);
  row.appendChild(btn);

  if (sectionFolder) {
    btn.addEventListener("contextmenu", (event) => {
      openResourceContextMenu(event, {
        kind: "memorySection",
        sectionFolder,
        readmeExists,
        storageMode: sectionStorageMode,
        externalMode: sectionExternalMode,
        mediaMode: sectionMediaMode,
        label: getMemorySectionDisplayLabel(sectionFolder) || label,
        onReadmeEdit: onSectionReadmeEdit
      });
    });
  }

  list.appendChild(row);
  return btn;
}

function ensureMediaSectionTree(container) {
  if (!container) return;
  if (
    container.querySelector(":scope > .media-section-tree-list") &&
    !isMemorySectionTreeStale(container, {
      getExpectedCount: () => getMediaUserSections().length,
      datasetAttr: "media-section"
    })
  ) {
    syncMediaSectionTreeActiveState();
    decorateMemorySectionSortRows(container);
    return;
  }
  renderMediaSectionTree(container);
}

function renderMediaSectionTree(container) {
  if (!container) return;
  container.replaceChildren();

  const list = document.createElement("div");
  list.className = "media-section-tree-list";
  list.setAttribute("role", "tree");
  container.appendChild(list);

  const allBtn = appendMediaSectionTreeItem(list, {
    icon: "📋",
    label: "Все файлы",
    count: formatMemorySectionTreeCount(getMediaSectionFileCounts(null), { allItems: true }),
    isActive: mediaViewMode === "all" && !activeMediaSectionFolder,
    onClick: () => setMediaViewMode("all", { clearSection: true })
  });
  allBtn.dataset.mediaView = "all";

  const divider = document.createElement("div");
  divider.className = "media-section-tree-divider";
  divider.setAttribute("role", "presentation");
  list.appendChild(divider);

  const userSections = getMediaUserSections();
  if (userSections.length === 0) {
    const empty = document.createElement("div");
    empty.className = "media-section-tree-empty";
    empty.textContent = "Нет разделов. Создайте раздел через «+ Раздел».";
    list.appendChild(empty);
  } else {
    appendMemorySectionTreeNodes(list, buildMemorySectionForest(userSections), {
      datasetKey: "mediaSection",
      countFn: getMediaSectionFileCounts,
      isActive: (folderPath) => activeMediaSectionFolder === folderPath,
      onSelect: (folderPath) => setActiveMediaSectionFolder(folderPath),
      readmeExists: mediaSectionReadmeExists,
      onReadmeEdit: (readmePath, folderPath) => void openMediaSectionReadme(readmePath, folderPath),
      mediaMode: true
    });
  }
  ensureStorageTreePolicyFooter(container, activeContentMode);
  decorateMemorySectionSortRows(container);
}

function ensureMediaListViewLayout() {
  const mode = activeContentMode;
  const mountRoot = getListViewMountRoot(mode);
  const existing = mountRoot.querySelector(".media-list-view-wrap:not(.external-list-view-wrap):not(.flat-storage-list-view-wrap)");
  if (!existing) {
    mountRoot.innerHTML = "";
    if (!shouldUseDataHubListShell(mode)) listViewContentNode.innerHTML = "";
    mountMediaListViewLayout(mountRoot);
  } else if (shouldUseDataHubListShell(mode)) {
    const slotTree = getStorageSlotTreeNode();
    if (shouldRenderStorageSlotTree(slotTree)) {
      void renderStorageSlotTree(slotTree);
    } else {
      syncStorageSlotTreeActiveState(slotTree);
    }
  }
  const wrap = mountRoot.querySelector(".media-list-view-wrap:not(.external-list-view-wrap):not(.flat-storage-list-view-wrap)");
  if (!wrap) return null;
  ensureMediaListViewMainWrapper();
  ensureMediaSectionTree(wrap.querySelector(".media-section-tree"));
  syncStorageSectionsPanelUi();
  syncMediaListSectionHead(isStorageSectionsPanelVisible() ? activeMediaSectionFolder : null);
  return wrap.querySelector(".media-list-view-body");
}

function renderMediaAllFilesSections(container) {
  const raw = getListViewRawContent();
  const sections = parseMediaSections(raw);
  const naturalCollator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });

  function comparePathsNatural(aPath, bPath) {
    const aParts = aPath.split("/").filter(Boolean);
    const bParts = bPath.split("/").filter(Boolean);
    const len = Math.min(aParts.length, bParts.length);
    for (let i = 0; i < len; i += 1) {
      const cmp = naturalCollator.compare(aParts[i], bParts[i]);
      if (cmp !== 0) return cmp;
    }
    return aParts.length - bParts.length;
  }

  if (!raw.trim()) {
    renderListEmptyMessage(container, getStorageFolderEmptyMessage(activeContentMode));
    return;
  }

  for (const section of sections) {
    const normalizedItems = section.items
      .map((item) => normalizeListItem(item))
      .filter((item) => item.path && !isSectionReadmePath(item.path))
      .sort((a, b) => {
        if (a.isFolder !== b.isFolder) return a.isFolder ? -1 : 1;
        return comparePathsNatural(a.path, b.path);
      });

    if (normalizedItems.length === 0) continue;

    const sectionNode = document.createElement("section");
    sectionNode.className = "list-section";

    const headerNode = document.createElement("div");
    headerNode.className = "list-section-header";
    headerNode.textContent = section.title;
    sectionNode.appendChild(headerNode);

    const listNode = document.createElement("ul");
    listNode.className = "list-items";

    for (const normalized of normalizedItems) {
      const li = document.createElement("li");
      li.className = "list-item";

      const icon = document.createElement("span");
      icon.className = "list-item-icon";
      icon.textContent = normalized.isFolder ? "📁" : "📄";

      const pathNode = document.createElement("span");
      pathNode.className = "list-item-path";
      pathNode.textContent = normalized.path;

      li.appendChild(icon);
      li.appendChild(pathNode);

      if (!normalized.isFolder) {
        li.classList.add("list-item-with-actions");
        const actions = document.createElement("div");
        actions.className = "list-item-actions";
        appendMediaItemActionButtons(actions, { path: normalized.path });
        li.appendChild(actions);
      }

      listNode.appendChild(li);
    }

    sectionNode.appendChild(listNode);
    container.appendChild(sectionNode);
  }
}

function renderMediaListViewBody(container) {
  if (!mediaAssetsExists) {
    renderListEmptyMessage(container, getStorageFolderMissingMessage("media"));
    return;
  }
  if (!Object.values(mediaFilesCache).some((items) => Array.isArray(items) && items.length > 0)) {
    syncMediaFilesCache(modeContentCache.media, mediaFilesCache);
  }
  pruneActiveMediaSectionFolder();
  syncMediaViewSelectOptions();
  if (mediaViewSelectNode) mediaViewSelectNode.value = getEffectiveMediaViewMode();
  const viewMode = getEffectiveMediaViewMode();
  const mediaTree = getMediaSectionTreeNode();
  if (mediaTree) ensureMediaSectionTree(mediaTree);
  syncStorageSectionsPanelUi();
  syncMediaListSectionHead(isStorageSectionsPanelVisible() ? activeMediaSectionFolder : null);
  if (viewMode === "dashboard" && (!activeMediaSectionFolder || !isStorageSectionsPanelVisible())) {
    renderMediaUsageDashboard(container);
    return;
  }
  if (isStorageSectionsPanelVisible() && activeMediaSectionFolder) {
    if (viewMode === "all") {
      renderMediaSectionFolderView(container, activeMediaSectionFolder);
      return;
    }
    renderMediaFilteredView(container, viewMode);
    return;
  }
  if (viewMode !== "all") {
    renderMediaFilteredView(container, viewMode);
    return;
  }
  renderMediaAllFilesSections(container);
}

function mountMediaListViewLayout(root) {
  const wrap = document.createElement("div");
  wrap.className = "media-list-view-wrap";

  const uploadHost = document.createElement("div");
  uploadHost.className = "media-bulk-upload-host";
  wrap.appendChild(uploadHost);
  mountMediaBulkUploadZone(uploadHost);
  syncMediaBulkUploadPanelUi();

  const split = document.createElement("div");
  split.className = "media-list-view-split";

  const treeHost = document.createElement("nav");
  treeHost.className = "media-section-tree";
  treeHost.setAttribute("aria-label", "Разделы медиа");
  split.appendChild(treeHost);

  const main = document.createElement("div");
  main.className = "media-list-view-main";
  const sectionHead = document.createElement("div");
  sectionHead.className = "media-list-section-head";
  const body = document.createElement("div");
  body.className = "media-list-view-body";
  main.append(sectionHead, body);
  split.appendChild(main);

  wrap.appendChild(split);
  root.appendChild(wrap);
  ensureMediaSectionTree(treeHost);
  syncStorageSectionsPanelUi();
  syncMediaListSectionHead(isStorageSectionsPanelVisible() ? activeMediaSectionFolder : null);
  return body;
}

function buildExternalListingFallbackContent(files = externalFilesCache, folders = externalFoldersCache) {
  const lines = [];
  for (const folder of folders) {
    const folderPath = String(folder.path || "").replace(/\\/g, "/").replace(/\/$/, "");
    if (folderPath) lines.push(`📁 ${folderPath}/`);
  }
  for (const file of files) {
    const path = String(file.relativePath || "").replace(/\\/g, "/");
    if (path) lines.push(path);
  }
  return lines.join("\n");
}

function compareExternalPathsNatural(aPath, bPath) {
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  const aParts = String(aPath || "").split("/").filter(Boolean);
  const bParts = String(bPath || "").split("/").filter(Boolean);
  const len = Math.min(aParts.length, bParts.length);
  for (let i = 0; i < len; i += 1) {
    const cmp = collator.compare(aParts[i], bParts[i]);
    if (cmp !== 0) return cmp;
  }
  return aParts.length - bParts.length;
}

function getExternalUserSections() {
  const folderPaths = new Set();

  for (const raw of parseFlatListItems(modeContentCache.external)) {
    const normalized = normalizeListItem(raw);
    if (!normalized.isFolder) continue;
    const folderPath = String(normalized.path || "").replace(/\/$/, "");
    addMemorySectionFolderPath(folderPaths, folderPath);
  }

  for (const folder of externalFoldersCache) {
    const folderPath = String(folder.path || "").replace(/\\/g, "/").replace(/\/$/, "");
    if (!folderPath) continue;
    addMemorySectionFolderPath(folderPaths, folderPath);
    const parts = folderPath.split("/").filter(Boolean);
    let built = "";
    for (const part of parts) {
      built = built ? `${built}/${part}` : part;
      addMemorySectionFolderPath(folderPaths, built);
    }
  }

  for (const file of externalFilesCache) {
    const parent = String(file.parent || "").replace(/\\/g, "/");
    if (!parent || parent === ".") continue;
    const parts = parent.split("/").filter(Boolean);
    let built = "";
    for (const part of parts) {
      built = built ? `${built}/${part}` : part;
      addMemorySectionFolderPath(folderPaths, built);
    }
  }

  for (const file of externalFilesCache) {
    const path = String(file.relativePath || "").replace(/\\/g, "/");
    if (!path || isSectionReadmePath(path) || isMemorySectionInfrastructureFilePath(path)) continue;
    for (const ancestor of collectNavigationFolderAncestors(path)) {
      addMemorySectionFolderPath(folderPaths, ancestor);
    }
  }

  return mapMemorySectionFolderPaths(folderPaths);
}

function getExternalSectionFileCounts(sectionFolder) {
  const normalizedSection = String(sectionFolder || "").replace(/\\/g, "/").replace(/\/$/, "");
  let direct = 0;
  let total = 0;
  for (const file of externalFilesCache) {
    const path = String(file.relativePath || "").replace(/\\/g, "/");
    if (isSectionReadmePath(path)) continue;
    if (!normalizedSection) {
      total += 1;
      continue;
    }
    const prefix = `${normalizedSection}/`;
    const parent = String(file.parent || "").replace(/\\/g, "/");
    if (!path.startsWith(prefix) && parent !== normalizedSection) continue;
    total += 1;
    if (parent === normalizedSection) direct += 1;
  }
  return { direct, total };
}

function countExternalFilesInSection(sectionFolder) {
  return getExternalSectionFileCounts(sectionFolder).total;
}

function pruneActiveExternalSectionFolder() {
  if (!activeExternalSectionFolder) return;
  const exists = getExternalUserSections().some(
    (section) => section.folderPath === activeExternalSectionFolder
  );
  if (!exists) activeExternalSectionFolder = null;
}

function getExternalItemContextPath(item, nodePath = activePath) {
  const rel = String(item?.path || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const base = getResolvedNodePath(nodePath);
  if (!rel) return getNodeStorageSubfolderPath(base, "external");
  return `${getNodeStorageSubfolderPath(base, "external")}/${rel}`.replace(/\/+/g, "/");
}

function normalizeExternalMemoryMdRelPath(relPath) {
  const normalized = String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "").trim();
  if (!normalized) return "";
  if (/\.md$/i.test(normalized)) return normalized;
  const baseName = normalized.split("/").pop() || "";
  if (/\.[a-z0-9]+$/i.test(baseName)) return normalized;
  return `${normalized}.md`;
}

function resolveExternalItemPreviewUi(item, nodePath = activePath) {
  const props = Array.isArray(item?.props) ? item.props : [];
  const previewPath = getPropsEntryValueByKey(props, "awn-preview");
  const contextPath = getExternalItemContextPath(item, nodePath);
  if (previewPath) return buildPreviewUiFromPath(previewPath, contextPath);
  if (item?.hasPreview && item?.previewUrl) {
    return { imageUrl: item.previewUrl, previewPath: "" };
  }
  return null;
}

function resolveNavigationItemPreviewUi(item, nodePath = activePath) {
  const externalPreview = resolveExternalItemPreviewUi(item, nodePath);
  if (externalPreview) return externalPreview;

  const path = String(item?.path || "").replace(/\\/g, "/");
  const group = String(item?.group || "").trim();
  const ext = String(item?.ext || path.split(".").pop() || "").toLowerCase();
  const isImage =
    group === "Images" || /^(?:jpe?g|png|gif|webp|heic|heif|bmp|svg)$/.test(ext.replace(/^\./, ""));
  if (!path || !isImage) return null;

  const imageUrl = appendCacheBuster(buildMediaThumbUrl(path, nodePath, MEDIA_THUMB_MAX_SMALL));
  return imageUrl ? { imageUrl, previewPath: path } : null;
}

function appendExternalItemPreviewThumb(parent, item, { className = "" } = {}) {
  const preview = resolveExternalItemPreviewUi(item);
  if (!preview) return false;

  if (preview.broken) {
    parent.appendChild(
      createBrokenImagePlaceholder({ label: "Превью не найдено", className })
    );
    return true;
  }

  const rawUrl = String(preview.imageUrl || "").trim();
  if (!rawUrl) return false;

  const imageUrl =
    /^https?:\/\//i.test(rawUrl) || rawUrl.startsWith("/api/")
      ? appendCacheBuster(appendAgentToApiUrl(rawUrl))
      : appendCacheBuster(rawUrl);

  const img = document.createElement("img");
  img.className = className;
  img.alt = "";
  img.loading = "lazy";
  img.draggable = false;
  img.src = imageUrl;
  img.onerror = () => {
    parent.replaceChildren(
      createBrokenImagePlaceholder({ label: "Превью не найдено", className })
    );
  };
  parent.appendChild(img);
  return true;
}

function getExternalMdItems() {
  return externalFilesCache
    .map((item) => ({
      path: item.relativePath,
      name: item.name,
      parent: item.parent,
      createdAt: item.createdAt,
      updatedAt: item.updatedAt,
      title: item.title || item.name.replace(/\.md$/i, ""),
      props: Array.isArray(item.props) ? item.props : [],
      status: item.status || "",
      tags: item.tags || "",
      hasPreview: Boolean(item.hasPreview),
      previewUrl: item.previewUrl || null
    }))
    .sort((a, b) => compareExternalPathsNatural(a.path, b.path));
}

const EXTERNAL_LIST_SORT_OPTIONS = [
  { key: "path", label: "Путь" },
  { key: "file", label: "Файл" },
  { key: "title", label: "Заголовок" },
  { key: "section", label: "Раздел" },
  { key: "created", label: "Создан" },
  { key: "updated", label: "Обновлён" }
];

function getExternalItemSearchHaystack(item) {
  const parts = [
    item.path,
    item.name,
    item.title,
    item.status,
    item.tags,
    formatExternalCardSection(item),
    formatExternalTableParent(item),
    getExternalCardFileName(item)
  ];
  if (Array.isArray(item.props)) {
    for (const entry of item.props) {
      if (!entry?.key) continue;
      parts.push(entry.key);
      if (entry.kind === "array") parts.push((entry.value || []).join(", "));
      else if (entry.kind === "bool") parts.push(entry.value ? "true" : "false");
      else if (entry.value !== null && entry.value !== undefined) parts.push(String(entry.value));
    }
  }
  return parts.filter(Boolean).join("\n").toLowerCase();
}

function filterExternalListItems(items, query = externalListFilterQuery) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return items;
  return items.filter((item) => getExternalItemSearchHaystack(item).includes(q));
}

function getExternalItemSortValue(item, key) {
  switch (key) {
    case EXTERNAL_TABLE_FILE_COLUMN_KEY:
    case "file":
      return getExternalListItemDisplayTitle(item);
    case "title":
      return getExternalListItemDisplayTitle(item);
    case "section":
      return formatExternalCardSection(item);
    case "created":
      return item.createdAt || "";
    case "updated":
      return item.updatedAt || "";
    default:
      if (key === "path") return item.path || "";
      return getPropsEntryValueByKey(Array.isArray(item.props) ? item.props : [], key);
  }
}

function sortExternalListItems(items, sort = externalListSort) {
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  const dir = sort.dir === "desc" ? -1 : 1;
  const key = sort.key;
  return [...items].sort((a, b) => {
    let cmp = 0;
    if (key === "path") {
      cmp = compareExternalPathsNatural(a.path, b.path);
    } else if (key === "created" || key === "updated") {
      const av = getExternalItemSortValue(a, key);
      const bv = getExternalItemSortValue(b, key);
      cmp = av === bv ? 0 : av < bv ? -1 : 1;
    } else {
      cmp = collator.compare(getExternalItemSortValue(a, key), getExternalItemSortValue(b, key));
    }
    return cmp * dir;
  });
}

function prepareExternalListItems(items) {
  const contentItems = items.filter((item) => !isSectionReadmePath(item.path));
  return sortExternalListItems(filterExternalListItems(contentItems));
}

function getExternalListSchemaManifestPath(nodePath = getResolvedNodePath(activePath)) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (!normalized) return null;
  if (isTopicManifestPath(normalized)) return normalized;
  const fromBundle = resolveTopicManifestFromBundlePath(normalized);
  if (fromBundle) return fromBundle;
  if (isNodeManifestPath(normalized)) return normalized;
  return getTopicSchemaManifestPath(nodePath);
}

function getExternalListColumnsStorageKey() {
  const manifest = getExternalListSchemaManifestPath() || activePath || "";
  return `${EXTERNAL_LIST_COLUMNS_STORAGE_PREFIX}${activeAgentId || "main"}:${manifest}`;
}

function mergeExternalListVisibleColumnKeys(storedKeys, allKeys) {
  const standard = new Set(getStandardPropsFieldKeys());
  const merged = [...storedKeys];
  for (const key of allKeys) {
    if (standard.has(key) || merged.includes(key)) continue;
    merged.push(key);
  }
  return merged.filter((key) => allKeys.includes(key));
}

function getExternalListVisibleColumnKeys() {
  const scope = getExternalListColumnsStorageKey();
  const allKeys = getExternalTableSchemaColumns().map((column) => column.key);
  if (!allKeys.length) return [];

  if (externalListVisibleColumnKeysScope !== scope) {
    externalListVisibleColumnKeysScope = scope;
    externalListVisibleColumnKeysCache = null;
    const stored = readStorageItem(scope);
    if (stored) {
      try {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          externalListVisibleColumnKeysCache = parsed.filter((key) => allKeys.includes(key));
        }
      } catch {
        externalListVisibleColumnKeysCache = null;
      }
    }
  }

  if (!externalListVisibleColumnKeysCache?.length) return allKeys;
  return mergeExternalListVisibleColumnKeys(externalListVisibleColumnKeysCache, allKeys);
}

function setExternalListVisibleColumnKeys(keys) {
  const allKeys = getExternalTableSchemaColumns().map((column) => column.key);
  const normalized = keys.filter((key) => allKeys.includes(key));
  externalListVisibleColumnKeysCache = normalized.length ? normalized : [...allKeys];
  externalListVisibleColumnKeysScope = getExternalListColumnsStorageKey();
  writeStorageItem(externalListVisibleColumnKeysScope, JSON.stringify(externalListVisibleColumnKeysCache));
  syncExternalListToolbarFromState();
  rerenderExternalListViewBody();
}

function getExternalTableVisibleColumns() {
  const visible = new Set(getExternalListVisibleColumnKeys());
  return getExternalTableSchemaColumns().filter((column) => visible.has(column.key));
}

function getExternalTableFixedColumns() {
  return [
    {
      key: "awn-preview",
      label: "Превью",
      fieldDef: null,
      typeId: null,
      fixed: true,
      optional: true
    },
    {
      key: EXTERNAL_TABLE_FILE_COLUMN_KEY,
      label: "Название",
      fieldDef: null,
      typeId: null,
      fixed: true
    }
  ];
}

function getExternalTableDisplayColumns() {
  const visibleKeys = new Set(getExternalListVisibleColumnKeys());
  const fixed = getExternalTableFixedColumns().filter(
    (column) => !column.optional || visibleKeys.has(column.key)
  );
  const schema = getExternalTableVisibleColumns().filter((column) => column.key !== "awn-preview");
  return [...fixed, ...schema];
}

function syncExternalListToolbarMeta(shown, total) {
  const countNode = listViewContentNode?.querySelector(".external-list-results-count");
  if (!countNode) return;
  countNode.textContent =
    shown === total ? `${total} элементов` : `${shown} из ${total}`;
}

function syncExternalListToolbarFromState() {
  syncExternalListSectionHead(
    isStorageSectionsPanelVisible() ? activeExternalSectionFolder : null
  );

  const toolbar = listViewContentNode?.querySelector(".external-list-toolbar");
  if (!toolbar) return;
  const filterInput = toolbar.querySelector(".external-list-filter-input");
  const sortSelect = toolbar.querySelector(".external-list-sort-select");
  const sortDirBtn = toolbar.querySelector(".external-list-sort-dir-btn");
  const columnsBtn = toolbar.querySelector(".external-list-columns-btn");
  if (filterInput && filterInput.value !== externalListFilterQuery) {
    filterInput.value = externalListFilterQuery;
  }
  const sectionHeadSearch = listViewContentNode?.querySelector(
    ".external-list-section-head .node-navigation-section-search-input"
  );
  if (sectionHeadSearch && sectionHeadSearch.value !== externalListFilterQuery) {
    sectionHeadSearch.value = externalListFilterQuery;
  }
  syncExternalListSortSelectOptions(sortSelect);
  if (sortSelect && !sortSelect.querySelector(`option[value="${CSS.escape(externalListSort.key)}"]`)) {
    externalListSort.key = "path";
  }
  if (sortSelect) sortSelect.value = externalListSort.key;
  if (sortDirBtn) sortDirBtn.textContent = externalListSort.dir === "asc" ? "↑" : "↓";
  if (columnsBtn) {
    const visibleCount = getExternalListVisibleColumnKeys().length;
    const totalCount = getExternalTableSchemaColumns().length;
    columnsBtn.textContent =
      visibleCount === totalCount ? "Колонки" : `Колонки (${visibleCount})`;
  }
}

function renderExternalListColumnsPanel(panel) {
  if (!panel) return;
  panel.replaceChildren();

  const head = document.createElement("div");
  head.className = "external-list-columns-panel-head";
  const title = document.createElement("span");
  title.className = "external-list-columns-panel-title";
  title.textContent = "Колонки YAML";
  const actions = document.createElement("div");
  actions.className = "external-list-columns-panel-actions";
  const showAllBtn = document.createElement("button");
  showAllBtn.type = "button";
  showAllBtn.className = "external-list-columns-action-btn";
  showAllBtn.textContent = "Все";
  showAllBtn.addEventListener("click", () => {
    setExternalListVisibleColumnKeys(getExternalTableSchemaColumns().map((column) => column.key));
    renderExternalListColumnsPanel(panel);
  });
  actions.append(showAllBtn);
  head.append(title, actions);
  panel.appendChild(head);

  const list = document.createElement("div");
  list.className = "external-list-columns-panel-list";
  const visible = new Set(getExternalListVisibleColumnKeys());

  for (const column of getExternalTableSchemaColumns()) {
    const label = document.createElement("label");
    label.className = "external-list-columns-option";

    const input = document.createElement("input");
    input.type = "checkbox";
    input.checked = visible.has(column.key);
    input.addEventListener("change", () => {
      const next = new Set(getExternalListVisibleColumnKeys());
      if (input.checked) next.add(column.key);
      else next.delete(column.key);
      if (!next.size) {
        input.checked = true;
        return;
      }
      setExternalListVisibleColumnKeys([...next]);
      renderExternalListColumnsPanel(panel);
    });

    const text = document.createElement("span");
    text.textContent = column.label;
    text.title = column.key;
    label.append(input, text);
    list.appendChild(label);
  }

  panel.appendChild(list);
}

function bindExternalListColumnsPicker(wrap, columnsBtn, columnsPanel) {
  if (!wrap || !columnsBtn || !columnsPanel || columnsBtn.dataset.bound === "1") return;
  columnsBtn.dataset.bound = "1";

  columnsBtn.addEventListener("click", (event) => {
    event.stopPropagation();
    const willOpen = columnsPanel.classList.contains("hidden");
    document.querySelectorAll(".external-list-columns-panel").forEach((node) => {
      if (node !== columnsPanel) node.classList.add("hidden");
    });
    if (willOpen) renderExternalListColumnsPanel(columnsPanel);
    columnsPanel.classList.toggle("hidden");
  });

  if (!wrap.dataset.columnsPickerBound) {
    wrap.dataset.columnsPickerBound = "1";
    document.addEventListener("click", (event) => {
      if (wrap.contains(event.target)) return;
      columnsPanel.classList.add("hidden");
    });
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") columnsPanel.classList.add("hidden");
    });
  }
}

function syncExternalListSortSelectOptions(sortSelect) {
  if (!sortSelect) return;
  const options = getExternalListSortOptions();
  const current = sortSelect.value || externalListSort.key;
  sortSelect.replaceChildren();
  for (const option of options) {
    const opt = document.createElement("option");
    opt.value = option.key;
    opt.textContent = option.label;
    sortSelect.appendChild(opt);
  }
  sortSelect.value = options.some((option) => option.key === current) ? current : "path";
}

function createExternalListToolbar() {
  const toolbar = document.createElement("div");
  toolbar.className = "external-list-toolbar";

  const countNode = document.createElement("span");
  countNode.className = "external-list-results-count";
  countNode.textContent = "0 элементов";

  const filterInput = document.createElement("input");
  filterInput.type = "search";
  filterInput.className = "external-list-filter-input";
  filterInput.placeholder = "Поиск по файлам, заголовкам, тэгам…";
  filterInput.setAttribute("aria-label", "Фильтр внешней памяти");
  filterInput.value = externalListFilterQuery;
  filterInput.addEventListener("input", () => {
    externalListFilterQuery = filterInput.value;
    rerenderExternalListViewBody();
  });

  const sortSelect = document.createElement("select");
  sortSelect.className = "external-list-sort-select";
  sortSelect.setAttribute("aria-label", "Сортировка внешней памяти");
  for (const option of EXTERNAL_LIST_SORT_OPTIONS) {
    const opt = document.createElement("option");
    opt.value = option.key;
    opt.textContent = option.label;
    sortSelect.appendChild(opt);
  }
  sortSelect.value = externalListSort.key;
  sortSelect.addEventListener("change", () => {
    externalListSort.key = sortSelect.value;
    rerenderExternalListViewBody();
  });

  const sortDirBtn = document.createElement("button");
  sortDirBtn.type = "button";
  sortDirBtn.className = "external-list-sort-dir-btn";
  sortDirBtn.title = "Направление сортировки";
  sortDirBtn.setAttribute("aria-label", "Направление сортировки");
  const syncSortDirBtn = () => {
    sortDirBtn.textContent = externalListSort.dir === "asc" ? "↑" : "↓";
  };
  syncSortDirBtn();
  sortDirBtn.addEventListener("click", () => {
    externalListSort.dir = externalListSort.dir === "asc" ? "desc" : "asc";
    syncSortDirBtn();
    rerenderExternalListViewBody();
  });

  const controls = document.createElement("div");
  controls.className = "external-list-toolbar-controls";

  const columnsWrap = document.createElement("div");
  columnsWrap.className = "external-list-columns-wrap";
  const columnsBtn = document.createElement("button");
  columnsBtn.type = "button";
  columnsBtn.className = "external-list-columns-btn";
  columnsBtn.textContent = "Колонки";
  columnsBtn.title = "Видимые колонки таблицы";
  columnsBtn.setAttribute("aria-haspopup", "true");
  const columnsPanel = document.createElement("div");
  columnsPanel.className = "external-list-columns-panel hidden";
  columnsPanel.setAttribute("role", "menu");
  columnsWrap.append(columnsBtn, columnsPanel);
  bindExternalListColumnsPicker(columnsWrap, columnsBtn, columnsPanel);

  controls.append(filterInput, columnsWrap, sortSelect, sortDirBtn);

  toolbar.append(countNode, controls);
  return toolbar;
}

function ensureExternalListToolbar(wrap) {
  if (!wrap) return;
  const split = wrap.querySelector(".external-list-view-split");
  let body = wrap.querySelector(".external-list-view-body");
  if (!split || !body) return;

  let main = wrap.querySelector(".external-list-view-main");
  main?.querySelector(".memory-list-view-crumbs")?.remove();

  if (!main) {
    main = document.createElement("div");
    main.className = "external-list-view-main media-list-view-main";
    split.replaceChild(main, body);
    const sectionHead = document.createElement("div");
    sectionHead.className = "external-list-section-head";
    main.append(sectionHead, createExternalListToolbar(), body);
    return;
  }

  ensureExternalListSectionHeadHost(main);

  if (!main.querySelector(".external-list-toolbar")) {
    const sectionHead = main.querySelector(".external-list-section-head");
    const toolbar = createExternalListToolbar();
    if (sectionHead) sectionHead.insertAdjacentElement("afterend", toolbar);
    else main.prepend(toolbar);
  }

  ensureExternalListColumnsPicker(main.querySelector(".external-list-toolbar"));
}

function ensureExternalListColumnsPicker(toolbar) {
  if (!toolbar || toolbar.querySelector(".external-list-columns-wrap")) return;
  const controls = toolbar.querySelector(".external-list-toolbar-controls");
  const sortSelect = controls?.querySelector(".external-list-sort-select");
  if (!controls || !sortSelect) return;

  const columnsWrap = document.createElement("div");
  columnsWrap.className = "external-list-columns-wrap";
  const columnsBtn = document.createElement("button");
  columnsBtn.type = "button";
  columnsBtn.className = "external-list-columns-btn";
  columnsBtn.textContent = "Колонки";
  columnsBtn.title = "Видимые колонки таблицы";
  columnsBtn.setAttribute("aria-haspopup", "true");
  const columnsPanel = document.createElement("div");
  columnsPanel.className = "external-list-columns-panel hidden";
  columnsPanel.setAttribute("role", "menu");
  columnsWrap.append(columnsBtn, columnsPanel);
  bindExternalListColumnsPicker(columnsWrap, columnsBtn, columnsPanel);
  controls.insertBefore(columnsWrap, sortSelect);
}

async function ensureExternalListSchemaReady() {
  const manifestPath = getExternalListSchemaManifestPath();
  const key = `${activeAgentId || ""}:${manifestPath || ""}`;
  if (externalListSchemaReadyKey !== key) {
    externalListSchemaReadyKey = key;
    externalListSchemaReadyPromise = null;
  }
  if (!externalListSchemaReadyPromise) {
    externalListSchemaReadyPromise = (async () => {
      if (!awnTypesCache) await loadAwnTypes(activeAgentId);
      if (manifestPath && !getTopicSchemaCache(manifestPath)) {
        await loadTopicSchemaForManifest(manifestPath).catch(() => null);
      }
    })();
  }
  return externalListSchemaReadyPromise;
}

function getExternalCardFileName(item) {
  return String(item.name || item.path.split("/").pop() || "").replace(/\.md$/i, "");
}

function getExternalListItemDisplayTitle(item) {
  const props = Array.isArray(item?.props) ? item.props : [];
  const awnName = getPropsEntryValueByKey(props, "awn-name");
  const slug = getExternalCardFileName(item);
  const resolved = resolveNodeDisplayName(awnName, slug);
  if (resolved && resolved !== slug) return resolved;
  const title = normalizeYamlDisplayString(String(item?.title || "").trim());
  return title || resolved || slug;
}

function formatExternalCardPathLine(item) {
  const path = String(item?.path || "").replace(/\\/g, "/").trim();
  if (path) return path.split("/").pop() || path;
  const name = String(item?.name || "").trim();
  if (name) return name;
  const slug = getExternalCardFileName(item);
  return slug ? `${slug}.md` : "";
}

function formatExternalFileCreatedLabel(createdAt) {
  if (!createdAt) return "—";
  try {
    return new Date(createdAt).toLocaleDateString("ru-RU", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric"
    });
  } catch {
    return "—";
  }
}

function formatExternalCardSection(item) {
  const parent = String(item.parent || "").replace(/\\/g, "/").trim();
  if (!parent || parent === ".") return "Корень";
  return parent;
}

function formatExternalTableParent(item) {
  const parent = String(item.parent || "").replace(/\\/g, "/").trim();
  if (!parent || parent === ".") return "—";
  return parent;
}

function formatExternalTableFilePathBasenames(rawValue) {
  const raw = String(rawValue || "").trim();
  if (!raw) return "—";
  const paths = raw
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
  if (!paths.length) return "—";
  return paths
    .map((path) => {
      const normalized = path.replace(/\\/g, "/");
      return normalized.split("/").pop() || normalized;
    })
    .join(", ");
}

function formatExternalTablePropDisplay(column, item) {
  const entries = Array.isArray(item.props) ? item.props : [];
  let value = getPropsEntryValueByKey(entries, column.key);
  if (!value && column.key === "awn-status") value = String(item.status || "").trim();
  if (!value && column.key === "awn-tags") value = String(item.tags || "").trim();
  if (!value) return "—";

  if (column.key === "awn-attachments" || column.typeId === "awn.file") {
    return formatExternalTableFilePathBasenames(value);
  }

  if (column.key === "awn-type") {
    const typeDef = awnTypesCache?.types?.[value];
    if (typeDef?.name) return typeDef.name;
  }

  if (column.typeId === "awn.boolean") {
    const normalized = String(value).trim().toLowerCase();
    if (normalized === "true" || normalized === "да") return "Да";
    if (normalized === "false" || normalized === "нет") return "Нет";
  }

  if (column.typeId === "awn.link") {
    const linkMatch = String(value).match(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/);
    if (linkMatch) return (linkMatch[2] || linkMatch[1]).trim();
  }

  return value;
}

function appendExternalTableSchemaCell(row, column, item) {
  const cell = document.createElement("td");

  if (column.key === EXTERNAL_TABLE_FILE_COLUMN_KEY) {
    cell.className = "external-table-file-cell";
    const fileName = getExternalCardFileName(item);
    const title = getExternalListItemDisplayTitle(item);
    cell.textContent = title || fileName;
    if (title && title !== fileName) cell.title = fileName;
    row.appendChild(cell);
    return;
  }

  if (column.key === "awn-preview") {
    cell.className = "external-table-cover-cell";
    if (!appendExternalItemPreviewThumb(cell, item, { className: "external-table-cover-thumb" })) {
      cell.textContent = "—";
    }
    row.appendChild(cell);
    return;
  }

  if (column.typeId === "awn.color") {
    cell.className = "external-table-color-cell";
    const raw = formatExternalTablePropDisplay(column, item);
    if (raw && raw !== "—") {
      const swatch = document.createElement("span");
      swatch.className = "external-table-color-swatch";
      swatch.style.backgroundColor = raw;
      swatch.setAttribute("aria-hidden", "true");
      cell.appendChild(swatch);
      cell.append(document.createTextNode(raw));
    } else {
      cell.textContent = "—";
    }
    row.appendChild(cell);
    return;
  }

  cell.textContent = formatExternalTablePropDisplay(column, item);
  if (column.key === "awn-attachments" || column.typeId === "awn.file") {
    const entries = Array.isArray(item.props) ? item.props : [];
    const fullValue = getPropsEntryValueByKey(entries, column.key);
    if (fullValue && fullValue !== cell.textContent) {
      cell.title = fullValue.replace(/,\s*/g, "\n");
    }
  }
  row.appendChild(cell);
}

function renderExternalTableView(container, mdItems) {
  const schemaColumns = getExternalTableVisibleColumns();
  if (!schemaColumns.length) {
    renderListEmptyMessage(container, "Нет выбранных колонок — откройте «Колонки»");
    return;
  }
  const columns = getExternalTableDisplayColumns();
  const wrap = document.createElement("div");
  wrap.className = "external-table-wrap";

  const table = document.createElement("table");
  table.className = "external-table";

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  const dragHead = document.createElement("th");
  dragHead.scope = "col";
  dragHead.className = "external-table-drag-header";
  dragHead.textContent = "";
  dragHead.setAttribute("aria-label", "Перетаскивание");
  headRow.appendChild(dragHead);
  for (const column of columns) {
    const th = document.createElement("th");
    th.scope = "col";
    th.className = "external-table-sort-header";
    const active = externalListSort.key === column.key;
    th.classList.toggle("is-active", active);
    th.textContent = active
      ? `${column.label} ${externalListSort.dir === "asc" ? "↑" : "↓"}`
      : column.label;
    const activateSort = () => {
      if (externalListSort.key === column.key) {
        externalListSort.dir = externalListSort.dir === "asc" ? "desc" : "asc";
      } else {
        externalListSort.key = column.key;
        externalListSort.dir = "asc";
      }
      syncExternalListToolbarFromState();
      rerenderExternalListViewBody();
    };
    th.addEventListener("click", activateSort);
    th.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        activateSort();
      }
    });
    th.tabIndex = 0;
    headRow.appendChild(th);
  }
  thead.appendChild(headRow);
  table.appendChild(thead);

  const tbody = document.createElement("tbody");
  for (const item of mdItems) {
    const row = document.createElement("tr");
    row.className = "external-table-row";
    row.dataset.memoryFilePath = item.path;
    row.dataset.memoryFileScope = "external";
    row.tabIndex = 0;
    row.addEventListener("click", () => openExternalFile(item.path));
    row.addEventListener("contextmenu", (event) => {
      openResourceContextMenu(event, {
        kind: "externalFile",
        filePath: item.path,
        label: getExternalListItemDisplayTitle(item)
      });
    });
    row.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openExternalFile(item.path);
      }
    });

    const dragCell = document.createElement("td");
    dragCell.className = "external-table-drag-cell";
    dragCell.appendChild(createMemoryFileDragHandle());
    row.appendChild(dragCell);

    for (const column of columns) {
      appendExternalTableSchemaCell(row, column, item);
    }

    tbody.appendChild(row);
  }

  table.appendChild(tbody);
  wrap.appendChild(table);
  container.appendChild(wrap);
}

function getExternalCardStatusClass(status) {
  return `external-card-status--${getAwnStatusTone(status)}`;
}

function appendExternalCardStatusBadge(cover, status) {
  const label = String(status || "").trim();
  if (!label) return;
  const badge = document.createElement("span");
  badge.className = `external-card-status ${getExternalCardStatusClass(label)}`;
  badge.textContent = label;
  cover.appendChild(badge);
}

function createExternalCard(item) {
  const card = document.createElement("article");
  card.className = "external-card";

  const cover = document.createElement("div");
  cover.className = "external-card-image";
  if (
    !appendExternalItemPreviewThumb(cover, item, {
      className: "external-card-cover-img"
    })
  ) {
    const icon = createNodeCoverIconElement(getActiveNodeApiPath());
    icon.classList.add("external-card-cover-icon");
    cover.appendChild(icon);
  }
  appendExternalCardStatusBadge(cover, item.status);

  const body = document.createElement("div");
  body.className = "external-card-body";

  const titleNode = document.createElement("div");
  titleNode.className = "external-card-file-name";
  titleNode.textContent = getExternalListItemDisplayTitle(item);
  titleNode.title = item.path;

  const sectionNode = document.createElement("div");
  sectionNode.className = "external-card-path";
  sectionNode.textContent = formatExternalCardPathLine(item);

  body.append(titleNode, sectionNode);
  card.append(cover, body);
  card.style.cursor = "pointer";
  card.addEventListener("click", () => openExternalFile(item.path));
  return card;
}

function filterExternalMdItems(items, sectionFolder) {
  if (!sectionFolder) return items;
  const normalizedSection = String(sectionFolder || "").replace(/\\/g, "/").replace(/\/$/, "");
  return items.filter((item) => {
    const path = String(item.path || "").replace(/\\/g, "/");
    if (isSectionReadmePath(path)) return false;
    const parent = String(item.parent || "").replace(/\\/g, "/");
    return parent === normalizedSection;
  });
}

function getExternalChildSections(sectionFolder) {
  const prefix = sectionFolder ? `${sectionFolder}/` : "";
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  return getExternalUserSections()
    .filter((section) => {
      const folderPath = section.folderPath;
      if (!folderPath.startsWith(prefix) || folderPath === sectionFolder) return false;
      const remainder = folderPath.slice(prefix.length);
      return remainder && !remainder.includes("/");
    })
    .sort((a, b) => collator.compare(a.label, b.label));
}

let entryOverviewExternalCreateActive = false;
let entryOverviewExternalCreateParentOverride = null;

function isEntryOverviewExternalMemory(context = activeEntryOverviewContext) {
  return (
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE &&
    context?.memoryKind === "external" &&
    Boolean(activePath)
  );
}

function resolveEntryOverviewExternalCreateParent(context = activeEntryOverviewContext) {
  if (!context) return null;
  if (isEntryOverviewMemoryTocRoot(context)) return null;
  const sectionFolder = getEntryOverviewSectionFolderPath(context);
  if (sectionFolder) return sectionFolder;
  const parentFolder = getEntryOverviewParentFolderPath(context);
  return parentFolder || null;
}

function beginEntryOverviewExternalCreate(context = activeEntryOverviewContext) {
  entryOverviewExternalCreateActive = true;
  entryOverviewExternalCreateParentOverride = resolveEntryOverviewExternalCreateParent(context);
}

function endEntryOverviewExternalCreate() {
  entryOverviewExternalCreateActive = false;
  entryOverviewExternalCreateParentOverride = null;
}

function canCreateExternalMemoryNow() {
  if (!activePath) return false;
  if (activeContentMode === "external" && !activeExternalFilePath) return true;
  return isEntryOverviewExternalMemory();
}

function canCreateExternalSectionNow() {
  if (!activePath) return false;
  if (activeContentMode === "external" && !activeExternalFilePath) return true;
  return isEntryOverviewExternalMemory();
}

async function refreshAfterExternalWorkspaceCreate({ openForEdit = false } = {}) {
  const fromEntryOverview = isEntryOverviewExternalMemory();
  endEntryOverviewExternalCreate();
  try {
    await refreshExternalMemoryCaches();
  } catch {
    // ignore cache refresh errors in overview create flow
  }
  if (fromEntryOverview) {
    if (!openForEdit) {
      await renderEntryOverview();
    }
    return;
  }
  await loadContentByMode();
}

async function openCreatedExternalMemoryForEdit(filePath) {
  const normalized = String(filePath || "").replace(/\\/g, "/").trim();
  if (!normalized) return;
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE) {
    await openMemoryModeFromOverview("external", normalized);
    return;
  }
  await openExternalFile(normalized);
}

function getActiveExternalSectionParentForCreate() {
  if (entryOverviewExternalCreateActive) {
    return entryOverviewExternalCreateParentOverride;
  }
  if (!isStorageSectionsPanelVisible()) return null;
  if (activeExternalSectionFolder) return activeExternalSectionFolder;
  const route = parseAppRoute(location.pathname);
  if (route.view === "external" && route.mediaSectionPath) {
    return route.mediaSectionPath;
  }
  return null;
}

function setActiveExternalSectionFolder(folderName, { rerender = true, skipRouteSync = false } = {}) {
  const next = folderName ? String(folderName).replace(/\\/g, "/").replace(/\/$/, "").trim() : null;
  if (next === activeExternalSectionFolder) {
    syncExternalSectionTreeActiveState();
    return;
  }
  activeExternalSectionFolder = next;
  syncExternalSectionTreeActiveState();
  refreshStorageSlotTree();
  if (rerender) rerenderExternalListViewBody();
  updateBreadcrumbsForActiveMode();
  if (!skipRouteSync) syncAppRouteToUrl({ push: true });
}

function getRenderedMemorySectionCount(container, datasetAttr) {
  return container.querySelectorAll(`.media-section-tree-item[data-${datasetAttr}]`).length;
}

function isMemorySectionTreeStale(container, { getExpectedCount, datasetAttr }) {
  if (!container?.querySelector(":scope > .media-section-tree-list")) return false;
  const expected = getExpectedCount();
  const rendered = getRenderedMemorySectionCount(container, datasetAttr);
  const hasEmpty = Boolean(container.querySelector(".media-section-tree-empty"));
  if (expected === 0) return rendered > 0;
  return hasEmpty || rendered !== expected;
}

function syncExternalSectionTreeFromCaches() {
  const tree =
    listViewContentNode?.querySelector(".external-section-tree") ||
    listViewContentNode?.querySelector(".data-hub-panel .external-section-tree");
  if (!tree) return;
  if (
    isMemorySectionTreeStale(tree, {
      getExpectedCount: () => getExternalUserSections().length,
      datasetAttr: "external-section"
    })
  ) {
    renderExternalSectionTree(tree);
    return;
  }
  syncExternalSectionTreeActiveState();
  decorateMemorySectionSortRows(tree);
}

function syncMediaSectionTreeFromCaches() {
  const tree = getMediaSectionTreeNode();
  if (!tree) return;
  if (
    isMemorySectionTreeStale(tree, {
      getExpectedCount: () => getMediaUserSections().length,
      datasetAttr: "media-section"
    })
  ) {
    renderMediaSectionTree(tree);
    return;
  }
  syncMediaSectionTreeActiveState();
  decorateMemorySectionSortRows(tree);
}

function syncExternalSectionTreeActiveState() {
  const tree = listViewContentNode.querySelector(".external-section-tree");
  if (!tree) return;
  for (const btn of tree.querySelectorAll(".media-section-tree-item[data-external-view]")) {
    btn.classList.toggle("is-active", btn.dataset.externalView === "all" && !activeExternalSectionFolder);
  }
  for (const btn of tree.querySelectorAll(".media-section-tree-item[data-external-section]")) {
    btn.classList.toggle("is-active", btn.dataset.externalSection === activeExternalSectionFolder);
  }
}

function ensureExternalSectionTree(container) {
  if (!container) return;
  if (
    container.querySelector(":scope > .media-section-tree-list") &&
    !isMemorySectionTreeStale(container, {
      getExpectedCount: () => getExternalUserSections().length,
      datasetAttr: "external-section"
    })
  ) {
    syncExternalSectionTreeActiveState();
    decorateMemorySectionSortRows(container);
    return;
  }
  renderExternalSectionTree(container);
}

function renderExternalSectionTree(container) {
  if (!container) return;
  container.replaceChildren();

  const list = document.createElement("div");
  list.className = "media-section-tree-list";
  list.setAttribute("role", "tree");
  container.appendChild(list);

  const allBtn = appendMediaSectionTreeItem(list, {
    icon: "📋",
    label: "Все элементы",
    count: formatMemorySectionTreeCount(getExternalSectionFileCounts(null), { allItems: true }),
    isActive: !activeExternalSectionFolder,
    onClick: () => setActiveExternalSectionFolder(null)
  });
  allBtn.dataset.externalView = "all";

  const divider = document.createElement("div");
  divider.className = "media-section-tree-divider";
  divider.setAttribute("role", "presentation");
  list.appendChild(divider);

  const userSections = getExternalUserSections();
  if (userSections.length === 0) {
    const empty = document.createElement("div");
    empty.className = "media-section-tree-empty";
    empty.textContent = "Нет разделов. Создайте раздел через «+ Раздел».";
    list.appendChild(empty);
  } else {
    appendMemorySectionTreeNodes(list, buildMemorySectionForest(userSections), {
      datasetKey: "externalSection",
      countFn: getExternalSectionFileCounts,
      isActive: (folderPath) => activeExternalSectionFolder === folderPath,
      onSelect: (folderPath) => setActiveExternalSectionFolder(folderPath),
      readmeExists: externalSectionReadmeExists,
      onReadmeEdit: (readmePath, folderPath) => void openExternalSectionReadme(readmePath, folderPath),
      externalMode: true
    });
  }
  ensureStorageTreePolicyFooter(container, "external");
  decorateMemorySectionSortRows(container);
}

function mountExternalListViewLayout(root) {
  const wrap = document.createElement("div");
  wrap.className = "media-list-view-wrap external-list-view-wrap";

  const split = document.createElement("div");
  split.className = "media-list-view-split external-list-view-split";

  const treeHost = document.createElement("nav");
  treeHost.className = "media-section-tree external-section-tree";
  treeHost.setAttribute("aria-label", "Разделы многофайловой памяти");
  split.appendChild(treeHost);

  const main = document.createElement("div");
  main.className = "external-list-view-main media-list-view-main";

  const sectionHead = document.createElement("div");
  sectionHead.className = "external-list-section-head";
  main.append(sectionHead, createExternalListToolbar());

  const body = document.createElement("div");
  body.className = "media-list-view-body external-list-view-body";
  main.appendChild(body);
  split.appendChild(main);

  wrap.appendChild(split);
  root.appendChild(wrap);
  ensureExternalSectionTree(treeHost);
  syncStorageSectionsPanelUi();
  syncExternalListSectionHead(
    isStorageSectionsPanelVisible() ? activeExternalSectionFolder : null
  );
  return body;
}

function ensureExternalListViewLayout() {
  const mountRoot = getListViewMountRoot("external");
  const existing = mountRoot.querySelector(".media-list-view-wrap.external-list-view-wrap");
  if (!existing) {
    mountRoot.innerHTML = "";
    if (!shouldUseDataHubListShell("external")) listViewContentNode.innerHTML = "";
    mountExternalListViewLayout(mountRoot);
  } else if (shouldUseDataHubListShell("external")) {
    const slotTree = getStorageSlotTreeNode();
    if (shouldRenderStorageSlotTree(slotTree)) {
      void renderStorageSlotTree(slotTree);
    } else {
      syncStorageSlotTreeActiveState(slotTree);
    }
  }
  const wrap = mountRoot.querySelector(".external-list-view-wrap");
  if (!wrap) return null;
  ensureExternalListToolbar(wrap);
  ensureExternalSectionTree(wrap.querySelector(".external-section-tree"));
  syncStorageSectionsPanelUi();
  return wrap.querySelector(".external-list-view-body");
}

function rerenderExternalListViewBody() {
  if (activeContentMode !== "external" || isExternalFileEditing()) return;
  externalListRenderToken += 1;
  syncExternalSectionTreeFromCaches();
  const body = listViewContentNode.querySelector(".external-list-view-body");
  if (body) {
    renderExternalListViewBody(body);
    return;
  }
  renderListViewContent();
}

function renderExternalSectionFolderView(container, sectionFolder, items) {
  const childSections = getExternalChildSections(sectionFolder);
  const { items: contentItems } = splitSectionReadmeItems(items, sectionFolder);
  const readmeExists = externalSectionReadmeExists(sectionFolder);

  if (!readmeExists) {
    appendSectionReadmeOffer(container, sectionFolder, {
      categoryType: "awn.record.category",
      onCreate: (readmePath) => void openExternalSectionReadme(readmePath, sectionFolder)
    });
  }

  if (childSections.length === 0 && contentItems.length === 0) {
    if (!readmeExists) return;
    renderListEmptyMessage(
      container,
      externalListFilterQuery.trim()
        ? "Ничего не найдено по фильтру"
        : `В разделе «${sectionFolder}» пока нет элементов`
    );
    return;
  }

  if (childSections.length > 0) {
    const subList = document.createElement("ul");
    subList.className = "media-section-subfolder-list";
    for (const child of childSections) {
      const li = document.createElement("li");
      li.className = "media-section-subfolder-item";
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "media-section-subfolder-btn";
      btn.textContent = `📁 ${child.label}`;
      btn.title = child.folderPath;
      btn.addEventListener("click", () => setActiveExternalSectionFolder(child.folderPath));
      li.appendChild(btn);
      subList.appendChild(li);
    }
    container.appendChild(subList);
  }

  if (contentItems.length > 0) {
    renderExternalViewContent(container, contentItems);
    return;
  }

  if (externalListFilterQuery.trim()) {
    renderListEmptyMessage(container, "Ничего не найдено по фильтру");
  }
}

function getExternalItemPropValue(item, key) {
  const entries = Array.isArray(item?.props) ? item.props : [];
  return String(getPropsEntryValueByKey(entries, key) || "").trim();
}

function getExternalMocTopicKey(item) {
  const tagsRaw = String(item?.tags || "").trim();
  if (tagsRaw && tagsRaw !== "[]" && tagsRaw !== "—") {
    const firstTag = tagsRaw.split(",")[0].trim();
    if (firstTag) return firstTag;
  }

  const category = getExternalItemPropValue(item, "awn-category");
  if (category) return category;

  const section = formatExternalCardSection(item);
  if (section && section !== "Корень") return section;

  return "Без категории";
}

function renderExternalViewContent(container, mdItems) {
  const naturalCollator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });

  if (mdItems.length === 0) {
    renderListEmptyMessage(
      container,
      externalListFilterQuery.trim() ? "Ничего не найдено по фильтру" : "Markdown-файлы не найдены"
    );
    return;
  }

  if (externalViewMode === "table") {
    renderExternalTableView(container, mdItems);
    return;
  }

  if (externalViewMode === "cards") {
    const grid = document.createElement("div");
    grid.className = "external-cards-grid";
    for (const item of mdItems) {
      grid.appendChild(createExternalCard(item));
    }
    container.appendChild(grid);
    return;
  }

  if (externalViewMode === "calendar") {
    const weekDays = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];
    const calendar = document.createElement("div");
    calendar.className = "external-calendar-grid";
    const buckets = weekDays.map((title) => ({ title, items: [] }));
    mdItems.forEach((item, idx) => {
      buckets[idx % 7].items.push(item.path.split("/").pop() || item.path);
    });
    for (const bucket of buckets) {
      const day = document.createElement("div");
      day.className = "external-calendar-day";
      const head = document.createElement("div");
      head.className = "external-calendar-day-title";
      head.textContent = bucket.title;
      day.appendChild(head);
      for (const entry of bucket.items.slice(0, 5)) {
        const chip = document.createElement("div");
        chip.className = "external-calendar-item";
        chip.textContent = entry;
        day.appendChild(chip);
      }
      calendar.appendChild(day);
    }
    container.appendChild(calendar);
    return;
  }

  if (externalViewMode === "index") {
    const groups = new Map();
    for (const item of mdItems) {
      const key = item.parent && item.parent !== "." ? item.parent : "Корень";
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(item);
    }

    const sortedGroups = Array.from(groups.entries()).sort((a, b) =>
      compareExternalPathsNatural(a[0], b[0])
    );

    for (const [groupTitle, items] of sortedGroups) {
      const sectionNode = document.createElement("section");
      sectionNode.className = "external-index-section";

      const headerNode = document.createElement("div");
      headerNode.className = "external-index-section-title";
      headerNode.textContent = groupTitle;
      sectionNode.appendChild(headerNode);

      const listNode = document.createElement("ul");
      listNode.className = "external-index-list";

      for (const item of items) {
        const li = document.createElement("li");
        li.className = "external-index-item";
        li.textContent = item.title;
        li.title = item.path;
        li.addEventListener("click", () => openExternalFile(item.path));
        listNode.appendChild(li);
      }

      sectionNode.appendChild(listNode);
      container.appendChild(sectionNode);
    }
    return;
  }

  if (externalViewMode === "moc") {
    const groups = new Map();
    for (const item of mdItems) {
      const topic = getExternalMocTopicKey(item);
      if (!groups.has(topic)) groups.set(topic, []);
      groups.get(topic).push(item);
    }

    const grid = document.createElement("div");
    grid.className = "external-moc-grid";

    for (const [topic, items] of Array.from(groups.entries()).sort((a, b) =>
      naturalCollator.compare(a[0], b[0])
    )) {
      const card = document.createElement("article");
      card.className = "external-moc-card";

      const title = document.createElement("div");
      title.className = "external-moc-card-title";
      title.textContent = topic;
      card.appendChild(title);

      const listNode = document.createElement("ul");
      listNode.className = "external-moc-list";

      for (const item of items) {
        const li = document.createElement("li");
        li.className = "external-moc-item";
        li.textContent = item.title;
        li.title = item.path;
        li.addEventListener("click", () => openExternalFile(item.path));
        listNode.appendChild(li);
      }

      card.appendChild(listNode);
      grid.appendChild(card);
    }

    container.appendChild(grid);
    return;
  }

  if (externalViewMode === "mindmap") {
    renderExternalMindmapCanvas(container, mdItems);
    return;
  }

  if (externalViewMode === "cheatsheet") {
    renderExternalCheatsheetView(container, mdItems);
    return;
  }

  if (externalViewMode === "graph") {
    renderExternalGraphCanvas(container, mdItems);
    return;
  }

  const listNode = document.createElement("ul");
  listNode.className = "list-items";
  for (const item of mdItems) {
    const li = document.createElement("li");
    li.className = "list-item list-item-with-actions external-list-item";
    li.dataset.memoryFilePath = item.path;
    li.dataset.memoryFileScope = "external";
    li.style.cursor = "pointer";
    li.addEventListener("click", () => openExternalFile(item.path));
    li.addEventListener("contextmenu", (event) => {
      openResourceContextMenu(event, {
        kind: "externalFile",
        filePath: item.path,
        label: getExternalListItemDisplayTitle(item)
      });
    });

    const icon = document.createElement("span");
    icon.className = "list-item-icon";
    icon.textContent = "📄";

    const titleNode = document.createElement("span");
    titleNode.className = "external-list-item-title";
    titleNode.textContent = getExternalListItemDisplayTitle(item);
    titleNode.title = item.path;

    const dateNode = document.createElement("span");
    dateNode.className = "external-list-item-date";
    dateNode.textContent = formatExternalFileCreatedLabel(item.createdAt);
    if (item.createdAt) dateNode.title = `Создан: ${item.createdAt}`;

    li.append(createMemoryFileDragHandle(), icon, titleNode, dateNode);
    listNode.appendChild(li);
  }
  container.appendChild(listNode);
}

function renderExternalListViewBody(container) {
  if (!container) return;
  container.replaceChildren();

  pruneActiveExternalSectionFolder();
  syncExternalSectionTreeActiveState();
  syncExternalListSectionHead(
    isStorageSectionsPanelVisible() ? activeExternalSectionFolder : null
  );

  const allItems = getExternalMdItems();
  if (allItems.length === 0 && getExternalUserSections().length === 0) {
    syncExternalListToolbarMeta(0, 0);
    renderListEmptyMessage(container, "Markdown-файлы не найдены");
    return;
  }

  if (isStorageSectionsPanelVisible() && activeExternalSectionFolder) {
    const sectionItems = filterExternalMdItems(allItems, activeExternalSectionFolder);
    const preparedItems = prepareExternalListItems(sectionItems);
    syncExternalListToolbarMeta(
      preparedItems.length,
      countExternalFilesInSection(activeExternalSectionFolder)
    );
    syncExternalListToolbarFromState();
    renderExternalSectionFolderView(container, activeExternalSectionFolder, preparedItems);
    syncDataHubSlugWarning("external");
    return;
  }

  const preparedItems = prepareExternalListItems(allItems);
  syncExternalListToolbarMeta(preparedItems.length, countExternalFilesInSection(null));
  syncExternalListToolbarFromState();
  renderExternalViewContent(container, preparedItems);
  syncDataHubSlugWarning("external");
}

function getFlatStorageSectionTreeLabel(mode) {
  if (mode === "scripts") return "Разделы скриптов";
  if (mode === "inbox") return "Разделы входящих";
  if (mode === "note" || mode === "quick-notes") return "Разделы заметок";
  if (mode === "references") return "Разделы источников";
  if (mode === "artefacts") return "Разделы артефактов";
  if (mode === "assets") return "Разделы активов";
  if (mode === "repository") return "Разделы репозитория";
  return "Разделы";
}

function getFlatStorageNormalizedItems(mode) {
  return parseFlatListItems(modeContentCache[mode] || "")
    .map((raw) => normalizeListItem(raw))
    .filter((item) => item.path);
}

function getFlatStorageUserSections(mode) {
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  const folderPaths = new Set();

  for (const item of getFlatStorageNormalizedItems(mode)) {
    if (item.isFolder) {
      const folderPath = String(item.path || "").replace(/\/$/, "");
      addMemorySectionFolderPath(folderPaths, folderPath);
      continue;
    }
    const path = String(item.path || "").replace(/\\/g, "/");
    if (isMemorySectionInfrastructureFilePath(path)) continue;
    const parts = path.split("/").filter(Boolean);
    if (parts.length <= 1) continue;
    let built = "";
    for (let i = 0; i < parts.length - 1; i += 1) {
      built = built ? `${built}/${parts[i]}` : parts[i];
      addMemorySectionFolderPath(folderPaths, built);
    }
  }

  return Array.from(folderPaths)
    .filter((folderPath) => !isMemorySectionInfrastructureFolderPath(folderPath))
    .map((folderPath) => {
      const segments = folderPath.split("/").filter(Boolean);
      return {
        folderPath,
        label: segments[segments.length - 1] || folderPath,
        depth: Math.max(0, segments.length - 1)
      };
    })
    .sort((a, b) => collator.compare(a.folderPath, b.folderPath));
}

function getFlatStorageSectionFileCounts(mode, sectionFolder) {
  const normalizedSection = String(sectionFolder || "").replace(/\\/g, "/").replace(/\/$/, "");
  let direct = 0;
  let total = 0;
  for (const item of getFlatStorageNormalizedItems(mode)) {
    if (item.isFolder) continue;
    if (isSectionReadmePath(item.path)) continue;
    const path = String(item.path || "").replace(/\\/g, "/");
    if (!normalizedSection) {
      total += 1;
      continue;
    }
    const prefix = `${normalizedSection}/`;
    if (!path.startsWith(prefix)) continue;
    total += 1;
    const remainder = path.slice(prefix.length);
    if (remainder && !remainder.includes("/")) direct += 1;
  }
  return { direct, total };
}

function countFlatStorageItemsInSection(mode, sectionFolder) {
  return getFlatStorageSectionFileCounts(mode, sectionFolder).total;
}

function filterFlatStorageSectionItems(items, sectionFolder) {
  if (!sectionFolder) {
    return items.filter((item) => !item.isFolder && !isSectionReadmePath(item.path));
  }
  const prefix = `${sectionFolder}/`;
  return items.filter((item) => {
    if (item.isFolder) return false;
    if (isSectionReadmePath(item.path)) return false;
    const path = String(item.path || "");
    if (!path.startsWith(prefix)) return false;
    return !path.slice(prefix.length).includes("/");
  });
}

function flatStorageSectionReadmeExists(mode, sectionFolder) {
  const readmePath = getSectionReadmeRelPath(sectionFolder);
  return getFlatStorageNormalizedItems(mode).some(
    (item) => !item.isFolder && item.path === readmePath
  );
}

function getFlatStorageChildSections(mode, sectionFolder) {
  const prefix = sectionFolder ? `${sectionFolder}/` : "";
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  return getFlatStorageUserSections(mode)
    .filter((section) => {
      const folderPath = section.folderPath;
      if (!folderPath.startsWith(prefix) || folderPath === sectionFolder) return false;
      const remainder = folderPath.slice(prefix.length);
      return remainder && !remainder.includes("/");
    })
    .sort((a, b) => collator.compare(a.label, b.label));
}

function pruneActiveFlatStorageSectionFolder(mode = activeContentMode) {
  if (!isFlatStorageSectionMode(mode) || !activeFlatStorageSectionFolder[mode]) return;
  const exists = getFlatStorageUserSections(mode).some(
    (section) => section.folderPath === activeFlatStorageSectionFolder[mode]
  );
  if (!exists) activeFlatStorageSectionFolder[mode] = null;
}

function getActiveFlatStorageSectionParentForCreate(mode = activeContentMode) {
  if (!isFlatStorageSectionMode(mode) || !isStorageSectionsPanelVisible()) return null;
  if (activeFlatStorageSectionFolder[mode]) return activeFlatStorageSectionFolder[mode];
  const route = parseAppRoute(location.pathname);
  if (route.view === mode && route.mediaSectionPath) return route.mediaSectionPath;
  return null;
}

function setActiveFlatStorageSectionFolder(mode, folderName, { rerender = true, skipRouteSync = false } = {}) {
  if (!isFlatStorageSectionMode(mode)) return;
  const next = folderName ? String(folderName).replace(/\\/g, "/").replace(/\/$/, "").trim() : null;
  if (next === activeFlatStorageSectionFolder[mode]) {
    syncFlatStorageSectionTreeActiveState(mode);
    return;
  }
  activeFlatStorageSectionFolder[mode] = next;
  syncFlatStorageSectionTreeActiveState(mode);
  if (rerender) rerenderFlatStorageListViewBody(mode);
  updateBreadcrumbsForActiveMode();
  if (!skipRouteSync) syncAppRouteToUrl({ push: true });
}

function syncFlatStorageSectionTreeActiveState(mode) {
  const tree = listViewContentNode.querySelector(`.flat-storage-section-tree[data-mode="${mode}"]`);
  if (!tree) return;
  for (const btn of tree.querySelectorAll(".media-section-tree-item[data-flat-storage-view]")) {
    btn.classList.toggle("is-active", btn.dataset.flatStorageView === "all" && !activeFlatStorageSectionFolder[mode]);
  }
  for (const btn of tree.querySelectorAll(".media-section-tree-item[data-flat-storage-section]")) {
    btn.classList.toggle("is-active", btn.dataset.flatStorageSection === activeFlatStorageSectionFolder[mode]);
  }
}

function ensureFlatStorageSectionTree(container, mode) {
  if (!container) return;
  if (
    container.querySelector(":scope > .media-section-tree-list") &&
    !isMemorySectionTreeStale(container, {
      getExpectedCount: () => getFlatStorageUserSections(mode).length,
      datasetAttr: "flat-storage-section"
    })
  ) {
    syncFlatStorageSectionTreeActiveState(mode);
    decorateMemorySectionSortRows(container);
    return;
  }
  renderFlatStorageSectionTree(container, mode);
}

function renderFlatStorageSectionTree(container, mode) {
  if (!container) return;
  container.replaceChildren();

  const list = document.createElement("div");
  list.className = "media-section-tree-list";
  list.setAttribute("role", "tree");
  container.appendChild(list);

  const allBtn = appendMediaSectionTreeItem(list, {
    icon: "📋",
    label: "Все элементы",
    count: formatMemorySectionTreeCount(getFlatStorageSectionFileCounts(mode, null), { allItems: true }),
    isActive: !activeFlatStorageSectionFolder[mode],
    onClick: () => setActiveFlatStorageSectionFolder(mode, null)
  });
  allBtn.dataset.flatStorageView = "all";

  const divider = document.createElement("div");
  divider.className = "media-section-tree-divider";
  divider.setAttribute("role", "presentation");
  list.appendChild(divider);

  const userSections = getFlatStorageUserSections(mode);
  if (userSections.length === 0) {
    const empty = document.createElement("div");
    empty.className = "media-section-tree-empty";
    empty.textContent = "Нет разделов. Создайте раздел через «+ Раздел».";
    list.appendChild(empty);
  } else {
    appendMemorySectionTreeNodes(list, buildMemorySectionForest(userSections), {
      datasetKey: "flatStorageSection",
      countFn: (folderPath) => getFlatStorageSectionFileCounts(mode, folderPath),
      isActive: (folderPath) => activeFlatStorageSectionFolder[mode] === folderPath,
      onSelect: (folderPath) => setActiveFlatStorageSectionFolder(mode, folderPath),
      readmeExists: (folderPath) => flatStorageSectionReadmeExists(mode, folderPath),
      onReadmeEdit: (readmePath, folderPath) =>
        void openFlatStorageSectionReadme(mode, readmePath, folderPath),
      storageMode: mode
    });
  }
  ensureStorageTreePolicyFooter(container, mode);
}

function mountFlatStorageListViewLayout(root, mode) {
  const wrap = document.createElement("div");
  wrap.className = `media-list-view-wrap flat-storage-list-view-wrap flat-storage-list-view-wrap--${mode}`;

  const split = document.createElement("div");
  split.className = "media-list-view-split flat-storage-list-view-split";

  const treeHost = document.createElement("nav");
  treeHost.className = "media-section-tree flat-storage-section-tree";
  treeHost.dataset.mode = mode;
  treeHost.setAttribute("aria-label", getFlatStorageSectionTreeLabel(mode));
  split.appendChild(treeHost);

  const body = document.createElement("div");
  body.className = "media-list-view-body flat-storage-list-view-body";
  split.appendChild(body);

  wrap.appendChild(split);
  root.appendChild(wrap);
  ensureFlatStorageSectionTree(treeHost, mode);
  syncStorageSectionsPanelUi();
  return body;
}

function ensureFlatStorageListViewLayout(mode) {
  const mountRoot = getListViewMountRoot(mode);
  let wrap = mountRoot.querySelector(`.flat-storage-list-view-wrap--${mode}`);
  if (!wrap) {
    mountRoot.innerHTML = "";
    if (!shouldUseDataHubListShell(mode)) listViewContentNode.innerHTML = "";
    return mountFlatStorageListViewLayout(mountRoot, mode);
  }
  if (shouldUseDataHubListShell(mode)) {
    void renderStorageSlotTree(getStorageSlotTreeNode());
  }
  ensureFlatStorageSectionTree(wrap.querySelector(".flat-storage-section-tree"), mode);
  syncStorageSectionsPanelUi();
  return wrap.querySelector(".flat-storage-list-view-body");
}

function rerenderFlatStorageListViewBody(mode = activeContentMode) {
  const body = listViewContentNode.querySelector(`.flat-storage-list-view-wrap--${mode} .flat-storage-list-view-body`);
  if (!body) {
    renderListViewContent();
    return;
  }
  body.innerHTML = "";
  renderFlatStorageListViewBody(body, mode);
}

function renderFlatStorageListItems(container, items, mode = activeContentMode) {
  if (items.length === 0) {
    renderListEmptyMessage(container, getStorageFolderEmptyMessage(mode));
    return;
  }

  const naturalCollator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  const normalizedItems = items
    .slice()
    .sort((a, b) => naturalCollator.compare(String(a.path || ""), String(b.path || "")));

  const listNode = document.createElement("ul");
  listNode.className = "list-items";
  for (const normalized of normalizedItems) {
    const li = document.createElement("li");
    li.className = "list-item";
    li.style.cursor = "pointer";
    li.dataset.flatStorageFile = normalized.path;
    li.addEventListener("click", () => {
      openFlatStorageRecordOverviewFromNavigation({ path: normalized.path }, mode);
    });
    li.addEventListener("contextmenu", (event) => {
      openResourceContextMenu(event, {
        kind: "flatStorageFile",
        mode,
        filePath: normalized.path,
        label: String(normalized.path || "").split("/").pop() || normalized.path
      });
    });

    const icon = document.createElement("span");
    icon.className = "list-item-icon";
    icon.textContent = "📄";
    const pathNode = document.createElement("span");
    pathNode.className = "list-item-path";
    pathNode.textContent = normalized.path;
    li.append(icon, pathNode);
    listNode.appendChild(li);
  }
  container.appendChild(listNode);
}

function renderFlatStorageSectionFolderView(container, mode, sectionFolder) {
  const childSections = getFlatStorageChildSections(mode, sectionFolder);
  const items = filterFlatStorageSectionItems(getFlatStorageNormalizedItems(mode), sectionFolder);
  const readmeExists = flatStorageSectionReadmeExists(mode, sectionFolder);

  if (!readmeExists) {
    appendSectionReadmeOffer(container, sectionFolder, {
      categoryType: "awn.record.category",
      onCreate: (readmePath) => void openFlatStorageSectionReadme(mode, readmePath, sectionFolder)
    });
  }

  if (childSections.length === 0 && items.length === 0) {
    if (!readmeExists) return;
    renderListEmptyMessage(container, `В разделе «${sectionFolder}» пока нет элементов`);
    return;
  }

  if (childSections.length > 0) {
    const subList = document.createElement("ul");
    subList.className = "media-section-subfolder-list";
    for (const child of childSections) {
      const li = document.createElement("li");
      li.className = "media-section-subfolder-item";
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "media-section-subfolder-btn";
      btn.textContent = `📁 ${child.label}`;
      btn.title = child.folderPath;
      btn.addEventListener("click", () => setActiveFlatStorageSectionFolder(mode, child.folderPath));
      li.appendChild(btn);
      subList.appendChild(li);
    }
    container.appendChild(subList);
  }

  if (items.length > 0) {
    renderFlatStorageListItems(container, items, mode);
  }
}

function getInboxTriageItemsForSection(sectionFolder = null) {
  const items = Array.isArray(inboxItemsMetaCache) ? inboxItemsMetaCache : [];
  if (!sectionFolder) return items;
  const prefix = String(sectionFolder).replace(/\\/g, "/").replace(/\/$/, "");
  if (!prefix) return items;
  return items.filter((item) => {
    const itemPath = String(item.path || "").replace(/\\/g, "/");
    return itemPath === prefix || itemPath.startsWith(`${prefix}/`);
  });
}

function renderFlatStorageAllItemsView(container, mode) {
  if (!activeStorageFolderExists) {
    renderListEmptyMessage(container, getStorageFolderMissingMessage(mode));
    return;
  }
  const items = filterFlatStorageSectionItems(getFlatStorageNormalizedItems(mode), null);
  if (items.length === 0 && getFlatStorageUserSections(mode).length === 0) {
    renderListEmptyMessage(container, getStorageFolderEmptyMessage(mode));
    return;
  }
  renderFlatStorageListItems(container, items, mode);
}

function renderFlatStorageListViewBody(container, mode) {
  ensureFlatStorageSectionTree(
    listViewContentNode.querySelector(`.flat-storage-section-tree[data-mode="${mode}"]`),
    mode
  );
  syncStorageSectionsPanelUi();

  if (!activeStorageFolderExists) {
    renderListEmptyMessage(container, getStorageFolderMissingMessage(mode));
    void refreshStorageTreePolicyFooters(mode);
    return;
  }

  pruneActiveFlatStorageSectionFolder(mode);

  if (isStorageSectionsPanelVisible() && activeFlatStorageSectionFolder[mode]) {
    renderFlatStorageSectionFolderView(container, mode, activeFlatStorageSectionFolder[mode]);
    syncDataHubSlugWarning(mode);
    return;
  }

  renderFlatStorageAllItemsView(container, mode);
  syncDataHubSlugWarning(mode);
}

function updateMediaBulkUploadProgressUI() {
  const zone = listViewContentNode.querySelector(".media-bulk-upload-zone");
  if (zone) syncMediaBulkUploadZoneUi(zone);
}

function syncMediaBulkUploadZoneUi(zone) {
  const idle = zone.querySelector(".media-bulk-upload-idle");
  const progress = zone.querySelector(".media-bulk-upload-progress");
  const fill = zone.querySelector(".media-bulk-upload-progress-fill");
  const label = zone.querySelector(".media-bulk-upload-progress-label");
  const percent = zone.querySelector(".media-bulk-upload-progress-percent");

  const { active, done, total, label: statusLabel } = mediaBulkUploadState;
  const pct = total > 0 ? Math.min(100, Math.round((done / total) * 100)) : 0;

  zone.classList.toggle("is-uploading", active);
  zone.classList.toggle("is-dragover", false);
  idle?.classList.toggle("hidden", active);
  progress?.classList.toggle("hidden", !active);
  if (fill) fill.style.width = `${pct}%`;
  if (percent) percent.textContent = `${pct}%`;
  if (label) {
    label.textContent =
      statusLabel || (active ? `Загружено ${done} из ${total}` : "");
  }
}

function mountMediaBulkUploadZone(host) {
  host.innerHTML = "";

  const panel = document.createElement("div");
  panel.className = "media-bulk-upload-panel";

  const closeBtn = document.createElement("button");
  closeBtn.type = "button";
  closeBtn.className = "media-bulk-upload-close modal-close-btn";
  closeBtn.setAttribute("aria-label", "Закрыть");
  closeBtn.textContent = "×";
  closeBtn.addEventListener("click", (event) => {
    event.stopPropagation();
    if (mediaBulkUploadState.active) return;
    setMediaBulkUploadPanelOpen(false);
  });

  const zone = document.createElement("div");
  zone.className = "media-bulk-upload-zone";
  zone.tabIndex = 0;
  zone.setAttribute("role", "button");
  zone.setAttribute("aria-label", `Массовая загрузка файлов в ${getMediaLibraryModeLabel()}`);

  const idle = document.createElement("div");
  idle.className = "media-bulk-upload-idle";
  const icon = document.createElement("div");
  icon.className = "media-bulk-upload-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.textContent = "📤";
  const title = document.createElement("p");
  title.className = "media-bulk-upload-title";
  title.textContent = "Перетащите файлы сюда";
  const hint = document.createElement("p");
  hint.className = "media-bulk-upload-hint";
  hint.textContent = "или нажмите для выбора · можно несколько файлов";
  idle.append(icon, title, hint);

  const progress = document.createElement("div");
  progress.className = "media-bulk-upload-progress hidden";
  const percent = document.createElement("div");
  percent.className = "media-bulk-upload-progress-percent";
  percent.textContent = "0%";
  const track = document.createElement("div");
  track.className = "media-bulk-upload-progress-track";
  track.setAttribute("aria-hidden", "true");
  const fill = document.createElement("div");
  fill.className = "media-bulk-upload-progress-fill";
  track.appendChild(fill);
  const progressLabel = document.createElement("p");
  progressLabel.className = "media-bulk-upload-progress-label";
  progressLabel.textContent = "Загрузка…";
  progress.append(percent, track, progressLabel);

  const input = document.createElement("input");
  input.type = "file";
  input.multiple = true;
  input.hidden = true;
  input.className = "media-bulk-upload-input";
  if (mediaUploadInputNode?.accept) input.accept = mediaUploadInputNode.accept;

  zone.append(idle, progress);
  panel.append(closeBtn, zone);
  host.append(panel, input);

  wireMediaBulkUploadZone(zone, input);
  syncMediaBulkUploadZoneUi(zone);
}

function wireMediaBulkUploadZone(zone, input) {
  const pickFiles = () => {
    if (mediaBulkUploadState.active) return;
    input.click();
  };

  zone.addEventListener("click", () => {
    if (mediaBulkUploadState.active) return;
    pickFiles();
  });

  zone.addEventListener("keydown", (event) => {
    if (mediaBulkUploadState.active) return;
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      pickFiles();
    }
  });

  input.addEventListener("change", () => {
    const files = input.files ? [...input.files] : [];
    input.value = "";
    if (files.length) void uploadMediaFilesBulk(files);
  });

  zone.addEventListener("dragover", (event) => {
    if (mediaBulkUploadState.active) return;
    event.preventDefault();
    zone.classList.add("is-dragover");
  });

  zone.addEventListener("dragleave", () => {
    zone.classList.remove("is-dragover");
  });

  zone.addEventListener("drop", (event) => {
    if (mediaBulkUploadState.active) return;
    event.preventDefault();
    zone.classList.remove("is-dragover");
    const files = event.dataTransfer?.files ? [...event.dataTransfer.files] : [];
    if (files.length) void uploadMediaFilesBulk(files);
  });
}

async function uploadMediaFilesBulk(files) {
  const list = [...files].filter((file) => file instanceof File);
  if (!list.length) return;
  if (!activePath) {
    showToast("Сначала откройте тему", "error");
    return;
  }

  mediaBulkUploadState = {
    active: true,
    done: 0,
    total: list.length,
    failed: 0,
    label: "Подготовка…"
  };
  updateMediaBulkUploadProgressUI();

  let succeeded = 0;
  for (let i = 0; i < list.length; i += 1) {
    const file = list[i];
    mediaBulkUploadState.label = `${file.name} · ${i + 1} из ${list.length}`;
    updateMediaBulkUploadProgressUI();
    try {
      await uploadMediaAttachment(file);
      succeeded += 1;
    } catch (error) {
      mediaBulkUploadState.failed += 1;
      showToast(`${file.name}: ${error.message}`, "error");
    }
    mediaBulkUploadState.done = i + 1;
    updateMediaBulkUploadProgressUI();
  }

  mediaBulkUploadState.active = false;
  mediaBulkUploadState.label = "";
  updateMediaBulkUploadProgressUI();
  await refreshMediaListIfVisible();

  if (succeeded > 0) {
    const failed = mediaBulkUploadState.failed;
    showToast(
      failed
        ? `Загружено ${succeeded} из ${list.length} (${failed} с ошибкой)`
        : `Загружено файлов: ${succeeded}`,
      failed ? "info" : "success"
    );
  } else if (mediaBulkUploadState.failed > 0) {
    showToast("Не удалось загрузить файлы", "error");
  }
}

function getMediaSidecarPath(mediaFilePath) {
  const normalized = String(mediaFilePath || "").replace(/\\/g, "/");
  if (!normalized || normalized.endsWith("/")) return null;
  const lastSlash = normalized.lastIndexOf("/");
  const dir = lastSlash >= 0 ? normalized.slice(0, lastSlash + 1) : "";
  const filename = lastSlash >= 0 ? normalized.slice(lastSlash + 1) : normalized;
  const dotIndex = filename.lastIndexOf(".");
  const base = dotIndex > 0 ? filename.slice(0, dotIndex) : filename;
  if (!base) return null;
  return `${dir}${base}.sidecar.md`;
}

const MEDIA_ACTION_ICON_EDIT =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>';
const MEDIA_ACTION_ICON_OPEN =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>';
const MEDIA_ACTION_ICON_FINDER =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M3 7h18"/></svg>';

let mediaPathPopoverState = null;

let mediaSidecarOpenInFlight = null;
let mediaAssetOpenLockedUntil = 0;

function createMediaActionIcon(svgMarkup) {
  const icon = document.createElement("span");
  icon.className = "media-action-btn-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.innerHTML = svgMarkup;
  return icon;
}

function guardMediaActionClick(event, action) {
  event.preventDefault();
  event.stopPropagation();
  if (typeof event.stopImmediatePropagation === "function") {
    event.stopImmediatePropagation();
  }
  const btn = event.currentTarget;
  if (btn?.dataset?.actionLocked === "1") return false;
  if (btn) btn.dataset.actionLocked = "1";
  window.setTimeout(() => {
    if (btn) delete btn.dataset.actionLocked;
  }, 500);
  action();
  return true;
}

function openMediaAssetExternal(filePath) {
  const now = Date.now();
  if (now < mediaAssetOpenLockedUntil) return;
  mediaAssetOpenLockedUntil = now + 500;
  const url = buildMediaAssetUrl(filePath);
  if (!url) return;
  window.open(url, "_blank", "noopener,noreferrer");
}

function getMediaAssetFileName(filePath) {
  const normalized = String(filePath || "").replace(/\\/g, "/").trim();
  if (!normalized) return "";
  const parts = normalized.split("/").filter(Boolean);
  return parts[parts.length - 1] || normalized;
}

const MEDIA_DOCUMENT_PREVIEW_EXTENSIONS = new Set([
  ".pdf",
  ".doc",
  ".docx",
  ".xls",
  ".xlsx",
  ".ppt",
  ".pptx",
  ".txt",
  ".md"
]);

function isMediaDocumentPreviewCandidate(fileName) {
  const ext = window.DocumentViewer?.getExtension?.(fileName) || "";
  return MEDIA_DOCUMENT_PREVIEW_EXTENSIONS.has(ext);
}

function openMediaAsset(filePath, nodePath = activePath) {
  const normalizedPath = String(filePath || "").replace(/\\/g, "/");
  if (isSectionReadmePath(normalizedPath)) {
    const sectionFolder = normalizedPath.slice(0, normalizedPath.length - AREA_MANIFEST_FILE.length).replace(/\/$/, "");
    void openMediaSectionReadme(normalizedPath, sectionFolder);
    return;
  }

  const fileName = getMediaAssetFileName(filePath);
  const url = buildMediaAssetUrl(filePath, nodePath);
  if (!url) return;

  if (isMediaDocumentPreviewCandidate(fileName) && window.DocumentViewer?.open) {
    void window.DocumentViewer.open({
      url,
      fileName,
      onExternal: () => openMediaAssetExternal(filePath)
    });
    return;
  }

  openMediaAssetExternal(filePath);
}

function getRevealMediaFileLabel() {
  const platform = window.desktopApp?.platform;
  if (platform === "darwin") return "Показать в Finder";
  if (platform === "win32") return "Показать в проводнике";
  return "Показать в папке";
}

async function revealMediaFileInExplorer(mediaFilePath) {
  if (!activePath || !mediaFilePath) return;
  try {
    if (window.desktopApp?.revealFile) {
      await window.desktopApp.revealFile(getResolvedNodePath(activePath), mediaFilePath, activeAgentId);
      return;
    }

    const response = await fetch(buildApiUrl("/api/reveal"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path: getActiveNodeApiPath(),
        file: mediaFilePath
      })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(data.details || data.error || `HTTP ${response.status}`);
    }
  } catch (error) {
    showToast(`Не удалось показать файл: ${error.message}`, "error");
  }
}

async function resolveMediaAbsolutePath(item, { quiet = false } = {}) {
  if (!activePath || !item?.path) return "";
  try {
    const response = await fetch(
      buildApiUrl("/api/reveal/file", {
        path: getActiveNodeApiPath(),
        file: item.path
      })
    );
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(data.details || data.error || `HTTP ${response.status}`);
    }
    return String(data.fileAbsolute || "").trim();
  } catch (error) {
    if (!quiet) {
      showToast(`Не удалось получить путь: ${error.message}`, "error");
    }
    return "";
  }
}

function buildMediaLinkPath(item) {
  return buildMarkdownAttachmentRef(item?.path, getMarkdownAssetSourcePath() || getActiveNodeApiPath());
}

async function copyMediaPathText(text, successMessage) {
  const value = String(text || "").trim();
  if (!value) {
    showToast("Путь недоступен", "error");
    return false;
  }
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(value);
      showToast(successMessage, "success");
      return true;
    }
  } catch {
    // fallback below
  }
  window.prompt("Скопируйте:", value);
  return true;
}

function closeMediaPathPopover() {
  if (mediaPathPopoverState?.onDocumentClick) {
    document.removeEventListener("mousedown", mediaPathPopoverState.onDocumentClick);
  }
  if (mediaPathPopoverState?.onKeyDown) {
    document.removeEventListener("keydown", mediaPathPopoverState.onKeyDown);
  }
  mediaPathPopoverState?.popover?.remove();
  mediaPathPopoverState = null;
}

function positionMediaPathPopover(anchor, popover) {
  const rect = anchor.getBoundingClientRect();
  const margin = 8;
  popover.style.visibility = "hidden";
  popover.style.left = "0";
  popover.style.top = "0";
  const popoverRect = popover.getBoundingClientRect();
  let left = rect.right - popoverRect.width;
  let top = rect.bottom + margin;
  left = Math.max(margin, Math.min(left, window.innerWidth - popoverRect.width - margin));
  if (top + popoverRect.height > window.innerHeight - margin) {
    top = rect.top - popoverRect.height - margin;
  }
  top = Math.max(margin, Math.min(top, window.innerHeight - popoverRect.height - margin));
  popover.style.left = `${left}px`;
  popover.style.top = `${top}px`;
  popover.style.visibility = "";
}

function createMediaPathPopoverAction(label, hint, options = {}) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "media-path-popover-action";

  const labelNode = document.createElement("span");
  labelNode.className = "media-path-popover-action-label";
  labelNode.textContent = label;

  const hintNode = document.createElement("span");
  hintNode.className = "media-path-popover-action-hint";
  hintNode.textContent = hint;

  btn.append(labelNode, hintNode);
  btn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    void (async () => {
      btn.disabled = true;
      try {
        const value =
          typeof options.resolveValue === "function"
            ? await options.resolveValue()
            : String(options.value || "");
        const copied = await copyMediaPathText(value, options.successMessage || "Скопировано");
        if (copied) closeMediaPathPopover();
      } finally {
        btn.disabled = false;
      }
    })();
  });
  return btn;
}

function openMediaPathPopover(anchor, item) {
  closeMediaPathPopover();

  const linkPath = buildMediaLinkPath(item);
  const popover = document.createElement("div");
  popover.className = "media-path-popover";
  popover.setAttribute("role", "dialog");
  popover.setAttribute("aria-label", "Копирование пути");

  const title = document.createElement("p");
  title.className = "media-path-popover-title";
  title.textContent = item?.name || "Файл";

  const fullPathAction = createMediaPathPopoverAction("Скопировать полный путь", "Загрузка…", {
    resolveValue: () => resolveMediaAbsolutePath(item),
    successMessage: "Полный путь скопирован"
  });

  popover.append(
    title,
    fullPathAction,
    createMediaPathPopoverAction(
      "Скопировать путь для ссылок",
      linkPath || "—",
      {
        value: linkPath,
        successMessage: "Путь для ссылок скопирован"
      }
    )
  );

  document.body.appendChild(popover);
  positionMediaPathPopover(anchor, popover);

  void resolveMediaAbsolutePath(item, { quiet: true }).then((absolutePath) => {
    if (mediaPathPopoverState?.popover !== popover) return;
    const hint = fullPathAction.querySelector(".media-path-popover-action-hint");
    if (hint) hint.textContent = absolutePath || "—";
  });

  const onDocumentClick = (event) => {
    const target = event.target;
    if (popover.contains(target) || anchor.contains(target)) return;
    closeMediaPathPopover();
  };
  const onKeyDown = (event) => {
    if (event.key === "Escape") closeMediaPathPopover();
  };

  mediaPathPopoverState = { popover, anchor, onDocumentClick, onKeyDown };
  document.addEventListener("mousedown", onDocumentClick);
  document.addEventListener("keydown", onKeyDown);
}

