function formatFileSize(bytes) {
  const size = Number(bytes) || 0;
  if (size < 1024) return `${size} B`;
  if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)} KB`;
  return `${(size / (1024 * 1024)).toFixed(1)} MB`;
}

function getDocumentIcon(ext) {
  const extension = String(ext || "").toLowerCase();
  if (extension === ".pdf") return "📕";
  if ([".doc", ".docx"].includes(extension)) return "📘";
  if ([".xls", ".xlsx"].includes(extension)) return "📗";
  if ([".ppt", ".pptx"].includes(extension)) return "📙";
  if ([".md", ".txt"].includes(extension)) return "📝";
  return "📄";
}

function getMediaItemsForView(viewMode) {
  if (activeMediaSectionFolder) {
    return getMediaItemsForSection(activeMediaSectionFolder, viewMode);
  }
  const groupName = MEDIA_VIEW_GROUPS[viewMode];
  if (!groupName) return [];
  const items = Array.isArray(mediaFilesCache[groupName]) ? mediaFilesCache[groupName] : [];
  return items.filter((item) => isMediaContentFileItem(item));
}

function getMediaIconForItem(item) {
  if (item?.group && NAVIGATION_MEDIA_GROUP_ICONS[item.group]) {
    return NAVIGATION_MEDIA_GROUP_ICONS[item.group];
  }
  return getDocumentIcon(item?.ext);
}

function getMediaChildSections(sectionFolder) {
  const prefix = sectionFolder ? `${sectionFolder}/` : "";
  const folders = Array.isArray(mediaFilesCache.Folders) ? mediaFilesCache.Folders : [];
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  return folders
    .filter((item) => {
      if (!item.isFolder) return false;
      const folderPath = String(item.path || "").replace(/\/$/, "");
      if (!folderPath.startsWith(prefix) || folderPath === sectionFolder) return false;
      const remainder = folderPath.slice(prefix.length);
      return remainder && !remainder.includes("/");
    })
    .map((item) => {
      const folderPath = String(item.path || "").replace(/\/$/, "");
      const segment = folderPath.split("/").pop() || folderPath;
      return {
        folderPath,
        label: getMemorySectionDisplayLabel(folderPath) || item.name || segment
      };
    })
    .sort((a, b) => collator.compare(a.label, b.label));
}

function renderMediaSectionFolderView(container, sectionFolder) {
  const childSections = getMediaChildSections(sectionFolder);
  const allItems = getMediaItemsForSection(sectionFolder, "all");
  const { items } = splitSectionReadmeItems(allItems, sectionFolder);
  const readmeExists = mediaSectionReadmeExists(sectionFolder);

  if (!readmeExists) {
    appendSectionReadmeOffer(container, sectionFolder, {
      categoryType: "awn.media.category",
      onCreate: (readmePath) => void openMediaSectionReadme(readmePath, sectionFolder)
    });
  }

  if (childSections.length === 0 && items.length === 0) {
    if (!readmeExists) return;
    renderMediaEmpty(container, `В разделе «${sectionFolder}» пока нет файлов и подразделов`);
    return;
  }

  if (childSections.length > 0) {
    const subList = document.createElement("ul");
    subList.className = "media-section-subfolder-list";
    for (const child of childSections) {
      const li = document.createElement("li");
      li.className = "media-section-subfolder-item";
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "media-section-subfolder-btn";
      btn.textContent = `📁 ${child.label}`;
      btn.title = child.folderPath;
      btn.addEventListener("click", () => setActiveMediaSectionFolder(child.folderPath));
      li.appendChild(btn);
      subList.appendChild(li);
    }
    container.appendChild(subList);
  }

  if (items.length === 0) return;

  renderMediaFileRows(container, items, { icon: "📄", showSize: true });
  for (const [index, row] of Array.from(container.querySelectorAll(".media-file-item")).entries()) {
    const item = items[index];
    if (!item) continue;
    const iconNode = row.querySelector(".media-file-icon");
    if (iconNode) iconNode.textContent = getMediaIconForItem(item);
  }
}

const MEDIA_GROUP_LABELS = {
  Images: "Изображения",
  Videos: "Видео",
  Audio: "Аудио",
  Documents: "Документы",
  Archives: "Архивы",
  Other: "Прочее"
};

const MEDIA_DASHBOARD_SORT_DEFAULT = { key: "name", dir: "asc" };
let mediaDashboardSort = { ...MEDIA_DASHBOARD_SORT_DEFAULT };
let mediaDashboardFilters = { type: "all", usage: "all" };

function getAllMediaFileItems() {
  const items = [];
  for (const groupItems of Object.values(mediaFilesCache)) {
    if (!Array.isArray(groupItems)) continue;
    for (const item of groupItems) {
      if (isMediaContentFileItem(item)) items.push(item);
    }
  }
  return items;
}

function buildMediaReferenceCorpus() {
  return [
    modeContentCache.description,
    modeContentCache.internal,
    modeContentCache.todo,
    modeContentCache.configs,
    modeContentCache.env,
    modeContentCache.tabular,
    modeContentCache.external,
    fileContentInputNode?.value || ""
  ]
    .filter(Boolean)
    .join("\n")
    .toLowerCase();
}

function countMediaFileUsage(item, corpus) {
  if (!corpus) return 0;
  const path = String(item.path || "").toLowerCase();
  const name = String(item.name || "").toLowerCase();
  const assetRef = buildMarkdownAttachmentRef(
    item.path,
    getMarkdownAssetSourcePath() || getActiveNodeApiPath()
  ).toLowerCase();
  const legacyFullRef = buildStorageLayerRef(
    resolveManifestPathForNodeApi(getResolvedNodePath(activePath)),
    STORAGE_SUBFOLDER_ASSETS,
    item.path
  )?.toLowerCase() || "";
  const base = name.includes(".") ? name.slice(0, name.lastIndexOf(".")) : name;
  let count = 0;
  const bump = (token) => {
    if (!token || token.length < 2) return;
    if (corpus.includes(token)) count += 1;
  };
  bump(path);
  bump(name);
  bump(assetRef);
  bump(legacyFullRef);
  bump(`assets/${path}`.toLowerCase());
  bump(base);
  return count;
}

function getMediaFileDirectory(item) {
  const normalized = String(item.path || "").replace(/\\/g, "/");
  const idx = normalized.lastIndexOf("/");
  if (idx <= 0) return "/";
  return `/${normalized.slice(0, idx)}`;
}

function getMediaDashboardGroupLabel(group) {
  return MEDIA_GROUP_LABELS[group] || group || "Прочее";
}

function getMediaDashboardTypeIcon(item) {
  if (item.group === "Images") return "🖼";
  if (item.group === "Videos") return "🎬";
  if (item.group === "Audio") return "🎵";
  if (item.group === "Documents") return getDocumentIcon(item.ext);
  if (item.group === "Archives") return "📦";
  return "📎";
}

function enrichMediaDashboardItems(items) {
  const corpus = buildMediaReferenceCorpus();
  return items.map((item) => ({
    ...item,
    directory: getMediaFileDirectory(item),
    usage: countMediaFileUsage(item, corpus),
    typeLabel: getMediaDashboardGroupLabel(item.group)
  }));
}

function filterMediaDashboardItems(items) {
  return items.filter((item) => {
    if (mediaDashboardFilters.type !== "all" && item.group !== mediaDashboardFilters.type) return false;
    if (mediaDashboardFilters.usage === "used" && item.usage <= 0) return false;
    if (mediaDashboardFilters.usage === "unused" && item.usage > 0) return false;
    return true;
  });
}

function sortMediaDashboardItems(items) {
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  const dir = mediaDashboardSort.dir === "desc" ? -1 : 1;
  const key = mediaDashboardSort.key;
  return [...items].sort((a, b) => {
    let cmp = 0;
    if (key === "usage") cmp = (a.usage || 0) - (b.usage || 0);
    else if (key === "directory") cmp = collator.compare(a.directory || "", b.directory || "");
    else cmp = collator.compare(a.name || "", b.name || "");
    return cmp * dir;
  });
}

function createMediaDashboardStatCard({ icon, iconClass, label, value }) {
  const card = document.createElement("article");
  card.className = "media-dashboard-stat-card";

  const iconWrap = document.createElement("div");
  iconWrap.className = `media-dashboard-stat-icon ${iconClass}`;
  iconWrap.setAttribute("aria-hidden", "true");
  iconWrap.textContent = icon;

  const body = document.createElement("div");
  body.className = "media-dashboard-stat-body";

  const valueNode = document.createElement("div");
  valueNode.className = "media-dashboard-stat-value";
  valueNode.textContent = String(value);

  const labelNode = document.createElement("div");
  labelNode.className = "media-dashboard-stat-label";
  labelNode.textContent = label;

  body.append(valueNode, labelNode);
  card.append(iconWrap, body);
  return card;
}

function createMediaDashboardSortButton(label, sortKey) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "media-dashboard-sort-btn";
  const active = mediaDashboardSort.key === sortKey;
  btn.classList.toggle("is-active", active);
  btn.textContent = active
    ? `${label} ${mediaDashboardSort.dir === "asc" ? "↑" : "↓"}`
    : label;
  btn.addEventListener("click", () => {
    if (mediaDashboardSort.key === sortKey) {
      mediaDashboardSort.dir = mediaDashboardSort.dir === "asc" ? "desc" : "asc";
    } else {
      mediaDashboardSort.key = sortKey;
      mediaDashboardSort.dir = "asc";
    }
    renderListViewContent();
  });
  return btn;
}

function renderMediaUsageDashboard(container) {
  container.innerHTML = "";

  if (!Object.values(mediaFilesCache).some((items) => Array.isArray(items) && items.length > 0)) {
    syncMediaFilesCache(modeContentCache.media, mediaFilesCache);
  }

  const allItems = enrichMediaDashboardItems(getAllMediaFileItems());
  const filteredItems = sortMediaDashboardItems(filterMediaDashboardItems(allItems));
  const usedCount = allItems.filter((item) => item.usage > 0).length;
  const unusedCount = Math.max(0, allItems.length - usedCount);

  const dashboard = document.createElement("div");
  dashboard.className = "media-usage-dashboard";

  const stats = document.createElement("div");
  stats.className = "media-dashboard-stats";
  stats.append(
    createMediaDashboardStatCard({
      icon: "🗄",
      iconClass: "is-total",
      label: "Всего файлов",
      value: allItems.length
    }),
    createMediaDashboardStatCard({
      icon: "✓",
      iconClass: "is-used",
      label: "Используются",
      value: usedCount
    }),
    createMediaDashboardStatCard({
      icon: "⊘",
      iconClass: "is-unused",
      label: "Не используются",
      value: unusedCount
    })
  );
  dashboard.appendChild(stats);

  const inventory = document.createElement("section");
  inventory.className = "media-dashboard-inventory";

  const inventoryHead = document.createElement("div");
  inventoryHead.className = "media-dashboard-inventory-head";

  const inventoryTitle = document.createElement("h4");
  inventoryTitle.className = "media-dashboard-inventory-title";
  inventoryTitle.textContent = "Каталог медиа";

  const inventoryMeta = document.createElement("div");
  inventoryMeta.className = "media-dashboard-inventory-meta";
  const results = document.createElement("span");
  results.className = "media-dashboard-results";
  results.textContent = `${filteredItems.length} результатов`;

  const filters = document.createElement("div");
  filters.className = "media-dashboard-filters";

  const typeSelect = document.createElement("select");
  typeSelect.className = "media-dashboard-filter-select";
  typeSelect.setAttribute("aria-label", "Тип файла");
  typeSelect.innerHTML = `
    <option value="all">Все типы</option>
    <option value="Images">Изображения</option>
    <option value="Videos">Видео</option>
    <option value="Audio">Аудио</option>
    <option value="Documents">Документы</option>
    <option value="Archives">Архивы</option>
    <option value="Other">Прочее</option>
  `;
  typeSelect.value = mediaDashboardFilters.type;
  typeSelect.addEventListener("change", () => {
    mediaDashboardFilters.type = typeSelect.value;
    renderListViewContent();
  });

  const usageSelect = document.createElement("select");
  usageSelect.className = "media-dashboard-filter-select";
  usageSelect.setAttribute("aria-label", "Использование");
  usageSelect.innerHTML = `
    <option value="all">Все</option>
    <option value="used">Используются</option>
    <option value="unused">Не используются</option>
  `;
  usageSelect.value = mediaDashboardFilters.usage;
  usageSelect.addEventListener("change", () => {
    mediaDashboardFilters.usage = usageSelect.value;
    renderListViewContent();
  });

  filters.append(typeSelect, usageSelect);
  inventoryMeta.append(results, filters);
  inventoryHead.append(inventoryTitle, inventoryMeta);
  inventory.appendChild(inventoryHead);

  if (filteredItems.length === 0) {
    const empty = document.createElement("div");
    empty.className = "media-dashboard-empty";
    empty.textContent = allItems.length ? "Нет файлов по выбранным фильтрам" : getStorageFolderEmptyMessage(activeContentMode);
    inventory.appendChild(empty);
    dashboard.appendChild(inventory);
    container.appendChild(dashboard);
    return;
  }

  const tableWrap = document.createElement("div");
  tableWrap.className = "media-dashboard-table-wrap";

  const table = document.createElement("table");
  table.className = "media-dashboard-table";

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  const thPreview = document.createElement("th");
  thPreview.textContent = "Превью";
  const thName = document.createElement("th");
  thName.appendChild(createMediaDashboardSortButton("Имя файла", "name"));
  const thUsage = document.createElement("th");
  thUsage.appendChild(createMediaDashboardSortButton("Использование", "usage"));
  const thActions = document.createElement("th");
  thActions.textContent = "Действия";
  headRow.append(thPreview, thName, thUsage, thActions);
  thead.appendChild(headRow);
  table.appendChild(thead);

  const tbody = document.createElement("tbody");
  for (const item of filteredItems) {
    const row = document.createElement("tr");
    row.className = "media-dashboard-row";

    const previewCell = document.createElement("td");
    previewCell.className = "media-dashboard-cell-preview";
    const preview = document.createElement("div");
    preview.className = "media-dashboard-preview";
    if (item.group === "Images") {
      const img = document.createElement("img");
      img.alt = item.name;
      img.loading = "lazy";
      img.src = buildMediaThumbUrl(item.path, activePath, MEDIA_THUMB_MAX_DEFAULT);
      img.addEventListener("error", () => {
        preview.classList.add("is-fallback");
        img.remove();
        preview.textContent = getMediaDashboardTypeIcon(item);
      });
      preview.appendChild(img);
    } else {
      preview.classList.add("is-fallback");
      preview.textContent = getMediaDashboardTypeIcon(item);
      if (item.group === "Documents" && isMediaDocumentPreviewCandidate(item.name)) {
        preview.classList.add("is-clickable");
        preview.title = "Просмотр";
        preview.addEventListener("click", (event) => {
          guardMediaActionClick(event, () => {
            openMediaAsset(item.path);
          });
        });
      }
    }
    previewCell.appendChild(preview);

    const nameCell = document.createElement("td");
    nameCell.className = "media-dashboard-cell-name";
    const nameMain = document.createElement("div");
    nameMain.className = "media-dashboard-filename";
    nameMain.textContent = item.displayName || item.name;
    const nameMeta = document.createElement("div");
    nameMeta.className = "media-dashboard-filemeta";
    nameMeta.textContent = `${item.typeLabel}${item.size ? ` · ${formatFileSize(item.size)}` : ""}`;
    nameCell.append(nameMain, nameMeta);

    const usageCell = document.createElement("td");
    usageCell.className = "media-dashboard-cell-usage";
    const usageBadge = document.createElement("span");
    usageBadge.className = `media-dashboard-usage-badge ${item.usage > 0 ? "is-used" : "is-unused"}`;
    usageBadge.textContent = String(item.usage);
    usageCell.appendChild(usageBadge);

    const actionsCell = document.createElement("td");
    actionsCell.className = "media-dashboard-cell-actions";
    appendMediaItemActionButtons(actionsCell, item);

    row.append(previewCell, nameCell, usageCell, actionsCell);
    tbody.appendChild(row);
  }

  table.appendChild(tbody);
  tableWrap.appendChild(table);
  inventory.appendChild(tableWrap);
  dashboard.appendChild(inventory);
  container.appendChild(dashboard);
}

function renderMediaEmpty(container, message = "Файлы не найдены") {
  renderListEmptyMessage(container, message);
}

const STORAGE_FOLDER_LABELS = {
  inbox: STORAGE_SUBFOLDER_INBOX,
  "quick-notes": STORAGE_SUBFOLDER_QUICK_NOTES,
  references: STORAGE_SUBFOLDER_REFERENCES,
  scripts: STORAGE_SUBFOLDER_SCRIPTS,
  artefacts: STORAGE_SUBFOLDER_ARTEFACTS,
  assets: STORAGE_SUBFOLDER_ASSETS,
  repository: STORAGE_SUBFOLDER_REPOSITORY,
  media: STORAGE_SUBFOLDER_MEDIA,
  temp: STORAGE_SUBFOLDER_TEMP,
  external: STORAGE_SUBFOLDER_CONTENT
};

function getStorageFolderDisplayLabel(mode = activeContentMode) {
  const label = getContentModeLabel(mode);
  if (label && label !== mode) return label;
  return STORAGE_FOLDER_LABELS[mode] || label || "";
}

function getStorageFolderMissingMessage(mode = activeContentMode, { short = false } = {}) {
  if (short) return "Папка не найдена на диске";
  const label = getStorageFolderDisplayLabel(mode);
  return label ? `Папка «${label}» не найдена` : "Папка не найдена";
}

function getStorageFolderEmptyMessage(mode = activeContentMode, { short = false } = {}) {
  if (short) return "Папка пуста";
  const label = getStorageFolderDisplayLabel(mode);
  return label ? `Папка «${label}» пуста` : "Список пуст";
}

function getDataStorageSlotPathHint(spec) {
  if (!spec) return "";
  const folderName = getStorageFolderNamesForSlotKey(spec.key)[0] || spec.key;
  return `${STORAGE_ROOT_FOLDER}/${folderName}/`;
}

function isDataHubPanelContainer(container) {
  return Boolean(container?.closest?.(".data-hub-panel") || container?.classList?.contains("data-hub-panel"));
}

function renderDataHubPanelEmptyState(
  container,
  { icon = "📁", message = "", path = "", variant = "muted", actionLabel = "", onAction = null } = {}
) {
  container.replaceChildren();
  const state = document.createElement("div");
  state.className = `data-hub-panel-empty-state data-hub-panel-empty-state--${variant}`;

  const iconNode = document.createElement("div");
  iconNode.className = "data-hub-panel-empty-state-icon";
  iconNode.textContent = icon;
  iconNode.setAttribute("aria-hidden", "true");
  state.appendChild(iconNode);

  if (message) {
    const text = document.createElement("p");
    text.className = "data-hub-panel-empty-state-message";
    text.textContent = message;
    state.appendChild(text);
  }

  if (path) {
    const pathNode = document.createElement("p");
    pathNode.className = "data-hub-panel-empty-state-path";
    pathNode.textContent = path;
    state.appendChild(pathNode);
  }

  if (actionLabel && typeof onAction === "function") {
    const actionBtn = document.createElement("button");
    actionBtn.type = "button";
    actionBtn.className = "data-hub-panel-empty-state-action";
    actionBtn.textContent = actionLabel;
    actionBtn.addEventListener("click", onAction);
    state.appendChild(actionBtn);
  }

  container.appendChild(state);
}

function isFlatStorageListMode(mode = activeContentMode) {
  return (
    mode === "inbox" ||
    mode === "note" ||
    mode === "quick-notes" ||
    mode === "references" ||
    mode === "scripts" ||
    mode === "artefacts" ||
    mode === "repository" ||
    mode === "temp"
  );
}

function isFlatStorageListSourceToggleMode() {
  return false;
}

function isTabularSourceEditing() {
  return activeContentMode === "tabular" && editorViewMode === "source";
}

function isListViewWithSourceToggleMode() {
  return false;
}

function isNodeManifestContextPath(nodePath = activePath) {
  const normalized = getResolvedNodePath(nodePath);
  if (!normalized || activeSystemFile) return false;
  if (isGitRepoLooseFilePath(normalized)) return false;
  if (isAgentSystemEditableFilePath(normalized)) return false;
  return isNodeManifestPath(normalized) || isTopicManifestPath(normalized) || isAreaNodePath(normalized);
}

function isWorkspaceRefreshAvailable() {
  return Boolean(
    activePath ||
      activeSystemFile ||
      (activeFolderBrowsePath &&
        (activeContentMode === FOLDER_BROWSE_MODE || activeContentMode === FOLDER_BROWSE_FILE_MODE))
  );
}

function getActiveRevealFolderPath() {
  if (
    activeFolderBrowsePath &&
    (activeContentMode === FOLDER_BROWSE_MODE || activeContentMode === FOLDER_BROWSE_FILE_MODE)
  ) {
    return normalizeCreateParentPath(activeFolderBrowsePath);
  }
  if (activePath && !activeSystemFile) {
    return getResolvedNodePath(activePath);
  }
  return "";
}

function isRevealNodeFolderAvailable() {
  return Boolean(getActiveRevealFolderPath());
}

function syncWorkspaceRevealFolderButton() {
  if (!workspaceRevealFolderBtn) return;
  const detailLabel = getRevealFolderLabel();
  workspaceRevealFolderBtn.title = detailLabel;
  workspaceRevealFolderBtn.setAttribute("aria-label", detailLabel);
  workspaceRevealFolderBtn.classList.toggle("hidden", !isRevealNodeFolderAvailable());
}

const WORKSPACE_CRUMBS_ACTION_ORDER = [
  "workspace-links-menu-wrap",
  "folder-browse-upload-input",
  "folder-browse-upload-btn",
  "workspace-print-btn",
  "workspace-reveal-folder-btn",
  "workspace-refresh-btn",
  "folder-browse-file-rename-btn",
  "folder-browse-delete-selected-btn"
];

function syncWorkspaceCrumbsActionsOrder() {
  if (!workspacePathCrumbsActionsNode) return;
  for (const id of WORKSPACE_CRUMBS_ACTION_ORDER) {
    const node = document.getElementById(id);
    if (node?.parentElement === workspacePathCrumbsActionsNode) {
      workspacePathCrumbsActionsNode.appendChild(node);
    }
  }
}

function syncWorkspaceRefreshButton() {
  if (!workspaceRefreshBtn) return;
  const available = isWorkspaceRefreshAvailable();
  workspaceRefreshBtn.classList.toggle("hidden", !available);
  workspaceRefreshBtn.disabled = workspaceRefreshInFlight;
  workspaceRefreshBtn.classList.toggle("is-spinning", workspaceRefreshInFlight);
}

let workspaceRefreshInFlight = false;

async function reloadActiveNodeManifestFromDisk() {
  const apiPath = getActiveNodeApiPath();
  if (!apiPath || !isNodeManifestContextPath()) return;

  const response = await fetch(buildApiUrl("/api/file", { path: apiPath }));
  if (!response.ok) throw new Error(`Request failed with ${response.status}`);
  const data = await response.json();
  modeContentCache.description = data.content || "";

  invalidateNodeConfigCache(activePath);
  try {
    await loadNodeConfig(activePath, { force: true });
  } catch {
    // ignore config reload errors during refresh
  }

  const schemaManifestPath = getTopicSchemaManifestPath(activePath);
  if (schemaManifestPath) {
    topicSchemaCacheByManifest.delete(schemaManifestPath);
  }
}

async function refreshWorkspaceContent() {
  if (!isWorkspaceRefreshAvailable() || workspaceRefreshInFlight) return;
  workspaceRefreshInFlight = true;
  syncWorkspaceRefreshButton();
  try {
    invalidateStorageRootScanCache();
    resetPropsLibrariesCache();

    if (activeSystemFile) {
      await selectSystemFile(activeSystemFile, { skipRouteSync: true });
      return;
    }

    if (
      (activeContentMode === FOLDER_BROWSE_MODE || activeContentMode === FOLDER_BROWSE_FILE_MODE) &&
      activeFolderBrowsePath
    ) {
      await refreshMenu({ agentId: activeAgentId });
      if (activeContentMode === FOLDER_BROWSE_FILE_MODE && activeFolderBrowseFilePath) {
        await renderFolderBrowseFileView();
      } else {
        await renderFolderBrowseView();
      }
      return;
    }

    if (isAgentSystemFileEditing()) {
      await selectAgentSystemFile(activeLabel || getLabelFromPath(activePath), activePath, {
        skipRouteSync: true
      });
      return;
    }

    if (isGitRepoLooseFilePath(activePath)) {
      await selectRepoLooseFile(activeLabel || getLabelFromPath(activePath), activePath, {
        skipRouteSync: true
      });
      return;
    }

    if (activeContentMode === "external" && activeExternalFilePath) {
      const file = activeExternalFilePath;
      await refreshExternalMemoryCaches();
      await openExternalFile(file, { skipRouteSync: true });
      return;
    }

    if (isMediaSidecarEditing() && activeMediaSidecarSourcePath) {
      const file = activeMediaSidecarSourcePath;
      await refreshMediaCache();
      await openMediaSidecar(file, { skipRouteSync: true });
      return;
    }

    if (isMediaMarkdownEditing() && activeMediaMarkdownPath) {
      const file = activeMediaMarkdownPath;
      await refreshMediaCache();
      await openMediaMarkdownFile(file, { skipRouteSync: true });
      return;
    }

    if (isNodeManifestContextPath()) {
      await reloadActiveNodeManifestFromDisk();
      await loadPropertiesForActivePath();
    } else if (activePath) {
      modeContentCache.description = "";
    }

    if (activeContentMode && Object.prototype.hasOwnProperty.call(modeContentCache, activeContentMode)) {
      modeContentCache[activeContentMode] = "";
    }
    if (activeContentMode === "tabular") {
      tabularDataCache = { columns: [], rows: [], rowCount: 0 };
    }

    await loadContentByMode({ forceReload: true });
  } finally {
    workspaceRefreshInFlight = false;
    syncWorkspaceRefreshButton();
  }
}

function renderListEmptyMessage(container, message, { centeredInDataHub = false } = {}) {
  if (centeredInDataHub || isDataHubPanelContainer(container)) {
    const spec = getDataStorageSlotForMode(activeContentMode);
    const shortMessage =
      message === getStorageFolderMissingMessage(activeContentMode)
        ? getStorageFolderMissingMessage(activeContentMode, { short: true })
        : message === getStorageFolderEmptyMessage(activeContentMode)
          ? getStorageFolderEmptyMessage(activeContentMode, { short: true })
          : message;
    renderDataHubPanelEmptyState(container, {
      icon: spec?.icon || "📁",
      message: shortMessage,
      path: getDataStorageSlotPathHint(spec),
      variant: shortMessage.includes("не найден") ? "missing" : "muted"
    });
    return;
  }
  const empty = document.createElement("div");
  empty.className = "list-empty";
  empty.textContent = message;
  container.appendChild(empty);
}

function applyFlatStorageFolderLoadState(mode, data) {
  activeStorageFolderExists = Boolean(data.exists);
  modeContentCache[mode] = data.content || "";
  if (!activeStorageFolderExists) {
    fileContentInputNode.value = "";
    return;
  }
  fileContentInputNode.value = modeContentCache[mode];
}

function renderMediaFileRows(container, items, { icon = "📄", showSize = true } = {}) {
  if (items.length === 0) {
    renderMediaEmpty(container);
    return;
  }

  const list = document.createElement("ul");
  list.className = "media-file-list";

  for (const item of items) {
    const li = document.createElement("li");
    li.className = "media-file-item";
    li.dataset.memoryFilePath = item.path;
    li.dataset.memoryFileScope = "media";

    const dragHandle = createMemoryFileDragHandle();
    li.appendChild(dragHandle);

    const iconNode = document.createElement("span");
    iconNode.className = "media-file-icon";
    iconNode.textContent = icon;

    const body = document.createElement("div");
    body.className = "media-file-body";

    const nameNode = document.createElement("div");
    nameNode.className = "media-file-name";
    nameNode.textContent = String(item.displayName || "").trim() || item.name;
    nameNode.addEventListener("click", (event) => {
      guardMediaActionClick(event, () => {
        openMediaAsset(item.path);
      });
    });

    const pathNode = document.createElement("div");
    pathNode.className = "media-file-path";
    pathNode.textContent = item.path;

    body.appendChild(nameNode);
    body.appendChild(pathNode);

    if (showSize && item.size) {
      const sizeNode = document.createElement("div");
      sizeNode.className = "media-file-size";
      sizeNode.textContent = formatFileSize(item.size);
      body.appendChild(sizeNode);
    }

    const actions = document.createElement("div");
    actions.className = "media-file-actions";
    appendMediaItemActionButtons(actions, item);

    li.appendChild(iconNode);
    li.appendChild(body);
    li.appendChild(actions);
    list.appendChild(li);
  }

  container.appendChild(list);
}

function renderMediaImagesGrid(container, items) {
  if (items.length === 0) {
    renderMediaEmpty(container, "Изображения не найдены");
    return;
  }

  const grid = document.createElement("div");
  grid.className = "media-images-grid";

  for (const item of items) {
    const card = document.createElement("article");
    card.className = "media-image-card";

    const imgWrap = document.createElement("div");
    imgWrap.className = "media-image-thumb";

    const img = document.createElement("img");
    img.alt = item.name;
    img.loading = "lazy";
    img.src = buildMediaThumbUrl(item.path, activePath, MEDIA_THUMB_MAX_GRID);
    img.addEventListener("error", () => {
      imgWrap.classList.add("media-image-thumb-error");
      img.remove();
      const fallback = document.createElement("span");
      fallback.className = "media-image-fallback";
      fallback.textContent = "🖼";
      imgWrap.appendChild(fallback);
    });
    imgWrap.addEventListener("click", (event) => {
      guardMediaActionClick(event, () => {
        openMediaAssetExternal(item.path);
      });
    });
    imgWrap.appendChild(img);

    const nameNode = document.createElement("div");
    nameNode.className = "media-image-name";
    nameNode.textContent = item.name;

    const actions = document.createElement("div");
    actions.className = "media-image-actions";

    appendMediaItemActionButtons(actions, item);

    card.appendChild(imgWrap);
    card.appendChild(nameNode);
    card.appendChild(actions);
    grid.appendChild(card);
  }

  container.appendChild(grid);
}

function renderMediaAudioList(container, items) {
  if (items.length === 0) {
    renderMediaEmpty(container, "Аудиофайлы не найдены");
    return;
  }

  const list = document.createElement("div");
  list.className = "media-player-list";

  for (const item of items) {
    const row = document.createElement("article");
    row.className = "media-player-item";

    const meta = document.createElement("div");
    meta.className = "media-player-meta";
    meta.innerHTML = `
      <div class="media-file-name">${escapeHtml(item.name)}</div>
      <div class="media-file-path">${escapeHtml(item.path)}</div>
    `;

    const audio = document.createElement("audio");
    audio.className = "media-audio-player";
    audio.controls = true;
    audio.preload="none";
    audio.src = buildMediaAssetUrl(item.path);

    row.appendChild(meta);
    row.appendChild(audio);

    const actions = document.createElement("div");
    actions.className = "media-player-actions";
    appendMediaItemActionButtons(actions, item);
    row.appendChild(actions);
    list.appendChild(row);
  }

  container.appendChild(list);
}

function renderMediaVideoList(container, items) {
  if (items.length === 0) {
    renderMediaEmpty(container, "Видеофайлы не найдены");
    return;
  }

  const list = document.createElement("div");
  list.className = "media-player-list";

  for (const item of items) {
    const row = document.createElement("article");
    row.className = "media-player-item media-video-item";

    const meta = document.createElement("div");
    meta.className = "media-player-meta";
    meta.innerHTML = `
      <div class="media-file-name">${escapeHtml(item.name)}</div>
      <div class="media-file-path">${escapeHtml(item.path)}</div>
    `;

    const video = document.createElement("video");
    video.className = "media-video-player";
    video.controls = true;
    video.preload = "metadata";
    video.src = buildMediaAssetUrl(item.path);

    row.appendChild(meta);
    row.appendChild(video);

    const actions = document.createElement("div");
    actions.className = "media-player-actions";
    appendMediaItemActionButtons(actions, item);
    row.appendChild(actions);
    list.appendChild(row);
  }

  container.appendChild(list);
}

function renderMediaFilteredView(container, viewMode = getEffectiveMediaViewMode()) {
  const items = getMediaItemsForView(viewMode);

  if (viewMode === "images") {
    renderMediaImagesGrid(container, items);
    return;
  }
  if (viewMode === "audio") {
    renderMediaAudioList(container, items);
    return;
  }
  if (viewMode === "video") {
    renderMediaVideoList(container, items);
    return;
  }
  if (viewMode === "documents") {
    renderMediaFileRows(
      container,
      items,
      { icon: "📄", showSize: true }
    );
    for (const row of container.querySelectorAll(".media-file-item")) {
      const index = Array.from(container.querySelectorAll(".media-file-item")).indexOf(row);
      const item = items[index];
      if (!item) continue;
      const iconNode = row.querySelector(".media-file-icon");
      if (iconNode) iconNode.textContent = getDocumentIcon(item.ext);
    }
    return;
  }
  if (viewMode === "archives") {
    renderMediaFileRows(container, items, { icon: "📦", showSize: true });
    return;
  }
  if (viewMode === "other") {
    renderMediaFileRows(container, items, { icon: "📎", showSize: true });
  }
}

function renderDataHubAllItemsPanel(container, scan) {
  container.replaceChildren();
  if (!scan?.exists) {
    renderDataHubPanelEmptyState(container, {
      icon: "📦",
      message: "Папка awn-storage не найдена",
      path: `${STORAGE_ROOT_FOLDER}/`,
      variant: "missing"
    });
    return;
  }
  const entries = buildStorageSlotTreeModel(scan || {});
  const looseFiles = scan?.looseFiles || [];
  const root = document.createElement("div");
  root.className = "data-hub-all-items-view";

  const grid = document.createElement("div");
  grid.className = "data-hub-all-items-grid";
  grid.setAttribute("role", "list");
  root.appendChild(grid);

  for (const entry of entries) {
    if (entry.kind === "divider") continue;

    const spec = entry.kind === "slot" ? entry.spec : null;
    const folder = entry.folder || null;
    const isOrphan = entry.kind === "orphan";
    const disabled = isStorageScanFolderDisabled(folder, spec);
    const folderName =
      folder?.name || (spec ? getStorageFolderNamesForSlotKey(spec.key)[0] : "") || spec?.key || "";
    const entryCount = Number(folder?.entryCount) || 0;
    const icon = spec?.icon || "📁";
    const label = spec?.label || folder?.name || folderName;
    const pathHint = folderName ? `${STORAGE_ROOT_FOLDER}/${folderName}/` : "";
    const hasFolder = Boolean(folder);
    const isMissing = !hasFolder && !isOrphan;

    const card = document.createElement("article");
    card.className = "data-hub-slot-card";
    card.setAttribute("role", "listitem");
    if (disabled) card.classList.add("is-disabled");
    if (isMissing) card.classList.add("is-missing");
    else if (!entryCount) card.classList.add("is-empty");
    else card.classList.add("has-items");

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "data-hub-slot-card-btn";
    btn.disabled = disabled || isMissing;

    const iconNode = document.createElement("span");
    iconNode.className = "data-hub-slot-card-icon";
    iconNode.textContent = icon;
    iconNode.setAttribute("aria-hidden", "true");

    const body = document.createElement("span");
    body.className = "data-hub-slot-card-body";

    const title = document.createElement("span");
    title.className = "data-hub-slot-card-label";
    title.textContent = label;

    const status = document.createElement("span");
    status.className = "data-hub-slot-card-status";
    if (isMissing) {
      status.textContent = "нет на диске";
    } else if (entryCount > 0) {
      status.textContent = `${entryCount} эл.`;
    } else {
      status.textContent = "пусто";
    }

    body.append(title, status);

    if (pathHint) {
      const pathNode = document.createElement("span");
      pathNode.className = "data-hub-slot-card-path";
      pathNode.textContent = pathHint;
      body.appendChild(pathNode);
    }

    btn.append(iconNode, body);

    if (!disabled && spec && hasFolder) {
      btn.addEventListener("click", () => setActiveDataStorageSlot(spec));
    } else if (isOrphan) {
      btn.title = "Папка не сопоставлена ни с одним слотом";
    } else if (spec?.disabled) {
      btn.title = "Скоро";
    } else if (isMissing) {
      btn.title = "Папка не найдена на диске";
    }

    card.appendChild(btn);
    grid.appendChild(card);
  }

  if (looseFiles.length > 0) {
    const section = document.createElement("section");
    section.className = "data-hub-all-items-loose-section";

    const header = document.createElement("div");
    header.className = "data-hub-all-items-loose-head";
    header.textContent = `📄 Файлы вне папок (${looseFiles.length})`;
    section.appendChild(header);

    const list = document.createElement("ul");
    list.className = "data-hub-all-items-loose-list";
    for (const fileName of looseFiles) {
      const item = document.createElement("li");
      item.className = "data-hub-all-items-loose-item";
      item.textContent = `${STORAGE_ROOT_FOLDER}/${fileName}`;
      list.appendChild(item);
    }
    section.appendChild(list);
    root.appendChild(section);
  }

  container.appendChild(root);
}

function renderListViewContent() {
  closeMediaPathPopover();
  syncListViewHead();
  const raw = getListViewRawContent();
  const useDataHub = shouldUseDataHubListShell();
  const listMountRoot = useDataHub ? getListViewMountRoot() : listViewContentNode;
  const isMediaListView = isMediaLibraryContentMode() && !isMediaAssetEditing();
  const isExternalListView = activeContentMode === "external" && !isExternalFileEditing();
  const isFlatStorageSectionListView = isFlatStorageSectionMode() && isFlatStorageListMode();

  if (useDataHub && shouldShowDataHubAllSlotsPanel()) {
    ensureDataHubShell();
    void loadDataHubAllItemsPanel(getListViewMountRoot());
    return;
  }

  if (useDataHub && isDataHubBundleSlotShellMode()) {
    ensureDataHubShell();
    void renderDataHubBundleSlotPanel(getListViewMountRoot(), activeContentMode);
    return;
  }

  if (activeContentMode === "tabular" && !isTabularSourceEditing()) {
    if (useDataHub) ensureDataHubShell();
    listMountRoot.innerHTML = "";
    if (!useDataHub) listViewContentNode.innerHTML = "";
    renderTabularTableView(listMountRoot);
    return;
  }

  let listTarget = listMountRoot;
  if (isMediaListView) {
    listTarget = ensureMediaListViewLayout();
    listTarget.innerHTML = "";
    renderMediaListViewBody(listTarget);
    return;
  }
  if (isExternalListView) {
    listTarget = ensureExternalListViewLayout();
    const renderToken = ++externalListRenderToken;
    listTarget.replaceChildren();
    void ensureExternalListSchemaReady().then(() => {
      if (renderToken !== externalListRenderToken) return;
      if (activeContentMode !== "external" || isExternalFileEditing()) return;
      const body = listViewContentNode.querySelector(".external-list-view-body");
      if (!body || body !== listTarget) return;
      renderExternalListViewBody(body);
    });
    return;
  }
  if (isFlatStorageSectionListView) {
    listTarget = ensureFlatStorageListViewLayout(activeContentMode);
    listTarget.innerHTML = "";
    renderFlatStorageListViewBody(listTarget, activeContentMode);
    return;
  }

  if (useDataHub) {
    listMountRoot.innerHTML = "";
  } else {
    listViewContentNode.innerHTML = "";
  }

  if (isFlatStorageListMode()) {
    if (!activeStorageFolderExists) {
      renderListEmptyMessage(listViewContentNode, getStorageFolderMissingMessage());
      return;
    }
    if (!raw.trim()) {
      renderListEmptyMessage(listViewContentNode, getStorageFolderEmptyMessage());
      return;
    }
  }

  const naturalCollator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });

  function comparePathsNatural(aPath, bPath) {
    const aParts = aPath.split("/").filter(Boolean);
    const bParts = bPath.split("/").filter(Boolean);
    const len = Math.min(aParts.length, bParts.length);
    for (let i = 0; i < len; i += 1) {
      const cmp = naturalCollator.compare(aParts[i], bParts[i]);
      if (cmp !== 0) return cmp;
    }
    return aParts.length - bParts.length;
  }

  if (!raw.trim()) {
    const empty = document.createElement("div");
    empty.className = "list-empty";
    if (isMediaLibraryContentMode() && !isMediaAssetEditing()) {
      empty.textContent = getStorageFolderEmptyMessage(activeContentMode);
    } else {
      empty.textContent = "Список пуст";
    }
    listTarget.appendChild(empty);
    return;
  }

  const sections = isMediaLibraryContentMode()
    ? parseMediaSections(raw)
    : [{ title: "Файлы", items: parseFlatListItems(raw) }];

  for (const section of sections) {
    const normalizedItems = section.items
      .map((item) => normalizeListItem(item))
      .filter((item) => item.path)
      .sort((a, b) => {
        if (a.isFolder !== b.isFolder) return a.isFolder ? -1 : 1;
        return comparePathsNatural(a.path, b.path);
      });

    const sectionNode = document.createElement("section");
    sectionNode.className = "list-section";

    if (!isFlatStorageListMode()) {
      const headerNode = document.createElement("div");
      headerNode.className = "list-section-header";
      headerNode.textContent = section.title;
      sectionNode.appendChild(headerNode);
    }

    const listNode = document.createElement("ul");
    listNode.className = "list-items";

    for (const normalized of normalizedItems) {
      const li = document.createElement("li");
      li.className = "list-item";
        if (activeContentMode === "external" && normalized.path.toLowerCase().endsWith(".md")) {
          li.style.cursor = "pointer";
          li.addEventListener("click", () => openExternalFile(normalized.path));
        }

      const icon = document.createElement("span");
      icon.className = "list-item-icon";
      icon.textContent = normalized.isFolder ? "📁" : "📄";

      const pathNode = document.createElement("span");
      pathNode.className = "list-item-path";
      pathNode.textContent = normalized.path;

      li.appendChild(icon);
      li.appendChild(pathNode);

      if (isMediaLibraryContentMode() && !normalized.isFolder) {
        li.classList.add("list-item-with-actions");
        const actions = document.createElement("div");
        actions.className = "list-item-actions";
        appendMediaItemActionButtons(actions, { path: normalized.path });
        li.appendChild(actions);
      }

      listNode.appendChild(li);
    }

    sectionNode.appendChild(listNode);
    listTarget.appendChild(sectionNode);
  }
}

function clearMediaSidecarEditor() {
  activeMediaSidecarSourcePath = null;
  activeMediaSidecarPath = null;
  activeMediaMarkdownPath = null;
  resetTitleInputState();
}

function placeTitleFixedInBreadcrumbs() {
  if (!filePathNode || !titleFixedValueNode) return;
  titleFixedValueNode.classList.add("breadcrumb-service-title");
  if (titleFixedValueNode.parentElement !== filePathNode) {
    filePathNode.appendChild(titleFixedValueNode);
  }
}

function placeTitleFixedInTitleRow() {
  if (!titleRowNode || !titleFixedValueNode) return;
  titleFixedValueNode.classList.remove("breadcrumb-service-title");
  if (titleFixedValueNode.parentElement !== titleRowNode) {
    titleRowNode.appendChild(titleFixedValueNode);
  }
}

function clearFilePathNode() {
  if (!filePathNode) return;
  Array.from(filePathNode.childNodes).forEach((node) => {
    if (node !== titleFixedValueNode) node.remove();
  });
}

function setTitleLockedDisplay(label) {
  titleInputNode.classList.add("hidden");
  titleInputNode.readOnly = true;
  titleMediaExtNode?.classList.add("hidden");
  titleFixedValueNode.classList.remove("hidden");
  if (titleFixedTextNode) titleFixedTextNode.textContent = label || "";
  if (activeSystemFile || isGitRepoLooseFilePath(activePath)) {
    placeTitleFixedInBreadcrumbs();
  } else {
    placeTitleFixedInTitleRow();
  }
}

function isReservedRootManifestPath(nodePath) {
  return (
    isAgentSystemRootIndexPath(nodePath) ||
    isAgentContainerRootIndexPath(nodePath) ||
    isAgentSharedRootIndexPath(nodePath)
  );
}

function getSystemReferenceManifestRelPaths(agentId = activeAgentId) {
  const kitFolder = getActiveAgentKitFolder(agentId);
  if (!kitFolder) return [];
  const paths = [];
  for (const fileName of Object.values(SERVICE_CATALOG_PRESET_FILES)) {
    paths.push(`${kitFolder}/${SERVICE_CATALOG_FOLDER}/${fileName}.md`);
    paths.push(`${kitFolder}/${SERVICE_CATALOG_FOLDER}/${fileName}/manifest.md`);
    paths.push(`${kitFolder}/${LEGACY_SERVICE_CATALOG_FOLDER}/${fileName}.md`);
    paths.push(`${kitFolder}/${LEGACY_SERVICE_CATALOG_FOLDER}/${fileName}/manifest.md`);
    paths.push(`${kitFolder}/${fileName}.md`);
    paths.push(`${kitFolder}/${fileName}/manifest.md`);
  }
  for (const fileName of Object.values(SERVICE_DOC_PRESET_FILES)) {
    paths.push(`${kitFolder}/${fileName}.md`);
    paths.push(`${kitFolder}/${fileName}/manifest.md`);
  }
  return paths.map((item) => normalizeMenuNodePath(item));
}

function isSystemReferenceManifestPath(nodePath, agentId = activeAgentId) {
  const normalized = normalizeMenuNodePath(nodePath);
  if (!normalized || !isServiceNodePath(normalized)) return false;
  return getSystemReferenceManifestRelPaths(agentId).includes(normalized);
}

function isSlugLockedManifestPath(nodePath, agentId = activeAgentId) {
  return isReservedRootManifestPath(nodePath) || isSystemReferenceManifestPath(nodePath, agentId);
}

function isTitleLockedNodePath(nodePath = getActiveNodeApiPath()) {
  return false;
}

function setTitleLockedInput(label) {
  titleInputNode.classList.remove("hidden");
  titleInputNode.value = label || "";
  titleInputNode.readOnly = true;
  titleInputNode.disabled = true;
  titleMediaExtNode?.classList.add("hidden");
  titleFixedValueNode.classList.add("hidden");
  if (titleFixedTextNode) titleFixedTextNode.textContent = "";
  placeTitleFixedInTitleRow();
  titleSlugRowNode?.classList.add("hidden");
}

function syncTitleInputEditableState() {
  if (activeSystemFile || isGitRepoLooseFilePath(activePath)) return;

  const mediaSidecarEditing = isMediaAssetEditing();
  const externalEditing =
    activeContentMode === "external" && Boolean(activeExternalFilePath);
  const titleEditable = isCurrentModeTitleEditable();

  if (mediaSidecarEditing) {
    syncMediaSidecarTitleFields();
    return;
  }

  if (titleEditable) {
    showTitleEditableInput();
    titleInputNode.disabled = false;
    titleInputNode.readOnly = false;
    if (externalEditing && activeExternalFilePath) {
      syncTitleFieldsFromNode(activeExternalFilePath);
    } else if (isMediaMarkdownEditing() && activeMediaMarkdownPath) {
      syncTitleFieldsFromNode(activeMediaMarkdownPath);
    }
  }
}

function syncTitleLockForActivePath() {
  syncTitleInputEditableState();
}

function showTitleEditableInput() {
  titleInputNode.classList.remove("hidden");
  titleInputNode.disabled = false;
  titleInputNode.readOnly = false;
  titleFixedValueNode.classList.add("hidden");
  if (titleFixedTextNode) titleFixedTextNode.textContent = "";
  placeTitleFixedInTitleRow();
  showTitleSlugRow();
}

function resetTitleInputState() {
  showTitleEditableInput();
  titleMediaExtNode?.classList.add("hidden");
  if (titleMediaExtNode) titleMediaExtNode.textContent = "";
}

function getMediaFileSlugFromPath(filePath = activeMediaSidecarSourcePath) {
  const normalized = String(filePath || "").replace(/\\/g, "/");
  return normalized.split("/").filter(Boolean).pop() || "";
}

function syncMediaSidecarTitleFields() {
  if (!isMediaSidecarEditing() || !activeMediaSidecarSourcePath || !titleInputNode) return;
  const filePath = activeMediaSidecarSourcePath;
  const slug = getMediaFileSlugFromPath(filePath);
  const rawAwnName = getAwnNameRawForNode(filePath);

  showTitleEditableInput();
  titleMediaExtNode?.classList.add("hidden");
  if (titleMediaExtNode) titleMediaExtNode.textContent = "";

  titleInputNode.value = rawAwnName;
  titleInputNode.readOnly = false;
  titleInputNode.disabled = false;
  titleInputNode.placeholder = slug ? `Пусто → в меню: ${slug}` : "Название";
  if (titleSlugInputNode) {
    titleSlugInputNode.value = slug;
  }
  titleSlugLinked = false;
  applyTitleSlugLinkedUi();
  showTitleSlugRow(filePath);
}

function getMediaSidecarFileName(filePath = activeMediaSidecarSourcePath) {
  return filePath ? (filePath.split("/").pop() || filePath) : "";
}

async function refreshMediaCache() {
  if (!activePath || !isMediaLibraryContentMode()) return;
  const mode = activeContentMode;
  try {
    const response = await fetch(
      buildApiUrl("/api/media", buildMediaLibraryApiParams({ path: getActiveNodeApiPath() }, mode))
    );
    if (!response.ok) return;
    const data = await response.json();
    mediaAssetsExists = Boolean(data.exists);
    modeContentCache[mode] = data.content || "";
    mediaSectionSortOrders =
      data.sectionSortOrders && typeof data.sectionSortOrders === "object" ? data.sectionSortOrders : {};
    syncMediaFilesCache(data.content, data.groups, data.sectionManifests);
    syncMediaViewSelectOptions();
    syncMediaSectionTreeFromCaches();
  } catch {
    // ignore cache refresh errors
  }
}

function closeMediaSidecarEditor() {
  memoryEntryCloseTargetView = null;
  clearMediaSidecarEditor();
  fileContentInputNode.value = "";
  applyModeUi();
  renderListViewContent();
  updateBreadcrumbsForActiveMode();
  syncAppRouteToUrl({ replace: true });
}

async function refreshExternalMemoryCaches() {
  const [filesResponse, listingResponse] = await Promise.all([
    fetch(buildApiUrl("/api/external/files", { path: getActiveNodeApiPath() })),
    fetch(buildApiUrl("/api/external", { path: getActiveNodeApiPath() }))
  ]);

  if (filesResponse.ok) {
    const data = await filesResponse.json();
    externalFilesCache = Array.isArray(data.files) ? data.files : [];
    externalFoldersCache = Array.isArray(data.folders) ? data.folders : [];
    externalSectionSortOrders =
      data.sectionSortOrders && typeof data.sectionSortOrders === "object" ? data.sectionSortOrders : {};
  } else {
    throw new Error(`Request failed with ${filesResponse.status}`);
  }

  await ensureExternalListSchemaReady();

  if (listingResponse.ok) {
    const listingData = await listingResponse.json();
    modeContentCache.external =
      listingData.content || buildExternalListingFallbackContent(externalFilesCache, externalFoldersCache);
    syncExternalSectionTreeFromCaches();
    return Boolean(listingData.exists);
  }

  modeContentCache.external = buildExternalListingFallbackContent(externalFilesCache, externalFoldersCache);
  syncExternalSectionTreeFromCaches();
  return externalFilesCache.length > 0;
}

function closeExternalFileEditor() {
  memoryEntryCloseTargetView = null;
  void refreshExternalFileListView();
}

async function refreshExternalFileListView({ reloadFromServer = true } = {}) {
  if (!activePath || activeContentMode !== "external") return;

  activeExternalFilePath = null;
  setPropsYamlContent("");
  titleInputNode.value = "";
  syncPropsInputPlaceholder();
  editorViewMode = "preview";

  syncAppRouteToUrl({ replace: true });

  if (reloadFromServer) {
    try {
      const exists = await refreshExternalMemoryCaches();
      fileContentInputNode.value = exists ? modeContentCache.external : "Папка не найдена";
    } catch {
      fileContentInputNode.value = modeContentCache.external || "";
    }
  } else {
    fileContentInputNode.value = modeContentCache.external || "";
  }

  updateBreadcrumbsForActiveMode();
  applyModeUi();
  renderListViewContent();
}

function enableMediaSidecarEditor(sourceFilePath, sidecarPath, content, options = {}) {
  if (options.memoryEntryCloseTargetView != null) {
    assignMemoryEntryCloseTargetView(options.memoryEntryCloseTargetView);
  } else if (memoryEntryCloseTargetView == null) {
    assignMemoryEntryCloseTargetView(captureMemoryEntryCloseTargetView());
  }
  activeMediaMarkdownPath = null;
  activeMediaSidecarSourcePath = sourceFilePath;
  activeMediaSidecarPath = sidecarPath;
  updateBreadcrumbsForActiveMode();
  titleEditorBlockNode.classList.remove("hidden");
  applyMediaSidecarContentUi(content || "");
  syncMediaSidecarTitleFields();
  syncPropsInputPlaceholder();
  editorViewMode = "preview";
  applyModeUi();
  setEditorViewMode("preview", { skipRouteSync: true });
  if (!options.skipRouteSync) {
    syncAppRouteToUrl({ push: true });
  }
}

async function openMediaSidecar(mediaFilePath, options = {}) {
  if (!activePath || activeContentMode !== "media" || !mediaFilePath) return;
  const normalizedPath = String(mediaFilePath || "").replace(/\\/g, "/");
  if (mediaSidecarOpenInFlight === normalizedPath) return;
  mediaSidecarOpenInFlight = normalizedPath;
  try {
    const response = await fetch(
      buildApiUrl("/api/media/sidecar", buildTopicMediaSidecarApiParams(mediaFilePath))
    );
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${response.status}`);
    }
    const data = await response.json();
    const content =
      data.exists || String(data.content || "").trim()
        ? data.content || ""
        : buildDefaultMediaSidecarContent(data.sourceFile || mediaFilePath);
    enableMediaSidecarEditor(data.sourceFile, data.sidecar, content, options);
  } catch (error) {
    const details = error?.message ? `: ${error.message}` : "";
    showToast(`Ошибка открытия sidecar${details}`, "error");
  } finally {
    if (mediaSidecarOpenInFlight === normalizedPath) {
      mediaSidecarOpenInFlight = null;
    }
  }
}

function isExternalFileEditing() {
  return activeContentMode === "external" && Boolean(activeExternalFilePath);
}

let propsFormEntries = [];
let propsFormHiddenEntries = [];
let propsRawYamlVisible = false;
let awnTypesCache = null;
let typeCatalogCacheByAgent = new Map();
let typeCatalogLoadPromiseByAgent = new Map();
let agentCatalogsCache = null;

function invalidateTypeCatalogCache(agentId = activeAgentId) {
  const cacheKey = String(agentId || "default");
  typeCatalogCacheByAgent.delete(cacheKey);
  typeCatalogLoadPromiseByAgent.delete(cacheKey);
}

function isAgentSystemRelPath(nodePath) {
  const normalized = normalizeMenuNodePath(nodePath);
  return normalized === AGENT_SYSTEM_ROOT || normalized.startsWith(`${AGENT_SYSTEM_ROOT}/`);
}

function isAgentSystemManifestPath(nodePath) {
  return isAgentSystemRelPath(nodePath) && /(^|\/)manifest\.md$/i.test(normalizeMenuNodePath(nodePath));
}

function isAgentSystemEditableFilePath(nodePath) {
  return isAgentSystemRelPath(nodePath) && !isAgentSystemManifestPath(nodePath);
}

function isAgentSystemFileEditing() {
  return isAgentSystemEditableFilePath(activePath);
}

function agentHasTypeCatalogOverview(nodePath = activePath) {
  if (TYPE_CATALOG_OVERVIEW_AGENT_IDS.has(String(activeAgentId || ""))) return true;
  if (currentMenuData?.systemTree) return true;
  return isAgentSystemRelPath(nodePath);
}

let agentCatalogsLoadPromise = null;
let awnTypesSelectedKey = null;

const STANDARD_PROPS_FIELD_KEYS = [
  "awn-preview",
  "awn-web-url",
  "awn-emoji",
  "awn-name",
  "awn-status",
  "awn-type",
  "awn-create",
  "awn-update",
  "awn-description",
  "awn-main",
  "awn-category",
  "awn-owner",
  "awn-priority",
  "awn-tags",
  "awn-color",
  "awn-version",
  "awn-sort",
  "awn-runtime-load-always",
  "awn-runtime-cron",
  "awn-runtime-cron-schedule",
  "awn-runtime-heartbeat",
  "awn-runtime-commands"
];

function getStandardPropsFieldKeys() {
  // Поля активного типа (запись, тема, область…) — форма зависит от типа узла.
  const typeDef = getActiveAwnTypeDef();
  const typeKeys = typeDef?.fields ? Object.keys(typeDef.fields) : null;
  if (typeKeys && typeKeys.length) return typeKeys;

  const fromApi = awnTypesCache?.baseFieldOrder;
  if (Array.isArray(fromApi) && fromApi.length) return fromApi;
  return STANDARD_PROPS_FIELD_KEYS;
}

