async function loadAwnTypes(agentId = activeAgentId) {
  if (!agentId) {
    awnTypesCache = null;
    agentCatalogsCache = null;
    agentCatalogsLoadPromise = null;
    return null;
  }
  try {
    const response = await fetch(buildApiUrl("/api/awn-types", {}, agentId));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    awnTypesCache = await response.json();
    for (const cache of topicSchemaCacheByManifest.values()) {
      enrichTopicSchemaCacheFromTypes(cache);
    }
    if (getDocAsideTab() === "blocks") renderDocContentBlocks();
    if (shouldRefreshPropsFormFromYaml()) {
      absorbPropsYamlEntries(parsePropsYaml(propsInputNode.value || ""));
      syncYamlFromPropsForm();
      renderPropsForm();
    }
    return awnTypesCache;
  } catch {
    awnTypesCache = null;
    return null;
  }
}

async function loadAgentCatalogs(agentId = activeAgentId) {
  if (!agentId) {
    agentCatalogsCache = null;
    agentCatalogsLoadPromise = null;
    return null;
  }
  if (agentCatalogsLoadPromise) return agentCatalogsLoadPromise;

  agentCatalogsLoadPromise = (async () => {
    try {
      const response = await fetch(buildApiUrl("/api/agent/catalogs", {}, agentId));
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      agentCatalogsCache = await response.json();
      if (getDocAsideTab() === "props" && !propsRawYamlVisible) renderPropsForm();
      return agentCatalogsCache;
    } catch {
      agentCatalogsCache = null;
      return null;
    } finally {
      agentCatalogsLoadPromise = null;
    }
  })();

  return agentCatalogsLoadPromise;
}

const PROPS_FIELD_CATALOG_PRESET = {
  "awn-category": "categories",
  "awn-tags": "tags",
  "awn-status": "statuses",
  "awn-owner": "users",
  "awn-priority": "priorities",
  "awn-color": "colors"
};

function getPropsCatalogAddScopeLabel() {
  return activeAgentId === PLATFORM_AGENT_ID ? "глобальный справочник" : "локальный справочник агента";
}

function applyCatalogItemToPropsEntry(fieldKey, preset, itemId) {
  const normalizedKey = normalizePropsKey(fieldKey);
  const index = propsFormEntries.findIndex((entry) => normalizePropsKey(entry.key) === normalizedKey);
  if (index < 0 || !itemId) return;

  const entry = propsFormEntries[index];
  if (preset === "tags") {
    const current =
      entry.kind === "array" && Array.isArray(entry.value)
        ? entry.value.map((item) => String(item).replace(/^#+/, "").trim()).filter(Boolean)
        : String(entry.value || "")
            .split(",")
            .map((item) => item.trim().replace(/^#+/, ""))
            .filter(Boolean);
    if (!current.includes(itemId)) current.push(itemId);
    propsFormEntries[index] = { ...entry, kind: "array", value: current };
    return;
  }

  propsFormEntries[index] = { ...entry, kind: "string", value: itemId };
}

async function submitPropsCatalogAdd(preset, fieldKey, values = {}) {
  const response = await fetch(buildApiUrl("/api/agent/catalogs/items", {}, activeAgentId), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      preset,
      id: values.id || "",
      label: values.label || "",
      color: values.color || "",
      email: values.email || ""
    })
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || `HTTP ${response.status}`);
  }

  applyCatalogItemToPropsEntry(fieldKey, preset, data.item?.id);
  syncYamlFromPropsForm();
  await loadAgentCatalogs(activeAgentId);
  showToast(`Добавлено в ${getPropsCatalogAddScopeLabel()}: ${data.item?.label || data.item?.id}`, "success");
  return data;
}

function createPropsFormCatalogAddPanel(preset, fieldKey, { locked = false } = {}) {
  const panel = document.createElement("div");
  panel.className = "props-form-catalog-add";
  if (locked) return panel;

  const toggleBtn = document.createElement("button");
  toggleBtn.type = "button";
  toggleBtn.className = "props-form-catalog-add-toggle";
  toggleBtn.textContent = "+ В справочник";
  toggleBtn.title = `Добавить запись в ${getPropsCatalogAddScopeLabel()}`;

  const form = document.createElement("div");
  form.className = "props-form-catalog-add-form hidden";

  const hint = document.createElement("p");
  hint.className = "props-form-catalog-add-hint";
  hint.textContent = `Будет сохранено в ${getPropsCatalogAddScopeLabel()}.`;
  form.appendChild(hint);

  const fields = [];
  if (preset === "tags") {
    fields.push({ name: "label", label: "Новый тег", placeholder: "my-tag" });
  } else if (preset === "colors") {
    fields.push({ name: "label", label: "Название", placeholder: "Blue" });
    fields.push({ name: "color", label: "Hex", placeholder: "#2563eb" });
  } else {
    fields.push({ name: "label", label: "Название", placeholder: "Новая запись" });
  }

  const inputs = {};
  for (const field of fields) {
    const label = document.createElement("label");
    label.className = "props-form-catalog-add-field";
    const caption = document.createElement("span");
    caption.textContent = field.label;
    const input = document.createElement("input");
    input.type = "text";
    input.className = "props-form-value props-form-catalog-add-input";
    input.placeholder = field.placeholder;
    input.dataset.field = field.name;
    inputs[field.name] = input;
    label.append(caption, input);
    form.appendChild(label);
  }

  const actions = document.createElement("div");
  actions.className = "props-form-catalog-add-actions";
  const saveBtn = document.createElement("button");
  saveBtn.type = "button";
  saveBtn.className = "props-form-catalog-add-save";
  saveBtn.textContent = "Добавить";
  const cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "props-form-catalog-add-cancel";
  cancelBtn.textContent = "Отмена";

  const setOpen = (open) => {
    form.classList.toggle("hidden", !open);
    toggleBtn.setAttribute("aria-expanded", open ? "true" : "false");
  };

  toggleBtn.addEventListener("click", () => {
    setOpen(form.classList.contains("hidden"));
  });
  cancelBtn.addEventListener("click", () => {
    setOpen(false);
    for (const input of Object.values(inputs)) input.value = "";
  });
  saveBtn.addEventListener("click", () => {
    void (async () => {
      saveBtn.disabled = true;
      try {
        const values = Object.fromEntries(
          Object.entries(inputs).map(([key, input]) => [key, input.value.trim()])
        );
        await submitPropsCatalogAdd(preset, fieldKey, values);
        for (const input of Object.values(inputs)) input.value = "";
        setOpen(false);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        showToast(message ? `Справочник: ${message}` : "Не удалось добавить", "error");
      } finally {
        saveBtn.disabled = false;
      }
    })();
  });

  actions.append(saveBtn, cancelBtn);
  form.appendChild(actions);
  panel.append(toggleBtn, form);
  return panel;
}

function appendPropsFormCatalogAddControl(wrap, preset, fieldKey, options = {}) {
  if (options.locked) return;
  wrap.appendChild(createPropsFormCatalogAddPanel(preset, fieldKey, options));
}

const TOPIC_SCHEMA_TARGETS = getTopicSchemaTargetSpecs();

const AWN_SCHEMA_TARGET_TYPE_NAMES = Object.fromEntries(
  getTopicSchemaTargetSpecs()
    .filter((item) => item.typeName)
    .map((item) => [item.id, item.typeName])
);
AWN_SCHEMA_TARGET_TYPE_NAMES.sidecar = "awn.sidecar";

function getTopicSchemaTargetLabel(targetId) {
  const configured = getTopicSchemaTargetSpecs().find((item) => item.id === targetId);
  if (configured?.label) return configured.label;
  const typeName = getTopicSchemaTargetTypeName(targetId) || AWN_SCHEMA_TARGET_TYPE_NAMES[targetId];
  const typeDef = typeName ? awnTypesCache?.types?.[typeName] : null;
  if (typeDef?.name) return typeDef.name;
  return targetId;
}

function resolveTopicSchemaBaseType(target, cache = getTopicSchemaCache()) {
  const fromCache = cache?.baseTypes?.[target];
  if (fromCache?.fields && Object.keys(fromCache.fields).length) return fromCache;

  const typeName = getTopicSchemaTargetTypeName(target) || AWN_SCHEMA_TARGET_TYPE_NAMES[target];
  const typeDef = typeName ? awnTypesCache?.types?.[typeName] : null;
  if (!typeDef?.fields) return fromCache || null;

  return {
    name: typeName,
    kind: typeDef.kind || "type",
    fields: { ...typeDef.fields }
  };
}

function resolveTopicSchemaMergedType(target, cache = getTopicSchemaCache()) {
  const fromCache = cache?.merged?.[target];
  const customFields = cache?.awnSchema?.[target]?.fields || {};
  if (fromCache?.fields && Object.keys(fromCache.fields).length) {
    return fromCache;
  }

  const base = resolveTopicSchemaBaseType(target, cache);
  if (!base) return fromCache || null;

  return {
    ...base,
    fields: { ...base.fields, ...customFields }
  };
}

function enrichTopicSchemaCacheFromTypes(cache) {
  if (!cache || !awnTypesCache?.types) return cache;
  cache.baseTypes = { ...(cache.baseTypes || {}) };
  cache.merged = { ...(cache.merged || {}) };
  const targets = [...getTopicSchemaTargetSpecs(), { id: "sidecar" }];
  for (const { id } of targets) {
    const base = resolveTopicSchemaBaseType(id, cache);
    if (base) cache.baseTypes[id] = base;
    const merged = resolveTopicSchemaMergedType(id, cache);
    if (merged) cache.merged[id] = merged;
  }
  return cache;
}

const topicSchemaCacheByManifest = new Map();
let topicSchemaActiveTarget = "topic";
const topicSchemaExpandedKeys = new Set();

function getTopicSchemaExpandedKey(target, key) {
  return `${target}:${key}`;
}

function isTopicSchemaFieldExpanded(target, key) {
  return topicSchemaExpandedKeys.has(getTopicSchemaExpandedKey(target, key));
}

function setTopicSchemaFieldExpanded(target, key, expanded) {
  const token = getTopicSchemaExpandedKey(target, key);
  if (expanded) topicSchemaExpandedKeys.add(token);
  else topicSchemaExpandedKeys.delete(token);
}

function toggleTopicSchemaFieldExpanded(target, key) {
  const token = getTopicSchemaExpandedKey(target, key);
  if (topicSchemaExpandedKeys.has(token)) {
    topicSchemaExpandedKeys.delete(token);
    return false;
  }
  topicSchemaExpandedKeys.add(token);
  return true;
}

function emptyTopicSchemaState() {
  const result = {};
  for (const { id } of getTopicSchemaTargetSpecs()) {
    result[id] = { fields: {} };
  }
  result.sidecar = { fields: {} };
  return result;
}

function migrateLegacyTopicSchemaTargets(source, result) {
  for (const [legacyId, modernId] of TOPIC_SCHEMA_LEGACY_TARGET_MIGRATIONS) {
    const legacyFields = source?.[legacyId]?.fields;
    if (!legacyFields || typeof legacyFields !== "object") continue;
    if (!result[modernId]) result[modernId] = { fields: {} };
    if (!Object.keys(result[modernId].fields).length) {
      result[modernId].fields = { ...legacyFields };
    }
  }
  const legacySidecarFields = source?.sidecar?.fields;
  if (legacySidecarFields && typeof legacySidecarFields === "object") {
    if (!result.slot_media) result.slot_media = { fields: {} };
    if (!Object.keys(result.slot_media.fields).length) {
      result.slot_media.fields = { ...legacySidecarFields };
    }
  }
}

function normalizeTopicSchemaState(raw) {
  const result = emptyTopicSchemaState();
  if (!raw || typeof raw !== "object") return result;
  const source = { ...raw };
  if (source.file && !source.topic) {
    source.topic = source.file;
  }
  for (const { id } of getTopicSchemaTargetSpecs()) {
    const block = source[id];
    if (block?.fields && typeof block.fields === "object") {
      result[id].fields = { ...block.fields };
    }
  }
  if (source.sidecar?.fields && typeof source.sidecar.fields === "object") {
    result.sidecar.fields = { ...source.sidecar.fields };
  }
  migrateLegacyTopicSchemaTargets(source, result);
  if (result.settings?.fields) {
    result.settings.fields = ExternalFileMask.stripBuiltinSettingsSchemaFields(result.settings.fields);
  }
  return result;
}

function mergeTopicSchemaSettingsFields(fields = {}) {
  return ExternalFileMask.mergeBuiltinSettingsSchemaFields(fields);
}

function getAwnMaskFileValueFromSettingsCache(cache = getNodeSettingsCache()) {
  const entry = (cache?.entries || []).find((item) => item.key === ExternalFileMask.AWN_MASK_FILE_KEY);
  return ExternalFileMask.normalizeMaskValue(entry?.value ?? "");
}

function resolveTopicManifestFromBundlePath(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  const storageMarker = `/${STORAGE_ROOT_FOLDER}/`;
  const storageIdx = normalized.toLowerCase().indexOf(storageMarker.toLowerCase());
  if (storageIdx >= 0) {
    const prefix = normalized.slice(0, storageIdx).replace(/\/$/, "");
    return prefix ? `${prefix}/${MANIFEST_FILE}` : MANIFEST_FILE;
  }
  const match = normalized.match(new RegExp(`^(.*)/${STORAGE_SLOT_REGEX}(?:/|$)`));
  if (!match) return null;
  const prefix = match[1] || "";
  const slotKey = match[2];
  if (!slotKey) return null;
  const areaSlotKey = AREA_MANIFEST_FILE.replace(/\.md$/i, "");
  if (slotKey.toLowerCase() === areaSlotKey.toLowerCase()) {
    const manifest = prefix ? `${prefix}/${AREA_MANIFEST_FILE}` : AREA_MANIFEST_FILE;
    return isAreaManifestFileName(AREA_MANIFEST_FILE) ? manifest : null;
  }
  const manifest = prefix ? `${prefix}/${slotKey}.md` : `${slotKey}.md`;
  return isTopicManifestPath(manifest) ? manifest : null;
}

const NODE_CONFIG_RESERVED_KEYS = new Set([
  "awn_schema",
  "awn_ui",
  "awn_settings",
  "default_landing_mode"
]);

const NODE_CONFIG_VALUE_TYPES = [
  { id: "string", label: "Текст", icon: "🔤" },
  { id: "number", label: "Число", icon: "📊" },
  { id: "bool", label: "Да/нет", icon: "☑️" },
  { id: "null", label: "Пусто", icon: "⚪" },
  { id: "array", label: "Список", icon: "📚" }
];

const nodeSettingsCacheByManifest = new Map();

function getNodeConfigValueTypeLabel(kind) {
  const match = NODE_CONFIG_VALUE_TYPES.find((item) => item.id === kind);
  if (!match) return kind;
  return match.icon ? `${match.icon} ${match.label}` : match.label;
}

function extractConfigHeaderComment(content) {
  const lines = String(content || "").replace(/^\uFEFF/, "").split(/\r?\n/);
  const comments = [];
  for (const line of lines) {
    if (!line.trim()) break;
    if (line.trim().startsWith("#")) comments.push(line);
    else break;
  }
  return comments.join("\n");
}

function extractAwnSchemaYamlFromConfig(content) {
  return NodeConfigBundle.extractSectionYamlText(content, "awn_schema");
}

function getNodeSettingsFieldMeta(key, fieldDef) {
  return {
    label: getFieldDefDisplayName(fieldDef, key),
    hint: String(fieldDef?.hint || fieldDef?.description || "").trim(),
    required: Boolean(fieldDef?.required),
    format: fieldDef?.format || "",
    fieldDef
  };
}

function normalizeNodeSettingsEntryValue(entry, fieldDef) {
  if (!fieldDef) return entry;
  let next = { ...entry, kind: fieldDefToEntryKind(fieldDef), fieldDef };
  if (next.kind === "string" && Array.isArray(next.value)) {
    next = { ...next, value: ExternalFileMask.normalizeMaskValue(next.value) };
  } else if (next.kind === "string" && next.value != null && typeof next.value !== "string") {
    next = { ...next, value: String(next.value) };
  }
  if (!Array.isArray(fieldDef.enum) || !fieldDef.enum.length) return next;

  const api = awnEnumOptionsApi();
  if (isArrayFieldTypeId(fieldDef.type)) {
    const source = Array.isArray(next.value)
      ? next.value
      : String(getPropsEntryDisplayValue(next) || "")
          .split(",")
          .map((item) => item.trim())
          .filter(Boolean);
    const nextValue =
      typeof api.normalizeArrayStoredKeys === "function"
        ? api.normalizeArrayStoredKeys(source, fieldDef.enum)
        : source;
    return { ...next, kind: "array", value: nextValue };
  }

  const raw = Array.isArray(next.value) ? getPropsEntryDisplayValue(next) : String(next.value ?? "");
  const normalized = normalizeEnumDisplayValue(raw, fieldDef.enum);
  if (normalized !== raw) {
    return { ...next, kind: "string", value: normalized };
  }
  return next;
}

function buildNodeSettingsEntriesFromSchema(storedEntries, schemaFields) {
  const map = new Map((storedEntries || []).map((entry) => [entry.key, entry]));
  const result = [];
  for (const [key, fieldDef] of Object.entries(schemaFields || {})) {
    if (!key || !fieldDef || typeof fieldDef !== "object") continue;
    const existing = map.get(key);
    const base = existing
      ? normalizeNodeSettingsEntryValue(existing, fieldDef)
      : {
          key,
          kind: fieldDefToEntryKind(fieldDef),
          value: fieldDefDefaultValue(fieldDef),
          fieldDef
        };
    result.push({ ...base, key, fieldDef });
  }
  return result;
}

function mergeNodeSettingsEntriesWithSchema(entries, schemaFields) {
  return buildNodeSettingsEntriesFromSchema(entries, schemaFields);
}

function parseNodeSettingsState(content) {
  const bundle = NodeConfigBundle.parseNodeConfigBundle(content);
  const headerComment = bundle.headerComment || extractConfigHeaderComment(content);
  const mode = bundle.awn_ui?.default_landing_mode;
  return {
    headerComment: headerComment || NODE_CONFIG_HEADER.trim(),
    entries: NodeConfigBundle.settingsObjectToEntries(bundle.awn_settings),
    defaultLandingMode: mode && isValidNodeDefaultLandingMode(mode) ? mode : null,
    awnSchemaYaml: extractAwnSchemaYamlFromConfig(content)
  };
}

function buildNodeConfigYamlFromState(state) {
  return NodeConfigBundle.composeNodeConfigBundle({
    headerComment: state?.headerComment,
    awn_ui: state?.defaultLandingMode ? { default_landing_mode: state.defaultLandingMode } : {},
    awn_settings: NodeConfigBundle.settingsEntriesToObject(state?.entries || []),
    awn_schemaYaml: state?.awnSchemaYaml || ""
  });
}

function getNodeSettingsManifestPath(nodePath = getResolvedNodePath(activePath)) {
  const normalized = String(nodePath || "").replace(/\\/g, "/").trim();
  if (!normalized || !isNodeMdPath(normalized)) return "";
  return normalized;
}

function isNodeSettingsModeAvailable(nodePath = getResolvedNodePath(activePath)) {
  return Boolean(getNodeSettingsManifestPath(nodePath));
}

function getNodeSettingsCache(manifestPath = getNodeSettingsManifestPath()) {
  if (!manifestPath) return null;
  return nodeSettingsCacheByManifest.get(manifestPath) || null;
}

function getNodeSettingsSavePayload() {
  const cache = getNodeSettingsCache();
  if (!cache) return null;
  return {
    entries: cache.entries || [],
    headerComment: cache.headerComment || "",
    defaultLandingMode: cache.defaultLandingMode || null,
    awnSchemaYaml: cache.awnSchemaYaml || ""
  };
}

async function loadNodeSettingsForManifest(nodePath, options = {}) {
  const manifestPath = getNodeSettingsManifestPath(nodePath);
  if (!manifestPath) return null;

  if (!options.force) {
    const cached = nodeSettingsCacheByManifest.get(manifestPath);
    if (cached) return cached;
  }

  const data = await loadNodeConfig(manifestPath, { force: true });
  const state = parseNodeSettingsState(data.content || "");
  let settingsFields = {};
  try {
    const schemaCache = await loadTopicSchemaForManifest(manifestPath, { force: options.force });
    settingsFields = mergeTopicSchemaSettingsFields(schemaCache?.awnSchema?.settings?.fields || {});
    state.entries = buildNodeSettingsEntriesFromSchema(state.entries, settingsFields);
  } catch {
    state.entries = buildNodeSettingsEntriesFromSchema(state.entries, {});
  }
  const payload = {
    manifestPath,
    configPath: data.path || "",
    exists: Boolean(data.exists),
    settingsFields,
    ...state
  };
  nodeSettingsCacheByManifest.set(manifestPath, payload);
  return payload;
}

function formatNodeSettingsFieldLabel(key, fieldDef) {
  const displayName = getFieldDefDisplayName(fieldDef, key);
  if (displayName && displayName !== key) return displayName;
  const suffix = String(key || "")
    .replace(/^field_/i, "")
    .replace(/[_-]+/g, " ")
    .trim();
  if (suffix && /^field_/i.test(key)) return `Поле ${suffix}`;
  return displayName || key || "Поле";
}

function createNodeSettingsFieldRow(entry, fieldDef) {
  const meta = getNodeSettingsFieldMeta(entry.key, fieldDef);
  const typeId = resolveFieldTypeId(fieldDef?.type || "awn.string");
  const displayLabel = formatNodeSettingsFieldLabel(entry.key, fieldDef);
  const entryKind = fieldDefToEntryKind(fieldDef);

  const row = document.createElement("div");
  row.className = "node-config-field-row node-config-field-row--compact";
  if (entryKind === "array" || typeId === "awn.file" || typeId === "awn.text") {
    row.classList.add("is-tall");
  }
  row.dataset.configRowKey = entry.key;

  const head = document.createElement("div");
  head.className = "node-config-field-head";

  const label = buildFieldLabelElement(displayLabel, {
    tag: "label",
    className: "node-config-field-label",
    typeId,
    key: entry.key,
    required: meta.required,
    title: meta.hint
      ? `${entry.key} — ${meta.hint}`
      : fieldDef?.description
        ? `${entry.key} — ${fieldDef.description}`
        : entry.key
  });

  const keyCode = document.createElement("code");
  keyCode.className = "node-config-field-key";
  keyCode.textContent = entry.key;
  keyCode.title = "Ключ в awn_settings";

  const labelWrap = document.createElement("div");
  labelWrap.className = "node-config-field-label-wrap";
  labelWrap.append(label, keyCode);
  head.append(labelWrap);

  const valueControl = createPropsFormValueControl(entry, meta);
  valueControl.classList.add("node-config-field-value");

  row.append(head, valueControl);
  return row;
}

function readNodeSettingsEntryFromRow(row) {
  const key = row?.dataset?.configRowKey || "";
  const cache = getNodeSettingsCache();
  const fieldDef = cache?.settingsFields?.[key];
  const base =
    (cache?.entries || []).find((entry) => entry.key === key) ||
    (fieldDef
      ? { key, kind: fieldDefToEntryKind(fieldDef), value: fieldDefDefaultValue(fieldDef), fieldDef }
      : { key, kind: "string", value: "" });
  const valueWrap = row?.querySelector('.props-form-value-wrap[data-field="value"]');
  if (!valueWrap) return { ...base, key };
  const entry = fieldDef
    ? { ...base, kind: fieldDefToEntryKind(fieldDef), fieldDef }
    : { ...base };
  return applyFormValueToEntry(entry, readPropsFormValueFromControl(valueWrap));
}

function syncNodeSettingsCacheFromDom(cache = getNodeSettingsCache()) {
  if (!cache || !nodeConfigFieldsNode) return cache;
  const schemaFields = cache.settingsFields || {};
  const entries = [];
  nodeConfigFieldsNode.querySelectorAll(".node-config-field-row").forEach((row) => {
    const entry = readNodeSettingsEntryFromRow(row);
    if (!entry.key || !schemaFields[entry.key]) return;
    entries.push(entry);
  });
  cache.entries = buildNodeSettingsEntriesFromSchema(entries, schemaFields);
  return cache;
}

function renderNodeSettingsEditor(cache = getNodeSettingsCache()) {
  if (!nodeConfigFieldsNode || !nodeConfigEmptyNode) return;

  nodeConfigFieldsNode.replaceChildren();

  const schemaFields = cache?.settingsFields || {};
  const schemaKeys = Object.keys(schemaFields);
  if (!schemaKeys.length) {
    nodeConfigEmptyNode.classList.remove("hidden");
    nodeConfigEmptyNode.textContent =
      "Полей пока нет — добавьте их во вкладке «Настройки» в редакторе схемы полей.";
    return;
  }

  const entries = buildNodeSettingsEntriesFromSchema(cache?.entries || [], schemaFields);
  cache.entries = entries;

  if (!entries.length) {
    nodeConfigEmptyNode.classList.remove("hidden");
    return;
  }
  nodeConfigEmptyNode.classList.add("hidden");

  for (const entry of entries) {
    nodeConfigFieldsNode.append(createNodeSettingsFieldRow(entry, schemaFields[entry.key]));
  }
}

function handleNodeConfigFieldsInput() {
  if (activeContentMode !== "configs") return;
  syncNodeSettingsCacheFromDom();
  syncSaveButtonLamp();
}

async function saveNodeSettingsContent() {
  const manifestPath = getNodeSettingsManifestPath();
  if (!manifestPath) throw new Error("Конфигурация доступна только для тем с bundle");
  const cache = syncNodeSettingsCacheFromDom();
  if (!cache) throw new Error("Конфигурация не загружена");

  const content = buildNodeConfigYamlFromState(cache);
  const response = await fetch(buildApiUrl("/api/file/node-config"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ path: manifestPath, content })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const reason = errorData.error || `Request failed with ${response.status}`;
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${reason}${details}`);
  }

  const data = await response.json();
  cache.exists = Boolean(data.exists);
  cache.configPath = data.path || cache.configPath;
  const nextState = parseNodeSettingsState(data.content || content);
  cache.headerComment = nextState.headerComment;
  cache.entries = buildNodeSettingsEntriesFromSchema(
    nextState.entries,
    cache.settingsFields || {}
  );
  cache.defaultLandingMode = nextState.defaultLandingMode;
  cache.awnSchemaYaml = nextState.awnSchemaYaml;
  setCachedNodeConfig(manifestPath, {
    path: data.path || cache.configPath,
    content: data.content || content,
    exists: Boolean(data.exists),
    defaultLandingMode: nextState.defaultLandingMode
  });
  modeContentCache.configs = data.content || content;
  syncNodeDefaultLandingBtn();
  renderNodeSettingsEditor(cache);
  return data;
}

function getTopicSchemaManifestPath(nodePath = getResolvedNodePath(activePath)) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (isAgentRootIndexPath(normalized)) return normalized;
  if (isAreaNodePath(normalized)) return normalized;
  if (isTopicManifestPath(normalized)) return normalized;
  return resolveTopicManifestFromBundlePath(normalized);
}

function isTopicSchemaModeAvailable(nodePath = getResolvedNodePath(activePath)) {
  return Boolean(getTopicSchemaManifestPath(nodePath));
}

function resolveSchemaSlotKeyForContext() {
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE) {
    return getDataStorageSlotKeyForEntryView(NODE_ENTRY_OVERVIEW_MODE);
  }
  return getDataStorageSlotForMode()?.key || null;
}

function resolveAwnSchemaTargetForType(typeName, slotKey = null) {
  const resolvedSlotKey = slotKey || resolveSchemaSlotKeyForContext();
  if (resolvedSlotKey && typeof TopicSchemaSlotSpecs !== "undefined") {
    const bySlot = TopicSchemaSlotSpecs.resolveTopicSchemaTargetIdForAwnType(resolvedSlotKey, typeName);
    if (bySlot) return bySlot;
  }
  const normalized =
    typeof TopicSchemaSlotSpecs !== "undefined"
      ? TopicSchemaSlotSpecs.normalizeAwnContentTypeName(typeName)
      : typeName;
  if (normalized === "awn.content.record.category" || typeName === "awn.media.category") {
    return resolvedSlotKey === "media" ? "slot_media_category" : "slot_memory_category";
  }
  if (normalized === "awn.content.record" || typeName === "awn.record") {
    return resolvedSlotKey === "media" ? "slot_media_record" : "slot_memory";
  }
  if (normalized === "awn.content.sidecar" || typeName === "awn.sidecar") {
    if (resolvedSlotKey === "media") return "slot_media";
    if (resolvedSlotKey && typeof TopicSchemaSlotSpecs !== "undefined") {
      return TopicSchemaSlotSpecs.resolveTopicSchemaTargetId(resolvedSlotKey, { contentKind: "sidecar" });
    }
  }
  return "topic";
}

function resolveAwnSchemaTargetForContext(nodePath = getResolvedNodePath(activePath)) {
  const typeName = resolveAwnTypeForContext(nodePath);
  const slotKey = resolveSchemaSlotKeyForContext();
  if (slotKey && typeof TopicSchemaSlotSpecs !== "undefined") {
    const bySlot = TopicSchemaSlotSpecs.resolveTopicSchemaTargetIdForAwnType(slotKey, typeName);
    if (bySlot) return bySlot;
  }
  if (typeName === "awn.media.category") return "slot_media_category";
  if (typeName === "awn.record.category" || typeName === "awn.content.record.category") {
    return slotKey === "media" ? "slot_media_category" : "slot_memory_category";
  }
  if (slotKey) {
    if (typeName === "awn.sidecar" && slotKey === "media") return "slot_media";
    if (typeName === "awn.file" && slotKey === "repository") return "slot_repository";
    if (typeName === "awn.record" || typeName === "awn.content.record") {
      const slotTarget = resolveStorageSlotSchemaTargetId(slotKey);
      if (slotTarget) return slotTarget;
    }
  }
  return resolveAwnSchemaTargetForType(typeName, slotKey);
}

function getTopicSchemaCacheKey(manifestPath, contentPath = "") {
  const manifest = String(manifestPath || "").replace(/\\/g, "/");
  const content = String(contentPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  return content ? `${manifest}\0${content}` : manifest;
}

function getSchemaContentPathForContext(nodePath = activePath) {
  const ctx = getPropsContextPath(nodePath);
  const normalized = String(ctx || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return "";
  if (/\/awn-storage\/[^/]+\/.+/i.test(normalized)) return normalized;
  return "";
}

function getTopicSchemaCache(manifestPath = getTopicSchemaManifestPath(), contentPath = "") {
  const schemaContentPath = contentPath || getSchemaContentPathForContext();
  const cacheKey = getTopicSchemaCacheKey(manifestPath, schemaContentPath);
  if (!cacheKey) return null;
  return topicSchemaCacheByManifest.get(cacheKey) || null;
}

function getTopicSchemaSavePayload() {
  const cache = getTopicSchemaCache();
  return cache ? normalizeTopicSchemaState(cache.awnSchema) : null;
}

async function loadWorkspaceSchemaForAgentRoot(nodePath, options = {}) {
  const manifestPath = String(nodePath || "").replace(/\\/g, "/");
  const cacheKey = getTopicSchemaCacheKey(manifestPath, "");

  if (!options.force) {
    const cached = topicSchemaCacheByManifest.get(cacheKey);
    if (cached) return cached;
  }

  const response = await fetch(buildApiUrl("/api/file/workspace-schema", { path: manifestPath }));
  if (!response.ok) throw new Error(`Request failed with ${response.status}`);
  const data = await response.json();
  if (!awnTypesCache?.types) {
    await loadAwnTypes(activeAgentId);
  }
  let fieldRegistry = data.fieldRegistry || awnTypesCache?.fieldRegistry || {};
  const canonicalFieldTypes = Object.keys(fieldRegistry).filter((id) => id.startsWith("awn.")).length;
  if (canonicalFieldTypes < 2) {
    await loadAwnTypes(activeAgentId);
    fieldRegistry = awnTypesCache?.fieldRegistry || fieldRegistry;
  }
  const workspaceAwnSchema = normalizeTopicSchemaState(data.workspaceAwnSchema || data.awnSchema);
  const payload = {
    manifestPath,
    contentPath: "",
    configPath: data.schemaPath || "configuration-schema.yml",
    configExists: Boolean(data.schemaExists),
    schemaPath: data.schemaPath || "configuration-schema.yml",
    schemaExists: Boolean(data.schemaExists),
    isWorkspaceSchema: true,
    awnSchema: workspaceAwnSchema,
    workspaceAwnSchema,
    topicAwnSchema: emptyTopicSchemaState(),
    sectionAwnSchema: null,
    sectionChain: [],
    baseTypes: data.baseTypes || {},
    merged: data.merged || {},
    fieldRegistry
  };
  enrichTopicSchemaCacheFromTypes(payload);
  topicSchemaCacheByManifest.set(cacheKey, payload);
  return payload;
}

async function loadTopicSchemaForManifest(nodePath, options = {}) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (isWorkspaceSchemaContext(normalized)) {
    return loadWorkspaceSchemaForAgentRoot(normalized, options);
  }

  const manifestPath =
    (isTopicManifestPath(normalized) || isNodeManifestPath(normalized) ? normalized : null) ||
    getTopicSchemaManifestPath(nodePath) ||
    resolveTopicManifestFromBundlePath(normalized);
  if (!manifestPath) return null;

  const contentPath = (() => {
    if (options.contentPath !== undefined) {
      return String(options.contentPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
    }
    if (options.topicOnly === true || activeContentMode === "topic-schema") return "";
    return getSchemaContentPathForContext(nodePath);
  })();
  const cacheKey = getTopicSchemaCacheKey(manifestPath, contentPath);

  if (!options.force) {
    const cached = topicSchemaCacheByManifest.get(cacheKey);
    if (cached) return cached;
  }

  const query = { path: manifestPath };
  if (contentPath) query.contentPath = contentPath;
  const response = await fetch(buildApiUrl("/api/file/topic-schema", query));
  if (!response.ok) throw new Error(`Request failed with ${response.status}`);
  const data = await response.json();
  if (!awnTypesCache?.types) {
    await loadAwnTypes(activeAgentId);
  }
  let fieldRegistry = data.fieldRegistry || awnTypesCache?.fieldRegistry || {};
  const canonicalFieldTypes = Object.keys(fieldRegistry).filter((id) => id.startsWith("awn.")).length;
  if (canonicalFieldTypes < 2) {
    await loadAwnTypes(activeAgentId);
    fieldRegistry = awnTypesCache?.fieldRegistry || fieldRegistry;
  }
  const topicAwnSchema = normalizeTopicSchemaState(
    isAreaSchemaContext(manifestPath)
      ? emptyTopicSchemaState()
      : data.topicAwnSchema ?? emptyTopicSchemaState()
  );
  const areaAwnSchema = normalizeTopicSchemaState(
    isAreaSchemaContext(manifestPath)
      ? data.areaAwnSchema ?? data.topicAwnSchema ?? emptyTopicSchemaState()
      : data.areaAwnSchema ?? emptyTopicSchemaState()
  );
  const editableSchema = isAreaSchemaContext(manifestPath) ? areaAwnSchema : topicAwnSchema;
  const effectiveAwnSchema = normalizeTopicSchemaState(data.awnSchema);
  const payload = {
    manifestPath,
    contentPath: contentPath || "",
    configPath: data.configPath || "",
    configExists: Boolean(data.configExists),
    awnSchema: editableSchema,
    effectiveAwnSchema,
    topicAwnSchema,
    areaAwnSchema,
    workspaceAwnSchema: normalizeTopicSchemaState(data.workspaceAwnSchema ?? emptyTopicSchemaState()),
    sectionAwnSchema: data.sectionAwnSchema ? normalizeTopicSchemaState(data.sectionAwnSchema) : null,
    sectionChain: Array.isArray(data.sectionChain) ? data.sectionChain : [],
    baseTypes: data.baseTypes || {},
    merged: data.merged || {},
    fieldRegistry
  };
  enrichTopicSchemaCacheFromTypes(payload);
  topicSchemaCacheByManifest.set(cacheKey, payload);
  return payload;
}

function getTopicSchemaRegistryEntries(cache = getTopicSchemaCache()) {
  const registry = cache?.fieldRegistry || awnTypesCache?.fieldRegistry || {};
  return Object.entries(registry)
    .filter(([id]) => id.startsWith("awn."))
    .map(([id, def]) => ({ id, name: def?.name || def?.label || id }))
    .sort((a, b) => a.name.localeCompare(b.name, "ru"));
}

const FIELD_TYPE_SELECT_GROUPS = [
  { label: "Текст", types: ["awn.string", "awn.text", "awn.url"] },
  { label: "Числа", types: ["awn.integer", "awn.number"] },
  { label: "Дата и время", types: ["awn.date", "awn.datetime"] },
  {
    label: "Выбор значений",
    types: ["awn.boolean", "awn.enum", "awn.array"]
  },
  { label: "Связи и файлы", types: ["awn.link", "awn.file"] },
  { label: "Другое", types: ["awn.color", "awn.null"] }
];

function getFieldTypeSelectGroups(registryEntries = []) {
  const byId = new Map(registryEntries.map((entry) => [entry.id, entry]));
  const used = new Set();
  const groups = [];

  for (const spec of FIELD_TYPE_SELECT_GROUPS) {
    const entries = [];
    for (const typeId of spec.types) {
      const resolved = resolveFieldTypeId(typeId);
      if (!byId.has(resolved) || used.has(resolved)) continue;
      entries.push(byId.get(resolved));
      used.add(resolved);
    }
    if (entries.length) groups.push({ label: spec.label, entries });
  }

  const rest = registryEntries.filter((entry) => !used.has(entry.id));
  if (rest.length) groups.push({ label: "Другие", entries: rest });

  return groups;
}

function populateFieldTypeSelect(select, registryEntries, selectedTypeId = "awn.string") {
  if (!select) return;
  select.replaceChildren();

  for (const group of getFieldTypeSelectGroups(registryEntries)) {
    const optgroup = document.createElement("optgroup");
    optgroup.label = group.label;
    for (const entry of group.entries) {
      const option = document.createElement("option");
      option.value = entry.id;
      option.textContent = getFieldTypeOptionLabel(entry.id, entry.name);
      optgroup.appendChild(option);
    }
    select.appendChild(optgroup);
  }

  const resolved = resolveFieldTypeId(selectedTypeId || "awn.string");
  select.value = resolved;
  if (select.value !== resolved && resolved) {
    const legacy = document.createElement("option");
    legacy.value = resolved;
    legacy.textContent = getFieldTypeOptionLabel(resolved, resolved);
    legacy.selected = true;
    select.prepend(legacy);
  }
}

function getTopicSchemaCustomFieldKeys(target = topicSchemaActiveTarget, cache = getTopicSchemaCache()) {
  if (!cache) return [];
  const keys = Object.keys(cache.awnSchema?.[target]?.fields || {});
  if (target !== "settings") return keys;
  return keys.filter((key) => !ExternalFileMask.isBuiltinSettingsSchemaKey(key));
}

function topicSchemaTargetHasCustomFields(targetId, cache = getTopicSchemaCache()) {
  return getTopicSchemaCustomFieldKeys(targetId, cache).length > 0;
}

function topicSchemaFieldHasAdvancedSettings(fieldDef) {
  if (!fieldDef || typeof fieldDef !== "object") return false;
  const typeId = resolveFieldTypeId(fieldDef.type || "awn.string");
  const allowedSettings = new Set(["type", "title", "name", ...getFieldTypeSettingsKeys(typeId)]);
  for (const [propKey, value] of Object.entries(fieldDef)) {
    if (!allowedSettings.has(propKey)) continue;
    if (shouldPersistFieldDefSetting(propKey, value, fieldDef)) return true;
  }
  return false;
}

function topicSchemaSlotHasCustomFields(slot, cache = getTopicSchemaCache()) {
  return (slot?.tabs || []).some((tab) => topicSchemaTargetHasCustomFields(tab.id, cache));
}

function topicSchemaTabGroupHasCustomFields(group, cache = getTopicSchemaCache()) {
  if (group?.coreTabs?.length) {
    return group.coreTabs.some((tab) => topicSchemaTargetHasCustomFields(tab.id, cache));
  }
  if (group?.slots?.length) {
    return group.slots.some((slot) => topicSchemaSlotHasCustomFields(slot, cache));
  }
  return false;
}

function addTopicSchemaField(target = topicSchemaActiveTarget) {
  const cache = getTopicSchemaCache();
  if (!cache) return;
  if (!cache.awnSchema[target]) cache.awnSchema[target] = { fields: {} };
  const fields = cache.awnSchema[target].fields;
  let index = 1;
  let key = isWorkspaceSchemaContext()
    ? `ws-field_${index}`
    : isAreaSchemaContext()
      ? `area-field_${index}`
      : `field_${index}`;
  while (fields[key]) {
    index += 1;
    key = isWorkspaceSchemaContext()
      ? `ws-field_${index}`
      : isAreaSchemaContext()
        ? `area-field_${index}`
        : `field_${index}`;
  }
  fields[key] = { type: "awn.string", name: "", title: "" };
  renderTopicSchemaEditor();
  syncSaveButtonLamp();
  const keyInput = topicSchemaFieldsNode?.querySelector(`[data-schema-key="${CSS.escape(key)}"]`);
  keyInput?.focus();
  keyInput?.select();
}

function removeTopicSchemaField(target, key) {
  if (target === "settings" && ExternalFileMask.isBuiltinSettingsSchemaKey(key)) return;
  const cache = getTopicSchemaCache();
  if (!cache?.awnSchema?.[target]?.fields) return;
  delete cache.awnSchema[target].fields[key];
  setTopicSchemaFieldExpanded(target, key, false);
  renderTopicSchemaEditor();
  syncSaveButtonLamp();
}

function reorderTopicSchemaFields(target, key, direction) {
  const cache = getTopicSchemaCache();
  if (!cache?.awnSchema?.[target]?.fields) return;
  const fields = cache.awnSchema[target].fields;
  const keys = Object.keys(fields);
  const index = keys.indexOf(key);
  if (index < 0) return;
  const nextIndex = direction === "up" ? index - 1 : index + 1;
  if (nextIndex < 0 || nextIndex >= keys.length) return;
  keys.splice(index, 1);
  keys.splice(nextIndex, 0, key);
  const reordered = {};
  for (const fieldKey of keys) {
    reordered[fieldKey] = fields[fieldKey];
  }
  cache.awnSchema[target].fields = reordered;
  renderTopicSchemaEditor();
  syncSaveButtonLamp();
}

function renameTopicSchemaField(target, oldKey, newKey) {
  if (target === "settings" && ExternalFileMask.isBuiltinSettingsSchemaKey(oldKey)) return;
  const cache = getTopicSchemaCache();
  if (!cache?.awnSchema?.[target]?.fields || oldKey === newKey) return;
  const fields = cache.awnSchema[target].fields;
  let trimmed = String(newKey || "").trim();
  if (isWorkspaceSchemaContext() && target === "workspace") {
    trimmed = normalizeWorkspaceSchemaFieldKey(trimmed);
  } else if (isAreaSchemaContext() && target === "area") {
    trimmed = normalizeAreaSchemaFieldKey(trimmed);
  }
  if (!trimmed || (trimmed !== oldKey && fields[trimmed])) return;
  fields[trimmed] = fields[oldKey];
  delete fields[oldKey];
  if (isTopicSchemaFieldExpanded(target, oldKey)) {
    setTopicSchemaFieldExpanded(target, oldKey, false);
    setTopicSchemaFieldExpanded(target, trimmed, true);
  }
}

function createTopicSchemaTargetTabButton(spec, cache = getTopicSchemaCache()) {
  const { id, group, slotKey, contentKind, label, fullLabel, isDefault } = spec;
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "topic-schema-target-tab";
  if (group === "core" || group === "settings") btn.classList.add("topic-schema-target-tab--core");
  if (group === "slot") btn.classList.add("topic-schema-target-tab--slot");
  if (group === "slot-meta") btn.classList.add("topic-schema-target-tab--slot-meta");
  if (group === "slot-sidecar") btn.classList.add("topic-schema-target-tab--slot-sidecar");
  if (isDefault) btn.classList.add("topic-schema-target-tab--default");
  if (slotKey) btn.dataset.slotKey = slotKey;
  if (contentKind) btn.dataset.contentKind = contentKind;
  btn.dataset.target = id;
  btn.setAttribute("role", "tab");
  btn.setAttribute("aria-selected", id === topicSchemaActiveTarget ? "true" : "false");
  btn.classList.toggle("is-active", id === topicSchemaActiveTarget);
  const configured = topicSchemaTargetHasCustomFields(id, cache);
  btn.classList.toggle("is-configured", configured);
  const typeName = getTopicSchemaTargetTypeName(id) || AWN_SCHEMA_TARGET_TYPE_NAMES[id];
  const tabLabel = label || getTopicSchemaTargetLabel(id);
  btn.replaceChildren();
  if (configured) {
    const mark = document.createElement("span");
    mark.className = "topic-schema-target-tab-mark";
    mark.setAttribute("aria-hidden", "true");
    btn.appendChild(mark);
  }
  const labelNode = document.createElement("span");
  labelNode.className = "topic-schema-target-tab-label";
  labelNode.textContent = tabLabel;
  btn.appendChild(labelNode);
  if (fullLabel || typeName) {
    btn.title = [fullLabel || getTopicSchemaTargetLabel(id), typeName, configured ? "Есть доп. поля" : ""]
      .filter(Boolean)
      .join(" · ");
  } else if (configured) {
    btn.title = `${tabLabel} · есть доп. поля`;
  }
  return btn;
}

function renderTopicSchemaTargetTabs(cache = getTopicSchemaCache()) {
  if (!topicSchemaTargetTabsNode) return;
  topicSchemaTargetTabsNode.replaceChildren();

  if (isWorkspaceSchemaContext()) {
    topicSchemaTargetTabsNode.append(
      createTopicSchemaTargetTabButton(
        { id: "workspace", label: "Workspace", typeName: "awn.page.ws", group: "core" },
        cache
      )
    );
    return;
  }

  if (isAreaSchemaContext()) {
    topicSchemaTargetTabsNode.append(
      createTopicSchemaTargetTabButton(
        { id: "area", label: "Область", typeName: "awn.page.area", group: "core" },
        cache
      )
    );
    return;
  }

  const groups =
    typeof TopicSchemaSlotSpecs !== "undefined" && TopicSchemaSlotSpecs.buildTopicSchemaTargetTabGroups
      ? TopicSchemaSlotSpecs.buildTopicSchemaTargetTabGroups()
      : null;

  if (!groups) {
    topicSchemaTargetTabsNode.append(
      ...getTopicSchemaTargetSpecs().map((spec) => createTopicSchemaTargetTabButton(spec, cache))
    );
    return;
  }

  for (const group of groups) {
    const section = document.createElement("section");
    section.className = "topic-schema-target-tab-group";
    section.dataset.tabGroup = group.id;
    section.classList.toggle("is-configured", topicSchemaTabGroupHasCustomFields(group, cache));

    const heading = document.createElement("div");
    heading.className = "topic-schema-target-tab-group-label";
    if (section.classList.contains("is-configured")) {
      const groupMark = document.createElement("span");
      groupMark.className = "topic-schema-target-group-mark";
      groupMark.setAttribute("aria-hidden", "true");
      heading.appendChild(groupMark);
    }
    heading.append(document.createTextNode(group.label));
    section.appendChild(heading);

    const body = document.createElement("div");
    body.className = "topic-schema-target-tab-group-body";

    if (group.id === "core" && group.coreTabs) {
      const row = document.createElement("div");
      row.className = "topic-schema-target-tab-row topic-schema-target-tab-row--core";
      for (const tab of group.coreTabs) {
        row.appendChild(createTopicSchemaTargetTabButton(tab, cache));
      }
      body.appendChild(row);
    } else if (group.slots) {
      for (const slot of group.slots) {
        const row = document.createElement("div");
        row.className = "topic-schema-target-tab-row";
        row.classList.toggle("is-configured", topicSchemaSlotHasCustomFields(slot, cache));

        const slotLabel = document.createElement("span");
        slotLabel.className = "topic-schema-target-slot-label";
        slotLabel.textContent = slot.label;
        row.appendChild(slotLabel);

        const tabs = document.createElement("div");
        tabs.className = "topic-schema-target-slot-tabs";
        tabs.setAttribute("role", "presentation");
        for (const tab of slot.tabs) {
          tabs.appendChild(createTopicSchemaTargetTabButton(tab, cache));
        }
        row.appendChild(tabs);
        body.appendChild(row);
      }
    }

    section.appendChild(body);
    topicSchemaTargetTabsNode.appendChild(section);
  }
}

function renderTopicSchemaBaseFields(cache = getTopicSchemaCache()) {
  if (!topicSchemaBaseFieldsNode) return;
  const target = topicSchemaActiveTarget;
  const base = resolveTopicSchemaBaseType(target, cache);
  const titleNode = topicSchemaPanelNode?.querySelector(".topic-schema-base-title");
  const typeName = getTopicSchemaTargetTypeName(target) || AWN_SCHEMA_TARGET_TYPE_NAMES[target];
  if (titleNode) {
    const label = getTopicSchemaTargetLabel(target);
    titleNode.textContent = typeName
      ? `Базовые поля · ${label} (${typeName})`
      : "Базовые поля (read-only)";
  }
  if (!base?.fields) {
    topicSchemaBaseFieldsNode.textContent = "—";
    return;
  }
  const fieldEntries = { ...base.fields };
  if (target === "settings") {
    fieldEntries[ExternalFileMask.AWN_MASK_FILE_KEY] = ExternalFileMask.AWN_MASK_FILE_FIELD_DEF;
  }
  const parts = Object.entries(fieldEntries).map(([key, def]) => {
    const title = def?.title ? ` (${def.title})` : "";
    const typeLabel = getAwnFieldTypeLabel(def?.type);
    return `${key}${title} · ${typeLabel}`;
  });
  topicSchemaBaseFieldsNode.textContent = parts.join(" · ") || "—";
}

function createTopicSchemaSortButton(action, key, { disabled = false, title = "" } = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "topic-schema-sort-btn";
  button.dataset.schemaAction = action;
  button.dataset.schemaKey = key;
  button.textContent = action === "move-up" ? "↑" : "↓";
  button.title = title;
  button.disabled = disabled;
  return button;
}

function renderTopicSchemaCustomFields(cache = getTopicSchemaCache()) {
  if (!topicSchemaFieldsNode || !topicSchemaEmptyNode) return;
  const target = topicSchemaActiveTarget;
  const keys = getTopicSchemaCustomFieldKeys(target, cache);
  const registryEntries = getTopicSchemaRegistryEntries(cache);

  topicSchemaFieldsNode.replaceChildren();
  if (!keys.length) {
    topicSchemaEmptyNode.classList.remove("hidden");
    return;
  }
  topicSchemaEmptyNode.classList.add("hidden");

  keys.forEach((key, index) => {
    const fieldDef = cache?.awnSchema?.[target]?.fields?.[key] || {};
    const expanded = isTopicSchemaFieldExpanded(target, key);
    const hasAdvancedSettings = topicSchemaFieldHasAdvancedSettings(fieldDef);
    const row = document.createElement("div");
    row.className = "topic-schema-field-row";
    row.dataset.schemaRowKey = key;
    row.classList.toggle("is-settings-open", expanded);
    row.classList.toggle("is-configured", hasAdvancedSettings);

    const compact = document.createElement("div");
    compact.className = "topic-schema-field-compact";

    const sort = document.createElement("div");
    sort.className = "topic-schema-field-sort";
    sort.append(
      createTopicSchemaSortButton("move-up", key, {
        disabled: index === 0,
        title: "Выше"
      }),
      createTopicSchemaSortButton("move-down", key, {
        disabled: index === keys.length - 1,
        title: "Ниже"
      })
    );

    const keyInput = document.createElement("input");
    keyInput.type = "text";
    keyInput.className = "topic-schema-inline-input";
    keyInput.value = key;
    keyInput.placeholder =
      isWorkspaceSchemaContext() && target === "workspace" ? "ws-ключ" : "ключ";
    keyInput.dataset.schemaKey = key;
    keyInput.dataset.schemaField = "key";
    keyInput.spellcheck = false;
    keyInput.title = isWorkspaceSchemaContext() && target === "workspace" ? "Ключ поля (ws-*)" : "Ключ поля";

    const typeSelect = document.createElement("select");
    typeSelect.className = "topic-schema-inline-select";
    typeSelect.dataset.schemaKey = key;
    typeSelect.dataset.schemaField = "type";
    typeSelect.title = "Тип поля";
    populateFieldTypeSelect(typeSelect, registryEntries, fieldDef.type || "awn.string");

    const titleInput = document.createElement("input");
    titleInput.type = "text";
    titleInput.className = "topic-schema-inline-input topic-schema-inline-input--title";
    titleInput.value = getFieldDefDisplayName(fieldDef, key);
    titleInput.placeholder = "name";
    titleInput.dataset.schemaKey = key;
    titleInput.dataset.schemaField = "title";
    titleInput.title = "name (подпись поля)";

    const settingsBtn = document.createElement("button");
    settingsBtn.type = "button";
    settingsBtn.className = "topic-schema-settings-toggle";
    settingsBtn.dataset.schemaAction = "toggle-settings";
    settingsBtn.dataset.schemaKey = key;
    settingsBtn.setAttribute("aria-expanded", expanded ? "true" : "false");
    settingsBtn.title = hasAdvancedSettings
      ? "Расширенные настройки (заполнены)"
      : "Расширенные настройки";
    settingsBtn.classList.toggle("is-configured", hasAdvancedSettings);
    settingsBtn.textContent = expanded ? "Скрыть" : "Настройки";

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "topic-schema-field-remove";
    removeBtn.dataset.schemaKey = key;
    removeBtn.dataset.schemaAction = "remove";
    removeBtn.title = "Удалить поле";
    removeBtn.textContent = "×";

    compact.append(sort, keyInput, typeSelect, titleInput, settingsBtn, removeBtn);
    row.appendChild(compact);
    appendTopicSchemaFieldSettings(row, fieldDef, key, { expanded });
    topicSchemaFieldsNode.append(row);
  });
}

function renderTopicSchemaEditor() {
  const cache = getTopicSchemaCache();
  const leadNode = topicSchemaPanelNode?.querySelector(".topic-schema-lead");
  if (leadNode) {
    if (isWorkspaceSchemaContext()) {
      leadNode.innerHTML =
        'Дополнительные поля workspace (<code>ws-*</code>) сохраняются в <code>configuration-schema.yml</code> в корне агента. ' +
        "Базовые поля (<code>awn-type</code>, <code>awn-name</code>…) наследуются от системного типа и не редактируются здесь. " +
        '<span class="topic-schema-lead-hint">Зелёная подсветка — у цели или поля уже есть свои настройки.</span>';
    } else if (isAreaSchemaContext()) {
      leadNode.innerHTML =
        'Дополнительные поля области (<code>area-*</code>) сохраняются в <code>configuration-schema.yml</code> рядом с manifest области. ' +
        "Наследуются поля workspace (<code>ws-*</code>) и ядра AWN. " +
        '<span class="topic-schema-lead-hint">Зелёная подсветка — у цели или поля уже есть свои настройки.</span>';
    } else {
      leadNode.innerHTML =
        "Дополнительные поля сохраняются в <code>configuration.yml</code> → <code>awn_schema</code> или <code>configuration-schema.yml</code> темы. " +
        "Базовые поля (<code>awn-type</code>, <code>awn-name</code>…) наследуются от системного типа и не редактируются здесь. " +
        '<span class="topic-schema-lead-hint">Зелёная подсветка — у цели или поля уже есть свои настройки.</span>';
    }
  }
  if (!cache) {
    if (topicSchemaBaseFieldsNode) topicSchemaBaseFieldsNode.textContent = "—";
    if (topicSchemaFieldsNode) topicSchemaFieldsNode.replaceChildren();
    topicSchemaEmptyNode?.classList.remove("hidden");
    return;
  }
  renderTopicSchemaTargetTabs();
  renderTopicSchemaBaseFields(cache);
  renderTopicSchemaCustomFields(cache);
}

function readTopicSchemaFieldFromRow(row, cache = getTopicSchemaCache()) {
  if (!row || !cache) return;
  const target = topicSchemaActiveTarget;
  const oldKey = row.dataset.schemaRowKey;
  if (!oldKey) return;

  const keyInput = row.querySelector('[data-schema-field="key"]');
  const typeSelect = row.querySelector('[data-schema-field="type"]');
  const titleInput = row.querySelector('[data-schema-field="title"]');
  const fields = cache.awnSchema[target].fields;

  const nextKeyRaw = String(keyInput?.value || "").trim() || oldKey;
  const nextKey =
    isWorkspaceSchemaContext() && target === "workspace"
      ? normalizeWorkspaceSchemaFieldKey(nextKeyRaw)
      : isAreaSchemaContext() && target === "area"
        ? normalizeAreaSchemaFieldKey(nextKeyRaw)
        : nextKeyRaw;
  if (nextKey !== oldKey) {
    renameTopicSchemaField(target, oldKey, nextKey);
    row.dataset.schemaRowKey = nextKey;
    if (keyInput && keyInput.value !== nextKey) keyInput.value = nextKey;
    row.querySelectorAll("[data-schema-key]").forEach((node) => {
      node.dataset.schemaKey = nextKey;
    });
  }

  const activeKey = row.dataset.schemaRowKey;
  const fieldDef = fields[activeKey] || {};
  const nextType = resolveFieldTypeId(typeSelect?.value || "awn.string");
  const allowedSettings = new Set(["type", "title", "name", ...getFieldTypeSettingsKeys(nextType)]);

  fieldDef.type = nextType;
  const nextName = String(titleInput?.value || "").trim();
  fieldDef.name = nextName;
  if (nextName) fieldDef.title = nextName;
  else delete fieldDef.title;

  for (const propKey of Object.keys(getFieldDefSchemaProperties())) {
    if (propKey === "type" || propKey === "title") continue;
    if (!allowedSettings.has(propKey)) delete fieldDef[propKey];
  }

  row.querySelectorAll(".topic-schema-enum-options, .topic-schema-setting [data-schema-field]").forEach((control) => {
    const propKey = control.dataset.schemaField;
    if (!propKey || !allowedSettings.has(propKey)) return;
    if (propKey === "enum" && typeof control.readEnumOptions === "function") {
      const parsed = control.readEnumOptions();
      if (shouldPersistFieldDefSetting(propKey, parsed, fieldDef)) fieldDef[propKey] = parsed;
      else delete fieldDef[propKey];
      return;
    }
    const propDef = getFieldTypeSettingPropDef(propKey);
    const parsed = parseFieldDefSettingValue(
      propKey,
      propDef,
      control.type === "checkbox" ? control.checked : control.value
    );
    if (shouldPersistFieldDefSetting(propKey, parsed, fieldDef)) {
      fieldDef[propKey] = parsed;
    } else {
      delete fieldDef[propKey];
    }
  });

  fields[activeKey] = fieldDef;
  row.classList.toggle("is-configured", topicSchemaFieldHasAdvancedSettings(fieldDef));
  row.querySelector(".topic-schema-settings-toggle")?.classList.toggle(
    "is-configured",
    topicSchemaFieldHasAdvancedSettings(fieldDef)
  );
}

function handleTopicSchemaFieldsInput(event) {
  if (activeContentMode !== "topic-schema") return;
  const row = event.target.closest(".topic-schema-field-row");
  if (!row) return;
  readTopicSchemaFieldFromRow(row);
  if (event.target.dataset.schemaField === "type") {
    const activeKey = row.dataset.schemaRowKey;
    const expanded = isTopicSchemaFieldExpanded(topicSchemaActiveTarget, activeKey);
    renderTopicSchemaCustomFields();
    if (expanded && activeKey) {
      setTopicSchemaFieldExpanded(topicSchemaActiveTarget, activeKey, true);
      const nextRow = topicSchemaFieldsNode?.querySelector(
        `[data-schema-row-key="${CSS.escape(activeKey)}"]`
      );
      nextRow?.classList.add("is-settings-open");
      nextRow?.querySelector(".topic-schema-field-settings")?.classList.remove("is-collapsed");
      const toggle = nextRow?.querySelector('[data-schema-action="toggle-settings"]');
      if (toggle) {
        toggle.setAttribute("aria-expanded", "true");
        toggle.textContent = "Скрыть";
      }
    }
  }
  syncSaveButtonLamp();
}

function handleTopicSchemaFieldsClick(event) {
  if (activeContentMode !== "topic-schema") return;
  const btn = event.target.closest("[data-schema-action]");
  if (!btn) return;
  const action = btn.dataset.schemaAction;
  const key = btn.dataset.schemaKey;
  if (!key) return;

  if (action === "remove") {
    removeTopicSchemaField(topicSchemaActiveTarget, key);
    return;
  }
  if (action === "move-up" || action === "move-down") {
    reorderTopicSchemaFields(topicSchemaActiveTarget, key, action === "move-up" ? "up" : "down");
    return;
  }
  if (action === "toggle-settings") {
    const expanded = toggleTopicSchemaFieldExpanded(topicSchemaActiveTarget, key);
    const row = btn.closest(".topic-schema-field-row");
    row?.classList.toggle("is-settings-open", expanded);
    btn.setAttribute("aria-expanded", expanded ? "true" : "false");
    btn.textContent = expanded ? "Скрыть" : "Настройки";
    const settingsHost = row?.querySelector(".topic-schema-field-settings");
    settingsHost?.classList.toggle("is-collapsed", !expanded);
  }
}

async function saveWorkspaceSchemaContent() {
  const manifestPath = getTopicSchemaManifestPath();
  if (!manifestPath || !isWorkspaceSchemaContext(manifestPath)) {
    throw new Error("Схема workspace доступна только в корне агента");
  }
  const cache = getTopicSchemaCache(manifestPath);
  if (!cache) throw new Error("Схема не загружена");

  topicSchemaFieldsNode?.querySelectorAll(".topic-schema-field-row").forEach((row) => {
    readTopicSchemaFieldFromRow(row, cache);
  });

  const awnSchemaToSave = normalizeTopicSchemaState(cache.awnSchema);
  const response = await fetch(buildApiUrl("/api/file/workspace-schema"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      path: manifestPath,
      awnSchema: awnSchemaToSave
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const reason = errorData.error || `Request failed with ${response.status}`;
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${reason}${details}`);
  }

  const data = await response.json();
  const workspaceAwnSchema = normalizeTopicSchemaState(data.workspaceAwnSchema || data.awnSchema);
  cache.awnSchema = workspaceAwnSchema;
  cache.workspaceAwnSchema = workspaceAwnSchema;
  cache.baseTypes = data.baseTypes || cache.baseTypes;
  cache.merged = data.merged || cache.merged;
  cache.schemaExists = Boolean(data.exists);
  cache.schemaPath = data.schemaPath || cache.schemaPath;
  enrichTopicSchemaCacheFromTypes(cache);
  renderTopicSchemaEditor();
  return data;
}

async function saveTopicSchemaContent() {
  if (isWorkspaceSchemaContext()) {
    return saveWorkspaceSchemaContent();
  }
  const manifestPath = getTopicSchemaManifestPath();
  if (!manifestPath) throw new Error("Схема полей недоступна для этого узла");
  const cache = getTopicSchemaCache(manifestPath);
  if (!cache) throw new Error("Схема не загружена");

  topicSchemaFieldsNode?.querySelectorAll(".topic-schema-field-row").forEach((row) => {
    readTopicSchemaFieldFromRow(row, cache);
  });

  const awnSchemaToSave = normalizeTopicSchemaState(cache.awnSchema);
  if (awnSchemaToSave.settings?.fields) {
    awnSchemaToSave.settings.fields = ExternalFileMask.stripBuiltinSettingsSchemaFields(
      awnSchemaToSave.settings.fields
    );
  }

  const response = await fetch(buildApiUrl("/api/file/topic-schema"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      path: manifestPath,
      awnSchema: awnSchemaToSave
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const reason = errorData.error || `Request failed with ${response.status}`;
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${reason}${details}`);
  }

  const data = await response.json();
  const topicAwnSchema = normalizeTopicSchemaState(
    isAreaSchemaContext(manifestPath) ? emptyTopicSchemaState() : data.topicAwnSchema ?? data.awnSchema
  );
  const areaAwnSchema = normalizeTopicSchemaState(
    isAreaSchemaContext(manifestPath)
      ? data.areaAwnSchema ?? data.awnSchema
      : data.areaAwnSchema ?? cache.areaAwnSchema
  );
  cache.awnSchema = isAreaSchemaContext(manifestPath) ? areaAwnSchema : topicAwnSchema;
  cache.topicAwnSchema = topicAwnSchema;
  cache.areaAwnSchema = areaAwnSchema;
  cache.effectiveAwnSchema = normalizeTopicSchemaState(data.awnSchema);
  cache.workspaceAwnSchema = normalizeTopicSchemaState(data.workspaceAwnSchema ?? cache.workspaceAwnSchema);
  cache.baseTypes = data.baseTypes || cache.baseTypes;
  cache.merged = data.merged || cache.merged;
  enrichTopicSchemaCacheFromTypes(cache);
  cache.configExists = Boolean(data.exists);
  cache.configPath = data.configPath || cache.configPath;
  if (typeof data.content === "string") {
    setCachedNodeConfig(manifestPath, {
      path: data.configPath || cache.configPath,
      content: data.content,
      exists: Boolean(data.exists),
      defaultLandingMode: NodeConfigBundle.extractDefaultLandingModeFromNodeConfig(data.content)
    });
    const settingsCache = nodeSettingsCacheByManifest.get(manifestPath);
    if (settingsCache) {
      const nextState = parseNodeSettingsState(data.content);
      settingsCache.awnSchemaYaml = nextState.awnSchemaYaml;
      settingsCache.defaultLandingMode = nextState.defaultLandingMode;
      settingsCache.settingsFields = mergeTopicSchemaSettingsFields(
        normalizeTopicSchemaState(data.awnSchema)?.settings?.fields || {}
      );
      settingsCache.entries = buildNodeSettingsEntriesFromSchema(
        nextState.entries,
        settingsCache.settingsFields
      );
      if (activeContentMode === "configs") renderNodeSettingsEditor(settingsCache);
    }
  }
  renderTopicSchemaEditor();
  return data;
}

const sectionSchemaCacheByKey = new Map();
const sectionSchemaExpandedKeys = new Set();
let sectionSchemaEditorSeq = 0;

function isEntryOverviewCategoryContext(context) {
  if (!context || isEntryOverviewMemoryTocRoot(context)) return false;
  return (
    context.entryKind === "awn.record.category" ||
    context.entryKind === "awn.media.category" ||
    isSectionReadmePath(String(context.relativePath || ""))
  );
}

function getSectionSchemaLayerForMemoryKind(memoryKind) {
  if (memoryKind === "external") return STORAGE_SUBFOLDER_CONTENT;
  if (memoryKind === "media") return STORAGE_SUBFOLDER_MEDIA;
  return getFlatStorageSectionFolderName(memoryKind) || STORAGE_SUBFOLDER_CONTENT;
}

function getSectionFolderFromCategoryContext(context) {
  const relativePath = String(context?.relativePath || "")
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "");
  if (!relativePath) return "";
  if (/\/manifest\.md$/i.test(relativePath)) {
    return relativePath.replace(/\/manifest\.md$/i, "");
  }
  return relativePath;
}

function resolveSectionSchemaParams(context, nodePath = activePath) {
  const manifestPath = getTopicSchemaManifestPath(nodePath);
  const sectionPath = getSectionFolderFromCategoryContext(context);
  const layer = getSectionSchemaLayerForMemoryKind(context?.memoryKind || "external");
  if (!manifestPath || !sectionPath) return null;
  return { manifestPath, sectionPath, layer };
}

function getSectionSchemaCacheKey(params) {
  return `${params.manifestPath}::${params.layer}::${params.sectionPath}`;
}

function getSectionSchemaSlotKeyForContext(context) {
  const memoryKind = context?.memoryKind || "external";
  if (memoryKind === "external") return "memory";
  if (memoryKind === "internal") return "main-single";
  if (memoryKind === "tabular") return "main-single-csv";
  if (memoryKind === "todo") return "todo-single";
  if (memoryKind === "media") return "media";
  if (isFlatEntryOverviewMemoryKind(memoryKind)) return memoryKind;
  return "memory";
}

function getSectionSchemaTargetsForContext(context) {
  const slotKey = getSectionSchemaSlotKeyForContext(context);
  if (typeof TopicSchemaSlotSpecs !== "undefined") {
    return ["record", "category", "sidecar"]
      .map((kind) => TopicSchemaSlotSpecs.resolveTopicSchemaTargetId(slotKey, { contentKind: kind }))
      .filter(Boolean);
  }
  if (context?.entryKind === "awn.media.category" || context?.memoryKind === "media") {
    return ["slot_media_record", "slot_media_category", "slot_media"];
  }
  return ["slot_memory", "slot_memory_category", "slot_memory_sidecar"];
}

function getSectionSchemaTargetTabLabel(targetId) {
  if (typeof TopicSchemaSlotSpecs !== "undefined") {
    const spec = TopicSchemaSlotSpecs.findTopicSchemaTargetSpecById(targetId);
    if (spec?.contentKind && TopicSchemaSlotSpecs.CONTENT_KIND_TAB_LABELS?.[spec.contentKind]) {
      return TopicSchemaSlotSpecs.CONTENT_KIND_TAB_LABELS[spec.contentKind];
    }
  }
  return getTopicSchemaTargetLabel(targetId);
}

function getSectionSchemaTargetTabGroup(targetId) {
  if (typeof TopicSchemaSlotSpecs !== "undefined") {
    const spec = TopicSchemaSlotSpecs.findTopicSchemaTargetSpecById(targetId);
    if (spec?.contentKind === "category") return "slot-meta";
    if (spec?.contentKind === "sidecar") return "slot-sidecar";
  }
  if (String(targetId).endsWith("_category") || targetId === "slot_media_category") return "slot-meta";
  if (String(targetId).endsWith("_sidecar") || targetId === "slot_media") return "slot-sidecar";
  return "slot";
}

function emptySectionSchemaState(context) {
  const result = {};
  for (const id of getSectionSchemaTargetsForContext(context)) {
    result[id] = { fields: {} };
  }
  return result;
}

function getSectionSchemaExpandedKey(scope, target, key) {
  return `${scope}:${target}:${key}`;
}

function isSectionSchemaFieldExpanded(scope, target, key) {
  return sectionSchemaExpandedKeys.has(getSectionSchemaExpandedKey(scope, target, key));
}

function setSectionSchemaFieldExpanded(scope, target, key, expanded) {
  const token = getSectionSchemaExpandedKey(scope, target, key);
  if (expanded) sectionSchemaExpandedKeys.add(token);
  else sectionSchemaExpandedKeys.delete(token);
}

function toggleSectionSchemaFieldExpanded(scope, target, key) {
  const token = getSectionSchemaExpandedKey(scope, target, key);
  if (sectionSchemaExpandedKeys.has(token)) {
    sectionSchemaExpandedKeys.delete(token);
    return false;
  }
  sectionSchemaExpandedKeys.add(token);
  return true;
}

async function loadSectionSchemaForEntry(context, options = {}) {
  const params = resolveSectionSchemaParams(context);
  if (!params) return null;
  const cacheKey = getSectionSchemaCacheKey(params);
  if (!options.force) {
    const cached = sectionSchemaCacheByKey.get(cacheKey);
    if (cached) return cached;
  }

  const response = await fetch(
    buildApiUrl("/api/file/section-schema", {
      manifest: params.manifestPath,
      section: params.sectionPath,
      layer: params.layer
    })
  );
  if (!response.ok) throw new Error(`Request failed with ${response.status}`);
  const data = await response.json();
  if (!awnTypesCache?.types) {
    await loadAwnTypes(activeAgentId);
  }
  const payload = {
    ...params,
    cacheKey,
    configPath: data.configPath || "",
    configExists: Boolean(data.configExists),
    awnSchema: normalizeTopicSchemaState(data.sectionAwnSchema || emptySectionSchemaState(context)),
    inheritedSectionChain: Array.isArray(data.inheritedSectionChain) ? data.inheritedSectionChain : [],
    topicAwnSchema: normalizeTopicSchemaState(data.topicAwnSchema || data.awnSchema),
    baseTypes: data.baseTypes || {},
    merged: data.merged || {},
    fieldRegistry: data.fieldRegistry || awnTypesCache?.fieldRegistry || {},
    memoryKind: context?.memoryKind || "external",
    entryKind: context?.entryKind || "",
    activeTarget: getSectionSchemaTargetsForContext(context)[0]
  };
  enrichTopicSchemaCacheFromTypes(payload);
  sectionSchemaCacheByKey.set(cacheKey, payload);
  return payload;
}

function invalidateTopicSchemaCacheForSection(params) {
  if (!params?.manifestPath || !params.sectionPath) return;
  const marker = buildStorageLayerRef(params.manifestPath, params.layer, params.sectionPath);
  for (const key of topicSchemaCacheByManifest.keys()) {
    const [, contentPath = ""] = String(key).split("::");
    if (contentPath && (contentPath === marker || contentPath.startsWith(`${marker}/`))) {
      topicSchemaCacheByManifest.delete(key);
    }
  }
}

async function saveSectionSchemaFromPanel(panel) {
  const cache = panel?._sectionSchemaCache;
  const params = panel?._sectionSchemaParams;
  if (!cache || !params) throw new Error("Схема раздела не загружена");

  readSectionSchemaFieldsFromPanel(panel, cache);

  const awnSchemaToSave = normalizeTopicSchemaState(cache.awnSchema);
  const response = await fetch(buildApiUrl("/api/file/section-schema"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      manifestPath: params.manifestPath,
      sectionPath: params.sectionPath,
      layer: params.layer,
      awnSchema: awnSchemaToSave
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const reason = errorData.error || `Request failed with ${response.status}`;
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${reason}${details}`);
  }

  const data = await response.json();
  cache.awnSchema = normalizeTopicSchemaState(data.sectionAwnSchema || awnSchemaToSave);
  cache.baseTypes = data.baseTypes || cache.baseTypes;
  cache.merged = data.merged || cache.merged;
  cache.configExists = Boolean(data.configExists);
  cache.configPath = data.configPath || cache.configPath;
  enrichTopicSchemaCacheFromTypes(cache);
  invalidateTopicSchemaCacheForSection(params);
  panel._sectionSchemaDirty = false;
  panel.querySelector(".section-schema-save-btn")?.classList.remove("is-dirty");
  renderSectionSchemaEditor(panel, cache);
  return data;
}

function readSectionSchemaFieldFromRow(row, cache, target, scope) {
  if (!row || !cache) return;
  const oldKey = row.dataset.schemaRowKey;
  if (!oldKey) return;

  const keyInput = row.querySelector('[data-schema-field="key"]');
  const typeSelect = row.querySelector('[data-schema-field="type"]');
  const titleInput = row.querySelector('[data-schema-field="title"]');
  const fields = cache.awnSchema[target].fields;

  const nextKey = String(keyInput?.value || "").trim() || oldKey;
  if (nextKey !== oldKey) {
    fields[nextKey] = fields[oldKey];
    delete fields[oldKey];
    if (isSectionSchemaFieldExpanded(scope, target, oldKey)) {
      setSectionSchemaFieldExpanded(scope, target, oldKey, false);
      setSectionSchemaFieldExpanded(scope, target, nextKey, true);
    }
    row.dataset.schemaRowKey = nextKey;
    row.querySelectorAll("[data-schema-key]").forEach((node) => {
      node.dataset.schemaKey = nextKey;
    });
  }

  const activeKey = row.dataset.schemaRowKey;
  const fieldDef = fields[activeKey] || {};
  const nextType = resolveFieldTypeId(typeSelect?.value || "awn.string");
  const allowedSettings = new Set(["type", "title", "name", ...getFieldTypeSettingsKeys(nextType)]);

  fieldDef.type = nextType;
  const nextName = String(titleInput?.value || "").trim();
  fieldDef.name = nextName;
  if (nextName) fieldDef.title = nextName;
  else delete fieldDef.title;

  for (const propKey of Object.keys(getFieldDefSchemaProperties())) {
    if (propKey === "type" || propKey === "title") continue;
    if (!allowedSettings.has(propKey)) delete fieldDef[propKey];
  }

  row.querySelectorAll(".topic-schema-enum-options, .topic-schema-setting [data-schema-field]").forEach((control) => {
    const propKey = control.dataset.schemaField;
    if (!propKey || !allowedSettings.has(propKey)) return;
    if (propKey === "enum" && typeof control.readEnumOptions === "function") {
      const parsed = control.readEnumOptions();
      if (shouldPersistFieldDefSetting(propKey, parsed, fieldDef)) fieldDef[propKey] = parsed;
      else delete fieldDef[propKey];
      return;
    }
    const propDef = getFieldTypeSettingPropDef(propKey);
    const parsed = parseFieldDefSettingValue(
      propKey,
      propDef,
      control.type === "checkbox" ? control.checked : control.value
    );
    if (shouldPersistFieldDefSetting(propKey, parsed, fieldDef)) fieldDef[propKey] = parsed;
    else delete fieldDef[propKey];
  });

  fields[activeKey] = fieldDef;
  row.classList.toggle("is-configured", topicSchemaFieldHasAdvancedSettings(fieldDef));
  row.querySelector(".topic-schema-settings-toggle")?.classList.toggle(
    "is-configured",
    topicSchemaFieldHasAdvancedSettings(fieldDef)
  );
}

function readSectionSchemaFieldsFromPanel(panel, cache) {
  const target = cache.activeTarget;
  panel.querySelectorAll(".topic-schema-field-row").forEach((row) => {
    readSectionSchemaFieldFromRow(row, cache, target, cache.cacheKey);
  });
}

function markSectionSchemaPanelDirty(panel) {
  panel._sectionSchemaDirty = true;
  panel.querySelector(".section-schema-save-btn")?.classList.add("is-dirty");
}

function renderSectionSchemaTargetTabs(panel, cache) {
  const tabsNode = panel.querySelector(".topic-schema-target-tabs");
  if (!tabsNode) return;
  tabsNode.replaceChildren();
  const row = document.createElement("div");
  row.className = "topic-schema-target-tab-row topic-schema-target-tab-row--core";
  const schemaContext = { entryKind: cache.entryKind, memoryKind: cache.memoryKind };
  for (const targetId of getSectionSchemaTargetsForContext(schemaContext)) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "topic-schema-target-tab topic-schema-target-tab--slot";
    const tabGroup = getSectionSchemaTargetTabGroup(targetId);
    if (tabGroup === "slot-meta") btn.classList.add("topic-schema-target-tab--slot-meta");
    if (tabGroup === "slot-sidecar") btn.classList.add("topic-schema-target-tab--slot-sidecar");
    btn.dataset.target = targetId;
    btn.setAttribute("role", "tab");
    btn.setAttribute("aria-selected", targetId === cache.activeTarget ? "true" : "false");
    btn.classList.toggle("is-active", targetId === cache.activeTarget);
    const configured = Object.keys(cache.awnSchema?.[targetId]?.fields || {}).length > 0;
    btn.classList.toggle("is-configured", configured);
    const labelNode = document.createElement("span");
    labelNode.className = "topic-schema-target-tab-label";
    labelNode.textContent = getSectionSchemaTargetTabLabel(targetId);
    btn.appendChild(labelNode);
    btn.title = getTopicSchemaTargetTypeName(targetId) || targetId;
    btn.addEventListener("click", () => {
      readSectionSchemaFieldsFromPanel(panel, cache);
      cache.activeTarget = targetId;
      renderSectionSchemaEditor(panel, cache);
    });
    row.appendChild(btn);
  }
  tabsNode.appendChild(row);
}

function renderSectionSchemaBaseFields(panel, cache) {
  const baseNode = panel.querySelector(".topic-schema-base-fields");
  const titleNode = panel.querySelector(".topic-schema-base-title");
  if (!baseNode) return;
  const target = cache.activeTarget;
  const base = resolveTopicSchemaBaseType(target, cache);
  const typeName = getTopicSchemaTargetTypeName(target) || AWN_SCHEMA_TARGET_TYPE_NAMES[target];
  if (titleNode) {
    const label = getSectionSchemaTargetTabLabel(target);
    titleNode.textContent = typeName
      ? `Базовые поля · ${label} (${typeName})`
      : "Базовые поля (read-only)";
  }
  if (!base?.fields) {
    baseNode.textContent = "—";
    return;
  }
  const parts = Object.entries(base.fields).map(([key, def]) => {
    const title = def?.title ? ` (${def.title})` : "";
    return `${key}${title} · ${getAwnFieldTypeLabel(def?.type)}`;
  });
  baseNode.textContent = parts.join(" · ") || "—";
}

function renderSectionSchemaCustomFields(panel, cache) {
  const fieldsNode = panel.querySelector(".topic-schema-fields");
  const emptyNode = panel.querySelector(".topic-schema-empty");
  if (!fieldsNode || !emptyNode) return;

  const target = cache.activeTarget;
  if (!cache.awnSchema[target]) cache.awnSchema[target] = { fields: {} };
  const keys = Object.keys(cache.awnSchema[target].fields || {});
  const registryEntries = getTopicSchemaRegistryEntries(cache);
  const scope = cache.cacheKey;

  fieldsNode.replaceChildren();
  if (!keys.length) {
    emptyNode.classList.remove("hidden");
    return;
  }
  emptyNode.classList.add("hidden");

  keys.forEach((key, index) => {
    const fieldDef = cache.awnSchema[target].fields[key] || {};
    const expanded = isSectionSchemaFieldExpanded(scope, target, key);
    const hasAdvancedSettings = topicSchemaFieldHasAdvancedSettings(fieldDef);
    const row = document.createElement("div");
    row.className = "topic-schema-field-row";
    row.dataset.schemaRowKey = key;
    row.classList.toggle("is-settings-open", expanded);
    row.classList.toggle("is-configured", hasAdvancedSettings);

    const compact = document.createElement("div");
    compact.className = "topic-schema-field-compact";

    const sort = document.createElement("div");
    sort.className = "topic-schema-field-sort";
    sort.append(
      createTopicSchemaSortButton("move-up", key, { disabled: index === 0, title: "Выше" }),
      createTopicSchemaSortButton("move-down", key, {
        disabled: index === keys.length - 1,
        title: "Ниже"
      })
    );

    const keyInput = document.createElement("input");
    keyInput.type = "text";
    keyInput.className = "topic-schema-inline-input";
    keyInput.value = key;
    keyInput.placeholder = "ключ";
    keyInput.dataset.schemaKey = key;
    keyInput.dataset.schemaField = "key";
    keyInput.spellcheck = false;

    const typeSelect = document.createElement("select");
    typeSelect.className = "topic-schema-inline-select";
    typeSelect.dataset.schemaKey = key;
    typeSelect.dataset.schemaField = "type";
    populateFieldTypeSelect(typeSelect, registryEntries, fieldDef.type || "awn.string");

    const titleInput = document.createElement("input");
    titleInput.type = "text";
    titleInput.className = "topic-schema-inline-input topic-schema-inline-input--title";
    titleInput.value = getFieldDefDisplayName(fieldDef, key);
    titleInput.placeholder = "name";
    titleInput.dataset.schemaKey = key;
    titleInput.dataset.schemaField = "title";

    const settingsBtn = document.createElement("button");
    settingsBtn.type = "button";
    settingsBtn.className = "topic-schema-settings-toggle";
    settingsBtn.dataset.schemaAction = "toggle-settings";
    settingsBtn.dataset.schemaKey = key;
    settingsBtn.setAttribute("aria-expanded", expanded ? "true" : "false");
    settingsBtn.classList.toggle("is-configured", hasAdvancedSettings);
    settingsBtn.textContent = expanded ? "Скрыть" : "Настройки";

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "topic-schema-field-remove";
    removeBtn.dataset.schemaKey = key;
    removeBtn.dataset.schemaAction = "remove";
    removeBtn.title = "Удалить поле";
    removeBtn.textContent = "×";

    compact.append(sort, keyInput, typeSelect, titleInput, settingsBtn, removeBtn);
    row.appendChild(compact);
    appendTopicSchemaFieldSettings(row, fieldDef, key, { expanded });
    fieldsNode.append(row);
  });
}

function bindSectionSchemaPanelEvents(panel, cache, context) {
  if (panel.dataset.schemaBound === "1") return;
  panel.dataset.schemaBound = "1";

  panel.addEventListener("input", (event) => {
    const row = event.target.closest(".topic-schema-field-row");
    if (!row) return;
    readSectionSchemaFieldFromRow(row, cache, cache.activeTarget, cache.cacheKey);
    if (event.target.dataset.schemaField === "type") {
      renderSectionSchemaCustomFields(panel, cache);
      markSectionSchemaPanelDirty(panel);
      return;
    }
    markSectionSchemaPanelDirty(panel);
  });

  panel.addEventListener("click", (event) => {
    const btn = event.target.closest("[data-schema-action]");
    if (!btn) return;
    const action = btn.dataset.schemaAction;
    const key = btn.dataset.schemaKey;
    const target = cache.activeTarget;
    const scope = cache.cacheKey;

    if (action === "remove" && key) {
      delete cache.awnSchema[target].fields[key];
      setSectionSchemaFieldExpanded(scope, target, key, false);
      renderSectionSchemaEditor(panel, cache);
      markSectionSchemaPanelDirty(panel);
      return;
    }
    if ((action === "move-up" || action === "move-down") && key) {
      const fields = cache.awnSchema[target].fields;
      const keys = Object.keys(fields);
      const index = keys.indexOf(key);
      if (index < 0) return;
      const nextIndex = action === "move-up" ? index - 1 : index + 1;
      if (nextIndex < 0 || nextIndex >= keys.length) return;
      keys.splice(index, 1);
      keys.splice(nextIndex, 0, key);
      const reordered = {};
      for (const fieldKey of keys) reordered[fieldKey] = fields[fieldKey];
      cache.awnSchema[target].fields = reordered;
      renderSectionSchemaEditor(panel, cache);
      markSectionSchemaPanelDirty(panel);
      return;
    }
    if (action === "toggle-settings" && key) {
      const expanded = toggleSectionSchemaFieldExpanded(scope, target, key);
      const row = btn.closest(".topic-schema-field-row");
      row?.classList.toggle("is-settings-open", expanded);
      btn.setAttribute("aria-expanded", expanded ? "true" : "false");
      btn.textContent = expanded ? "Скрыть" : "Настройки";
      row?.querySelector(".topic-schema-field-settings")?.classList.toggle("is-collapsed", !expanded);
    }
  });

  panel.querySelector(".section-schema-add-btn")?.addEventListener("click", () => {
    const target = cache.activeTarget;
    if (!cache.awnSchema[target]) cache.awnSchema[target] = { fields: {} };
    const fields = cache.awnSchema[target].fields;
    let index = 1;
    let key = `field_${index}`;
    while (fields[key]) {
      index += 1;
      key = `field_${index}`;
    }
    fields[key] = { type: "awn.string", name: "", title: "" };
    renderSectionSchemaEditor(panel, cache);
    markSectionSchemaPanelDirty(panel);
    panel.querySelector(`[data-schema-row-key="${CSS.escape(key)}"] input[data-schema-field="key"]`)?.focus();
  });

  panel.querySelector(".section-schema-save-btn")?.addEventListener("click", () => {
    const saveBtn = panel.querySelector(".section-schema-save-btn");
    if (saveBtn?.disabled) return;
    saveBtn.disabled = true;
    saveBtn.textContent = "Сохраняю…";
    void saveSectionSchemaFromPanel(panel)
      .then(() => {
        showToast(`Схема раздела сохранена в ${BUNDLE_CONFIG_FILE}`, "success");
      })
      .catch((error) => {
        showToast(`Ошибка сохранения схемы: ${error.message}`, "error");
      })
      .finally(() => {
        saveBtn.disabled = false;
        saveBtn.textContent = "Сохранить схему";
      });
  });
}

function renderSectionSchemaEditor(panel, cache) {
  if (!panel || !cache) return;
  renderSectionSchemaTargetTabs(panel, cache);
  renderSectionSchemaBaseFields(panel, cache);
  renderSectionSchemaCustomFields(panel, cache);
  const pathNode = panel.querySelector(".section-schema-path");
  if (pathNode) {
    pathNode.textContent = cache.configPath || `${cache.sectionPath}/${BUNDLE_CONFIG_FILE}`;
  }
  const chainNode = panel.querySelector(".section-schema-chain");
  if (chainNode) {
    const chain = cache.inheritedSectionChain || [];
    chainNode.textContent = chain.length
      ? chain.map((item) => item.sectionPrefix).join(" → ")
      : "— только схема темы и типов";
  }
}

function wrapEntryOverviewSectionSchemaFold(panel, params) {
  const accordionGroupId = `section-schema:${getSectionSchemaCacheKey(params)}`;
  const fold = createOverviewAccordionSection(
    accordionGroupId,
    "📋 Схема полей раздела",
    panel,
    { defaultOpen: false }
  );
  fold.classList.add(
    "node-overview-section-schema-fold",
    "node-overview-props-fold",
    "node-navigation-props"
  );
  return fold;
}

function createEntryOverviewSectionSchemaPanel(context) {
  const panel = document.createElement("section");
  panel.className = "node-entry-overview-section-schema topic-schema-panel";
  panel.setAttribute("aria-label", "Схема полей раздела");
  panel.innerHTML = `
    <header class="topic-schema-head">
      <div>
        <p class="topic-schema-lead">
          Дополнительные поля для записей и подразделов внутри «${escapeHtml(
            context.title || getSectionFolderFromCategoryContext(context)
          )}».
          <span class="topic-schema-lead-hint">Сохраняется в <code>${BUNDLE_CONFIG_FILE}</code> рядом с manifest раздела.</span>
        </p>
        <p class="section-schema-meta">
          <span class="section-schema-meta-label">Файл:</span>
          <code class="section-schema-path"></code>
        </p>
        <p class="section-schema-meta">
          <span class="section-schema-meta-label">Наследование:</span>
          <span class="section-schema-chain"></span>
        </p>
      </div>
    </header>
    <div class="topic-schema-target-tabs" role="tablist" aria-label="Цель схемы раздела"></div>
    <section class="topic-schema-base-card" aria-label="Базовые поля типа">
      <h4 class="topic-schema-base-title">Базовые поля (read-only)</h4>
      <p class="topic-schema-base-fields"></p>
    </section>
    <div class="topic-schema-fields"></div>
    <div class="topic-schema-add-area">
      <p class="topic-schema-empty hidden">Дополнительных полей пока нет — добавьте поле кнопкой ниже.</p>
      <footer class="topic-schema-footer section-schema-footer">
        <button type="button" class="topic-schema-add-btn section-schema-add-btn">+ Поле</button>
        <button type="button" class="section-schema-save-btn">Сохранить схему</button>
      </footer>
    </div>
  `;
  return panel;
}

async function appendEntryOverviewSectionSchemaPanel(container, context) {
  if (!isEntryOverviewCategoryContext(context)) return;
  const params = resolveSectionSchemaParams(context);
  if (!params) return;

  const panel = createEntryOverviewSectionSchemaPanel(context);
  panel.querySelector(".topic-schema-base-fields").textContent = "Загрузка…";
  const fold = wrapEntryOverviewSectionSchemaFold(panel, params);
  const anchor =
    container.querySelector(".node-overview-awn-props-fold") ||
    container.querySelector(".node-overview-props-custom") ||
    container.querySelector(".node-navigation-hero-main");
  if (anchor) anchor.insertAdjacentElement("afterend", fold);
  else container.appendChild(fold);

  const editorSeq = ++sectionSchemaEditorSeq;
  try {
    const cache = await loadSectionSchemaForEntry(context);
    if (editorSeq !== sectionSchemaEditorSeq) return;
    cache.entryKind = context.entryKind;
    cache.memoryKind = context.memoryKind || "external";
    panel._sectionSchemaCache = cache;
    panel._sectionSchemaParams = params;
    bindSectionSchemaPanelEvents(panel, cache, context);
    renderSectionSchemaEditor(panel, cache);
  } catch (error) {
    if (editorSeq !== sectionSchemaEditorSeq) return;
    panel.querySelector(".topic-schema-base-fields").textContent = `Ошибка: ${error.message}`;
  }
}

function isAwnFieldKey(key) {
  return /^awn-/i.test(String(key || "").trim());
}

function isWsFieldKey(key) {
  return /^ws-/i.test(String(key || "").trim());
}

function normalizeWorkspaceSchemaFieldKey(key) {
  const trimmed = String(key || "").trim();
  if (!trimmed) return trimmed;
  if (isWsFieldKey(trimmed)) return trimmed;
  return `ws-${trimmed.replace(/^ws-?/i, "")}`;
}

function isAreaFieldKey(key) {
  return /^area-/i.test(String(key || "").trim());
}

function normalizeAreaSchemaFieldKey(key) {
  const trimmed = String(key || "").trim();
  if (!trimmed) return trimmed;
  if (isAreaFieldKey(trimmed)) return trimmed;
  return `area-${trimmed.replace(/^area-?/i, "")}`;
}

function isSchemaDefinedFieldKey(key) {
  return isAwnFieldKey(key) || isWsFieldKey(key) || isAreaFieldKey(key);
}

function isEditorCustomPropsFieldKey(key) {
  const entryKey = normalizePropsKey(key);
  if (!entryKey || HIDDEN_PROPS_FIELD_KEYS.has(entryKey)) return false;
  if (entryKey === "awn-preview" || entryKey === "awn-attachments") return false;
  return !isSchemaDefinedFieldKey(entryKey);
}

function shouldShowEditorCustomPropsBar() {
  if (!editorCustomPropsBarNode || !editorCustomPropsFieldsNode) return false;
  if (propsRawYamlVisible) return false;
  if (!canEditPropsForm()) return false;
  return true;
}

function getPropsFormFieldContainers() {
  const containers = [];
  if (propsFormFieldsNode) containers.push(propsFormFieldsNode);
  if (editorCustomPropsFieldsNode) containers.push(editorCustomPropsFieldsNode);
  return containers;
}

function sortPropsFieldKeys(keys) {
  const list = [...keys];
  const standardKeys = getStandardPropsFieldKeys();
  return list.sort((a, b) => {
    const aNorm = String(a || "").toLowerCase();
    const bNorm = String(b || "").toLowerCase();
    const aBase = standardKeys.indexOf(aNorm);
    const bBase = standardKeys.indexOf(bNorm);
    const aAwn = isAwnFieldKey(aNorm);
    const bAwn = isAwnFieldKey(bNorm);
    const aWs = isWsFieldKey(aNorm);
    const bWs = isWsFieldKey(bNorm);
    if (aBase !== -1 && bBase !== -1) return aBase - bBase;
    if (aBase !== -1) return -1;
    if (bBase !== -1) return 1;
    if (aAwn && !bAwn) return -1;
    if (!aAwn && bAwn) return 1;
    if (aAwn && bAwn) return aNorm.localeCompare(bNorm);
    if (aWs && !bWs) return -1;
    if (!aWs && bWs) return 1;
    if (aWs && bWs) return aNorm.localeCompare(bNorm);
    return aNorm.localeCompare(bNorm);
  });
}

function sortPropsEntries(entries) {
  const drafts = entries.filter((entry) => !entry?.key);
  const keyed = entries.filter((entry) => entry?.key);
  const order = sortPropsFieldKeys(keyed.map((entry) => entry.key));
  const map = new Map(keyed.map((entry) => [entry.key, entry]));
  const result = [];
  for (const key of order) {
    if (map.has(key)) result.push(map.get(key));
  }
  for (const entry of keyed) {
    if (!order.includes(entry.key)) result.push(entry);
  }
  return [...result, ...drafts];
}

function isRecordCategoryContentPath(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (
    (normalized.toLowerCase().endsWith("/_registration.md") ||
      normalized.toLowerCase().endsWith("/_reg-info.md")) &&
    /\/content\//i.test(normalized)
  ) {
    return true;
  }
  return (
    /\/awn-storage\/categories\/content\/[^/]+\.md$/i.test(normalized) ||
    /\/content\/categories\/[^/]+\.md$/i.test(normalized)
  );
}

function isMediaCategoryContentPath(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (
    (normalized.toLowerCase().endsWith("/_registration.md") ||
      normalized.toLowerCase().endsWith("/_reg-info.md")) &&
    /\/media\//i.test(normalized)
  ) {
    return true;
  }
  return /\/media\/categories\/[^/]+\.md$/i.test(normalized);
}

function getPropsContextPath(nodePath = activePath) {
  const manifestBase = getResolvedNodePath(activePath);

  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext?.relPath) {
    return activeEntryOverviewContext.relPath;
  }

  if (manifestBase && activeContentMode === "external" && activeExternalFilePath) {
    const rel = String(activeExternalFilePath).replace(/\\/g, "/").replace(/^\/+/, "");
    return `${getNodeStorageSubfolderPath(manifestBase, "external")}/${rel}`.replace(/\/+/g, "/");
  }

  if (manifestBase && isMediaLibraryContentMode() && activeMediaMarkdownPath) {
    const rel = String(activeMediaMarkdownPath).replace(/\\/g, "/").replace(/^\/+/, "");
    const subfolder = getMediaLibraryStorageSubfolder();
    return `${getNodeStorageSubfolderPath(manifestBase, subfolder)}/${rel}`.replace(/\/+/g, "/");
  }

  if (manifestBase && isMediaLibraryContentMode() && activeMediaSidecarPath) {
    const rel = String(activeMediaSidecarPath).replace(/\\/g, "/").replace(/^\/+/, "");
    return `${getNodeStorageSubfolderPath(manifestBase, STORAGE_SUBFOLDER_ASSETS)}/${rel}`.replace(/\/+/g, "/");
  }

  if (manifestBase && activeContentMode === "internal") {
    return resolveNodeSidecarRelPath(manifestBase, "content");
  }

  if (manifestBase && activeContentMode === "tabular" && isTabularSourceEditing()) {
    return resolveNodeSidecarRelPath(manifestBase, "tabular");
  }

  return getResolvedNodePath(nodePath) || manifestBase || "";
}

function normalizeAwnTypeName(typeName) {
  const raw = String(typeName || "").trim();
  if (!raw) return "";
  const shortAliases = {
    area: "awn.page.area",
    topic: "awn.page.topic",
    workspace: "awn.page.ws",
    ws: "awn.page.ws",
    record: "awn.content.record",
    service: "service"
  };
  const normalized = /^awn\./i.test(raw) ? raw : shortAliases[raw.toLowerCase()] || raw;
  const legacyToCanonical = {
    "awn.record": "awn.content.record",
    "awn.record.category": "awn.content.record.category",
    "awn.sidecar": "awn.content.sidecar",
    "awn.media.category": "awn.content.record.category",
    "awn.topic": "awn.page.topic",
    "awn.area": "awn.page.area",
    "awn.workspace": "awn.page.ws"
  };
  return legacyToCanonical[normalized] || normalized;
}

function getPropertiesApiPath() {
  const manifestPath = getActiveNodeApiPath();
  if (!manifestPath) return "";

  if (
    activeContentMode === "description" ||
    activeContentMode === NODE_OVERVIEW_MODE ||
    activeContentMode === NODE_NAVIGATION_MODE ||
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE
  ) {
    if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext?.relPath) {
      return activeEntryOverviewContext.relPath;
    }
    return manifestPath;
  }

  if (activeContentMode === "external" && activeExternalFilePath) {
    return getPropsContextPath();
  }

  if (isMediaAssetEditing()) {
    return getPropsContextPath();
  }

  return getPropsContextPath() || manifestPath;
}

function countManifestFolderDepthUnderContainer(normalized, containerFolder = getActiveAgentContainerFolder()) {
  const container = String(containerFolder || CONTAINER_FOLDER_DEFAULT).replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
  if (!container) return null;
  const marker = `${container}/`;
  const idx = normalized.toLowerCase().indexOf(marker.toLowerCase());
  if (idx < 0) return null;
  const after = normalized.slice(idx + marker.length);
  const segments = after.split("/").filter(Boolean);
  if (!segments.length) return 0;
  const last = segments[segments.length - 1].toLowerCase();
  if (last === "manifest.md") return Math.max(0, segments.length - 1);
  return segments.length;
}

function countManifestFolderDepthFromWorkspaceRoot(normalized) {
  const parts = String(normalized || "").replace(/\\/g, "/").replace(/^\/+/, "").split("/").filter(Boolean);
  if (!parts.length) return 0;
  const last = parts[parts.length - 1].toLowerCase();
  if (last === "manifest.md") return Math.max(0, parts.length - 1);
  return parts.length;
}

function getManifestTreeFolderDepth(normalized) {
  const path = String(normalized || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (isServiceNodePath(path)) {
    const kitFolder = getActiveAgentKitFolder();
    const rel = path.slice(kitFolder.length + 1).replace(/^\//, "");
    const segments = rel.split("/").filter(Boolean);
    if (!segments.length) return 0;
    const last = segments[segments.length - 1].toLowerCase();
    if (last === "manifest.md") return Math.max(0, segments.length - 1);
    return segments.length;
  }
  const containerFolder = getActiveAgentContainerFolder();
  if (containerFolder && path.startsWith(`${containerFolder}/`)) {
    const depth = countManifestFolderDepthUnderContainer(path, containerFolder);
    if (depth !== null) return depth;
  }
  return countManifestFolderDepthFromWorkspaceRoot(path);
}

function inferAwnTypeFromRelPath(relPath, options = {}) {
  const normalized = String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return "awn.file";
  const fileName = normalized.split("/").filter(Boolean).pop() || "";
  const lower = fileName.toLowerCase();

  if (lower.endsWith(".sidecar.md")) return normalizeAwnTypeName("awn.content.sidecar");
  if (isMediaCategoryContentPath(normalized)) return normalizeAwnTypeName("awn.content.record.category");
  if (isRecordCategoryContentPath(normalized)) return normalizeAwnTypeName("awn.content.record.category");
  if (isSectionReadmePath(normalized) && /\/media\//i.test(normalized)) {
    return normalizeAwnTypeName("awn.content.record.category");
  }
  if (isSectionReadmePath(normalized) && /\/content\//i.test(normalized)) {
    return normalizeAwnTypeName("awn.content.record.category");
  }

  const flatStorageModes = ["inbox", "note", "references"];
  const isFlatStorageContentFile =
    flatStorageModes.includes(options.contentMode) ||
    flatStorageModes.some((mode) => new RegExp(`/(?:awn-storage|storage)/${mode}/`, "i").test(normalized));
  if (isFlatStorageContentFile && !isNodeManifestPath(normalized)) {
    if (isSectionReadmePath(normalized)) return normalizeAwnTypeName("awn.content.record.category");
    return normalizeAwnTypeName("awn.content.record");
  }

  const isStorageContentFile =
    options.contentMode === "external" ||
    /\/(?:awn-storage|storage)\/(?:main|memory|content)\//i.test(normalized);
  if (isStorageContentFile && !isNodeManifestPath(normalized)) {
    return normalizeAwnTypeName("awn.content.record");
  }

  if (isNodeManifestPath(normalized)) {
    if (options.isAgentRoot || isAgentRootIndexPath(normalized)) return normalizeAwnTypeName("awn.page.ws");
    if (options.isContainerRoot || isAgentContainerRootIndexPath(normalized)) {
      return normalizeAwnTypeName("awn.page.area");
    }
    if (options.isSharedRoot || isAgentSharedRootIndexPath(normalized)) {
      return normalizeAwnTypeName("awn.page.area");
    }
    if (isAgentSystemRootIndexPath(normalized)) return normalizeAwnTypeName("awn.page.area");
    if (isSystemReferenceManifestPath(normalized)) {
      return /\/taxonomies\/[^/]+\/manifest\.md$/i.test(normalized) ||
        /\/catalog\/[^/]+\/manifest\.md$/i.test(normalized)
        ? "catalog"
        : "service-doc";
    }

    const declared = getDeclaredManifestTreeType(normalized);
    if (declared === "topic") return normalizeAwnTypeName("awn.page.topic");
    if (declared === "area") return normalizeAwnTypeName("awn.page.area");

    if (isTopicManifestPath(normalized)) return normalizeAwnTypeName("awn.page.topic");
    if (isAreaNodePath(normalized)) return normalizeAwnTypeName("awn.page.area");
    const containerFolder = options.containerFolder || getActiveAgentContainerFolder();
    const folderDepth = countManifestFolderDepthUnderContainer(normalized, containerFolder);
    if (folderDepth !== null) {
      return folderDepth >= 2
        ? normalizeAwnTypeName("awn.page.topic")
        : normalizeAwnTypeName("awn.page.area");
    }
    return countManifestFolderDepthFromWorkspaceRoot(normalized) >= 2
      ? normalizeAwnTypeName("awn.page.topic")
      : normalizeAwnTypeName("awn.page.area");
  }

  return normalizeAwnTypeName("awn.content.record");
}

function resolveAwnTypeForContext(nodePath = activePath) {
  const manifestPath = String(getResolvedNodePath(nodePath) || "").replace(/\\/g, "/");
  const propsTarget = String(getPropertiesApiPath() || manifestPath).replace(/\\/g, "/");
  const typeOptions = {
    contentMode: activeContentMode,
    containerFolder: getActiveAgentContainerFolder(),
    isAgentRoot: isAgentRootIndexPath(manifestPath),
    isContainerRoot: isAgentContainerRootIndexPath(manifestPath),
    isSharedRoot: isAgentSharedRootIndexPath(manifestPath)
  };

  if (propsTarget && propsTarget !== manifestPath) {
    return inferAwnTypeFromRelPath(propsTarget, typeOptions);
  }

  return inferAwnTypeFromRelPath(manifestPath, typeOptions);
}

function getActiveAwnTypeDef(typeName = null) {
  let resolvedType = normalizeAwnTypeName(typeName || resolveAwnTypeForContext());

  // When no specific typeName is requested, prefer the declared awn-type from frontmatter
  // (path inference returns generic "awn.topic", but frontmatter may say "awn.page.topic.agent")
  if (!typeName) {
    const declared = getPropsEntryValueByKey(propsFormEntries, "awn-type");
    if (declared) {
      const normalized = normalizeAwnTypeName(declared);
      if (normalized && normalized !== resolvedType && awnTypesCache?.types?.[normalized]) {
        resolvedType = normalized;
      }
    }
  }

  const cache = getTopicSchemaCache();
  const target = typeName
    ? resolveAwnSchemaTargetForType(resolvedType)
    : resolveAwnSchemaTargetForContext();
  const merged = cache ? resolveTopicSchemaMergedType(target, cache) : null;
  if (merged?.fields) {
    const baseTypeDef = awnTypesCache?.types?.[resolvedType];
    return {
      name: merged.name || resolvedType,
      kind: merged.kind || baseTypeDef?.kind || "type",
      fields: merged.fields
    };
  }

  const baseTypeDef = awnTypesCache?.types?.[resolvedType];
  if (!baseTypeDef) return null;
  return { name: resolvedType, ...baseTypeDef };
}

// Returns fields defined in typeId that are NOT inherited from its parent type.
// Used to show only the "own" custom fields in the node overview form.
function getTypeOwnFields(typeId) {
  if (!typeId || !awnTypesCache?.types) return {};
  const typeDef = awnTypesCache.types[typeId];
  if (!typeDef?.fields) return {};

  const parentId = typeDef.extends;
  const parentFields = parentId && awnTypesCache.types[parentId]?.fields ? awnTypesCache.types[parentId].fields : {};

  const own = {};
  for (const [key, fieldDef] of Object.entries(typeDef.fields)) {
    if (!parentFields[key]) own[key] = fieldDef;
  }
  return own;
}

function getExternalRecordTypeDef() {
  const baseTypeDef = awnTypesCache?.types?.["awn.record"];
  const manifestPath = getExternalListSchemaManifestPath();
  const cache = manifestPath ? getTopicSchemaCache(manifestPath) : null;
  const merged = cache?.merged?.record;
  if (merged?.fields) {
    return {
      name: merged.name || "awn.record",
      kind: merged.kind || baseTypeDef?.kind || "type",
      fields: merged.fields
    };
  }
  if (baseTypeDef) return { name: "awn.record", ...baseTypeDef };
  return null;
}

function getExternalTableSchemaColumns() {
  const typeDef = getExternalRecordTypeDef();
  const standardKeys = getStandardPropsFieldKeys();
  if (!typeDef?.fields) {
    return standardKeys
      .filter((key) => !HIDDEN_PROPS_FIELD_KEYS.has(key))
      .map((key) => ({
        key,
        label: getPropsFieldMeta(key).label,
        fieldDef: null,
        typeId: null
      }));
  }

  const columns = [];
  const seen = new Set();
  const orderedKeys = [
    ...standardKeys,
    ...getTypeSchemaFieldKeys(typeDef).filter((key) => !standardKeys.includes(key))
  ];

  for (const key of orderedKeys) {
    if (seen.has(key) || HIDDEN_PROPS_FIELD_KEYS.has(key)) continue;
    const fieldDef = typeDef.fields[key];
    if (!fieldDef && !standardKeys.includes(key)) continue;
    seen.add(key);
    columns.push({
      key,
      label: fieldDef?.title || getPropsFieldMeta(key).label || key,
      fieldDef: fieldDef || null,
      typeId: fieldDef ? resolveFieldTypeId(fieldDef.type || "awn.string") : null
    });
  }

  return columns;
}

function getExternalListSortOptions() {
  const seen = new Set(["path", EXTERNAL_TABLE_FILE_COLUMN_KEY]);
  const options = [
    { key: "path", label: "Путь" },
    { key: EXTERNAL_TABLE_FILE_COLUMN_KEY, label: "Название" }
  ];
  for (const column of getExternalTableSchemaColumns()) {
    if (seen.has(column.key) || column.key === "awn-preview") continue;
    seen.add(column.key);
    options.push({ key: column.key, label: column.label });
  }
  return options.length > 1 ? options : EXTERNAL_LIST_SORT_OPTIONS;
}

