function openNavigationHubSlotList(modeId, externalFile = null) {
  openNavigationPanelMode(modeId, externalFile);
  syncAppRouteToUrl({ replace: true });
}

function openNavigationHubSlotPreview(modeId) {
  if (modeId === "media" && supportsDataEntryOverview("media")) {
    openEntryOverviewMemoryTocFromNavigation("media");
    syncAppRouteToUrl({ replace: true });
    return;
  }
  if (modeId === "external" && supportsDataEntryOverview("memory")) {
    openEntryOverviewMemoryTocFromNavigation("external");
    syncAppRouteToUrl({ replace: true });
    return;
  }
  if (isFlatEntryOverviewMemoryKind(modeId)) {
    const spec = DATA_STORAGE_SLOT_SPECS.find((item) => item.defaultMode === modeId);
    if (spec && supportsDataEntryOverview(spec.key)) {
      openEntryOverviewMemoryTocFromNavigation(modeId);
      syncAppRouteToUrl({ replace: true });
      return;
    }
  }
  if (isBundleEntryOverviewMemoryKind(modeId)) {
    openEntryOverviewMemoryTocFromNavigation(modeId);
    syncAppRouteToUrl({ replace: true });
    return;
  }
  openNavigationHubSlotList(modeId);
}

function openNavigationPanelMode(modeId, externalFile = null) {
  if (modeId === "media") {
    nodeMemoryViewActive = false;
    nodeSettingsViewActive = false;
    applyNodeWorkspaceViewUi();
    setContentMode("media");
    return;
  }
  if (modeId === "description") {
    openDescriptionFromOverview();
    return;
  }
  if (modeId === "todo") {
    openTodoFromOverview();
    return;
  }
  openMemoryModeFromOverview(modeId, externalFile);
}

function formatMemoryModeBadgeText(modeId, { exists = false, charCount = 0, count = 0, rowCount = 0, columnCount = 0, files = 0 } = {}) {
  if (modeId === "internal") {
    return exists || charCount > 0 ? String(charCount) : "—";
  }
  if (modeId === "external") {
    return exists || count > 0 ? String(count) : "—";
  }
  if (modeId === "tabular") {
    return exists || rowCount > 0 || columnCount > 0 ? `${rowCount}×${columnCount}` : "—";
  }
  if (modeId === "media") {
    return exists && files > 0 ? String(files) : "—";
  }
  return "—";
}

function getNavigationMemoryBadgeText(modeId, data = {}) {
  if (modeId === "internal") {
    const content = String(data.content || "").trim();
    return formatMemoryModeBadgeText("internal", {
      exists: content.length > 0,
      charCount: content.length
    });
  }
  if (modeId === "external") {
    const files = Array.isArray(data.files) ? data.files : [];
    return formatMemoryModeBadgeText("external", {
      exists: files.length > 0,
      count: files.length
    });
  }
  if (modeId === "tabular") {
    const columns = data.columns || [];
    const rows = data.rows || [];
    return formatMemoryModeBadgeText("tabular", {
      exists: columns.length > 0 || rows.length > 0,
      rowCount: Number(data.rowCount) || rows.length,
      columnCount: columns.length
    });
  }
  if (modeId === "media") {
    const fileCount = Number(data.files) || 0;
    return formatMemoryModeBadgeText("media", {
      exists: Boolean(data.exists),
      files: fileCount
    });
  }
  return null;
}

function createNavigationSectionSearchInput(options = {}) {
  const {
    value = "",
    placeholder = "Поиск...",
    ariaLabel = placeholder,
    onInput
  } = options;

  const wrap = document.createElement("div");
  wrap.className = "node-navigation-section-search menu-search-wrap";

  const inputId = `node-navigation-search-${Math.random().toString(36).slice(2, 9)}`;
  const label = document.createElement("label");
  label.className = "menu-search-bar node-navigation-section-search-bar";
  label.htmlFor = inputId;

  const input = document.createElement("input");
  input.id = inputId;
  input.type = "search";
  input.className = "menu-search-input node-navigation-section-search-input";
  input.placeholder = placeholder;
  input.value = value;
  input.autocomplete = "off";
  input.spellcheck = false;
  input.setAttribute("aria-label", ariaLabel);
  input.addEventListener("input", (event) => {
    event.stopPropagation();
    onInput?.(event.target.value || "");
  });
  input.addEventListener("click", (event) => event.stopPropagation());

  label.append(createMenuSearchIconNode(), input);
  wrap.appendChild(label);
  return wrap;
}

function createNavigationSectionHead(title, options = {}) {
  const variant = [1, 2, 3].includes(options.titleVariant) ? options.titleVariant : 1;
  const viewModeId = options.viewModeId;
  const head = document.createElement("div");
  head.className = `node-navigation-memory-head node-navigation-memory-head--title-v${variant}`;
  if (viewModeId) {
    head.classList.add("node-navigation-memory-head--actionable");
  }

  const titleNode = document.createElement(viewModeId ? "button" : "span");
  titleNode.className = "node-navigation-memory-title";
  if (viewModeId) {
    titleNode.type = "button";
    titleNode.title = `Открыть: ${title}`;
    titleNode.addEventListener("click", (event) => {
      event.stopPropagation();
      openNavigationHubSlotPreview(viewModeId);
    });
  }
  titleNode.textContent = title;

  const rule = document.createElement("span");
  rule.className = "node-navigation-memory-rule";
  rule.setAttribute("aria-hidden", "true");

  head.append(titleNode, rule);

  if (options.search?.enabled) {
    head.appendChild(
      createNavigationSectionSearchInput({
        value: options.search.value ?? "",
        placeholder: options.search.placeholder || "Поиск...",
        ariaLabel: options.search.ariaLabel || options.search.placeholder || "Поиск",
        onInput: options.search.onInput
      })
    );
  }

  if (options.badgeText != null) {
    const badge = document.createElement("span");
    badge.className = `node-navigation-memory-badge node-navigation-memory-badge--${options.badgeModeId || viewModeId || "default"}`;
    badge.textContent = options.badgeText;
    head.appendChild(badge);
  }

  if (viewModeId) {
    const viewBtn = document.createElement("button");
    viewBtn.type = "button";
    viewBtn.className = "node-navigation-memory-view-btn node-overview-action-btn";
    viewBtn.textContent = "Список";
    viewBtn.addEventListener("click", (event) => {
      event.stopPropagation();
      openNavigationHubSlotList(viewModeId, options.externalFile ?? null);
    });
    head.appendChild(viewBtn);
  } else if (options.demoViewButton) {
    const viewBtn = document.createElement("button");
    viewBtn.type = "button";
    viewBtn.className = "node-navigation-memory-view-btn node-overview-action-btn";
    viewBtn.textContent = "Просмотр";
    viewBtn.disabled = true;
    viewBtn.tabIndex = -1;
    head.appendChild(viewBtn);
  }

  return head;
}

