function appendEntryOverviewCodePreviewAfterHeroMain(hero, context, navigationIndex = null) {
  if (!hero || !context) return null;
  if (isEntryOverviewTabularPreviewContext(context)) return null;

  let section = null;
  if (isEntryOverviewTextCodeAsset(context.relativePath)) {
    const indexed = findEntryOverviewMediaItemMeta(navigationIndex, context.relativePath);
    section = createEntryOverviewCodePreviewSection(context, activePath, indexed?.size ?? null);
  }
  if (!section) return null;

  const main = hero.querySelector(".node-navigation-hero-main");
  if (main) main.insertAdjacentElement("afterend", section);
  else hero.appendChild(section);
  return section;
}

async function fetchMediaAssetTextPreview(relativePath, nodePath = activePath, sizeHint = null) {
  if (sizeHint != null && sizeHint > ENTRY_OVERVIEW_CODE_PREVIEW_MAX_BYTES) {
    return { tooLarge: true, size: sizeHint };
  }

  const url = appendCacheBuster(buildMediaAssetUrl(relativePath, nodePath));
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`);
  }

  const contentLength = Number(response.headers.get("content-length") || 0);
  if (contentLength > ENTRY_OVERVIEW_CODE_PREVIEW_MAX_BYTES) {
    return { tooLarge: true, size: contentLength };
  }

  const buffer = await response.arrayBuffer();
  if (buffer.byteLength > ENTRY_OVERVIEW_CODE_PREVIEW_MAX_BYTES) {
    return { tooLarge: true, size: buffer.byteLength };
  }

  const bytes = new Uint8Array(buffer);
  if (bytes.includes(0)) {
    return { binary: true };
  }

  return { text: new TextDecoder("utf-8", { fatal: false }).decode(buffer) };
}

function createEntryOverviewMediaAssetCodeShowcase(context, nodePath = activePath, sizeHint = null) {
  return createEntryOverviewCodePreviewSection(context, nodePath, sizeHint);
}

function createEntryOverviewMediaAssetShowcase(
  context,
  assetKind,
  nodePath = activePath,
  navigationIndex = null
) {
  const relativePath = String(context.relativePath || "");
  const indexed = findEntryOverviewMediaItemMeta(navigationIndex, relativePath);
  const sizeHint = indexed?.size ?? null;

  if (assetKind === "code") {
    return createEntryOverviewMediaAssetCodeShowcase(context, nodePath, sizeHint);
  }

  const assetUrl = appendCacheBuster(buildMediaAssetUrl(relativePath, nodePath));
  const showcase = document.createElement("div");
  showcase.className = `node-entry-overview-media-asset-showcase is-kind-${assetKind}`;

  if (assetKind === "video") {
    const video = document.createElement("video");
    video.className = "node-entry-overview-media-asset-video";
    video.controls = true;
    video.preload = "metadata";
    video.playsInline = true;
    video.src = assetUrl;
    showcase.appendChild(video);
    return showcase;
  }

  if (assetKind === "audio") {
    const visual = document.createElement("div");
    visual.className = "node-entry-overview-media-asset-audio-visual";
    visual.setAttribute("aria-hidden", "true");
    visual.textContent = "🎵";

    const audio = document.createElement("audio");
    audio.className = "node-entry-overview-media-asset-audio";
    audio.controls = true;
    audio.preload = "none";
    audio.src = assetUrl;

    showcase.append(visual, audio);
    return showcase;
  }

  if (assetKind === "image") {
    const img = document.createElement("img");
    img.className = "node-entry-overview-media-asset-image";
    img.alt = context.title || relativePath.split("/").pop() || "";
    img.decoding = "async";
    img.src = assetUrl;
    img.addEventListener("click", () => openMediaAssetExternal(relativePath));
    img.addEventListener("error", () => {
      showcase.replaceChildren();
      showcase.classList.add("is-fallback");
      const fallback = document.createElement("div");
      fallback.className = "node-entry-overview-media-asset-file-fallback";
      fallback.textContent = "🖼";
      showcase.appendChild(fallback);
    });
    showcase.appendChild(img);
    return showcase;
  }

  if (assetKind === "pdf") {
    const frame = document.createElement("iframe");
    frame.className = "node-entry-overview-media-asset-pdf";
    frame.title = context.title || "PDF документ";
    frame.loading = "lazy";
    frame.src = assetUrl;
    showcase.appendChild(frame);
    return showcase;
  }

  const fallback = document.createElement("div");
  fallback.className = "node-entry-overview-media-asset-file-fallback";
  fallback.textContent = getEntryOverviewMediaAssetKindIcon(assetKind);
  showcase.appendChild(fallback);
  return showcase;
}

function createEntryOverviewMediaAssetPanel(
  context,
  title,
  entries,
  nodeMeta,
  navigationIndex = null,
  { entryOverviewNav = null } = {}
) {
  const assetKind = getEntryOverviewMediaAssetKind(context.relativePath);
  const mediaItem = buildEntryOverviewMediaAssetItem(context, navigationIndex);
  const nodePath = activePath;
  const panel = document.createElement("section");
  panel.className = `node-entry-overview-media-asset node-entry-overview-media-asset--${assetKind} node-navigation-hero`;

  const heroNav = createEntryOverviewSiblingNav({ ...(entryOverviewNav || {}), variant: "hero" });
  if (heroNav) panel.appendChild(heroNav);

  if (assetKind !== "code") {
    panel.appendChild(createEntryOverviewMediaAssetShowcase(context, assetKind, nodePath, navigationIndex));
  }

  const main = document.createElement("div");
  main.className = "node-navigation-hero-main node-entry-overview-media-asset-head";

  const kindBadge = document.createElement("span");
  kindBadge.className = `node-entry-overview-media-asset-kind node-entry-overview-kind node-entry-overview-kind--${assetKind}`;
  kindBadge.textContent = `${getEntryOverviewMediaAssetKindIcon(assetKind)} ${getEntryOverviewMediaAssetKindLabel(assetKind)}`;

  const actions = document.createElement("div");
  actions.className = "node-navigation-hero-actions node-entry-overview-media-asset-actions";
  appendEntryOverviewMediaAssetActionButtons(actions, mediaItem, context);

  const titleRow = createHeroTitleRow(title, resolveAwnStatusFromPropEntries(entries), {
    propEntries: entries
  });

  const headerRow = document.createElement("div");
  headerRow.className = "node-navigation-hero-header";
  headerRow.append(titleRow, actions);

  const pathNode = document.createElement("p");
  pathNode.className = "node-navigation-hero-path";
  pathNode.textContent = formatEntryOverviewHeroPathLabel(entries, context.relativePath);

  const metaRow = document.createElement("div");
  metaRow.className = "node-entry-overview-media-asset-meta-row node-navigation-hero-meta-row";
  metaRow.append(kindBadge, pathNode);

  const datesPanel = buildNavigationHeroDatesPanel(nodeMeta, context.relPath);
  if (datesPanel.childElementCount > 0) {
    datesPanel.classList.add("node-entry-overview-media-asset-dates");
  }

  const body = document.createElement("div");
  body.className = "node-navigation-hero-body node-entry-overview-media-asset-body";
  body.append(headerRow, metaRow);

  if (datesPanel.childElementCount > 0) {
    body.appendChild(datesPanel);
  }

  const metaLineParts = [mediaItem.name];
  if (mediaItem.ext) metaLineParts.push(mediaItem.ext.replace(/^\./, "").toUpperCase());
  if (mediaItem.size) metaLineParts.push(formatFileSize(mediaItem.size));
  const metaLine = document.createElement("p");
  metaLine.className = "node-entry-overview-media-asset-meta-line";
  metaLine.textContent = metaLineParts.join(" · ");
  body.appendChild(metaLine);

  main.append(body);
  panel.appendChild(main);
  if (assetKind === "code") {
    appendEntryOverviewCodePreviewAfterHeroMain(panel, context, navigationIndex);
  }
  appendNavigationHeroProps(panel, entries);
  return panel;
}

function isEntryOverviewMediaImageItem(item) {
  if (String(item?.group || "").trim() === "Images") return true;
  const ext = String(item?.ext || "").toLowerCase();
  if (ext && [".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg", ".avif", ".bmp", ".ico"].includes(ext)) {
    return true;
  }
  const name = String(item?.name || item?.path || "");
  const dot = name.lastIndexOf(".");
  const fromName = dot === -1 ? "" : name.slice(dot).toLowerCase();
  return [".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg", ".avif", ".bmp", ".ico"].includes(fromName);
}

function getEntryOverviewMediaItemMetaLine(item) {
  const parts = [];
  const groupLabel = NAVIGATION_MEDIA_GROUP_LABELS[item?.group];
  if (groupLabel) parts.push(groupLabel);
  const displayName = String(item?.displayName || item?.title || "").trim();
  if (item?.name && item.name !== displayName) parts.push(item.name);
  if (item?.path && item.path !== item?.name) parts.push(item.path);
  if (item?.size) parts.push(formatFileSize(item.size));
  return parts.join(" · ");
}

function createEntryOverviewMediaFileLink(item, nodePath, onFileClick) {
  const link = document.createElement("button");
  link.type = "button";
  link.className = "node-entry-overview-media-item";
  link.title = item.path || item.name || "";

  const preview = document.createElement("span");
  preview.className = "node-entry-overview-media-item-preview";

  if (isEntryOverviewMediaImageItem(item)) {
    const img = document.createElement("img");
    img.alt = item.title || item.name || "";
    img.loading = "lazy";
    img.decoding = "async";
    img.src = appendCacheBuster(buildMediaAssetUrl(item.path, nodePath));
    img.addEventListener("error", () => {
      preview.classList.add("is-fallback");
      img.remove();
      const fallback = document.createElement("span");
      fallback.className = "node-entry-overview-media-item-fallback";
      fallback.textContent = "🖼";
      preview.appendChild(fallback);
    });
    preview.appendChild(img);
  } else {
    preview.classList.add("is-icon");
    preview.textContent = getMediaIconForItem(item);
  }

  const body = document.createElement("span");
  body.className = "node-entry-overview-media-item-body";

  const title = document.createElement("span");
  title.className = "node-entry-overview-media-item-title";
  title.textContent = String(item.displayName || item.title || item.name || item.path || "").trim();

  const meta = document.createElement("span");
  meta.className = "node-entry-overview-media-item-meta";
  meta.textContent = getEntryOverviewMediaItemMetaLine(item);

  body.append(title, meta);
  link.append(preview, body);
  appendNavBookTocStatusBadge(link, resolveNavigationItemStatus(item));
  link.addEventListener("click", (event) => {
    event.stopPropagation();
    onFileClick(item);
  });
  return link;
}

function createEntryOverviewMediaGridCard(item, nodePath, onFileClick) {
  const card = document.createElement("article");
  card.className = "node-entry-overview-media-grid-card";
  card.setAttribute("role", "listitem");

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "node-entry-overview-media-grid-btn";
  btn.title = item.path || item.name || "";

  const thumb = document.createElement("span");
  thumb.className = "node-entry-overview-media-grid-thumb";
  const img = document.createElement("img");
  img.alt = item.title || item.name || "";
  img.loading = "lazy";
  img.decoding = "async";
  img.src = appendCacheBuster(buildMediaAssetUrl(item.path, nodePath));
  img.addEventListener("error", () => {
    thumb.classList.add("is-fallback");
    img.remove();
    const fallback = document.createElement("span");
    fallback.className = "node-entry-overview-media-item-fallback";
    fallback.textContent = "🖼";
    thumb.appendChild(fallback);
  });
  thumb.appendChild(img);

  const caption = document.createElement("span");
  caption.className = "node-entry-overview-media-grid-caption";
  caption.textContent = String(item.displayName || item.title || item.name || "").trim();

  const meta = document.createElement("span");
  meta.className = "node-entry-overview-media-grid-meta";
  meta.textContent = getEntryOverviewMediaItemMetaLine(item);

  btn.append(thumb, caption, meta);
  btn.addEventListener("click", (event) => {
    event.stopPropagation();
    onFileClick(item);
  });
  card.appendChild(btn);
  return card;
}

function fillEntryOverviewMediaImageGrid(grid, items, nodePath, onFileClick) {
  for (const item of items) {
    grid.appendChild(createEntryOverviewMediaGridCard(item, nodePath, onFileClick));
  }
}

function appendEntryOverviewMediaImageGrid(parent, items, nodePath, onFileClick) {
  const images = items.filter(isEntryOverviewMediaImageItem);
  if (!images.length) return;

  const wrap = document.createElement("li");
  wrap.className = "node-entry-overview-media-grid-wrap";
  const grid = document.createElement("div");
  grid.className = "node-entry-overview-media-grid";
  grid.setAttribute("role", "list");
  grid.setAttribute("aria-label", "Изображения");
  fillEntryOverviewMediaImageGrid(grid, images, nodePath, onFileClick);
  wrap.appendChild(grid);
  parent.appendChild(wrap);
}

function appendEntryOverviewMediaBookTocList(parentList, node, depth = 0, handlers = {}) {
  const folderLabels = handlers.folderLabels || new Map();
  const folderDescriptions = handlers.folderDescriptions || new Map();
  const folderStatuses = handlers.folderStatuses || new Map();
  const sectionManifestByFolder = handlers.sectionManifestByFolder || new Map();
  const nodePath = handlers.nodePath || getResolvedNodePath(activePath);
  const onFolderClick = handlers.onFolderClick || openMediaCategoryOverviewFromNavigation;
  const onFileClick = handlers.onFileClick || openMediaEntryOverviewFromNavigation;
  const folderEntries = Array.from(node.folders.entries()).sort((a, b) =>
    compareNavigationPathsNatural(a[0], b[0])
  );
  const fileEntries = [...node.files].sort((a, b) => compareNavigationPathsNatural(a.path, b.path));

  for (const [, folderNode] of folderEntries) {
    const folderItem = document.createElement("li");
    folderItem.className = "nav-book-toc-folder";
    folderItem.classList.add(depth === 0 ? "nav-book-toc-folder--root" : "nav-book-toc-folder--nested");
    if (folderNode.folderPath && !isNavigationFolderRegistered(folderNode.folderPath, folderLabels)) {
      folderItem.classList.add("nav-book-toc-folder--unregistered");
    }

    const folderLabel = document.createElement("button");
    folderLabel.type = "button";
    folderLabel.className = "nav-book-toc-folder-label";
    const folderIcon = document.createElement("span");
    folderIcon.className = "nav-book-toc-folder-icon";
    folderIcon.setAttribute("aria-hidden", "true");
    populateNavBookTocFolderLabel(folderLabel, folderIcon, folderNode, folderLabels, {
      folderStatuses,
      folderDescriptions,
      sectionManifestByFolder
    });
    folderLabel.addEventListener("click", (event) => {
      event.stopPropagation();
      onFolderClick(folderNode.folderPath);
    });

    const subList = document.createElement("ul");
    subList.className = "nav-book-toc-list";
    appendEntryOverviewMediaBookTocList(subList, folderNode, depth + 1, {
      ...handlers,
      folderLabels,
      folderDescriptions,
      folderStatuses,
      sectionManifestByFolder
    });

    const childCount = countNavigationFolderItems(folderNode);
    const collapsible = handlers.collapsible !== false && childCount > 0;
    const collapsed =
      collapsible && isNavTocFolderCollapsed(nodePath, folderNode.folderPath, depth);

    const head = document.createElement("div");
    head.className = "nav-book-toc-folder-head";

    let toggleBtn = null;
    let countNode = null;

    if (collapsible) {
      toggleBtn = document.createElement("button");
      toggleBtn.type = "button";
      toggleBtn.className = "nav-book-toc-folder-toggle";
      toggleBtn.setAttribute("aria-expanded", "true");
      toggleBtn.title = "Свернуть ветку";
      const chevron = document.createElement("span");
      chevron.className = "nav-book-toc-folder-chevron";
      chevron.setAttribute("aria-hidden", "true");
      toggleBtn.appendChild(chevron);
      toggleBtn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const nextCollapsed = !folderItem.classList.contains("is-collapsed");
        setNavTocFolderCollapsed(nodePath, folderNode.folderPath, nextCollapsed);
        applyNavTocFolderCollapsedState(folderItem, subList, toggleBtn, countNode, nextCollapsed);
      });
      head.appendChild(toggleBtn);

      countNode = document.createElement("span");
      countNode.className = "nav-book-toc-folder-count";
      countNode.textContent = String(childCount);
      countNode.title = `${childCount} записей`;
    } else {
      const spacer = document.createElement("span");
      spacer.className = "nav-book-toc-folder-toggle-spacer";
      spacer.setAttribute("aria-hidden", "true");
      head.appendChild(spacer);
    }

    head.append(folderLabel);
    if (countNode) head.appendChild(countNode);
    folderItem.append(head, subList);

    if (collapsible) {
      applyNavTocFolderCollapsedState(folderItem, subList, toggleBtn, countNode, collapsed);
    }

    parentList.appendChild(folderItem);
  }

  const imageFiles = fileEntries.filter(isEntryOverviewMediaImageItem);
  const otherFiles = fileEntries.filter((item) => !isEntryOverviewMediaImageItem(item));

  if (imageFiles.length) {
    appendEntryOverviewMediaImageGrid(parentList, imageFiles, nodePath, onFileClick);
  }

  for (const item of otherFiles) {
    const entry = document.createElement("li");
    entry.className = "nav-book-toc-entry nav-book-toc-entry--media";
    if (depth === 0) {
      entry.classList.add("nav-book-toc-entry--root-level");
    }
    entry.appendChild(createEntryOverviewMediaFileLink(item, nodePath, onFileClick));
    parentList.appendChild(entry);
  }
}

function renderEntryOverviewMediaMemoryToc(context, navigationIndex) {
  if (!navigationIndex) return null;

  const { contentFiles, folderLabels, folderDescriptions, folderStatuses, sectionManifestByFolder, folderPaths } =
    navigationIndex;
  const mdItems = [...(contentFiles || [])].sort((a, b) => compareNavigationPathsNatural(a.path, b.path));

  if (!mdItems.length && (!folderPaths || folderPaths.size === 0)) return null;

  const nodePath = getResolvedNodePath(activePath);
  const handlers = {
    folderLabels,
    folderDescriptions,
    folderStatuses,
    sectionManifestByFolder,
    nodePath,
    onFolderClick: openMediaCategoryOverviewFromNavigation,
    onFileClick: openMediaEntryOverviewFromNavigation
  };

  const section = document.createElement("section");
  section.className = "node-entry-overview-memory-toc node-entry-overview-media-toc";

  const nav = document.createElement("nav");
  nav.className = "node-navigation-book-toc node-entry-overview-memory-toc-nav nav-book-toc-tree--guide";
  nav.setAttribute("aria-label", "Оглавление медиа");

  const list = document.createElement("ul");
  list.className = "nav-book-toc-list nav-book-toc-list--root";
  const tree = buildNavigationPathTree(mdItems, folderLabels);
  ensureNavigationTreeFolders(tree, folderPaths, folderLabels);
  appendEntryOverviewMediaBookTocList(list, tree, 0, handlers);
  nav.appendChild(list);
  section.appendChild(nav);
  return section;
}

function renderEntryOverviewFullMemoryToc(context, navigationIndex) {
  if (!navigationIndex) return null;

  if (context.memoryKind === "media") {
    return renderEntryOverviewMediaMemoryToc(context, navigationIndex);
  }

  const { contentFiles, folderLabels, folderDescriptions, folderStatuses, sectionManifestByFolder, folderPaths } =
    navigationIndex;
  const mdItems = [...(contentFiles || [])].sort((a, b) => compareNavigationPathsNatural(a.path, b.path));

  if (!mdItems.length && (!folderPaths || folderPaths.size === 0)) return null;

  const handlers = getEntryOverviewNavigationHandlers(context.memoryKind);

  const section = document.createElement("section");
  section.className = "node-entry-overview-memory-toc";

  const nav = document.createElement("nav");
  nav.className = "node-navigation-book-toc node-entry-overview-memory-toc-nav";
  nav.setAttribute("aria-label", getEntryOverviewTocTitle(context.memoryKind));

  const list = document.createElement("ul");
  list.className = "nav-book-toc-list nav-book-toc-list--root";
  const tree = buildNavigationPathTree(mdItems, folderLabels);
  ensureNavigationTreeFolders(tree, folderPaths, folderLabels);
  appendNavigationBookTocList(list, tree, 0, {
    folderLabels,
    folderDescriptions,
    folderStatuses,
    sectionManifestByFolder,
    showFileTypeLeading: false,
    showBranchLeading: false,
    treeStyle: "guide",
    ...handlers
  });
  nav.classList.add("nav-book-toc-tree--guide");
  nav.appendChild(list);
  section.appendChild(nav);
  return section;
}

async function renderEntryOverview() {
  if (!nodeOverviewContentNode || !activeEntryOverviewContext) return;

  const renderSeq = ++nodeOverviewRenderSeq;
  const context = activeEntryOverviewContext;
  const isMemoryTocRoot = isEntryOverviewMemoryTocRoot(context);
  const isStale = () =>
    renderSeq !== nodeOverviewRenderSeq ||
    activeContentMode !== NODE_ENTRY_OVERVIEW_MODE ||
    !nodeOverviewContentNode;

  const topicPath = getResolvedNodePath(activePath);
  let [entries, rawBody, nodeMeta, navigationIndex] = await Promise.all([
    isMemoryTocRoot ? [] : fetchEntryOverviewProperties(context.relPath, context),
    isMemoryTocRoot ? "" : fetchEntryOverviewBody(context),
    isMemoryTocRoot ? fetchNodeNavigationMeta(topicPath) : fetchNodeNavigationMeta(context.relPath),
    fetchEntryOverviewNavigationIndex(context, topicPath)
  ]);
  const displayTitle = isMemoryTocRoot
    ? "Оглавление"
    : resolveEntryOverviewDisplayTitle(context, entries, navigationIndex);
  if (!isMemoryTocRoot) {
    entryOverviewLoadedBody = String(rawBody || "");
    entryOverviewLoadedBodyPath = normalizeLiveSyncStoragePath(context.relPath || "");
  } else {
    entryOverviewLoadedBody = "";
    entryOverviewLoadedBodyPath = "";
  }
  if (!isMemoryTocRoot) {
    entries = await enrichEntryOverviewPropertiesWithSchema(entries, context);
  }
  if (isStale()) return;

  syncEntryOverviewKindClass(getEntryOverviewKindClass(context.entryKind));
  const mediaAssetKind =
    context.entryKind === "awn.media.asset" ? getEntryOverviewMediaAssetKind(context.relativePath) : null;
  syncEntryOverviewMediaAssetKindClass(mediaAssetKind);

  if (isMemoryTocRoot) {
    const hub = document.createElement("div");
    hub.className = "node-navigation-hub";

    const topicTitle = getEntryOverviewTopicTitle();
    const memoryTrail = renderEntryOverviewMemoryTrail(context, navigationIndex, "Оглавление", topicTitle);
    if (memoryTrail) hub.appendChild(memoryTrail);

    if (isStale()) return;
    appendEntryOverviewSlotPanel(hub, context, topicPath);

    entryOverviewSearchState = { context, navigationIndex, isMemoryTocRoot: true };
    appendEntryOverviewBrowsePanel(hub, context, navigationIndex, { isMemoryTocRoot: true });

    nodeOverviewContentNode.replaceChildren(hub);
    scheduleWorkspaceScrollChromeSync();
    syncDataHubSlugWarning(NODE_ENTRY_OVERVIEW_MODE);
    return;
  }

  const title = displayTitle;
  if (activeEntryOverviewContext && activeEntryOverviewContext.title !== title) {
    activeEntryOverviewContext = { ...activeEntryOverviewContext, title };
  }
  const previewPath = getPropsEntryValueByKey(entries, "awn-preview");
  let preview = previewPath ? buildPreviewUiFromPath(previewPath, context.relPath) : null;
  if (!preview?.imageUrl && context.entryKind !== "awn.media.asset") {
    preview = (await fetchNodeOverviewPreview(context.relPath, entries)) || preview;
  }
  if (isStale()) return;

  const hub = document.createElement("div");
  hub.className = "node-navigation-hub";

  const topicTitle = getEntryOverviewTopicTitle();
  const memoryTrail = renderEntryOverviewMemoryTrail(context, navigationIndex, title, topicTitle);
  if (memoryTrail) hub.appendChild(memoryTrail);

  if (isStale()) return;
  appendEntryOverviewSlotPanel(hub, context, topicPath);

  entryOverviewSearchState = { context, navigationIndex, isMemoryTocRoot: false };

  const entryOverviewNav = buildEntryOverviewSiblingNavOptions(context, navigationIndex);

  const hero =
    context.entryKind === "awn.media.asset"
      ? createEntryOverviewMediaAssetPanel(context, title, entries, nodeMeta, navigationIndex, {
          entryOverviewNav
        })
      : createNavigationHero(preview, title, context.relPath, {
          meta: nodeMeta,
          propEntries: entries,
          pathLabel: formatEntryOverviewHeroPathLabel(entries, context.relativePath),
          thumbWrap: createEntryOverviewThumbWrap(context, preview, title, entries),
          showWorkspaceMarkers: false,
          onEditClick: () => openEntryOverviewEdit(context),
          entryOverviewNav
        });
  hub.appendChild(hero);
  if (context.entryKind !== "awn.media.asset") {
    appendEntryOverviewCodePreviewAfterHeroMain(hero, context, navigationIndex);
  }
  if (isEntryOverviewCategoryContext(context)) {
    await appendEntryOverviewSectionSchemaPanel(hero, context);
    if (isStale()) return;
  }
  appendEntryOverviewAttachmentsAfterHeroProps(hero, entries, rawBody);
  appendEntryOverviewSectionReadmeOffer(hub, context);

  await appendNodeOverviewTypeRegistryFold(hub, context.relPath);
  if (isStale()) return;

  const sectionListAnchor = document.createElement("div");
  sectionListAnchor.className = "node-entry-overview-section-list-anchor hidden";
  sectionListAnchor.setAttribute("aria-hidden", "true");
  hub.appendChild(sectionListAnchor);

  const isCodePreviewFile =
    isEntryOverviewTextCodeAsset(context.relativePath) &&
    !isEntryOverviewTabularPreviewContext(context);
  const isTabularPreview = isEntryOverviewTabularPreviewContext(context);
  let contentPanel = null;
  if (isTabularPreview) {
    contentPanel = renderEntryOverviewTabularContentPart(context, context.relPath, entryOverviewNav);
  } else if (!isCodePreviewFile) {
    contentPanel = renderEntryOverviewContentPart(rawBody, context.relPath, entryOverviewNav, title);
  }
  if (contentPanel) hub.appendChild(contentPanel);

  appendEntryOverviewBrowsePanel(hub, context, navigationIndex, { isMemoryTocRoot: false });

  const topicManifestPath = getActiveNodeApiPath();
  nodeOverviewContentNode.replaceChildren(hub);

  if (topicManifestPath) {
    void appendNodeCommentsBlockToContainer(hub, {
      manifestPath: topicManifestPath,
      nodeTitle: title,
      mode: context.memoryKind === "media" ? "media" : "external",
      file:
        context.memoryKind === "media"
          ? context.relativePath
          : normalizeExternalMemoryMdRelPath(context.relativePath)
    }).then(() => {
      scheduleWorkspaceScrollChromeSync();
      syncDataHubSlugWarning(NODE_ENTRY_OVERVIEW_MODE);
    });
  }

  scheduleWorkspaceScrollChromeSync();
  syncDataHubSlugWarning(NODE_ENTRY_OVERVIEW_MODE);
}

function createNavBookTocLinkIcon({ branch = false, symbol = "" } = {}) {
  const icon = document.createElement("span");
  icon.className = branch
    ? "nav-book-toc-link-icon nav-book-toc-link-icon--branch"
    : "nav-book-toc-link-icon";
  icon.setAttribute("aria-hidden", "true");
  if (!branch) icon.textContent = symbol;
  return icon;
}

const NAV_TOC_COLLAPSED_KEY = "agentcms.navTocCollapsed.v1";

let navTocCollapsedOverridesCache = null;

function getNavTocCollapsedOverrides() {
  if (navTocCollapsedOverridesCache) return navTocCollapsedOverridesCache;
  try {
    const raw = localStorage.getItem(NAV_TOC_COLLAPSED_KEY);
    navTocCollapsedOverridesCache =
      raw && typeof JSON.parse(raw) === "object" && !Array.isArray(JSON.parse(raw))
        ? JSON.parse(raw)
        : {};
  } catch {
    navTocCollapsedOverridesCache = {};
  }
  return navTocCollapsedOverridesCache;
}

function getNavTocCollapseStorageKey(nodePath, folderPath) {
  const base = normalizeMenuNodePath(nodePath || activePath || "");
  const folder = String(folderPath || "")
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "");
  return folder ? `${base}::${folder}` : base;
}

function countNavigationFolderItems(folderNode) {
  if (!folderNode) return 0;
  let count = Array.isArray(folderNode.files) ? folderNode.files.length : 0;
  if (folderNode.folders instanceof Map) {
    for (const [, child] of folderNode.folders) {
      count += countNavigationFolderItems(child);
    }
  }
  return count;
}

function isNavTocFolderCollapsed(nodePath, folderPath, depth = 0) {
  const key = getNavTocCollapseStorageKey(nodePath, folderPath);
  const overrides = getNavTocCollapsedOverrides();
  if (Object.prototype.hasOwnProperty.call(overrides, key)) {
    return Boolean(overrides[key]);
  }
  return depth >= 1;
}

function setNavTocFolderCollapsed(nodePath, folderPath, collapsed) {
  const key = getNavTocCollapseStorageKey(nodePath, folderPath);
  const overrides = getNavTocCollapsedOverrides();
  overrides[key] = Boolean(collapsed);
  navTocCollapsedOverridesCache = overrides;
  try {
    localStorage.setItem(NAV_TOC_COLLAPSED_KEY, JSON.stringify(overrides));
  } catch {
    // ignore quota errors
  }
}

function applyNavTocFolderCollapsedState(folderItem, subList, toggleBtn, countNode, collapsed) {
  folderItem.classList.toggle("is-collapsed", collapsed);
  if (subList) subList.hidden = collapsed;
  if (toggleBtn) {
    toggleBtn.setAttribute("aria-expanded", collapsed ? "false" : "true");
    toggleBtn.setAttribute("aria-label", collapsed ? "Развернуть ветку" : "Свернуть ветку");
    toggleBtn.title = collapsed ? "Развернуть ветку" : "Свернуть ветку";
  }
  if (countNode) {
    countNode.hidden = false;
    countNode.classList.toggle("is-expanded-visible", !collapsed);
  }
}

function appendNavigationBookTocList(parentList, node, depth = 0, handlers = {}) {
  const folderLabels = handlers.folderLabels || new Map();
  const folderDescriptions = handlers.folderDescriptions || new Map();
  const folderStatuses = handlers.folderStatuses || new Map();
  const sectionManifestByFolder = handlers.sectionManifestByFolder || new Map();
  const nodePath = handlers.nodePath || activePath;
  const onFolderClick = handlers.onFolderClick || openExternalCategoryOverviewFromNavigation;
  const onFileClick =
    handlers.onFileClick || ((item) => openExternalRecordOverviewFromNavigation(item));
  const folderEntries = Array.from(node.folders.entries()).sort((a, b) =>
    compareNavigationPathsNatural(a[0], b[0])
  );
  const fileEntries = [...node.files].sort((a, b) => compareNavigationPathsNatural(a.path, b.path));

  for (const [, folderNode] of folderEntries) {
    const folderItem = document.createElement("li");
    folderItem.className = "nav-book-toc-folder";
    if (handlers.treeStyle === "guide") {
      folderItem.classList.add(depth === 0 ? "nav-book-toc-folder--root" : "nav-book-toc-folder--nested");
    }
    if (folderNode.folderPath && !isNavigationFolderRegistered(folderNode.folderPath, folderLabels)) {
      folderItem.classList.add("nav-book-toc-folder--unregistered");
    }

    const folderLabel = document.createElement("button");
    folderLabel.type = "button";
    folderLabel.className = "nav-book-toc-folder-label";
    const folderIcon = document.createElement("span");
    folderIcon.className = "nav-book-toc-folder-icon";
    folderIcon.setAttribute("aria-hidden", "true");
    populateNavBookTocFolderLabel(folderLabel, folderIcon, folderNode, folderLabels, {
      folderStatuses,
      folderDescriptions,
      sectionManifestByFolder
    });
    folderLabel.addEventListener("click", (event) => {
      event.stopPropagation();
      onFolderClick(folderNode.folderPath);
    });

    const subList = document.createElement("ul");
    subList.className = "nav-book-toc-list";
    appendNavigationBookTocList(subList, folderNode, depth + 1, {
      ...handlers,
      folderLabels,
      folderDescriptions,
      folderStatuses,
      sectionManifestByFolder
    });

    const childCount = countNavigationFolderItems(folderNode);
    const collapsible = handlers.collapsible !== false && childCount > 0;
    const collapsed =
      collapsible && isNavTocFolderCollapsed(nodePath, folderNode.folderPath, depth);

    const head = document.createElement("div");
    head.className = "nav-book-toc-folder-head";

    let toggleBtn = null;
    let countNode = null;

    if (collapsible) {
      toggleBtn = document.createElement("button");
      toggleBtn.type = "button";
      toggleBtn.className = "nav-book-toc-folder-toggle";
      toggleBtn.setAttribute("aria-expanded", "true");
      toggleBtn.title = "Свернуть ветку";
      const chevron = document.createElement("span");
      chevron.className = "nav-book-toc-folder-chevron";
      chevron.setAttribute("aria-hidden", "true");
      toggleBtn.appendChild(chevron);
      toggleBtn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const nextCollapsed = !folderItem.classList.contains("is-collapsed");
        setNavTocFolderCollapsed(nodePath, folderNode.folderPath, nextCollapsed);
        applyNavTocFolderCollapsedState(folderItem, subList, toggleBtn, countNode, nextCollapsed);
      });
      head.appendChild(toggleBtn);

      countNode = document.createElement("span");
      countNode.className = "nav-book-toc-folder-count";
      countNode.textContent = String(childCount);
      countNode.title = `${childCount} записей`;
    } else {
      const spacer = document.createElement("span");
      spacer.className = "nav-book-toc-folder-toggle-spacer";
      spacer.setAttribute("aria-hidden", "true");
      head.appendChild(spacer);
    }

    head.append(folderLabel);
    if (countNode) head.appendChild(countNode);
    folderItem.append(head, subList);

    if (collapsible) {
      applyNavTocFolderCollapsedState(folderItem, subList, toggleBtn, countNode, collapsed);
    }

    parentList.appendChild(folderItem);
  }

  for (const item of fileEntries) {
    const entry = document.createElement("li");
    entry.className = "nav-book-toc-entry";
    if (handlers.treeStyle === "guide" && depth === 0) {
      entry.classList.add("nav-book-toc-entry--root-level");
    }

    const link = document.createElement("button");
    link.type = "button";
    link.className = "nav-book-toc-link";
    const itemDescription = getNavigationAwnDescription(item);
    link.title = itemDescription ? `${item.path} (${itemDescription})` : item.path;

    const text = document.createElement("span");
    text.className = "nav-book-toc-link-text";
    appendNavBookTocStatusBadge(text, resolveNavigationItemStatus(item));
    appendNavBookTocTitleText(text, item.title, itemDescription);
    appendNavBookTocWebUrlLink(text, getNavigationItemWebUrl(item));

    const leaders = document.createElement("span");
    leaders.className = "nav-book-toc-leaders";
    populateNavBookTocLeaders(leaders, countNavigationItemAttachments(item));

    const leading =
      handlers.linkLeadingMode === "media"
        ? createNavigationMediaBookTocLinkLeading(item, nodePath)
        : createNavBookTocLinkLeading(item, nodePath, {
            showFileTypeLeading: handlers.showFileTypeLeading,
            showBranchLeading: handlers.showBranchLeading
          });

    if (leading) link.appendChild(leading);
    link.append(text, leaders);
    link.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      onFileClick(item);
    });

    entry.appendChild(link);
    parentList.appendChild(entry);
  }
}

function renderNavigationExternalBookToc(
  items,
  folderLabels = new Map(),
  folderPaths = new Set(),
  folderStatuses = new Map(),
  folderDescriptions = new Map(),
  sectionManifestByFolder = new Map()
) {
  const nav = document.createElement("nav");
  nav.className = "node-navigation-book-toc nav-book-toc-tree--guide";
  nav.setAttribute("aria-label", "Оглавление многофайловой памяти");

  const list = document.createElement("ul");
  list.className = "nav-book-toc-list nav-book-toc-list--root";
  const tree = buildNavigationPathTree(items, folderLabels);
  ensureNavigationTreeFolders(tree, folderPaths, folderLabels);
  appendNavigationBookTocList(list, tree, 0, {
    folderLabels,
    folderDescriptions,
    folderStatuses,
    sectionManifestByFolder,
    showFileTypeLeading: false,
    showBranchLeading: false,
    treeStyle: "guide"
  });
  nav.appendChild(list);
  return nav;
}

function refreshNavigationExternalTocSearch(card) {
  if (!card || !navigationExternalTocState) return;
  const body = card.querySelector(".node-navigation-external");
  if (!body) return;

  body.querySelector(".node-navigation-book-toc")?.remove();
  body.querySelector(".node-navigation-section-search-empty")?.remove();

  const { items, folderLabels, folderDescriptions, folderStatuses, sectionManifestByFolder, folderPaths } =
    navigationExternalTocState;
  const queryLower = navigationExternalTocSearchQuery.trim().toLowerCase();
  const filtered = filterEntryOverviewNavigationIndex(
    {
      contentFiles: items,
      folderPaths: [...folderPaths],
      folderLabels,
      folderDescriptions,
      folderStatuses,
      sectionManifestByFolder
    },
    queryLower
  );
  const filteredFolderPaths =
    filtered.folderPaths instanceof Set
      ? filtered.folderPaths
      : new Set(filtered.folderPaths || []);

  if (filtered.contentFiles.length || filteredFolderPaths.size) {
    body.appendChild(
      renderNavigationExternalBookToc(
        filtered.contentFiles,
        filtered.folderLabels,
        filteredFolderPaths,
        filtered.folderStatuses,
        filtered.folderDescriptions,
        filtered.sectionManifestByFolder
      )
    );
    return;
  }

  if (queryLower) {
    const empty = document.createElement("p");
    empty.className = "node-navigation-section-search-empty";
    empty.textContent = "Ничего не найдено";
    body.appendChild(empty);
  }
}

function renderNavigationExternalPart(externalData) {
  const nonMarkdownFiles = Array.isArray(externalData.nonMarkdownFiles) ? externalData.nonMarkdownFiles : [];
  const { contentFiles, folderLabels, folderDescriptions, folderStatuses, folderPaths, sectionManifestByFolder } = prepareNavigationExternalItems(
    externalData.files || [],
    externalData.folders || []
  );
  const mdItems = contentFiles.sort((a, b) => compareNavigationPathsNatural(a.path, b.path));

  if (!mdItems.length && folderPaths.size === 0 && !nonMarkdownFiles.length) {
    navigationExternalTocState = null;
    return null;
  }

  navigationExternalTocState = {
    items: mdItems,
    folderLabels,
    folderDescriptions,
    folderStatuses,
    sectionManifestByFolder,
    folderPaths
  };

  const body = document.createElement("div");
  body.className = "node-navigation-external";
  appendNavigationExternalNonMdNotice(body, nonMarkdownFiles);

  const showSearch =
    mdItems.length + folderPaths.size >= NAVIGATION_EXTERNAL_SEARCH_MIN_ITEMS;
  const card = document.createElement("section");
  card.className = "node-navigation-memory-card node-navigation-memory-card--external";
  card.append(
    createNavigationSectionHead("Многофайловая память", {
      viewModeId: "external",
      badgeText: getNavigationMemoryBadgeText("external", externalData),
      badgeModeId: "external",
      search: showSearch
        ? {
            enabled: true,
            value: navigationExternalTocSearchQuery,
            placeholder: "Поиск по записям...",
            ariaLabel: "Поиск по записям многофайловой памяти",
            onInput: (value) => {
              navigationExternalTocSearchQuery = value;
              refreshNavigationExternalTocSearch(card);
            }
          }
        : null
    }),
    body
  );

  if (mdItems.length || folderPaths.size > 0) {
    refreshNavigationExternalTocSearch(card);
  }

  return card;
}

function renderNavigationTabularPart(tabularData) {
  const columns = tabularData.columns || [];
  const rows = tabularData.rows || [];

  const body = document.createElement("div");
  body.className = "node-navigation-tabular";

  if (!columns.length && !rows.length) {
    return null;
  }

  appendTabularPreviewTable(body, tabularData, { showMeta: false });

  return createNavigationMemoryPanel("tabular", "Табличная память", body, tabularData);
}

