const NAVIGATION_MEDIA_IMAGE_THUMB_LIMIT = 12;

function createNavigationMediaImageThumb(item, nodePath) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "node-navigation-media-thumb";
  btn.title = item.path || item.name || "";

  const img = document.createElement("img");
  img.alt = item.name || "";
  img.loading = "lazy";
  img.decoding = "async";
  img.src = appendCacheBuster(buildMediaThumbUrl(item.path, nodePath, MEDIA_THUMB_MAX_SMALL));
  img.addEventListener("error", () => {
    btn.classList.add("node-navigation-media-thumb--error");
    img.remove();
    const fallback = document.createElement("span");
    fallback.className = "node-navigation-media-thumb-fallback";
    fallback.textContent = "🖼";
    btn.appendChild(fallback);
  });
  btn.appendChild(img);
  btn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openMediaEntryOverviewFromNavigation(item);
  });
  return btn;
}

function appendNavigationMediaImageStrip(parent, items, nodePath) {
  const images = items.filter((item) => !item.isFolder);
  if (!images.length) return;

  const strip = document.createElement("div");
  strip.className = "node-navigation-media-thumbs";
  strip.setAttribute("role", "list");
  strip.setAttribute("aria-label", "Превью изображений");

  const visible = images.slice(0, NAVIGATION_MEDIA_IMAGE_THUMB_LIMIT);
  for (const item of visible) {
    strip.appendChild(createNavigationMediaImageThumb(item, nodePath));
  }

  if (images.length > NAVIGATION_MEDIA_IMAGE_THUMB_LIMIT) {
    const moreBtn = document.createElement("button");
    moreBtn.type = "button";
    moreBtn.className = "node-navigation-media-thumbs-more";
    moreBtn.textContent = `+${images.length - NAVIGATION_MEDIA_IMAGE_THUMB_LIMIT}`;
    moreBtn.title = "Открыть все изображения";
    moreBtn.addEventListener("click", (event) => {
      event.stopPropagation();
      openNavigationPanelMode("media");
    });
    strip.appendChild(moreBtn);
  }

  parent.appendChild(strip);
}

function renderNavigationMediaPart(mediaData) {
  const groups = mediaData?.groups && typeof mediaData.groups === "object" ? mediaData.groups : {};
  const { contentFiles, folderLabels, folderStatuses, sectionManifestByFolder, folderPaths } = prepareNavigationMediaItems(
    groups,
    mediaData?.sectionManifests || []
  );

  if (!contentFiles.length && folderPaths.size === 0) {
    return null;
  }

  const body = document.createElement("div");
  body.className = "node-navigation-media";
  const nodePath = getResolvedNodePath(activePath);

  const imageItems = Array.isArray(groups.Images) ? groups.Images : [];
  if (imageItems.length) {
    appendNavigationMediaImageStrip(body, imageItems, nodePath);
  }

  const nav = document.createElement("nav");
  nav.className = "node-navigation-book-toc";
  nav.setAttribute("aria-label", "Оглавление медиа");

  const list = document.createElement("ul");
  list.className = "nav-book-toc-list nav-book-toc-list--root";
  const tree = buildNavigationPathTree(contentFiles, folderLabels);
  ensureNavigationTreeFolders(tree, folderPaths, folderLabels);
  appendNavigationBookTocList(list, tree, 0, {
    folderLabels,
    folderStatuses,
    sectionManifestByFolder,
    nodePath,
    linkLeadingMode: "media",
    onFolderClick: openMediaCategoryOverviewFromNavigation,
    onFileClick: openMediaEntryOverviewFromNavigation
  });
  nav.appendChild(list);
  body.appendChild(nav);
  return createNavigationMemoryPanel("media", "Медиа", body, mediaData);
}

async function ensureNavigationManifestCached(options = {}) {
  const forceReload = Boolean(options.forceReload);
  if (!forceReload && getNodeDescriptionHasContent(modeContentCache.description)) return;
  const apiPath = getActiveNodeApiPath();
  if (!apiPath) return;
  try {
    const response = await fetch(buildApiUrl("/api/file", { path: apiPath }));
    if (!response.ok) return;
    const data = await response.json();
    modeContentCache.description = data.content || "";
  } catch {
    // ignore transient manifest read errors in navigation
  }
}

function renderNavigationManifestPart(manifestRaw = "", heroTitle = "") {
  const content = extractManifestDisplayBody(manifestRaw, heroTitle);

  const wrap = document.createElement("div");
  wrap.className = "node-navigation-manifest";

  if (content) {
    const manifestPath = getActiveNodeApiPath();
    const nodePath = manifestPath || getResolvedNodePath(activePath);
    const preview = document.createElement("div");
    preview.className =
      "node-navigation-preview node-navigation-agent-instruction file-content-preview";
    preview.dataset.linkBasePath = nodePath;
    const inlineDiff = filterManifestBodyDiffPayload(
      getActiveLiveSyncInlineDiffForView(manifestPath)
    );
    if (
      inlineDiff &&
      renderPreviewWithEmbeddedDiff(preview, content, inlineDiff, nodePath)
    ) {
      nodeOverviewBlockNode?.classList.add("is-live-diff-active");
    } else {
      preview.innerHTML = renderMarkdownToHtml(content, { nodePath });
      hydrateMarkdownPreviewElement(preview, nodePath);
    }
    wrap.appendChild(preview);
  } else {
    const empty = document.createElement("p");
    empty.className = "node-navigation-empty-placeholder node-navigation-agent-instruction-empty";
    empty.textContent = AGENT_INSTRUCTION_EMPTY_TEXT;
    wrap.appendChild(empty);
  }

  return createNavigationMemoryPanel("description", AGENT_INSTRUCTION_CONTEXT_TITLE, wrap);
}

function renderNavigationTodoPart(todoData) {
  const wrap = document.createElement("div");
  wrap.className = "node-navigation-todo";
  const content = String(todoData?.content || "").trim();
  const previewLimit = 2400;

  if (!content) {
    return null;
  }

  const previewSource =
    content.length > previewLimit ? `${content.slice(0, previewLimit).trim()}…` : content;
  const preview = document.createElement("div");
  preview.className = "node-navigation-todo-content file-content-preview";
  const nodePath = getResolvedNodePath(activePath);
  const todoPath = resolveNodeSidecarRelPath(nodePath, "todo");
  setMarkdownPreviewHtml(preview, previewSource, { nodePath, workspacePath: todoPath });
  wrap.appendChild(preview);

  if (content.length > previewLimit) {
    const note = document.createElement("p");
    note.className = "node-navigation-preview-note";
    note.textContent = `Показано ${previewLimit.toLocaleString("ru-RU")} из ${content.length.toLocaleString("ru-RU")} символов.`;
    wrap.appendChild(note);
  }

  return createNavigationMemoryPanel("todo", "TODO", wrap);
}

const COMMENT_AUTHOR_STORAGE_KEY = "yamlcms.commentAuthor";
const COMMENT_AVATAR_TONES = ["blue", "violet", "green", "slate"];
const COMMENT_MENTION_HANDLE_PATTERN = "[a-zA-Z0-9_\\-.\\u0400-\\u04FF]";
const COMMENT_MENTION_RE = new RegExp(`@(${COMMENT_MENTION_HANDLE_PATTERN}+)`, "g");
const COMMENT_MENTION_TRIGGER_RE = new RegExp(`(?:^|\\s)@(${COMMENT_MENTION_HANDLE_PATTERN}*)$`);

function getStoredCommentAuthor() {
  try {
    return String(localStorage.getItem(COMMENT_AUTHOR_STORAGE_KEY) || "").trim();
  } catch {
    return "";
  }
}

function storeCommentAuthor(author) {
  const value = String(author || "").trim();
  if (!value) return;
  try {
    localStorage.setItem(COMMENT_AUTHOR_STORAGE_KEY, value);
  } catch {
    // ignore storage errors
  }
}

function resolveDialogAuthor() {
  return getStoredCommentAuthor() || "Вы";
}

function stripCommentAuthorDecorations(author) {
  return String(author || "")
    .replace(/[\p{Emoji_Presentation}\p{Extended_Pictographic}]/gu, "")
    .trim();
}

function isAgentCommentAuthor(author) {
  const cleaned = stripCommentAuthorDecorations(author).toLowerCase();
  return cleaned === "агент" || cleaned === "agent";
}

function getCommentAuthorInitials(author) {
  const raw = String(author || "").trim();
  if (!raw) return "?";
  if (isAgentCommentAuthor(raw)) return "🤖";
  const cleaned = stripCommentAuthorDecorations(raw);
  const parts = cleaned.split(/[\s_.-]+/).filter(Boolean);
  if (parts.length >= 2) {
    const first = [...parts[0]][0] || "?";
    const second = [...parts[1]][0] || "?";
    return `${first}${second}`.toUpperCase();
  }
  const chars = [...(parts[0] || "?")];
  return chars.slice(0, 2).join("").toUpperCase();
}

function getCommentAvatarTone(author) {
  if (isAgentCommentAuthor(author)) return "violet";
  const text = stripCommentAuthorDecorations(author);
  let hash = 0;
  for (let index = 0; index < text.length; index += 1) {
    hash = (hash + text.charCodeAt(index) * (index + 1)) % COMMENT_AVATAR_TONES.length;
  }
  return COMMENT_AVATAR_TONES[hash] || "slate";
}

function formatCommentAuthorLabel(author) {
  const cleaned = stripCommentAuthorDecorations(author);
  return cleaned || String(author || "").trim() || "guest";
}

function buildFileCommentsApiParams(context) {
  const params = { mode: context.mode || "description" };
  if (context.path) params.path = context.path;
  if (context.file) params.file = context.file;
  if (context.name) params.name = context.name;
  return params;
}

function buildThreadApiParams(context) {
  const params = { path: context.path || "" };
  if (context.mode) params.mode = context.mode;
  if (context.file) params.file = context.file;
  if (context.name) params.name = context.name;
  return params;
}

function getActiveThreadRequestContext() {
  const base = {
    path: getActiveNodeApiPath(),
    mode: "description",
    file: null,
    name: null
  };
  if (!activeThreadScope) return base;
  return {
    ...base,
    mode: activeThreadScope.mode || "external",
    file: activeThreadScope.file || null,
    name: activeThreadScope.name || null
  };
}

function clearActiveThreadScope() {
  activeThreadScope = null;
}

function openElementThreadDialog(filePath, mode = "external") {
  const file = String(filePath || "").trim();
  if (!file || !activePath) return;
  activeThreadScope = { mode, file, name: null };
  void setContentMode(NODE_THREAD_MODE);
}

function slugifyCommentMentionHandle(text) {
  return String(text || "")
    .trim()
    .replace(/\s+/g, "_")
    .replace(/[^\w\-\.\u0400-\u04FF]/g, "")
    .slice(0, 48);
}

function collectCommentMentionCandidates(options = {}) {
  const agentId = options.agentId || activeAgentId;
  const extraAuthors = Array.isArray(options.authors) ? options.authors : [];
  const candidates = new Map();

  const addCandidate = (handle, label, meta = {}) => {
    const key = slugifyCommentMentionHandle(handle);
    if (!key || candidates.has(key)) return;
    candidates.set(key, { handle: key, label: label || key, ...meta });
  };

  const menu = menuCacheByAgent.get(agentId) || (agentId === activeAgentId ? currentMenuData : null);
  if (menu) {
    for (const entry of collectAgentMenuFlatEntries(menu, agentId, { includeHiddenSections: true })) {
      if (!entry.path) continue;
      const label = entry.label || entry.displayPath || getLabelFromPath(entry.path);
      addCandidate(label, label, { path: entry.path, kind: "topic" });
      addCandidate(getLabelFromPath(entry.path), label, { path: entry.path, kind: "topic" });
    }
  }

  for (const author of extraAuthors) {
    addCandidate(author, author, { kind: "author" });
  }

  addCandidate(resolveDialogAuthor(), resolveDialogAuthor(), { kind: "author" });

  return [...candidates.values()].sort((left, right) =>
    left.label.localeCompare(right.label, "ru")
  );
}

function extractCommentMentions(body) {
  const found = new Set();
  const re = new RegExp(COMMENT_MENTION_RE.source, "g");
  let match;
  while ((match = re.exec(String(body || ""))) !== null) {
    const handle = String(match[1] || "").trim();
    if (handle) found.add(handle);
  }
  return [...found];
}

const COMMENT_MENTION_SEEN_STORAGE_PREFIX = "agentcms.commentMentionsSeen.v1:";

function commentMentionsUser(comment, userHandle) {
  if (!userHandle || !comment) return false;
  const mentions = Array.isArray(comment.mentions)
    ? comment.mentions
    : extractCommentMentions(comment.body || "");
  return mentions.some((mention) => slugifyCommentMentionHandle(mention) === userHandle);
}

function getCommentMentionSeenStorageKey(context) {
  const filePart = context.file ? `:${context.file}` : "";
  return `${COMMENT_MENTION_SEEN_STORAGE_PREFIX}${activeAgentId || "main"}:${context.path}:${context.mode}${filePart}`;
}

function getLastSeenMentionCommentId(context) {
  try {
    return String(localStorage.getItem(getCommentMentionSeenStorageKey(context)) || "").trim();
  } catch {
    return "";
  }
}

function markCommentMentionsSeen(context, commentId) {
  const id = String(commentId || "").trim();
  if (!id) return;
  try {
    localStorage.setItem(getCommentMentionSeenStorageKey(context), id);
  } catch {
    // ignore storage errors
  }
}

function countUnreadCommentMentions(comments, userHandle, context) {
  if (!userHandle) return 0;
  const lastSeen = getLastSeenMentionCommentId(context);
  let count = 0;
  for (const comment of comments) {
    if (commentMentionsUser(comment, userHandle) && (!lastSeen || comment.id > lastSeen)) {
      count += 1;
    }
  }
  return count;
}

function markAllCommentMentionsSeen(context, comments) {
  const items = Array.isArray(comments) ? comments : [];
  if (!items.length) return;
  markCommentMentionsSeen(context, items[0].id);
}

function renderCommentBodyWithMentions(container, text, mentionLookup = new Map()) {
  container.replaceChildren();
  const source = String(text || "");
  if (!source) return;

  const re = new RegExp(COMMENT_MENTION_RE.source, "g");
  let lastIndex = 0;
  let match;

  while ((match = re.exec(source)) !== null) {
    if (match.index > lastIndex) {
      container.appendChild(document.createTextNode(source.slice(lastIndex, match.index)));
    }

    const handle = match[1];
    const candidate = mentionLookup.get(handle);
    if (candidate?.path) {
      const linkBtn = document.createElement("button");
      linkBtn.type = "button";
      linkBtn.className = "node-comment-mention node-comment-mention--link";
      linkBtn.textContent = match[0];
      linkBtn.title = candidate.label || handle;
      linkBtn.addEventListener("click", () => {
        void openNodeFromMenu(candidate.label || getLabelFromPath(candidate.path), candidate.path);
      });
      container.appendChild(linkBtn);
    } else {
      const span = document.createElement("span");
      span.className = "node-comment-mention";
      span.textContent = match[0];
      span.title = `Упоминание ${handle}`;
      container.appendChild(span);
    }

    lastIndex = match.index + match[0].length;
  }

  if (lastIndex < source.length) {
    container.appendChild(document.createTextNode(source.slice(lastIndex)));
  }
}

function buildCommentMentionLookup(candidates) {
  const lookup = new Map();
  for (const candidate of candidates) {
    lookup.set(candidate.handle, candidate);
  }
  return lookup;
}

function attachCommentMentionAutocomplete(textarea, getCandidates) {
  let popup = null;
  let activeIndex = 0;
  let mentionStart = -1;

  const closePopup = () => {
    popup?.remove();
    popup = null;
    activeIndex = 0;
    mentionStart = -1;
  };

  const insertMention = (handle) => {
    const value = textarea.value;
    const cursor = textarea.selectionStart;
    const before = value.slice(0, mentionStart);
    const after = value.slice(cursor);
    const insert = `@${handle} `;
    textarea.value = `${before}${insert}${after}`;
    const pos = before.length + insert.length;
    textarea.setSelectionRange(pos, pos);
    textarea.dispatchEvent(new Event("input", { bubbles: true }));
    closePopup();
    textarea.focus();
  };

  const renderPopup = (items) => {
    closePopup();
    if (!items.length) return;

    popup = document.createElement("div");
    popup.className = "node-comment-mention-popup";
    popup.setAttribute("role", "listbox");

    items.slice(0, 8).forEach((item, index) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "node-comment-mention-option";
      if (index === activeIndex) btn.classList.add("is-active");
      btn.textContent = `@${item.handle}`;
      btn.title = item.label;
      btn.addEventListener("mousedown", (event) => {
        event.preventDefault();
        insertMention(item.handle);
      });
      popup.appendChild(btn);
    });

    const host = textarea.closest(".node-comments-composer-box") || textarea.parentElement;
    host?.appendChild(popup);
  };

  const updateFromCursor = () => {
    const pos = textarea.selectionStart;
    const prefix = textarea.value.slice(0, pos);
    const match = prefix.match(COMMENT_MENTION_TRIGGER_RE);
    if (!match) {
      closePopup();
      return;
    }

    mentionStart = pos - match[0].length + (match[0].startsWith(" ") ? 1 : 0);
    const query = String(match[1] || "").toLowerCase();
    const candidates = getCandidates().filter((candidate) => {
      const handle = candidate.handle.toLowerCase();
      const label = String(candidate.label || "").toLowerCase();
      return !query || handle.startsWith(query) || label.includes(query);
    });

    if (!candidates.length) {
      closePopup();
      return;
    }

    activeIndex = Math.min(activeIndex, candidates.length - 1);
    renderPopup(candidates);
  };

  textarea.addEventListener("input", () => {
    activeIndex = 0;
    updateFromCursor();
  });

  textarea.addEventListener("keydown", (event) => {
    if (!popup) return;
    const options = [...popup.querySelectorAll(".node-comment-mention-option")];
    if (!options.length) return;

    if (event.key === "ArrowDown") {
      event.preventDefault();
      activeIndex = Math.min(activeIndex + 1, options.length - 1);
      options.forEach((node, index) => node.classList.toggle("is-active", index === activeIndex));
      return;
    }

    if (event.key === "ArrowUp") {
      event.preventDefault();
      activeIndex = Math.max(activeIndex - 1, 0);
      options.forEach((node, index) => node.classList.toggle("is-active", index === activeIndex));
      return;
    }

    if (event.key === "Enter" || event.key === "Tab") {
      const active = options[activeIndex];
      if (active) {
        event.preventDefault();
        insertMention(active.textContent.replace(/^@/, ""));
      }
      return;
    }

    if (event.key === "Escape") {
      closePopup();
    }
  });

  textarea.addEventListener("blur", () => {
    window.setTimeout(closePopup, 150);
  });
}

