const LIVE_SYNC_ACK_STORAGE_PREFIX = "yamlcms:live-sync-ack:";
let liveSyncLastActivityId = 0;
let liveSyncBaselineReady = false;
let liveSyncInFlight = false;
let liveSyncPendingChange = null;
let liveSyncMtimeByPath = new Map();
let liveSyncMtimeBaselineReady = false;
let liveSyncOwnSaveUntilByPath = new Map();
let liveSyncInlineDiffState = null;
const LIVE_SYNC_OWN_SAVE_GRACE_MS = 4000;

function normalizeLiveSyncPath(value) {
  return String(value || "")
    .replace(/\\/g, "/")
    .trim()
    .replace(/^\/+/, "")
    .toLowerCase();
}

function getLiveSyncAckStorageKey(agentId = activeAgentId) {
  return `${LIVE_SYNC_ACK_STORAGE_PREFIX}${agentId || "main"}`;
}

function normalizeLiveSyncStoragePath(value) {
  return String(value || "")
    .replace(/\\/g, "/")
    .trim()
    .replace(/^\/+/, "");
}

function normalizeLiveSyncFileKey(pathValue) {
  let normalized = normalizeLiveSyncStoragePath(pathValue).toLowerCase();
  normalized = normalized.replace(/\/awn-storage\/main\/main\.md$/, "/main.md");
  normalized = normalized.replace(/\/awn-storage\/main\.md$/, "/main.md");
  normalized = normalized.replace(/\/awn-storage\/todo\/todo\.md$/, "/todo.md");
  normalized = normalized.replace(/\/awn-storage\/todo\.md$/, "/todo.md");
  normalized = normalized.replace(/\/awn-storage\/main\/main\.csv$/, "/main.csv");
  normalized = normalized.replace(/\/awn-storage\/main\.csv$/, "/main.csv");
  return normalized;
}

function liveSyncPathsReferToSameFile(pathA, pathB) {
  const a = normalizeLiveSyncPath(pathA);
  const b = normalizeLiveSyncPath(pathB);
  if (!a || !b) return false;
  if (a === b) return true;
  if (normalizeLiveSyncFileKey(pathA) === normalizeLiveSyncFileKey(pathB)) return true;

  const sidecarPath = /\.sidecar\.md$/i.test(a) ? a : /\.sidecar\.md$/i.test(b) ? b : "";
  if (sidecarPath) {
    const otherPath = sidecarPath === a ? b : a;
    const sidecarBase = normalizeLiveSyncPath(String(sidecarPath).replace(/\.sidecar\.md$/i, ""));
    const otherBase = normalizeLiveSyncPath(String(otherPath).replace(/\.[^/]+$/i, ""));
    if (sidecarBase && otherBase && sidecarBase === otherBase) return true;
  }

  return false;
}

function getLiveSyncActiveTopicDir() {
  const manifestPath = normalizeLiveSyncStoragePath(getActiveNodeApiPath());
  if (!manifestPath) return "";
  return manifestPath.replace(/\/[^/]+\.md$/i, "");
}

function liveSyncPathBelongsToActiveTopic(pathValue) {
  const topicDir = getLiveSyncActiveTopicDir();
  if (!topicDir) return false;
  const pathNorm = normalizeLiveSyncStoragePath(pathValue);
  if (!pathNorm) return false;
  if (pathNorm === topicDir) return true;
  return pathNorm.startsWith(`${topicDir}/`);
}

function isLiveSyncBroadTopicWatchMode() {
  if (activeContentMode === NODE_NAVIGATION_MODE || activeContentMode === NODE_OVERVIEW_MODE) {
    return true;
  }
  if (activeContentMode !== NODE_ENTRY_OVERVIEW_MODE || !activeEntryOverviewContext) return false;
  return (
    isEntryOverviewMemoryTocRoot(activeEntryOverviewContext) ||
    isEntryOverviewCategoryContext(activeEntryOverviewContext)
  );
}

const LIVE_SYNC_NAVIGATION_EXTERNAL_WATCH_LIMIT = 120;

function collectLiveSyncNavigationStoragePaths(paths) {
  const nodePath = getResolvedNodePath(activePath);
  if (nodePath) {
    paths.add(normalizeLiveSyncStoragePath(resolveNodeSidecarRelPath(nodePath, "tabular")));
  }

  if (!navigationExternalTocState) return;

  let count = 0;
  for (const item of navigationExternalTocState.items || []) {
    if (count >= LIVE_SYNC_NAVIGATION_EXTERNAL_WATCH_LIMIT) break;
    const relPath = getExternalItemContextPath(item, nodePath);
    if (relPath) {
      paths.add(normalizeLiveSyncStoragePath(relPath));
      count += 1;
    }
  }

  if (navigationExternalTocState.sectionManifestByFolder instanceof Map) {
    for (const item of navigationExternalTocState.sectionManifestByFolder.values()) {
      const relPath = getExternalItemContextPath(item, nodePath);
      if (relPath) paths.add(normalizeLiveSyncStoragePath(relPath));
    }
  }
}

function collectLiveSyncEntryOverviewWatchPaths(paths) {
  const ctx = activeEntryOverviewContext;
  if (!ctx) return;

  const nodePath = getResolvedNodePath(activePath);
  if (!isEntryOverviewMemoryTocRoot(ctx) && ctx.relPath) {
    paths.add(normalizeLiveSyncStoragePath(ctx.relPath));
  }

  const navIndex = entryOverviewSearchState?.navigationIndex;
  if (!navIndex) return;

  let count = 0;
  const addPath = (relPath) => {
    if (!relPath || count >= LIVE_SYNC_NAVIGATION_EXTERNAL_WATCH_LIMIT) return;
    paths.add(normalizeLiveSyncStoragePath(relPath));
    count += 1;
  };

  if (ctx.memoryKind === "external") {
    for (const item of navIndex.contentFiles || []) {
      addPath(getExternalItemContextPath(item, nodePath));
    }
    if (navIndex.sectionManifestByFolder instanceof Map) {
      for (const item of navIndex.sectionManifestByFolder.values()) {
        addPath(getExternalItemContextPath(item, nodePath));
      }
    }
    return;
  }

  if (ctx.memoryKind === "media") {
    for (const item of navIndex.contentFiles || []) {
      addPath(getMediaItemContextPath(item.path, nodePath));
    }
    if (navIndex.sectionManifestByFolder instanceof Map) {
      for (const item of navIndex.sectionManifestByFolder.values()) {
        const manifestPath = String(item?.path || item?.relativePath || "").replace(/\\/g, "/");
        if (manifestPath) addPath(getMediaItemContextPath(manifestPath, nodePath));
      }
    }
  }
}

function appendLiveSyncMediaEditorPaths(paths) {
  if (!isMediaLibraryContentMode()) return;
  const manifestPath = getActiveNodeApiPath();
  if (!manifestPath) return;

  if (activeMediaSidecarSourcePath) {
    const sourceRel = buildStorageLayerRef(manifestPath, "media", activeMediaSidecarSourcePath);
    if (sourceRel) paths.add(normalizeLiveSyncStoragePath(sourceRel));
    if (activeMediaSidecarPath) {
      const sidecarRel = buildStorageLayerRef(manifestPath, "media", activeMediaSidecarPath);
      if (sidecarRel) paths.add(normalizeLiveSyncStoragePath(sidecarRel));
    }
  }

  if (activeMediaMarkdownPath) {
    const markdownRel = buildStorageLayerRef(manifestPath, "media", activeMediaMarkdownPath);
    if (markdownRel) paths.add(normalizeLiveSyncStoragePath(markdownRel));
  }
}

function getLiveSyncAckEntry(path, agentId = activeAgentId) {
  const ackMap = loadLiveSyncAckMap(agentId);
  const raw = ackMap[normalizeLiveSyncPath(path)];
  if (typeof raw === "number") return { activity: raw, mtime: null };
  if (raw && typeof raw === "object") {
    return {
      activity: Number(raw.activity) || 0,
      mtime: raw.mtime ? String(raw.mtime) : null
    };
  }
  return { activity: 0, mtime: null };
}

function loadLiveSyncAckMap(agentId = activeAgentId) {
  try {
    const raw = localStorage.getItem(getLiveSyncAckStorageKey(agentId));
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

function saveLiveSyncAckMap(map, agentId = activeAgentId) {
  try {
    localStorage.setItem(getLiveSyncAckStorageKey(agentId), JSON.stringify(map));
  } catch {
    // ignore quota errors
  }
}

function isLiveSyncEventAcknowledged(path, eventId, agentId = activeAgentId) {
  const ack = getLiveSyncAckEntry(path, agentId);
  return eventId > 0 && ack.activity >= eventId;
}

function isLiveSyncExternalAcknowledged(path, mtime, agentId = activeAgentId) {
  const ackMtime = getLiveSyncAckEntry(path, agentId).mtime;
  if (!mtime || !ackMtime) return false;
  return String(ackMtime) >= String(mtime);
}

function acknowledgeLiveSyncChange(path, { eventId = 0, mtime = null } = {}, agentId = activeAgentId) {
  if (!path) return;
  const ackMap = loadLiveSyncAckMap(agentId);
  const key = normalizeLiveSyncPath(path);
  const prev = getLiveSyncAckEntry(path, agentId);
  const next = {
    activity: Math.max(prev.activity, Number(eventId) || 0),
    mtime: mtime ? String(mtime) : prev.mtime
  };
  if (mtime && prev.mtime) {
    next.mtime = String(prev.mtime) >= String(mtime) ? prev.mtime : String(mtime);
  }
  ackMap[key] = next;
  saveLiveSyncAckMap(ackMap, agentId);
}

function resetLiveSyncSession(agentId = activeAgentId) {
  liveSyncLastActivityId = Number(workspaceNotificationsLatestId) || 0;
  liveSyncBaselineReady = false;
  liveSyncMtimeBaselineReady = false;
  liveSyncMtimeByPath = new Map();
  liveSyncOwnSaveUntilByPath = new Map();
  liveSyncPendingChange = null;
  clearLiveSyncInlineDiffState();
  hideLiveFileUpdateBanner();
  hideLiveFileDiffPanel();
}

function liveSyncDiffHasVisibleChanges(diffPayload) {
  const stats = diffPayload?.diff?.stats;
  if (stats && (stats.added || stats.removed)) return true;
  const entries = diffPayload?.diff?.entries;
  return Array.isArray(entries) && entries.some((entry) => entry.type === "add" || entry.type === "remove");
}

function getActiveLiveSyncInlineDiffForView(workspacePath = null) {
  if (!liveSyncInlineDiffState?.diffPayload) return null;
  const diffPath = liveSyncInlineDiffState.path;
  if (!diffPath) return null;

  if (workspacePath) {
    return liveSyncPathsReferToSameFile(workspacePath, diffPath)
      ? liveSyncInlineDiffState.diffPayload
      : null;
  }

  for (const pathValue of getActiveLiveSyncWatchPaths()) {
    if (liveSyncPathsReferToSameFile(pathValue, diffPath)) {
      return liveSyncInlineDiffState.diffPayload;
    }
  }
  return null;
}

function clearLiveSyncInlineDiffState() {
  liveSyncInlineDiffState = null;
  editorSurfaceNode?.classList.remove("is-live-diff-active");
  nodeOverviewBlockNode?.classList.remove("is-live-diff-active");
  editorCodeWrapNode?.classList.remove("is-live-diff-source");
  liveSyncWysiwygDiffRemovedNode?.classList.add("hidden");
  liveSyncWysiwygDiffRemovedNode?.replaceChildren();
  document.querySelectorAll(".live-diff-embedded-active").forEach((node) => {
    node.classList.remove("live-diff-embedded-active");
  });
  editorWysiwygWrapNode
    ?.querySelectorAll(".live-diff-wysiwyg-add")
    .forEach((node) => node.classList.remove("live-diff-wysiwyg-add"));
}

function setLiveSyncInlineDiffState(diffPayload, pathValue) {
  if (!liveSyncDiffHasVisibleChanges(diffPayload)) {
    clearLiveSyncInlineDiffState();
    return;
  }
  liveSyncInlineDiffState = {
    path: normalizeLiveSyncStoragePath(pathValue),
    diffPayload,
    oldContent: diffPayload?.oldContent ?? "",
    newContent: diffPayload?.newContent ?? ""
  };
  editorSurfaceNode?.classList.add("is-live-diff-active");
  refreshLiveSyncInlineDiffView();
}

function refreshLiveSyncInlineDiffView() {
  if (!liveSyncInlineDiffState?.diffPayload) {
    clearLiveSyncInlineDiffState();
    return;
  }

  if (activeContentMode === NODE_NAVIGATION_MODE) {
    void renderNodeNavigation();
    return;
  }
  if (activeContentMode === NODE_OVERVIEW_MODE) {
    void renderNodeOverview();
    return;
  }
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE) {
    void renderEntryOverview();
    return;
  }

  if (editorViewMode === "preview") {
    renderPreviewFromEditor();
  } else if (editorViewMode === "wysiwyg") {
    applyWysiwygLiveDiffHighlights();
  } else if (editorViewMode === "source") {
    applySourceLiveDiffGutter();
    syncEditorLineNumbers();
  }
}

function hydrateMarkdownPreviewElement(element, nodePath) {
  applySyntaxHighlighting(element, { nodePath });
  void typesetMarkdownDiagrams(element);
  void hydrateAwnFenceBlocks(element);
  enhanceMarkdownPreviewImages(element);
}

function renderPreviewWithEmbeddedDiff(element, markdown, diffPayload, nodePath) {
  if (!element || !diffPayload) return false;
  const entries = Array.isArray(diffPayload?.diff?.entries) ? diffPayload.diff.entries : [];
  if (!entries.some((entry) => entry.type === "add" || entry.type === "remove")) {
    return false;
  }

  const isNavigationPreview = element.classList.contains("node-navigation-preview");
  const addedLines = buildLiveDiffAddedLineSet(diffPayload);
  const removedEntries = entries.filter((entry) => entry.type === "remove");

  if (isNavigationPreview) {
    const root = document.createElement("div");
    root.className = "live-diff-embedded-root";

    let sameBuffer = [];
    const flushSame = () => {
      if (!sameBuffer.length) return;
      const chunk = document.createElement("div");
      chunk.className = "live-diff-embedded-chunk";
      chunk.innerHTML = renderMarkdownToHtml(sameBuffer.join("\n"), { nodePath });
      for (const block of chunk.querySelectorAll("p, li, h1, h2, h3, h4, h5, h6, pre, blockquote")) {
        if (blockMatchesLiveDiffAddedLine(block.textContent, addedLines)) {
          block.classList.add("live-diff-embedded-block-add");
        }
      }
      root.appendChild(chunk);
      sameBuffer = [];
    };

    for (const entry of entries) {
      if (entry.type === "same") {
        sameBuffer.push(entry.text ?? "");
        continue;
      }
      flushSame();
      const row = document.createElement("div");
      row.className = `live-diff-embedded-row live-diff-embedded-row--${entry.type}`;
      if (entry.type === "add") {
        const inner = document.createElement("div");
        inner.innerHTML = renderMarkdownToHtml(entry.text ?? "", { nodePath });
        row.appendChild(inner);
      } else {
        row.textContent = entry.text ?? "";
      }
      root.appendChild(row);
    }
    flushSame();
    element.replaceChildren(root);
    element.classList.add("live-diff-embedded-active");
    hydrateMarkdownPreviewElement(element, nodePath);
    return true;
  }

  element.innerHTML = renderMarkdownToHtml(markdown, { nodePath });
  element.classList.add("live-diff-embedded-active");

  for (const block of element.querySelectorAll("p, li, h1, h2, h3, h4, h5, h6, pre, blockquote, td")) {
    if (blockMatchesLiveDiffAddedLine(block.textContent, addedLines)) {
      block.classList.add("live-diff-embedded-block-add");
    }
  }

  if (removedEntries.length) {
    const anchor = element.querySelector("p, li, h1, h2, h3, h4, h5, h6, pre, blockquote, td");
    for (const entry of removedEntries) {
      const ghost = document.createElement("span");
      ghost.className = "live-diff-embedded-inline-remove";
      ghost.textContent = entry.text ?? "";
      if (anchor) {
        anchor.insertAdjacentElement("beforebegin", ghost);
      } else {
        element.prepend(ghost);
      }
    }
  }

  hydrateMarkdownPreviewElement(element, nodePath);
  return true;
}

function renderInlineDiffIntoElement(element, diffPayload, nodePath) {
  if (!element || !diffPayload) return false;
  const entries = Array.isArray(diffPayload?.diff?.entries) ? diffPayload.diff.entries : [];
  if (!entries.length) return false;

  const root = document.createElement("div");
  root.className = "live-diff-inline-root";

  let buffer = [];
  const flushBuffer = () => {
    if (!buffer.length) return;
    const chunk = document.createElement("div");
    chunk.className = "live-diff-md-chunk";
    chunk.innerHTML = renderMarkdownToHtml(buffer.join("\n"), { nodePath });
    root.appendChild(chunk);
    buffer = [];
  };

  for (const entry of entries) {
    if (entry.type === "same") {
      buffer.push(entry.text ?? "");
      continue;
    }
    flushBuffer();
    const row = document.createElement("div");
    row.className = `live-diff-inline-row live-diff-inline-row--${entry.type}`;
    row.dataset.liveDiff = entry.type;
    if (entry.type === "add") {
      const inner = document.createElement("div");
      inner.className = "live-diff-inline-content";
      inner.innerHTML = renderMarkdownToHtml(entry.text ?? "", { nodePath });
      row.appendChild(inner);
    } else {
      row.textContent = entry.text ?? "";
    }
    root.appendChild(row);
  }
  flushBuffer();

  element.replaceChildren(root);
  hydrateMarkdownPreviewElement(element, nodePath);
  return true;
}

function buildLiveDiffAddedLineSet(diffPayload) {
  const set = new Set();
  for (const entry of diffPayload?.diff?.entries || []) {
    if (entry.type === "add" && entry.text != null) set.add(String(entry.text));
  }
  return set;
}

function blockMatchesLiveDiffAddedLine(blockText, addedLines) {
  const text = String(blockText || "").trim();
  if (!text || !addedLines.size) return false;
  if (addedLines.has(text)) return true;
  for (const line of addedLines) {
    const normalized = String(line || "").trim();
    if (normalized && normalized === text) return true;
  }
  return false;
}

function applyWysiwygLiveDiffHighlights() {
  const diffPayload = getActiveLiveSyncInlineDiffForView();
  const host = liveSyncWysiwygDiffRemovedNode;
  const proseMirror =
    editorWysiwygWrapNode?.querySelector(".toastui-editor-ww-container .ProseMirror") ||
    editorWysiwygWrapNode?.querySelector(".ProseMirror");

  proseMirror?.querySelectorAll(".live-diff-wysiwyg-add").forEach((node) => {
    node.classList.remove("live-diff-wysiwyg-add");
  });

  if (!diffPayload || editorViewMode !== "wysiwyg") {
    host?.classList.add("hidden");
    host?.replaceChildren();
    return;
  }

  const removedEntries = diffPayload.diff.entries.filter((entry) => entry.type === "remove");
  if (host) {
    if (removedEntries.length) {
      host.classList.remove("hidden");
      host.replaceChildren();
      const title = document.createElement("div");
      title.className = "live-sync-wysiwyg-diff-removed-title";
      title.textContent = "Удалено агентом / снаружи";
      host.appendChild(title);
      for (const entry of removedEntries) {
        const line = document.createElement("div");
        line.className = "live-sync-wysiwyg-diff-removed-line";
        line.textContent = entry.text ?? "";
        host.appendChild(line);
      }
    } else {
      host.classList.add("hidden");
      host.replaceChildren();
    }
  }

  if (!proseMirror) return;

  const editorDirty =
    isEditorSaveTrackingActive() &&
    savedEditorSnapshot !== null &&
    getEditorSavePayload() !== savedEditorSnapshot;
  if (editorDirty) return;

  const addedLines = buildLiveDiffAddedLineSet(diffPayload);
  for (const block of proseMirror.querySelectorAll(
    "p, li, h1, h2, h3, h4, h5, h6, blockquote, pre, td, th"
  )) {
    if (blockMatchesLiveDiffAddedLine(block.textContent, addedLines)) {
      block.classList.add("live-diff-wysiwyg-add");
    }
  }
}

function applySourceLiveDiffGutter() {
  const diffPayload = getActiveLiveSyncInlineDiffForView();
  if (!diffPayload || editorViewMode !== "source") {
    editorCodeWrapNode?.classList.remove("is-live-diff-source");
    return;
  }

  editorCodeWrapNode?.classList.add("is-live-diff-source");
  if (!editorLineNumbersNode || !editorLineNumbersEnabled) return;

  const addedLines = new Set();
  const removedLines = new Set();
  for (const entry of diffPayload.diff.entries || []) {
    if (entry.type === "add" && entry.newLine) addedLines.add(Number(entry.newLine));
    if (entry.type === "remove" && entry.oldLine) removedLines.add(Number(entry.oldLine));
  }

  const lineCount = Math.max(1, fileContentInputNode.value.split("\n").length);
  const parts = [];
  for (let index = 0; index < lineCount; index += 1) {
    const lineNo = index + 1;
    let className = "live-diff-gutter-line";
    if (addedLines.has(lineNo)) className += " live-diff-gutter-add";
    else if (removedLines.has(lineNo)) className += " live-diff-gutter-remove";
    parts.push(`<span class="${className}">${lineNo}</span>`);
  }
  editorLineNumbersNode.innerHTML = parts.join("");
}

function isLiveSyncEligibleEvent(event) {
  if (!event || typeof event !== "object") return false;
  const action = String(event.action || "").trim().toLowerCase();
  if (action !== "update" && action !== "create") return false;
  const source = String(event.source || "").trim().toLowerCase();
  if (source === "ui") return false;
  const pathValue = String(event.path || "").replace(/\\/g, "/").trim();
  if (!pathValue || pathValue.startsWith(".agent-cms/")) return false;
  return true;
}

function getActiveLiveSyncWatchPaths() {
  const paths = new Set();
  if (activeSystemFile) {
    paths.add(normalizeLiveSyncStoragePath(normalizeSystemFileName(activeSystemFile)));
    return paths;
  }
  if (!activePath) return paths;

  const nodePath = getResolvedNodePath(activePath);
  const manifestPath = getActiveNodeApiPath();

  if (
    activeContentMode === NODE_NAVIGATION_MODE ||
    activeContentMode === NODE_OVERVIEW_MODE
  ) {
    if (manifestPath) paths.add(normalizeLiveSyncStoragePath(manifestPath));
    if (nodePath) {
      paths.add(normalizeLiveSyncStoragePath(resolveNodeSidecarRelPath(nodePath, "content")));
      paths.add(normalizeLiveSyncStoragePath(resolveNodeSidecarRelPath(nodePath, "todo")));
      paths.add(normalizeLiveSyncStoragePath(resolveNodeSidecarRelPath(nodePath, "tabular")));
    }
    collectLiveSyncNavigationStoragePaths(paths);
    return paths;
  }

  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE) {
    collectLiveSyncEntryOverviewWatchPaths(paths);
    return paths;
  }

  const editorPath = getWorkspaceEditorLinkTargetRel();
  if (editorPath) paths.add(normalizeLiveSyncStoragePath(editorPath));
  appendLiveSyncMediaEditorPaths(paths);
  return paths;
}

function getLiveSyncLoadedContentForPath(pathValue) {
  const pathNorm = normalizeLiveSyncPath(pathValue);
  if (!pathNorm) return "";

  if (activeSystemFile && pathNorm === normalizeLiveSyncPath(normalizeSystemFileName(activeSystemFile))) {
    return fileContentInputNode?.value || "";
  }

  const manifestPath = normalizeLiveSyncPath(getActiveNodeApiPath());
  const nodePath = getResolvedNodePath(activePath);
  const internalPath = normalizeLiveSyncPath(resolveNodeSidecarRelPath(nodePath, "content"));
  const todoPath = normalizeLiveSyncPath(resolveNodeSidecarRelPath(nodePath, "todo"));
  const tabularPath = normalizeLiveSyncPath(resolveNodeSidecarRelPath(nodePath, "tabular"));
  const externalPath = normalizeLiveSyncPath(getWorkspaceEditorLinkTargetRel());

  if (pathNorm === manifestPath) {
    return modeContentCache.description ?? fileContentInputNode?.value ?? "";
  }
  if (pathNorm === internalPath) {
    return modeContentCache.internal ?? fileContentInputNode?.value ?? "";
  }
  if (pathNorm === todoPath) {
    return modeContentCache.todo ?? fileContentInputNode?.value ?? "";
  }
  if (pathNorm === tabularPath || liveSyncPathsReferToSameFile(pathNorm, tabularPath)) {
    return modeContentCache.tabular ?? fileContentInputNode?.value ?? "";
  }
  if (pathNorm === externalPath || liveSyncPathsReferToSameFile(pathNorm, externalPath)) {
    return fileContentInputNode?.value ?? modeContentCache.external ?? "";
  }

  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext?.relPath) {
    const entryPath = normalizeLiveSyncPath(activeEntryOverviewContext.relPath);
    if (liveSyncPathsReferToSameFile(pathNorm, entryPath)) {
      return entryOverviewLoadedBody || "";
    }
  }

  if (isMediaLibraryContentMode()) {
    const manifestRel = getActiveNodeApiPath();
    if (activeMediaSidecarPath) {
      const sidecarRel = normalizeLiveSyncPath(
        buildStorageLayerRef(manifestRel, "media", activeMediaSidecarPath)
      );
      if (liveSyncPathsReferToSameFile(pathNorm, sidecarRel)) {
        return fileContentInputNode?.value ?? "";
      }
    }
    if (activeMediaMarkdownPath) {
      const markdownRel = normalizeLiveSyncPath(
        buildStorageLayerRef(manifestRel, "media", activeMediaMarkdownPath)
      );
      if (liveSyncPathsReferToSameFile(pathNorm, markdownRel)) {
        return fileContentInputNode?.value ?? "";
      }
    }
  }

  return fileContentInputNode?.value ?? "";
}

function isLiveSyncOwnSaveActive(pathValue) {
  const until = Number(liveSyncOwnSaveUntilByPath.get(normalizeLiveSyncPath(pathValue))) || 0;
  return until > Date.now();
}

async function markLiveSyncOwnSaveForActivePath() {
  const paths = getActiveLiveSyncWatchPaths();
  if (!paths.size) return;
  const until = Date.now() + LIVE_SYNC_OWN_SAVE_GRACE_MS;
  for (const pathValue of paths) {
    liveSyncOwnSaveUntilByPath.set(normalizeLiveSyncPath(pathValue), until);
  }
  try {
    const revisions = await fetchLiveFileRevisions([...paths]);
    for (const [path, revision] of Object.entries(revisions || {})) {
      if (revision?.mtime) {
        liveSyncMtimeByPath.set(normalizeLiveSyncPath(path), String(revision.mtime));
      }
    }
  } catch {
    // ignore revision refresh errors after save
  }
}

async function fetchLiveFileRevisions(paths) {
  const response = await fetch(buildApiUrl("/api/file/revisions"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ paths: [...paths] })
  });
  if (!response.ok) throw new Error(`revisions:${response.status}`);
  const payload = await response.json();
  return payload?.revisions || {};
}

function setLiveSyncMtimeBaseline(pathValue, mtime) {
  if (!pathValue || !mtime) return;
  liveSyncMtimeByPath.set(normalizeLiveSyncPath(pathValue), String(mtime));
}

async function ensureLiveSyncMtimeBaseline(watchPaths) {
  if (!watchPaths.size) {
    liveSyncMtimeBaselineReady = false;
    liveSyncMtimeByPath = new Map();
    return;
  }

  const revisions = await fetchLiveFileRevisions([...watchPaths]);
  liveSyncMtimeByPath = new Map();
  for (const pathValue of watchPaths) {
    const revision =
      revisions[pathValue] ||
      revisions[
        Object.keys(revisions).find((key) => normalizeLiveSyncPath(key) === normalizeLiveSyncPath(pathValue)) ||
          ""
      ];
    if (revision?.mtime) {
      setLiveSyncMtimeBaseline(pathValue, revision.mtime);
    }
  }
  liveSyncMtimeBaselineReady = true;
}

function liveSyncEventMatchesWatch(event, watchPaths) {
  const eventPath = String(event?.path || "").replace(/\\/g, "/").trim();
  if (!eventPath || !watchPaths.size) return false;

  for (const watchPath of watchPaths) {
    if (liveSyncPathsReferToSameFile(eventPath, watchPath)) return true;
  }

  const manifestPath = resolveWorkspaceNotificationManifestPath(event);
  if (manifestPath) {
    for (const watchPath of watchPaths) {
      if (liveSyncPathsReferToSameFile(manifestPath, watchPath)) return true;
    }
  }

  if (isLiveSyncBroadTopicWatchMode()) {
    const eventPath = String(event?.path || "").replace(/\\/g, "/").trim();
    if (eventPath && liveSyncPathBelongsToActiveTopic(eventPath)) return true;
  }

  return false;
}

function formatLiveSyncPathLabel(pathValue) {
  const normalized = String(pathValue || "").replace(/\\/g, "/").trim();
  if (!normalized) return "файл";
  const parts = normalized.split("/").filter(Boolean);
  return parts.slice(-2).join("/") || normalized;
}

function formatLiveSyncDiffStats(stats) {
  const added = Number(stats?.added) || 0;
  const removed = Number(stats?.removed) || 0;
  if (!added && !removed) return "без видимых строковых изменений";
  const chunks = [];
  if (added) chunks.push(`+${added}`);
  if (removed) chunks.push(`-${removed}`);
  return chunks.join(" / ");
}

async function fetchLiveFileDiff(pathValue, oldContent = null) {
  if (oldContent != null) {
    const response = await fetch(buildApiUrl("/api/file/diff"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: pathValue, oldContent })
    });
    if (!response.ok) throw new Error(`diff:${response.status}`);
    return response.json();
  }
  const response = await fetch(buildApiUrl("/api/file/diff", { path: pathValue }));
  if (!response.ok) throw new Error(`diff:${response.status}`);
  return response.json();
}

function hideLiveFileDiffPanel() {
  liveFileDiffPanelNode?.classList.add("hidden");
  if (!liveSyncInlineDiffState) {
    editorSurfaceNode?.classList.remove("is-live-diff-active");
  }
}

function renderLiveFileDiffPanel(diffPayload, pathValue) {
  if (!liveFileDiffPanelNode || !liveFileDiffPanelBodyNode) return;
  const entries = Array.isArray(diffPayload?.diff?.entries) ? diffPayload.diff.entries : [];
  liveFileDiffPanelTitleNode.textContent = `Изменения: ${formatLiveSyncPathLabel(pathValue)}`;
  liveFileDiffPanelBodyNode.replaceChildren();

  if (diffPayload?.diff?.truncated) {
    const note = document.createElement("div");
    note.className = "live-file-diff-line";
    note.textContent = "Diff слишком большой — показаны только сводка и обновлённый текст.";
    liveFileDiffPanelBodyNode.appendChild(note);
  }

  let rendered = 0;
  for (const entry of entries) {
    if (entry.type === "same") continue;
    rendered += 1;
    const line = document.createElement("div");
    line.className = `live-file-diff-line live-file-diff-line--${entry.type}`;
    const prefix = entry.type === "add" ? "+ " : "- ";
    line.textContent = `${prefix}${entry.text ?? ""}`;
    liveFileDiffPanelBodyNode.appendChild(line);
  }

  if (!rendered && !diffPayload?.diff?.truncated) {
    const empty = document.createElement("div");
    empty.className = "live-file-diff-line";
    empty.textContent = "Строковых изменений не найдено.";
    liveFileDiffPanelBodyNode.appendChild(empty);
  }

  liveFileDiffPanelNode.classList.remove("hidden");
}

function hideLiveFileUpdateBanner() {
  liveFileUpdateBannerNode?.classList.add("hidden");
}

function showLiveFileUpdateBanner(change) {
  if (!liveFileUpdateBannerNode || !change) return;
  liveSyncPendingChange = change;

  const label = formatLiveSyncPathLabel(change.path);
  const statsText = formatLiveSyncDiffStats(change.diff?.stats);
  const dirty = Boolean(change.dirty);
  const external = change.kind === "external" || change.source === "external";

  if (liveFileUpdateBannerTitleNode) {
    if (dirty) {
      liveFileUpdateBannerTitleNode.textContent = external
        ? "Файл изменён снаружи — есть ваши правки"
        : "Файл изменён агентом — есть ваши правки";
    } else {
      liveFileUpdateBannerTitleNode.textContent = external
        ? "Файл обновлён снаружи"
        : "Файл обновлён агентом";
    }
  }
  if (liveFileUpdateBannerDetailNode) {
    const sourceHint = external ? "Cursor или другой редактор" : "агент";
    liveFileUpdateBannerDetailNode.textContent = dirty
      ? `${label}: ${statsText}. Изменение от ${sourceHint}. Обновление перезапишет несохранённые правки.`
      : `${label}: ${statsText}${external ? " (Cursor / внешний редактор)" : ""}.`;
  }

  liveFileUpdateReloadBtn?.classList.toggle("hidden", !dirty);
  liveFileUpdateShowDiffBtn?.classList.toggle(
    "hidden",
    !change.diff?.stats || (!change.diff.stats.added && !change.diff.stats.removed)
  );

  liveFileUpdateBannerNode.classList.remove("hidden");
}

async function applyLiveFileReload(change) {
  if (!change?.path) return;

  const pathNorm = normalizeLiveSyncPath(change.path);
  const manifestPath = normalizeLiveSyncPath(getActiveNodeApiPath());
  const internalPath = normalizeLiveSyncPath(
    resolveNodeSidecarRelPath(getResolvedNodePath(activePath), "content")
  );
  const todoPath = normalizeLiveSyncPath(resolveNodeSidecarRelPath(getResolvedNodePath(activePath), "todo"));
  const tabularPath = normalizeLiveSyncPath(
    resolveNodeSidecarRelPath(getResolvedNodePath(activePath), "tabular")
  );

  if (activeContentMode === NODE_NAVIGATION_MODE || activeContentMode === NODE_OVERVIEW_MODE) {
    const manifestChanged = liveSyncPathsReferToSameFile(change.path, manifestPath);
    if (liveSyncPathsReferToSameFile(change.path, tabularPath)) {
      modeContentCache.tabular = "";
    }
    const needsManifestReload =
      manifestChanged ||
      !getNodeDescriptionHasContent(modeContentCache.description);
    if (needsManifestReload) {
      await loadContentByMode({ forceReload: true });
    }
    if (activeContentMode === NODE_NAVIGATION_MODE) {
      await ensureNavigationManifestCached({ forceReload: manifestChanged });
      await renderNodeNavigation();
    } else if (activeContentMode === NODE_OVERVIEW_MODE) {
      await renderNodeOverview();
    }
    commitEditorSaveBaseline();
    return;
  }

  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext) {
    const ctx = activeEntryOverviewContext;
    const entryPath = normalizeLiveSyncPath(ctx.relPath);
    const isTocOrCategory =
      isEntryOverviewMemoryTocRoot(ctx) || isEntryOverviewCategoryContext(ctx);

    if (isTocOrCategory && liveSyncPathBelongsToActiveTopic(change.path)) {
      await renderEntryOverview();
      commitEditorSaveBaseline();
      return;
    }

    if (!isEntryOverviewMemoryTocRoot(ctx) && liveSyncPathsReferToSameFile(change.path, entryPath)) {
      entryOverviewLoadedBody = "";
      entryOverviewLoadedBodyPath = "";
      await renderEntryOverview();
      commitEditorSaveBaseline();
      return;
    }
  }

  if (activeContentMode === "description" && liveSyncPathsReferToSameFile(change.path, manifestPath)) {
    modeContentCache.description = "";
    await loadContentByMode({ forceReload: true });
    commitEditorSaveBaseline();
    return;
  }

  if (activeContentMode === "internal" && liveSyncPathsReferToSameFile(change.path, internalPath)) {
    modeContentCache.internal = "";
    await loadContentByMode({ forceReload: true });
    commitEditorSaveBaseline();
    return;
  }

  if (activeContentMode === "todo" && liveSyncPathsReferToSameFile(change.path, todoPath)) {
    modeContentCache.todo = "";
    await loadContentByMode({ forceReload: true });
    commitEditorSaveBaseline();
    return;
  }

  if (activeContentMode === "tabular" && liveSyncPathsReferToSameFile(change.path, tabularPath)) {
    modeContentCache.tabular = "";
    tabularDataCache = { columns: [], rows: [], rowCount: 0 };
    await loadContentByMode({ forceReload: true, preserveTabularSource: true });
    commitEditorSaveBaseline();
    return;
  }

  if (activeContentMode === "external" && activeExternalFilePath) {
    const externalPath = normalizeLiveSyncPath(getWorkspaceEditorLinkTargetRel());
    if (liveSyncPathsReferToSameFile(change.path, externalPath)) {
      modeContentCache.external = "";
      await openExternalFile(activeExternalFilePath, { skipRouteSync: true });
      commitEditorSaveBaseline();
      return;
    }
  }

  if (isMediaLibraryContentMode() && activeMediaSidecarSourcePath) {
    const manifestRel = getActiveNodeApiPath();
    const sourceRel = normalizeLiveSyncPath(
      buildStorageLayerRef(manifestRel, "media", activeMediaSidecarSourcePath)
    );
    const sidecarRel = activeMediaSidecarPath
      ? normalizeLiveSyncPath(buildStorageLayerRef(manifestRel, "media", activeMediaSidecarPath))
      : "";
    if (
      liveSyncPathsReferToSameFile(change.path, sourceRel) ||
      (sidecarRel && liveSyncPathsReferToSameFile(change.path, sidecarRel))
    ) {
      await openMediaSidecar(activeMediaSidecarSourcePath, { skipRouteSync: true });
      commitEditorSaveBaseline();
      return;
    }
  }

  if (isMediaLibraryContentMode() && activeMediaMarkdownPath) {
    const markdownRel = normalizeLiveSyncPath(
      buildStorageLayerRef(getActiveNodeApiPath(), "media", activeMediaMarkdownPath)
    );
    if (liveSyncPathsReferToSameFile(change.path, markdownRel)) {
      await openMediaMarkdownFile(activeMediaMarkdownPath, { skipRouteSync: true });
      commitEditorSaveBaseline();
      return;
    }
  }

  if (activeSystemFile && pathNorm === normalizeLiveSyncPath(normalizeSystemFileName(activeSystemFile))) {
    await selectAgentSystemFile(activeLabel, activeSystemFile, { skipRouteSync: true, forceReload: true });
    commitEditorSaveBaseline();
  }
}

async function presentLiveFileChange(change, diffPayload = null) {
  if (!change?.path) return;

  const diffData =
    diffPayload ||
    (change.diff ? { diff: change.diff, oldContent: change.oldContent, newContent: change.newContent } : null);

  if (liveSyncDiffHasVisibleChanges(diffData)) {
    setLiveSyncInlineDiffState(diffData, change.path);
  }

  if (!change.dirty) {
    await applyLiveFileReload(change);
  }
  void markLiveSyncOwnSaveForActivePath();

  showLiveFileUpdateBanner(change);
  if (liveSyncDiffHasVisibleChanges(diffData)) {
    renderLiveFileDiffPanel(diffData, change.path);
  } else {
    hideLiveFileDiffPanel();
    clearLiveSyncInlineDiffState();
  }
}

async function handleLiveFileChange(event) {
  const pathValue = String(event.path || "").replace(/\\/g, "/").trim();
  if (!pathValue || isLiveSyncEventAcknowledged(pathValue, event.id)) return;

  let diffPayload = null;
  try {
    diffPayload = await fetchLiveFileDiff(pathValue);
  } catch {
    diffPayload = null;
  }

  const dirty =
    isEditorSaveTrackingActive() &&
    savedEditorSnapshot !== null &&
    getEditorSavePayload() !== savedEditorSnapshot;

  await presentLiveFileChange(
    {
      kind: "agent",
      eventId: event.id,
      path: pathValue,
      source: event.source,
      diff: diffPayload?.diff || null,
      dirty
    },
    diffPayload
  );
}

async function handleExternalLiveFileChange(pathValue, revision) {
  const mtime = revision?.mtime ? String(revision.mtime) : "";
  if (!pathValue || !mtime) return;
  if (isLiveSyncExternalAcknowledged(pathValue, mtime)) return;
  if (isLiveSyncOwnSaveActive(pathValue)) {
    setLiveSyncMtimeBaseline(pathValue, mtime);
    return;
  }

  const previousMtime = liveSyncMtimeByPath.get(normalizeLiveSyncPath(pathValue));
  if (previousMtime && previousMtime === mtime) return;

  const oldContent = getLiveSyncLoadedContentForPath(pathValue);
  let diffPayload = null;
  try {
    diffPayload = await fetchLiveFileDiff(pathValue, oldContent);
  } catch {
    diffPayload = null;
  }

  if (!diffPayload?.changed && oldContent === (diffPayload?.newContent ?? oldContent)) {
    setLiveSyncMtimeBaseline(pathValue, mtime);
    return;
  }

  const dirty =
    isEditorSaveTrackingActive() &&
    savedEditorSnapshot !== null &&
    getEditorSavePayload() !== savedEditorSnapshot;

  await presentLiveFileChange(
    {
      kind: "external",
      eventId: 0,
      mtime,
      path: pathValue,
      source: "external",
      diff: diffPayload?.diff || null,
      dirty
    },
    diffPayload
  );
}

async function syncLiveFileExternalRevisions(watchPaths) {
  if (!watchPaths.size) {
    liveSyncMtimeBaselineReady = false;
    liveSyncMtimeByPath = new Map();
    return;
  }

  if (!liveSyncMtimeBaselineReady) {
    await ensureLiveSyncMtimeBaseline(watchPaths);
    return;
  }

  const revisions = await fetchLiveFileRevisions([...watchPaths]);
  for (const pathValue of watchPaths) {
    const revision =
      revisions[pathValue] ||
      revisions[
        Object.keys(revisions).find((key) => normalizeLiveSyncPath(key) === normalizeLiveSyncPath(pathValue)) ||
          ""
      ];
    if (!revision) continue;

    const nextMtime = revision.mtime ? String(revision.mtime) : "";
    const prevMtime = liveSyncMtimeByPath.get(normalizeLiveSyncPath(pathValue)) || "";
    if (!nextMtime || nextMtime === prevMtime) continue;

    if (!prevMtime) {
      setLiveSyncMtimeBaseline(pathValue, nextMtime);
      continue;
    }

    if (!revision.exists) {
      setLiveSyncMtimeBaseline(pathValue, nextMtime);
      continue;
    }

    await handleExternalLiveFileChange(pathValue, revision);
    setLiveSyncMtimeBaseline(pathValue, nextMtime);
  }
}

async function syncLiveFileUpdates() {
  if (liveSyncInFlight || document.hidden || !activeAgentId) return;
  liveSyncInFlight = true;
  try {
    const watchPaths = getActiveLiveSyncWatchPaths();

    const payload = await fetchWorkspaceActivityEvents({
      since: liveSyncBaselineReady && liveSyncLastActivityId > 0 ? liveSyncLastActivityId : 0,
      limit: 100
    });
    const latestId = Number(payload?.latestId) || liveSyncLastActivityId;

    if (!liveSyncBaselineReady) {
      liveSyncLastActivityId = latestId;
      liveSyncBaselineReady = true;
    } else if (watchPaths.size) {
      const incoming = Array.isArray(payload?.events) ? payload.events : [];
      const relevant = incoming
        .filter(isLiveSyncEligibleEvent)
        .filter((event) => liveSyncEventMatchesWatch(event, watchPaths))
        .sort((a, b) => a.id - b.id);

      for (const event of relevant) {
        liveSyncLastActivityId = Math.max(liveSyncLastActivityId, Number(event.id) || 0);
        await handleLiveFileChange(event);
      }

      liveSyncLastActivityId = Math.max(liveSyncLastActivityId, latestId);
    } else {
      liveSyncLastActivityId = Math.max(liveSyncLastActivityId, latestId);
    }

    await syncLiveFileExternalRevisions(watchPaths);
  } catch {
    // ignore transient live sync errors
  } finally {
    liveSyncInFlight = false;
  }
}

function initLiveFileSync() {
  resetLiveSyncSession();

  liveFileUpdateAckBtn?.addEventListener("click", () => {
    const change = liveSyncPendingChange;
    if (!change) {
      hideLiveFileUpdateBanner();
      hideLiveFileDiffPanel();
      return;
    }
    acknowledgeLiveSyncChange(change.path, {
      eventId: change.eventId,
      mtime: change.mtime || null
    });
    hideLiveFileUpdateBanner();
    hideLiveFileDiffPanel();
    clearLiveSyncInlineDiffState();
    liveSyncPendingChange = null;
    if (editorViewMode === "preview") renderPreviewFromEditor();
    else if (editorViewMode === "source") syncEditorLineNumbers();
  });

  liveFileUpdateReloadBtn?.addEventListener("click", () => {
    const change = liveSyncPendingChange;
    if (!change) return;
    const confirmed = window.confirm(
      "Перезагрузить файл и отменить несохранённые правки?"
    );
    if (!confirmed) return;
    void (async () => {
      await applyLiveFileReload(change);
      showLiveFileUpdateBanner({ ...change, dirty: false });
    })();
  });

  liveFileUpdateShowDiffBtn?.addEventListener("click", () => {
    const change = liveSyncPendingChange;
    if (!change) return;
    void (async () => {
      try {
        const oldContent =
          change.kind === "external" ? getLiveSyncLoadedContentForPath(change.path) : null;
        const diffPayload = await fetchLiveFileDiff(change.path, oldContent);
        renderLiveFileDiffPanel(diffPayload, change.path);
      } catch (error) {
        showToast(`Не удалось загрузить diff: ${error.message}`, "error");
      }
    })();
  });

  liveFileDiffPanelCloseBtn?.addEventListener("click", () => {
    hideLiveFileDiffPanel();
  });
}

function syncChannelAutoPoll() {
  stopChannelAutoPoll();
  if (document.hidden || !activePath) return;

  if (activeContentMode === NODE_THREAD_MODE) {
    channelPollTimer = setInterval(() => {
      if (document.hidden || activeContentMode !== NODE_THREAD_MODE || !activePath) return;
      nodeThreadRefreshOnFocus?.();
    }, CHANNEL_POLL_INTERVAL_MS);
    return;
  }

  if (activeContentMode === "inbox") {
    channelPollTimer = setInterval(() => {
      if (document.hidden || activeContentMode !== "inbox" || !activePath) return;
      nodeInboxRefreshOnPoll?.();
    }, CHANNEL_POLL_INTERVAL_MS);
  }
}

const WORKSPACE_NOTIFICATION_ACTION_LABELS = {
  create: "Создано",
  update: "Обновлено",
  delete: "Удалено",
  move: "Перемещено",
  notify: "Уведомление"
};

const WORKSPACE_NOTIFICATION_ACTION_ICONS = {
  create: "➕",
  update: "✏️",
  delete: "🗑",
  move: "↔️",
  notify: "💬"
};

const WORKSPACE_NOTIFICATION_SOURCE_LABELS = {
  mcp: "MCP",
  ui: "UI",
  api: "API",
  system: "система"
};

function getWorkspaceNotificationsSeenStorageKey(agentId = activeAgentId) {
  return agentId ? `${WORKSPACE_NOTIFICATIONS_SEEN_KEY_PREFIX}.${agentId}` : WORKSPACE_NOTIFICATIONS_SEEN_KEY_PREFIX;
}

function loadWorkspaceNotificationsSeenId(agentId = activeAgentId) {
  try {
    const raw = localStorage.getItem(getWorkspaceNotificationsSeenStorageKey(agentId));
    const parsed = Number(raw);
    workspaceNotificationsSeenId = Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
  } catch {
    workspaceNotificationsSeenId = 0;
  }
}

function saveWorkspaceNotificationsSeenId(agentId = activeAgentId) {
  try {
    localStorage.setItem(getWorkspaceNotificationsSeenStorageKey(agentId), String(workspaceNotificationsSeenId));
  } catch {
    // ignore storage errors
  }
}

function readWorkspaceNotificationsCookie(name) {
  const prefix = `${encodeURIComponent(name)}=`;
  for (const part of document.cookie.split("; ")) {
    if (part.startsWith(prefix)) {
      return decodeURIComponent(part.slice(prefix.length));
    }
  }
  return "";
}

function writeWorkspaceNotificationsCookie(name, value, maxAgeDays = 365) {
  document.cookie = `${encodeURIComponent(name)}=${encodeURIComponent(value)}; path=/; max-age=${maxAgeDays * 86400}; SameSite=Lax`;
}

function loadWorkspaceNotificationsFilter() {
  const saved = String(readWorkspaceNotificationsCookie(WORKSPACE_NOTIFICATIONS_FILTER_COOKIE) || "").toLowerCase();
  workspaceNotificationsFilter = WORKSPACE_NOTIFICATIONS_FILTER_VALUES.has(saved) ? saved : "all";
}

function saveWorkspaceNotificationsFilter() {
  writeWorkspaceNotificationsCookie(WORKSPACE_NOTIFICATIONS_FILTER_COOKIE, workspaceNotificationsFilter);
}

function loadWorkspaceNotificationsMuted() {
  workspaceNotificationsMuted = readWorkspaceNotificationsCookie(WORKSPACE_NOTIFICATIONS_MUTED_COOKIE) === "1";
}

function saveWorkspaceNotificationsMuted() {
  writeWorkspaceNotificationsCookie(
    WORKSPACE_NOTIFICATIONS_MUTED_COOKIE,
    workspaceNotificationsMuted ? "1" : "0"
  );
}

function isWorkspaceNotificationsContextActive() {
  return Boolean(activeAgentId) && !appRootNode?.classList.contains("app-landing-view");
}

function syncWorkspaceNotificationsAvailability() {
  const wrap = workspaceNotificationsBtn?.closest(".header-notifications-wrap");
  const active = isWorkspaceNotificationsContextActive();
  const wasActive = Boolean(wrap && !wrap.classList.contains("hidden"));
  wrap?.classList.toggle("hidden", !active);
  if (!active) {
    closeWorkspaceNotificationsPopover();
    return;
  }
  if (!wasActive) {
    workspaceNotificationsInitialLoadDone = false;
    workspaceNotificationsAnnouncedUpToId = 0;
    void refreshWorkspaceNotifications(false);
  }
}

function syncWorkspaceNotificationsMuteUi() {
  if (workspaceNotificationsMuteBtn) {
    workspaceNotificationsMuteBtn.textContent = workspaceNotificationsMuted ? "🔔 Включить" : "🔕 Отключить";
    workspaceNotificationsMuteBtn.classList.toggle("is-muted", workspaceNotificationsMuted);
    workspaceNotificationsMuteBtn.setAttribute("aria-pressed", workspaceNotificationsMuted ? "true" : "false");
    workspaceNotificationsMuteBtn.title = workspaceNotificationsMuted
      ? "Снова показывать badge, звук и toast"
      : "Отключить badge, звук и toast — журнал останется";
  }
  workspaceNotificationsBtn?.classList.toggle("is-muted", workspaceNotificationsMuted);
  if (workspaceNotificationsBtnIconNode) {
    workspaceNotificationsBtnIconNode.textContent = workspaceNotificationsMuted ? "🔕" : "🔔";
  }
  if (workspaceNotificationsBtn) {
    workspaceNotificationsBtn.title = workspaceNotificationsMuted
      ? "Уведомления отключены — журнал доступен"
      : "Уведомления об изменениях workspace";
    workspaceNotificationsBtn.setAttribute(
      "aria-label",
      workspaceNotificationsMuted ? "Уведомления отключены" : "Уведомления"
    );
  }
}

function toggleWorkspaceNotificationsMuted() {
  workspaceNotificationsMuted = !workspaceNotificationsMuted;
  saveWorkspaceNotificationsMuted();
  if (workspaceNotificationsMuted) {
    markWorkspaceNotificationsRead();
  }
  syncWorkspaceNotificationsMuteUi();
  syncWorkspaceNotificationsBadge();
  syncWorkspaceNotificationsHint();
}

function matchesWorkspaceNotificationFilter(event, filter = workspaceNotificationsFilter) {
  if (!filter || filter === "all") return true;
  if (filter === "notify") return String(event.action || "").toLowerCase() === "notify";
  return String(event.source || "").toLowerCase() === filter;
}

function getFilteredWorkspaceNotificationEvents() {
  return workspaceNotificationsEvents.filter((event) => matchesWorkspaceNotificationFilter(event));
}

function syncWorkspaceNotificationsFilterUi() {
  if (!workspaceNotificationsFiltersNode) return;
  for (const button of workspaceNotificationsFiltersNode.querySelectorAll("[data-filter]")) {
    button.classList.toggle(
      "is-active",
      String(button.getAttribute("data-filter") || "") === workspaceNotificationsFilter
    );
  }
}

function reconcileWorkspaceNotificationsSeenId() {
  if (workspaceNotificationsLatestId <= 0) return;
  if (workspaceNotificationsSeenId > workspaceNotificationsLatestId) {
    workspaceNotificationsSeenId = 0;
    saveWorkspaceNotificationsSeenId();
  }
}

function syncWorkspaceNotificationsFooter() {
  if (workspaceNotificationsClearBtn) {
    workspaceNotificationsClearBtn.disabled = !workspaceNotificationsEvents.length;
  }
}

function getWorkspaceNotificationFilterLabel(filter = workspaceNotificationsFilter) {
  if (filter === "mcp") return "MCP";
  if (filter === "ui") return "UI";
  if (filter === "notify") return "💬";
  return "Все";
}

function syncWorkspaceNotificationsHint() {
  const filtered = getFilteredWorkspaceNotificationEvents();
  const filteredCount = filtered.length;
  const unread = getWorkspaceNotificationUnreadCount();
  const filterLabel = getWorkspaceNotificationFilterLabel();

  if (workspaceNotificationsCountBadgeNode) {
    const displayUnread = workspaceNotificationsMuted ? 0 : unread;
    workspaceNotificationsCountBadgeNode.textContent = String(displayUnread > 0 ? displayUnread : filteredCount);
    workspaceNotificationsCountBadgeNode.classList.toggle("hidden", filteredCount <= 0 && displayUnread <= 0);
    workspaceNotificationsCountBadgeNode.classList.toggle("is-unread", displayUnread > 0);
  }

  if (workspaceNotificationsMetaNode) {
    const countLabel =
      filteredCount === 0
        ? "пусто"
        : workspaceNotificationsFilter !== "all" && filteredCount !== workspaceNotificationsEvents.length
          ? `${filteredCount}/${workspaceNotificationsEvents.length}`
          : String(filteredCount);
    const mutedSuffix = workspaceNotificationsMuted ? " · выкл" : "";
    workspaceNotificationsMetaNode.textContent = `${filterLabel} · ${countLabel} · до ${WORKSPACE_NOTIFICATIONS_FETCH_LIMIT}${mutedSuffix}`;
    workspaceNotificationsMetaNode.dataset.filter = workspaceNotificationsFilter;
  }

  if (workspaceNotificationsNoteNode) {
    let note = "";
    if (workspaceNotificationsTruncated) {
      note = `В файле ${workspaceNotificationsFileLines || "много"} строк — архив activity-archive.jsonl`;
    }
    workspaceNotificationsNoteNode.textContent = note;
    workspaceNotificationsNoteNode.classList.toggle("hidden", !note);
  }
}

function getWorkspaceNotificationUnreadCount() {
  return workspaceNotificationsEvents.filter((event) => event.id > workspaceNotificationsSeenId).length;
}

function formatWorkspaceNotificationAction(action) {
  return WORKSPACE_NOTIFICATION_ACTION_LABELS[String(action || "").toLowerCase()] || "Изменено";
}

function formatWorkspaceNotificationSource(source) {
  const normalized = String(source || "system").toLowerCase();
  return WORKSPACE_NOTIFICATION_SOURCE_LABELS[normalized] || normalized.toUpperCase();
}

function getWorkspaceNotificationDayStart(iso) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return null;
  const d = new Date(t);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}

function formatWorkspaceNotificationDayLabel(iso) {
  if (!iso) return "—";
  try {
    const dayStart = getWorkspaceNotificationDayStart(iso);
    if (dayStart == null) return "—";
    const todayStart = getWorkspaceNotificationDayStart(new Date().toISOString());
    const diffDays = Math.floor((todayStart - dayStart) / 86400000);
    if (diffDays === 0) return "Сегодня";
    if (diffDays === 1) return "Вчера";
    return new Date(dayStart).toLocaleDateString("ru-RU", {
      weekday: "long",
      day: "numeric",
      month: "long",
      year: "numeric"
    });
  } catch {
    return "—";
  }
}

function formatWorkspaceNotificationClock(iso) {
  if (!iso) return "—";
  try {
    const d = new Date(iso);
    const dayStart = getWorkspaceNotificationDayStart(iso);
    const todayStart = getWorkspaceNotificationDayStart(new Date().toISOString());
    const diffDays = dayStart == null || todayStart == null ? null : Math.floor((todayStart - dayStart) / 86400000);
    const time = d.toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit" });
    if (diffDays === 0) return time;
    if (diffDays === 1) return `Вчера, ${time}`;
    if (diffDays != null && diffDays < 7) {
      const day = d.toLocaleDateString("ru-RU", { day: "numeric", month: "short" });
      return `${day}, ${time}`;
    }
    return formatNodeMetaDateTime(iso);
  } catch {
    return "—";
  }
}

function resolveWorkspaceNotificationManifestPath(event) {
  if (event?.manifestPath) return String(event.manifestPath).replace(/\\/g, "/");
  const pathValue = String(event?.path || "").replace(/\\/g, "/");
  if (!pathValue || pathValue.startsWith(".agent-cms/")) return null;
  if (pathValue.endsWith("/manifest.md") || pathValue.endsWith("_registration.md")) return pathValue;
  const manifestIndex = pathValue.indexOf("/manifest.md");
  if (manifestIndex >= 0) return pathValue.slice(0, manifestIndex + "/manifest.md".length);
  const owned = resolveOwningManifestRelFromNodePath(pathValue);
  if (owned && /manifest\.md$|_registration\.md$/i.test(owned)) return owned;
  return null;
}

function resolveWorkspaceNotificationOpenPath(event) {
  const pathValue = String(event?.path || "").replace(/\\/g, "/").trim();
  const manifestPath = resolveWorkspaceNotificationManifestPath(event);
  if (pathValue && !pathValue.startsWith(".agent-cms/")) return pathValue;
  return manifestPath || pathValue || "";
}

function resolveWorkspaceNotificationStorageItemLabel(pathValue) {
  const normalized = String(pathValue || "").replace(/\\/g, "/").trim();
  if (!/\/awn-storage\//i.test(normalized)) return "";
  if (/\/(?:config|configuration)\.yml$/i.test(normalized)) {
    const parts = normalized.split("/").filter(Boolean);
    return parts.length >= 2 ? parts[parts.length - 2] : "";
  }
  if (/\/manifest\.md$/i.test(normalized)) {
    const parts = normalized.split("/").filter(Boolean);
    if (parts.length >= 2 && parts[parts.length - 1].toLowerCase() === "manifest.md") {
      return parts[parts.length - 2];
    }
  }
  const base = normalized.split("/").pop() || "";
  if (/\.md$/i.test(base) && base.toLowerCase() !== "manifest.md") {
    return base.replace(/\.md$/i, "");
  }
  return "";
}

function enrichWorkspaceNotificationEvent(event) {
  if (!event || typeof event !== "object") return event;
  let topicName = event.topicName ? String(event.topicName).trim() : "";
  let recordName = event.recordName ? String(event.recordName).trim() : "";
  const pathValue = String(event?.path || "").replace(/\\/g, "/").trim();
  const manifestPath = resolveWorkspaceNotificationManifestPath(event);

  if (currentMenuData) {
    if (!topicName && manifestPath) {
      const node = findMenuNodeInAgentMenu(currentMenuData, manifestPath);
      if (node?.label) topicName = String(node.label).trim();
    }
    if (!recordName && pathValue && pathValue !== manifestPath) {
      const storageLabel = resolveWorkspaceNotificationStorageItemLabel(pathValue);
      if (storageLabel) recordName = storageLabel;
      else {
        const node = findMenuNodeInAgentMenu(currentMenuData, pathValue);
        if (node?.label) recordName = String(node.label).trim();
      }
    }
  } else if (!recordName && pathValue) {
    const storageLabel = resolveWorkspaceNotificationStorageItemLabel(pathValue);
    if (storageLabel) recordName = storageLabel;
  }

  const patch = {};
  if (topicName) patch.topicName = topicName;
  if (recordName) patch.recordName = recordName;
  return Object.keys(patch).length ? { ...event, ...patch } : event;
}

function getWorkspaceNotificationTitle(event) {
  const enriched = enrichWorkspaceNotificationEvent(event);
  return (
    enriched.recordName ||
    enriched.label ||
    enriched.topicName ||
    enriched.path ||
    "—"
  );
}

function getWorkspaceNotificationTopicHint(event) {
  const enriched = enrichWorkspaceNotificationEvent(event);
  const title = getWorkspaceNotificationTitle(event);
  if (enriched.topicName && enriched.topicName !== title) {
    return enriched.topicName;
  }
  return "";
}

function syncWorkspaceNotificationsBadge() {
  if (!workspaceNotificationsBtn || !workspaceNotificationsBadgeNode) return;
  const unread = workspaceNotificationsMuted ? 0 : getWorkspaceNotificationUnreadCount();
  workspaceNotificationsBtn.classList.toggle("has-unread", unread > 0);
  workspaceNotificationsBadgeNode.classList.toggle("hidden", unread <= 0);
  workspaceNotificationsBadgeNode.textContent = unread > 99 ? "99+" : String(unread);
}

function positionWorkspaceNotificationsPopover() {
  const popover = workspaceNotificationsPopoverNode;
  const anchor = workspaceNotificationsBtn;
  if (!popover || !anchor || popover.classList.contains("hidden")) return;
  const rect = anchor.getBoundingClientRect();
  const width = 392;
  const left = Math.max(12, Math.min(rect.right - width, window.innerWidth - width - 12));
  const top = rect.bottom + 8;
  const maxHeight = Math.max(280, window.innerHeight - top - 16);
  popover.style.top = `${top}px`;
  popover.style.left = `${left}px`;
  popover.style.maxHeight = `${maxHeight}px`;
}

function createWorkspaceNotificationRow(event) {
  const row = document.createElement("button");
  row.type = "button";
  row.className = "workspace-notification-row";
  const isUnread = event.id > workspaceNotificationsSeenId;
  if (isUnread) row.classList.add("is-unread");
  row.setAttribute("role", "listitem");
  row.dataset.notificationId = String(event.id);

  const icon = document.createElement("span");
  const actionKey = String(event.action || "update").toLowerCase();
  icon.className = `workspace-notification-icon is-${actionKey}`;
  icon.textContent = WORKSPACE_NOTIFICATION_ACTION_ICONS[actionKey] || "•";
  icon.setAttribute("aria-hidden", "true");
  row.appendChild(icon);

  const body = document.createElement("span");
  body.className = "workspace-notification-body";

  const top = document.createElement("span");
  top.className = "workspace-notification-top";

  const badges = document.createElement("span");
  badges.className = "workspace-notification-badges";

  const action = document.createElement("span");
  action.className = "workspace-notification-action";
  action.textContent = formatWorkspaceNotificationAction(event.action);
  badges.appendChild(action);

  const source = document.createElement("span");
  source.className = `workspace-notification-source is-${String(event.source || "system").toLowerCase()}`;
  source.textContent = formatWorkspaceNotificationSource(event.source);
  badges.appendChild(source);
  top.appendChild(badges);
  body.appendChild(top);

  const label = document.createElement("span");
  label.className = "workspace-notification-label";
  label.textContent = getWorkspaceNotificationTitle(event);
  body.appendChild(label);

  const topicHint = getWorkspaceNotificationTopicHint(event);
  if (topicHint) {
    const topicNode = document.createElement("span");
    topicNode.className = "workspace-notification-topic";
    topicNode.textContent = topicHint;
    body.appendChild(topicNode);
  }

  if (event.message && event.message !== getWorkspaceNotificationTitle(event)) {
    const messageNode = document.createElement("span");
    messageNode.className = "workspace-notification-message";
    messageNode.textContent = event.message;
    body.appendChild(messageNode);
  }

  const pathText = event.path || "";
  const visiblePath =
    pathText.startsWith(".agent-cms/") && event.action === "notify" ? "" : pathText;
  if (visiblePath) {
    const pathNode = document.createElement("span");
    pathNode.className = "workspace-notification-path";
    pathNode.textContent = visiblePath;
    body.appendChild(pathNode);
  }

  row.appendChild(body);

  const meta = document.createElement("span");
  meta.className = "workspace-notification-meta";

  const num = document.createElement("span");
  num.className = "workspace-notification-num";
  num.textContent = `#${event.id}`;
  meta.appendChild(num);

  const time = document.createElement("time");
  time.className = "workspace-notification-time";
  time.dateTime = event.at || "";
  time.textContent = formatWorkspaceNotificationClock(event.at);
  time.title = formatNodeMetaDateTime(event.at);
  meta.appendChild(time);

  if (isUnread) {
    const unreadDot = document.createElement("span");
    unreadDot.className = "workspace-notification-unread-dot";
    unreadDot.setAttribute("aria-hidden", "true");
    meta.appendChild(unreadDot);
  }

  row.appendChild(meta);
  row.addEventListener("click", (clickEvent) => {
    clickEvent.stopPropagation();
    void openWorkspaceNotification(event);
  });
  return row;
}

function renderWorkspaceNotificationsList() {
  if (!workspaceNotificationsListNode) return;
  workspaceNotificationsListNode.replaceChildren();
  syncWorkspaceNotificationsFilterUi();
  syncWorkspaceNotificationsFooter();
  syncWorkspaceNotificationsHint();

  const filtered = getFilteredWorkspaceNotificationEvents();
  if (!filtered.length) {
    const empty = document.createElement("p");
    empty.className = "workspace-notifications-empty";
    empty.textContent = workspaceNotificationsEvents.length
      ? "Нет уведомлений для выбранного фильтра."
      : "Пока нет изменений. Действия агента через MCP появятся здесь.";
    workspaceNotificationsListNode.appendChild(empty);
    return;
  }

  let lastDayKey = "";
  for (const event of filtered) {
    const dayKey = formatWorkspaceNotificationDayLabel(event.at);
    if (dayKey !== lastDayKey) {
      lastDayKey = dayKey;
      const dayHead = document.createElement("h3");
      dayHead.className = "workspace-notifications-day";
      dayHead.textContent = dayKey;
      workspaceNotificationsListNode.appendChild(dayHead);
    }
    workspaceNotificationsListNode.appendChild(createWorkspaceNotificationRow(event));
  }
}

async function clearWorkspaceNotifications() {
  if (!activeAgentId) return;
  if (workspaceNotificationsEvents.length) {
    const confirmed = await askConfirm(
      "Список в колокольчике станет пустым — все текущие записи исчезнут из активного журнала.",
      {
        title: "Очистить уведомления?",
        hint:
          "Записи не удаляются навсегда. Они дописываются в архивный файл .agent-cms/activity-archive.jsonl в папке агента — туда же попадают старые события при автоматической ротации журнала. Из колокольчика они просто пропадут.",
        okLabel: "Очистить",
        cancelLabel: "Отмена",
        icon: "🔔",
        variant: "warning"
      }
    );
    if (!confirmed) return;
  }
  try {
    const response = await fetch(buildApiUrl("/api/agent/activity/clear"), { method: "POST" });
    if (!response.ok) throw new Error(`activity-clear:${response.status}`);
    workspaceNotificationsEvents = [];
    workspaceNotificationsLatestId = 0;
    workspaceNotificationsTruncated = false;
    workspaceNotificationsFileLines = 0;
    workspaceNotificationsSeenId = 0;
    workspaceNotificationsAnnouncedUpToId = 0;
    saveWorkspaceNotificationsSeenId();
    syncWorkspaceNotificationsBadge();
    syncWorkspaceNotificationsHint();
    renderWorkspaceNotificationsList();
    showToast("Журнал уведомлений очищен", "info");
  } catch (error) {
    showToast(`Не удалось очистить: ${error.message}`, "error");
  }
}

function buildWorkspaceNotificationOpenContext(event) {
  const openPath = resolveWorkspaceNotificationOpenPath(event);
  const manifestPath = resolveWorkspaceNotificationManifestPath(event);
  const label = getWorkspaceNotificationTitle(event) || event?.label || "";
  const context = {
    openPath,
    label,
    nodePath: manifestPath || undefined,
    mode: undefined,
    externalFile: undefined
  };

  const parsed = parseStorageLayerRef(openPath);
  if (!parsed?.relativePath) return context;

  const ownerManifest = manifestPath || resolveOwningManifestRelFromNodePath(openPath);
  if (ownerManifest) context.nodePath = ownerManifest;

  if (parsed.layer === STORAGE_SUBFOLDER_CONTENT) {
    context.mode = "external";
    context.externalFile = parsed.relativePath;
    return context;
  }
  if (parsed.layer === STORAGE_SUBFOLDER_MEDIA) {
    context.mode = "media";
    context.externalFile = parsed.relativePath;
    return context;
  }
  const flatMode = CHPU_SLOT_FOLDER_TO_MODE[parsed.layer];
  if (flatMode && FLAT_STORAGE_SECTION_MODES.has(flatMode)) {
    context.mode = flatMode;
    context.externalFile = parsed.relativePath;
  }
  return context;
}

async function openWorkspaceNotification(event) {
  closeWorkspaceNotificationsPopover();

  const { openPath, label, nodePath, mode, externalFile } = buildWorkspaceNotificationOpenContext(event);

  if (!openPath || (openPath.startsWith(".agent-cms/") && !nodePath)) {
    showToast(label || event?.message || "Уведомление", "info");
    return;
  }

  if (/_registration\.md$/i.test(openPath)) {
    await openNodeFromMenu(label || getLabelFromPath(openPath), openPath, { skipRouteSync: true });
    syncAppRouteToUrl({ push: true });
    return;
  }

  try {
    if (await tryOpenMarkdownLinkByWorkspaceRel(openPath)) {
      syncAppRouteToUrl({ push: true });
      return;
    }

    await openWorkspaceFilePreviewByRelPath(openPath, {
      label,
      nodePath,
      mode,
      externalFile
    });
    syncAppRouteToUrl({ push: true });
  } catch (error) {
    if (nodePath) {
      try {
        await openNodeFromMenu(label || getLabelFromPath(nodePath), nodePath, { skipRouteSync: true });
        syncAppRouteToUrl({ push: true });
        return;
      } catch {
        // fall through to menu lookup
      }
    }
    if (currentMenuData) {
      const menuNode = findMenuNodeInAgentMenu(currentMenuData, openPath);
      if (menuNode?.path) {
        try {
          await openNodeFromMenu(
            label || menuNode.label || getLabelFromPath(menuNode.path),
            menuNode.path,
            { skipRouteSync: true }
          );
          syncAppRouteToUrl({ push: true });
          return;
        } catch {
          // fall through
        }
      }
    }
    showToast(`Не удалось открыть: ${error.message}`, "error");
  }
}

function markWorkspaceNotificationsRead() {
  if (workspaceNotificationsLatestId > workspaceNotificationsSeenId) {
    workspaceNotificationsSeenId = workspaceNotificationsLatestId;
    saveWorkspaceNotificationsSeenId();
  }
  syncWorkspaceNotificationsBadge();
  renderWorkspaceNotificationsList();
}

function openWorkspaceNotificationsPopover() {
  if (!workspaceNotificationsPopoverNode || !workspaceNotificationsBtn) return;
  workspaceNotificationsOpen = true;
  workspaceNotificationsPopoverNode.classList.remove("hidden");
  workspaceNotificationsBtn.setAttribute("aria-expanded", "true");
  markWorkspaceNotificationsRead();
  positionWorkspaceNotificationsPopover();
}

function closeWorkspaceNotificationsPopover() {
  if (!workspaceNotificationsPopoverNode || !workspaceNotificationsBtn) return;
  workspaceNotificationsOpen = false;
  workspaceNotificationsPopoverNode.classList.add("hidden");
  workspaceNotificationsBtn.setAttribute("aria-expanded", "false");
}

function toggleWorkspaceNotificationsPopover() {
  if (workspaceNotificationsOpen) closeWorkspaceNotificationsPopover();
  else openWorkspaceNotificationsPopover();
}

function primeWorkspaceNotificationSound() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    if (!workspaceNotificationsAudioCtx) {
      workspaceNotificationsAudioCtx = new AudioCtx();
    }
    if (workspaceNotificationsAudioCtx.state === "suspended") {
      void workspaceNotificationsAudioCtx.resume();
    }
  } catch {
    // ignore autoplay restrictions until user gesture
  }
}

function resolveWorkspaceNotificationSoundKind(event) {
  if (String(event?.action || "").toLowerCase() === "notify") return "notify";
  const source = String(event?.source || "system").toLowerCase();
  if (source === "mcp" || source === "api") return "mcp";
  return "ui";
}

function playWorkspaceNotificationSound(event) {
  if (document.hidden) return;
  try {
    primeWorkspaceNotificationSound();
    const ctx = workspaceNotificationsAudioCtx;
    if (!ctx) return;
    const kind = resolveWorkspaceNotificationSoundKind(event);
    const now = ctx.currentTime;

    const playTone = (frequency, startOffset, duration, { volume = 0.1, type = "sine" } = {}) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const start = now + startOffset;
      const end = start + duration;
      osc.type = type;
      osc.frequency.setValueAtTime(frequency, start);
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(volume, start + 0.015);
      gain.gain.exponentialRampToValueAtTime(0.0001, end);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(start);
      osc.stop(end + 0.02);
    };

    if (kind === "notify") {
      playTone(659.25, 0, 0.11, { volume: 0.08, type: "triangle" });
      playTone(830.61, 0.09, 0.13, { volume: 0.075, type: "triangle" });
      playTone(987.77, 0.18, 0.16, { volume: 0.07, type: "triangle" });
      return;
    }

    if (kind === "mcp") {
      playTone(880, 0, 0.12, { volume: 0.09 });
      playTone(1174.66, 0.1, 0.16, { volume: 0.07 });
      return;
    }

    playTone(523.25, 0, 0.1, { volume: 0.065 });
    playTone(659.25, 0.08, 0.12, { volume: 0.055 });
  } catch {
    // ignore audio errors
  }
}

async function fetchWorkspaceActivityEvents({ since = 0, limit = WORKSPACE_NOTIFICATIONS_FETCH_LIMIT } = {}) {
  const response = await fetch(
    buildApiUrl("/api/agent/activity", {
      since: since > 0 ? since : undefined,
      limit
    })
  );
  if (!response.ok) throw new Error(`activity:${response.status}`);
  return response.json();
}

function maybeAnnounceWorkspaceNotifications() {
  if (!isWorkspaceNotificationsContextActive()) return;
  if (workspaceNotificationsMuted || workspaceNotificationsOpen || !workspaceNotificationsInitialLoadDone) {
    return;
  }

  const freshEvents = workspaceNotificationsEvents.filter(
    (event) => event.id > workspaceNotificationsAnnouncedUpToId
  );
  if (!freshEvents.length) return;

  const newest = [...freshEvents].sort((a, b) => b.id - a.id)[0];
  workspaceNotificationsAnnouncedUpToId = Math.max(
    workspaceNotificationsAnnouncedUpToId,
    newest.id
  );

  playWorkspaceNotificationSound(newest);
  const latestTitle = getWorkspaceNotificationTitle(newest);
  const toastText =
    newest.action === "notify" && newest.message
      ? latestTitle && latestTitle !== "—" && !newest.message.startsWith(latestTitle)
        ? `${latestTitle}: ${newest.message}`
        : newest.message
      : `${formatWorkspaceNotificationAction(newest.action)} (${formatWorkspaceNotificationSource(newest.source)}): ${latestTitle}`;
  showToast(toastText, "info");
}

async function refreshWorkspaceNotifications(mergeOnly = false) {
  if (!isWorkspaceNotificationsContextActive()) {
    syncWorkspaceNotificationsAvailability();
    return;
  }
  const previousLatestId = workspaceNotificationsLatestId;
  const wasInitialLoadDone = workspaceNotificationsInitialLoadDone;
  try {
    let payload = await fetchWorkspaceActivityEvents({
      since: mergeOnly && previousLatestId > 0 ? previousLatestId : 0,
      limit: WORKSPACE_NOTIFICATIONS_FETCH_LIMIT
    });
    let incoming = Array.isArray(payload?.events) ? payload.events : [];
    let serverLatestId = Number(payload?.latestId) || 0;
    let journalReset = false;

    if (mergeOnly && serverLatestId < previousLatestId) {
      journalReset = true;
      mergeOnly = false;
      payload = await fetchWorkspaceActivityEvents({
        since: 0,
        limit: WORKSPACE_NOTIFICATIONS_FETCH_LIMIT
      });
      incoming = Array.isArray(payload?.events) ? payload.events : [];
      serverLatestId = Number(payload?.latestId) || 0;
      workspaceNotificationsSeenId = 0;
      workspaceNotificationsAnnouncedUpToId = 0;
      saveWorkspaceNotificationsSeenId();
    }

    workspaceNotificationsLatestId = serverLatestId || workspaceNotificationsLatestId;
    workspaceNotificationsTruncated = Boolean(payload?.truncated);
    workspaceNotificationsFileLines = Number(payload?.fileLines) || incoming.length;

    if (mergeOnly && incoming.length) {
      const known = new Set(workspaceNotificationsEvents.map((event) => event.id));
      for (const event of incoming) {
        if (!known.has(event.id)) {
          workspaceNotificationsEvents.unshift(event);
        }
      }
      workspaceNotificationsEvents.sort((a, b) => b.id - a.id);
      workspaceNotificationsEvents = workspaceNotificationsEvents.slice(0, WORKSPACE_NOTIFICATIONS_FETCH_LIMIT);
    } else if (!mergeOnly) {
      workspaceNotificationsEvents = incoming
        .slice()
        .sort((a, b) => b.id - a.id)
        .slice(0, WORKSPACE_NOTIFICATIONS_FETCH_LIMIT);
    }

    reconcileWorkspaceNotificationsSeenId();
    syncWorkspaceNotificationsBadge();
    syncWorkspaceNotificationsHint();
    syncWorkspaceNotificationsMuteUi();
    if (workspaceNotificationsOpen) renderWorkspaceNotificationsList();

    if (!wasInitialLoadDone) {
      workspaceNotificationsAnnouncedUpToId = workspaceNotificationsLatestId;
    } else {
      maybeAnnounceWorkspaceNotifications();
    }
  } catch {
    // ignore transient activity fetch errors
  } finally {
    workspaceNotificationsInitialLoadDone = true;
  }
}

function initWorkspaceNotifications() {
  loadWorkspaceNotificationsSeenId();
  loadWorkspaceNotificationsFilter();
  loadWorkspaceNotificationsMuted();
  syncWorkspaceNotificationsFilterUi();
  syncWorkspaceNotificationsMuteUi();
  syncWorkspaceNotificationsAvailability();
  syncChannelLiveUpdates();
  void refreshWorkspaceNotifications(false);
  workspaceNotificationsPollTimer = window.setInterval(() => {
    if (document.hidden || !isWorkspaceNotificationsContextActive()) return;
    void refreshWorkspaceNotifications(true);
    void syncLiveFileUpdates();
  }, 3000);

  workspaceNotificationsBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    primeWorkspaceNotificationSound();
    toggleWorkspaceNotificationsPopover();
  });
  workspaceNotificationsCloseBtn?.addEventListener("click", closeWorkspaceNotificationsPopover);
  workspaceNotificationsMuteBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    toggleWorkspaceNotificationsMuted();
  });
  workspaceNotificationsClearBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    void clearWorkspaceNotifications();
  });
  workspaceNotificationsFiltersNode?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-filter]");
    if (!(button instanceof HTMLButtonElement)) return;
    event.stopPropagation();
    const nextFilter = String(button.getAttribute("data-filter") || "all").toLowerCase();
    if (!WORKSPACE_NOTIFICATIONS_FILTER_VALUES.has(nextFilter)) return;
    workspaceNotificationsFilter = nextFilter;
    saveWorkspaceNotificationsFilter();
    renderWorkspaceNotificationsList();
  });
  window.addEventListener("resize", positionWorkspaceNotificationsPopover);
  document.addEventListener("click", (event) => {
    if (!workspaceNotificationsOpen) return;
    const target = event.target;
    if (!(target instanceof Node)) return;
    if (workspaceNotificationsPopoverNode?.contains(target)) return;
    if (workspaceNotificationsBtn?.contains(target)) return;
    closeWorkspaceNotificationsPopover();
  });
}

function syncChannelLiveUpdates() {
  stopChannelEventStream();
  stopChannelAutoPoll();
  if (document.hidden || !activeAgentId) return;

  if (typeof EventSource === "undefined") {
    syncChannelAutoPoll();
    channelPollTimer = setInterval(() => {
      if (document.hidden || !activeAgentId) return;
      void refreshMenuIntakeSummary(currentMenuData, activeAgentId);
      if (activeContentMode === NODE_THREAD_MODE && activePath) nodeThreadRefreshOnFocus?.();
      if (activeContentMode === "inbox" && activePath) nodeInboxRefreshOnPoll?.();
      void refreshWorkspaceNotifications(true);
      void syncLiveFileUpdates();
    }, CHANNEL_POLL_INTERVAL_MS);
    return;
  }

  try {
    channelEventSource = new EventSource(buildApiUrl("/api/channels/stream", { scope: "agent" }));
    channelEventSource.addEventListener("update", () => {
      if (document.hidden || !activeAgentId) return;
      void refreshMenuIntakeSummary(currentMenuData, activeAgentId);
      if (activeContentMode === NODE_THREAD_MODE && activePath) nodeThreadRefreshOnFocus?.();
      if (activeContentMode === "inbox" && activePath) nodeInboxRefreshOnPoll?.();
      void refreshWorkspaceNotifications(true);
      void syncLiveFileUpdates();
    });
    channelEventSource.addEventListener("reconnect", () => {
      stopChannelEventStream();
      if (!document.hidden && activeAgentId) syncChannelLiveUpdates();
    });
    channelEventSource.onerror = () => {
      stopChannelEventStream();
      syncChannelAutoPoll();
      channelPollTimer = setInterval(() => {
        if (document.hidden || !activeAgentId) return;
        void refreshMenuIntakeSummary(currentMenuData, activeAgentId);
        if (activeContentMode === NODE_THREAD_MODE && activePath) nodeThreadRefreshOnFocus?.();
        if (activeContentMode === "inbox" && activePath) nodeInboxRefreshOnPoll?.();
        void refreshWorkspaceNotifications(true);
        void syncLiveFileUpdates();
      }, CHANNEL_POLL_INTERVAL_MS);
    };
  } catch {
    syncChannelAutoPoll();
  }
}

let externalFileCommentsRenderSeq = 0;
let mediaFileCommentsRenderSeq = 0;

async function syncExternalFileCommentsBlock() {
  const host = externalFileCommentsBlockNode;
  if (!host) return;

  // Комментарии к записи — только в обзоре (entry overview), не под редактором.
  externalFileCommentsRenderSeq += 1;
  host.classList.add("hidden");
  host.replaceChildren();
}

async function syncMediaFileCommentsBlock() {
  const host = mediaFileCommentsBlockNode;
  if (!host) return;

  // Комментарии к медиафайлу — только в обзоре записи, не под редактором.
  mediaFileCommentsRenderSeq += 1;
  host.classList.add("hidden");
  host.replaceChildren();
}

async function refreshTopicIntakeForActivePath(agentId = activeAgentId) {
  if (!activePath) return null;
  const manifestPath = getActiveNodeApiPath();
  if (!manifestPath) return null;
  try {
    const intake = await fetchTopicIntake(manifestPath, agentId);
    topicIntakeCacheByPath.set(manifestPath, intake);
    inboxPendingCount = Number(intake?.inbox?.pending) || 0;
    syncTopicIntakeDomainLabels();
    if (activeContentMode === "inbox") {
      syncListViewHead();
    }
    syncMenuIntakeBadges(agentId);
    return intake;
  } catch {
    return null;
  }
}

function getThreadLastSeenStorageKey(manifestPath) {
  return `${THREAD_LAST_SEEN_STORAGE_PREFIX}${activeAgentId || "main"}:${manifestPath}`;
}

function getThreadLastSeenId(manifestPath) {
  try {
    return String(localStorage.getItem(getThreadLastSeenStorageKey(manifestPath)) || "").trim();
  } catch {
    return "";
  }
}

function markThreadLastSeen(manifestPath, messageId) {
  const id = String(messageId || "").trim();
  if (!id) return;
  try {
    localStorage.setItem(getThreadLastSeenStorageKey(manifestPath), id);
  } catch {
    // ignore storage errors
  }
}

function getThreadUnreadCount(manifestPath, intake) {
  if (!intake?.thread?.lastMessageId) return 0;
  if (intake.thread.lastMessageRole !== "agent") return 0;
  const lastSeen = getThreadLastSeenId(manifestPath);
  if (!lastSeen) return 1;
  return intake.thread.lastMessageId !== lastSeen ? 1 : 0;
}

async function postInboxCreate(manifestPath, payload = {}, agentId = activeAgentId) {
  const response = await fetch(buildApiUrl("/api/inbox/create", {}, agentId), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      path: manifestPath,
      title: payload.title || "",
      body: payload.body || "",
      source: payload.source || "ui",
      author: payload.author || resolveDialogAuthor()
    })
  });
  if (!response.ok) {
    let details = `Request failed with ${response.status}`;
    try {
      const data = await response.json();
      if (data?.error) details = data.error;
    } catch {
      // ignore parse errors
    }
    throw new Error(details);
  }
  return response.json();
}

function mountInboxTriageToolbar(container) {
  const toolbar = document.createElement("div");
  toolbar.className = "inbox-triage-toolbar";

  const filterLabel = document.createElement("label");
  filterLabel.className = "inbox-triage-filter";
  const filterInput = document.createElement("input");
  filterInput.type = "checkbox";
  filterInput.checked = inboxPendingOnlyFilter;
  filterInput.addEventListener("change", () => {
    inboxPendingOnlyFilter = filterInput.checked;
    try {
      localStorage.setItem(INBOX_PENDING_ONLY_STORAGE_KEY, inboxPendingOnlyFilter ? "1" : "0");
    } catch {
      // ignore storage errors
    }
    rerenderFlatStorageListViewBody("inbox");
  });
  const filterText = document.createElement("span");
  filterText.textContent = "Только необработанные";
  filterLabel.append(filterInput, filterText);

  const addBtn = document.createElement("button");
  addBtn.type = "button";
  addBtn.className = "inbox-triage-btn inbox-triage-btn--primary";
  addBtn.textContent = "＋ Во входящие";
  addBtn.addEventListener("click", () => {
    void (async () => {
      addBtn.disabled = true;
      try {
        await postInboxCreate(getActiveNodeApiPath(), {
          title: "Входящее",
          body: "",
          source: "ui"
        });
        showToast("Запись добавлена во входящие", "success");
        await loadInboxSectionContent(activeFlatStorageSectionFolder.inbox);
        await refreshTopicIntakeForActivePath();
      } catch (error) {
        showToast(`Не удалось создать: ${error.message}`, "error");
      } finally {
        addBtn.disabled = false;
      }
    })();
  });

  toolbar.append(filterLabel, addBtn);
  container.appendChild(toolbar);
}

async function loadInboxSectionContent(preserveSectionFolder = null) {
  const data = await fetchInboxItems(getActiveNodeApiPath());
  inboxItemsMetaCache = Array.isArray(data.items) ? data.items : [];
  inboxPendingCount = Number(data.pending) || 0;
  activeStorageFolderExists = Boolean(data.exists);
  modeContentCache.inbox = inboxItemsMetaCache.map((item) => item.path).join("\n");
  void refreshTopicIntakeForActivePath();
  if (!activeStorageFolderExists) {
    fileContentInputNode.value = getStorageFolderMissingMessage("inbox");
    applyModeUi();
    renderListViewContent();
    nodeInboxRefreshOnPoll = () => {
      void loadInboxSectionContent(activeFlatStorageSectionFolder.inbox);
    };
    return;
  }
  fileContentInputNode.value = modeContentCache.inbox;
  const sectionToRestore =
    preserveSectionFolder ||
    activeFlatStorageSectionFolder.inbox ||
    getActiveFlatStorageSectionParentForCreate("inbox");
  if (sectionToRestore) {
    activeFlatStorageSectionFolder.inbox = String(sectionToRestore).replace(/\\/g, "/").replace(/\/$/, "");
    pruneActiveFlatStorageSectionFolder("inbox");
  }
  applyModeUi();
  renderListViewContent();
  nodeInboxRefreshOnPoll = () => {
    void loadInboxSectionContent(activeFlatStorageSectionFolder.inbox);
  };
}

function getInboxStatusLabel(status) {
  if (status === "done") return "разобрано";
  if (status === "in-progress") return "в работе";
  return "новое";
}

function renderInboxTriageItems(container, items) {
  const visibleItems = inboxPendingOnlyFilter
    ? items.filter((item) => item.status !== "done")
    : items;

  if (!visibleItems.length) {
    renderListEmptyMessage(
      container,
      inboxPendingOnlyFilter
        ? "Нет необработанных входящих"
        : getStorageFolderEmptyMessage("inbox")
    );
    return;
  }

  const list = document.createElement("ul");
  list.className = "inbox-triage-list";

  for (const item of visibleItems) {
    const li = document.createElement("li");
    li.className = "inbox-triage-item";
    if (item.status === "done") li.classList.add("is-done");

    const head = document.createElement("div");
    head.className = "inbox-triage-head";

    const pathNode = document.createElement("span");
    pathNode.className = "inbox-triage-path";
    pathNode.textContent = item.path;

    const statusNode = document.createElement("span");
    statusNode.className = `inbox-triage-status inbox-triage-status--${item.status || "new"}`;
    statusNode.textContent = getInboxStatusLabel(item.status);

    head.append(pathNode, statusNode);
    li.appendChild(head);

    const metaParts = [];
    if (item.source) metaParts.push(item.source);
    if (item.author) metaParts.push(item.author);
    if (item.created) metaParts.push(item.created);
    if (metaParts.length) {
      const meta = document.createElement("div");
      meta.className = "inbox-triage-meta";
      meta.textContent = metaParts.join(" · ");
      li.appendChild(meta);
    }

    if (item.preview) {
      const preview = document.createElement("p");
      preview.className = "inbox-triage-preview";
      preview.textContent = item.preview;
      li.appendChild(preview);
    }

    const actions = document.createElement("div");
    actions.className = "inbox-triage-actions";

    const toThreadBtn = document.createElement("button");
    toThreadBtn.type = "button";
    toThreadBtn.className = "inbox-triage-btn";
    toThreadBtn.textContent = "→ в Диалог";
    toThreadBtn.disabled = item.status === "done";
    toThreadBtn.addEventListener("click", () => {
      void (async () => {
        toThreadBtn.disabled = true;
        try {
          await postInboxTriage(getActiveNodeApiPath(), item.path, "to-thread");
          showToast("Перенесено в диалог — открываю…", "success");
          await loadInboxSectionContent(activeFlatStorageSectionFolder.inbox);
          await refreshTopicIntakeForActivePath();
          clearActiveThreadScope();
          setContentMode(NODE_THREAD_MODE);
        } catch (error) {
          showToast(`Не удалось перенести: ${error.message}`, "error");
          toThreadBtn.disabled = item.status === "done";
        }
      })();
    });

    const inProgressBtn = document.createElement("button");
    inProgressBtn.type = "button";
    inProgressBtn.className = "inbox-triage-btn";
    inProgressBtn.textContent = "В работе";
    inProgressBtn.disabled = item.status === "done" || item.status === "in-progress";
    inProgressBtn.addEventListener("click", () => {
      void (async () => {
        inProgressBtn.disabled = true;
        try {
          await postInboxTriage(getActiveNodeApiPath(), item.path, "set-status", "in-progress");
          showToast("Статус: в работе", "success");
          await loadInboxSectionContent(activeFlatStorageSectionFolder.inbox);
          await refreshTopicIntakeForActivePath();
        } catch (error) {
          showToast(`Не удалось обновить: ${error.message}`, "error");
          inProgressBtn.disabled = item.status === "done" || item.status === "in-progress";
        }
      })();
    });

    const toContentBtn = document.createElement("button");
    toContentBtn.type = "button";
    toContentBtn.className = "inbox-triage-btn";
    toContentBtn.textContent = "→ в Память";
    toContentBtn.disabled = item.status === "done";
    toContentBtn.addEventListener("click", () => {
      void (async () => {
        toContentBtn.disabled = true;
        try {
          await postInboxTriage(getActiveNodeApiPath(), item.path, "to-content");
          showToast("Перенесено в память", "success");
          await loadInboxSectionContent(activeFlatStorageSectionFolder.inbox);
          await refreshTopicIntakeForActivePath();
        } catch (error) {
          showToast(`Не удалось перенести: ${error.message}`, "error");
          toContentBtn.disabled = item.status === "done";
        }
      })();
    });

    const doneBtn = document.createElement("button");
    doneBtn.type = "button";
    doneBtn.className = "inbox-triage-btn";
    doneBtn.textContent = "✓ Разобрано";
    doneBtn.disabled = item.status === "done";
    doneBtn.addEventListener("click", () => {
      void (async () => {
        doneBtn.disabled = true;
        try {
          await postInboxTriage(getActiveNodeApiPath(), item.path, "mark-done");
          showToast("Отмечено как разобрано", "success");
          await loadInboxSectionContent(activeFlatStorageSectionFolder.inbox);
          await refreshTopicIntakeForActivePath();
        } catch (error) {
          showToast(`Не удалось обновить: ${error.message}`, "error");
          doneBtn.disabled = item.status === "done";
        }
      })();
    });

    actions.append(toThreadBtn, inProgressBtn, toContentBtn, doneBtn);
    li.appendChild(actions);
    list.appendChild(li);
  }

  container.appendChild(list);
}

function formatThreadMessageLabel(message) {
  if (message?.label) return message.label;
  if (message?.created) {
    try {
      return new Date(message.created).toLocaleString("ru-RU");
    } catch {
      return message.created;
    }
  }
  return message?.id || "";
}

async function openExternalMemoryFileFromThread(filePath) {
  const relFile = String(filePath || "").trim();
  if (!relFile || !activePath) return;
  setContentMode("external");
  await openExternalFile(relFile);
}

async function renderNodeThread() {
  if (!nodeThreadContentNode || !activePath) return;

  const renderSeq = ++nodeThreadRenderSeq;
  const isStale = () =>
    renderSeq !== nodeThreadRenderSeq || activeContentMode !== NODE_THREAD_MODE || !nodeThreadContentNode;

  const manifestPath = getActiveNodeApiPath();
  const threadContext = getActiveThreadRequestContext();
  const isElementScope = Boolean(activeThreadScope?.file);

  nodeThreadContentNode.replaceChildren();

  if (isElementScope) {
    const scopeBar = document.createElement("div");
    scopeBar.className = "node-thread-scope-bar";
    const scopeNote = document.createElement("span");
    scopeNote.className = "node-thread-scope-note";
    scopeNote.textContent = `Файл: ${activeThreadScope.file}`;
    const backBtn = document.createElement("button");
    backBtn.type = "button";
    backBtn.className = "node-thread-scope-back";
    backBtn.textContent = "← Диалог по теме";
    backBtn.addEventListener("click", () => {
      clearActiveThreadScope();
      void renderNodeThread();
    });
    scopeBar.append(scopeNote, backBtn);
    nodeThreadContentNode.appendChild(scopeBar);
  }

  const section = document.createElement("section");
  section.className = "node-comments node-thread-panel";
  section.setAttribute("aria-label", "Диалог");

  const composer = document.createElement("div");
  composer.className = "node-comments-composer node-thread-composer";

  const composerAvatar = createNodeCommentAvatar("Вы", "green");

  const composerMain = document.createElement("div");
  composerMain.className = "node-comments-composer-main";

  const composerBox = document.createElement("div");
  composerBox.className = "node-comments-composer-box";

  const composerField = document.createElement("textarea");
  composerField.className = "node-comments-input";
  composerField.rows = 3;
  composerField.placeholder = "Напишите агенту…";
  composerField.setAttribute("aria-label", "Новое сообщение в диалоге");

  const composerActions = document.createElement("div");
  composerActions.className = "node-comments-composer-actions";

  const composerHint = document.createElement("span");
  composerHint.className = "node-comments-composer-hint";
  composerHint.textContent = "Markdown · Ctrl/Cmd+Enter · автообновление ~2.5 с";

  const composerSubmit = document.createElement("button");
  composerSubmit.type = "button";
  composerSubmit.className = "node-comments-submit";
  composerSubmit.disabled = true;
  composerSubmit.textContent = "Отправить";

  composerActions.append(composerHint, composerSubmit);
  composerBox.append(composerField, composerActions);
  composerMain.appendChild(composerBox);
  composer.append(composerAvatar, composerMain);

  const thread = document.createElement("ol");
  thread.className = "node-comments-thread node-thread-messages";

  section.append(thread, composer);
  nodeThreadContentNode.appendChild(section);

  const scrollThreadToLatest = () => {
    requestAnimationFrame(() => {
      thread.scrollTop = thread.scrollHeight;
    });
  };

  const syncSubmitState = () => {
    composerSubmit.disabled = !String(composerField.value || "").trim();
  };
  composerField.addEventListener("input", syncSubmitState);
  composerField.addEventListener("change", syncSubmitState);
  composerField.addEventListener("keyup", syncSubmitState);

  const renderMessages = (messages) => {
    thread.replaceChildren();
    const items = Array.isArray(messages) ? messages : [];
    if (!items.length) {
      const empty = document.createElement("li");
      empty.className = "node-comments-empty node-thread-empty";
      empty.textContent = "Пока нет сообщений — напишите первое ниже.";
      thread.appendChild(empty);
      return;
    }
    for (const message of items) {
      const item = document.createElement("li");
      item.className = "node-comment node-thread-message";
      if (message.role === "agent") item.classList.add("node-thread-message--agent");

      const authorLabel =
        message.role === "agent"
          ? formatCommentAuthorLabel(message.author || "Агент")
          : formatCommentAuthorLabel(message.author || "Вы");
      const avatar = createNodeCommentAvatar(
        message.role === "agent" ? "🤖" : getCommentAuthorInitials(message.author || "Вы"),
        message.role === "agent" ? "violet" : "green"
      );

      const main = document.createElement("article");
      main.className = "node-comment-main";

      const commentHead = document.createElement("header");
      commentHead.className = "node-comment-head";

      const author = document.createElement("strong");
      author.className = "node-comment-author";
      author.textContent = authorLabel;

      const time = document.createElement("time");
      time.className = "node-comment-time";
      time.textContent = formatThreadMessageLabel(message);
      time.dateTime = message.created || message.id || "";

      commentHead.append(author, time);

      const body = document.createElement("div");
      body.className = "node-comment-body node-thread-body";
      body.textContent = message.body || "";

      main.append(commentHead, body);

      if (message.linkedFiles) {
        const foot = document.createElement("footer");
        foot.className = "node-comment-foot";
        for (const filePath of String(message.linkedFiles).split(",").map((s) => s.trim()).filter(Boolean)) {
          const linkBtn = document.createElement("button");
          linkBtn.type = "button";
          linkBtn.className = "inbox-triage-btn node-thread-file-link";
          linkBtn.textContent = `📄 ${filePath}`;
          linkBtn.title = filePath;
          linkBtn.addEventListener("click", () => {
            void openExternalMemoryFileFromThread(filePath);
          });
          foot.appendChild(linkBtn);
        }
        main.appendChild(foot);
      }

      item.append(avatar, main);
      thread.appendChild(item);
    }
    scrollThreadToLatest();
  };

  const refreshThread = async () => {
    const loading = document.createElement("li");
    loading.className = "node-comments-empty";
    loading.textContent = "Загрузка…";
    thread.replaceChildren(loading);
    try {
      const data = await fetchTopicThread(threadContext);
      if (isStale()) return;
      renderMessages(data.messages);
      const items = Array.isArray(data.messages) ? data.messages : [];
      if (items.length) {
        markThreadLastSeen(manifestPath, items[items.length - 1].id);
      }
      await refreshTopicIntakeForActivePath();
    } catch (error) {
      if (isStale()) return;
      loading.textContent = `Не удалось загрузить диалог: ${error.message}`;
    }
  };

  nodeThreadRefreshOnFocus = () => {
    void refreshThread();
  };

  composerSubmit.addEventListener("click", () => {
    void (async () => {
      const body = String(composerField.value || "").trim();
      if (!body) return;
      if (!manifestPath) {
        showToast("Не удалось определить тему для диалога", "error");
        return;
      }
      composerSubmit.disabled = true;
      composerField.disabled = true;
      try {
        const author = resolveDialogAuthor();
        storeCommentAuthor(author);
        await postTopicThreadMessage(threadContext, body, { role: "user", author });
        composerField.value = "";
        if (!isStale()) {
          await refreshThread();
        }
        await refreshTopicIntakeForActivePath();
        showToast("Сообщение сохранено", "success");
      } catch (error) {
        showToast(`Не удалось сохранить: ${error.message}`, "error");
      } finally {
        if (!isStale()) {
          composerField.disabled = false;
          syncSubmitState();
        }
      }
    })();
  });

  composerField.addEventListener("keydown", (event) => {
    if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
      event.preventDefault();
      if (!composerSubmit.disabled) composerSubmit.click();
    }
  });

  await refreshThread();
}

function createNodeCommentReplyComposer(parentComment, handlers = {}) {
  const wrap = document.createElement("div");
  wrap.className = "node-comment-reply-composer";

  const field = document.createElement("textarea");
  field.className = "node-comments-input node-comment-reply-input";
  field.rows = 2;
  field.placeholder = `Ответ @${parentComment.author || "guest"}…`;
  field.setAttribute("aria-label", `Ответ на комментарий ${parentComment.author || "guest"}`);

  const actions = document.createElement("div");
  actions.className = "node-comment-reply-actions";

  const cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "node-comment-reply-cancel";
  cancelBtn.textContent = "Отмена";

  const submitBtn = document.createElement("button");
  submitBtn.type = "button";
  submitBtn.className = "node-comments-submit";
  submitBtn.disabled = true;
  submitBtn.textContent = "Ответить";

  const syncSubmit = () => {
    submitBtn.disabled = !String(field.value || "").trim();
  };

  field.addEventListener("input", syncSubmit);
  cancelBtn.addEventListener("click", () => {
    wrap.remove();
    handlers.onClose?.();
  });
  submitBtn.addEventListener("click", () => {
    const body = String(field.value || "").trim();
    if (!body) return;
    handlers.onSubmit?.(body, wrap);
  });
  field.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      cancelBtn.click();
      return;
    }
    if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
      event.preventDefault();
      if (!submitBtn.disabled) submitBtn.click();
    }
  });

  actions.append(cancelBtn, submitBtn);
  wrap.append(field, actions);
  queueMicrotask(() => field.focus());
  return wrap;
}

function renderNodeCommentThreadItem(comment, handlers = {}) {
  const item = document.createElement("li");
  item.className = "node-comment";
  if (comment.replyTo) item.classList.add("node-comment--reply");
  if (handlers.myHandle && commentMentionsUser(comment, handlers.myHandle)) {
    item.classList.add("node-comment--mentions-me");
  }

  const avatar = createNodeCommentAvatar(
    getCommentAuthorInitials(comment.author),
    getCommentAvatarTone(comment.author)
  );

  const main = document.createElement("article");
  main.className = "node-comment-main";

  const commentHead = document.createElement("header");
  commentHead.className = "node-comment-head";

  const author = document.createElement("strong");
  author.className = "node-comment-author";
  author.textContent = formatCommentAuthorLabel(comment.author);

  const time = document.createElement("time");
  time.className = "node-comment-time";
  time.textContent = comment.label || comment.id || "";
  time.dateTime = comment.created || comment.id || "";

  commentHead.append(author, time);

  const body = document.createElement("div");
  body.className = "node-comment-body";
  renderCommentBodyWithMentions(body, comment.body || "", handlers.mentionLookup);

  const foot = document.createElement("footer");
  foot.className = "node-comment-foot";

  const replyBtn = document.createElement("button");
  replyBtn.type = "button";
  replyBtn.className = "node-comment-action";
  replyBtn.textContent = comment.replies?.length ? `Ответить · ${comment.replies.length}` : "Ответить";
  if (typeof handlers.onReply === "function") {
    replyBtn.addEventListener("click", () => handlers.onReply(comment, item, main));
  } else {
    replyBtn.disabled = true;
    replyBtn.title = "Скоро";
  }

  const reactBtn = document.createElement("button");
  reactBtn.type = "button";
  reactBtn.className = "node-comment-action node-comment-reaction";
  const reactionCount =
    Number(comment.reactionsUpCount) ||
    (Array.isArray(comment.reactionsUp) ? comment.reactionsUp.length : 0);
  const myReactionKey = slugifyCommentMentionHandle(getStoredCommentAuthor());
  const reactionsUp = Array.isArray(comment.reactionsUp) ? comment.reactionsUp : [];
  if (myReactionKey && reactionsUp.some((entry) => slugifyCommentMentionHandle(entry) === myReactionKey)) {
    reactBtn.classList.add("is-active");
  }
  reactBtn.textContent = reactionCount > 0 ? `👍 ${reactionCount}` : "👍";
  reactBtn.title = "Нравится";
  if (typeof handlers.onReaction === "function") {
    reactBtn.addEventListener("click", () => handlers.onReaction(comment, reactBtn));
  } else {
    reactBtn.disabled = true;
  }

  foot.append(replyBtn, reactBtn);
  main.append(commentHead, body, foot);
  item.append(avatar, main);

  const replies = Array.isArray(comment.replies) ? comment.replies : [];
  if (replies.length) {
    const repliesList = document.createElement("ol");
    repliesList.className = "node-comment-replies";
    for (const reply of replies) {
      repliesList.appendChild(renderNodeCommentThreadItem(reply, handlers));
    }
    item.appendChild(repliesList);
  }

  return item;
}

async function createNodeCommentsBlock(options = {}) {
  const nodeTitle = String(options.nodeTitle || "этой теме").trim() || "этой теме";
  const agentId = options.agentId || activeAgentId;
  const context = {
    mode: options.mode || "description",
    path: options.manifestPath || options.path || "",
    file: options.file || null,
    name: options.name || null
  };

  const section = document.createElement("section");
  section.className = "node-comments";
  section.setAttribute("aria-label", "Комментарии");

  const head = createNavigationSectionHead("Комментарии");

  const count = document.createElement("span");
  count.className = "node-comments-count";
  count.textContent = "0";

  const mentionBadge = document.createElement("span");
  mentionBadge.className = "node-comments-mention-badge hidden";
  mentionBadge.setAttribute("aria-label", "Новые упоминания");

  head.append(count, mentionBadge);

  const myHandle = slugifyCommentMentionHandle(getStoredCommentAuthor());
  let latestComments = [];

  const updateMentionBadge = (comments) => {
    latestComments = Array.isArray(comments) ? comments : [];
    const unread = countUnreadCommentMentions(latestComments, myHandle, context);
    mentionBadge.classList.toggle("hidden", unread <= 0);
    mentionBadge.textContent = unread > 0 ? `@ ${unread}` : "";
    mentionBadge.title = unread > 0 ? `${unread} новых упоминаний` : "";
  };

  const acknowledgeMentions = () => {
    markAllCommentMentionsSeen(context, latestComments);
    updateMentionBadge(latestComments);
  };

  head.addEventListener("click", acknowledgeMentions);

  const composer = document.createElement("div");
  composer.className = "node-comments-composer";

  const composerAvatar = createNodeCommentAvatar("Вы", "green");

  const composerMain = document.createElement("div");
  composerMain.className = "node-comments-composer-main";

  const composerBox = document.createElement("div");
  composerBox.className = "node-comments-composer-box";

  const composerField = document.createElement("textarea");
  composerField.className = "node-comments-input";
  composerField.rows = 3;
  composerField.placeholder = `Комментарий к «${nodeTitle}»…`;
  composerField.setAttribute("aria-label", "Новый комментарий");
  composerField.addEventListener("focus", acknowledgeMentions);

  const composerActions = document.createElement("div");
  composerActions.className = "node-comments-composer-actions";

  const composerHint = document.createElement("span");
  composerHint.className = "node-comments-composer-hint";
  composerHint.textContent = "Markdown · @упоминания · ↑↓ Enter";

  const composerSubmit = document.createElement("button");
  composerSubmit.type = "button";
  composerSubmit.className = "node-comments-submit";
  composerSubmit.disabled = true;
  composerSubmit.textContent = "Комментировать";

  composerActions.append(composerHint, composerSubmit);
  composerBox.append(composerField, composerActions);
  composerMain.appendChild(composerBox);
  composer.append(composerAvatar, composerMain);

  const thread = document.createElement("ol");
  thread.className = "node-comments-thread";

  section.append(head, composer, thread);

  let mentionCandidates = collectCommentMentionCandidates({ agentId });
  const mentionLookup = () => buildCommentMentionLookup(mentionCandidates);
  attachCommentMentionAutocomplete(composerField, () => mentionCandidates);

  const syncSubmitState = () => {
    composerSubmit.disabled = !String(composerField.value || "").trim();
  };

  composerField.addEventListener("input", syncSubmitState);

  let activeReplyComposer = null;

  const closeActiveReplyComposer = () => {
    activeReplyComposer?.remove();
    activeReplyComposer = null;
  };

  const submitComment = async (body, replyTo = null) => {
    const author = resolveDialogAuthor();
    storeCommentAuthor(author);
    await postFileComment(context, body, author, agentId, replyTo);
    return true;
  };

  const commentHandlers = {
    myHandle,
    mentionLookup: mentionLookup(),
    onReaction(comment, button) {
      void (async () => {
        button.disabled = true;
        try {
          const author = resolveDialogAuthor();
          storeCommentAuthor(author);
          await postCommentReaction(context, comment.id, author, agentId);
          await refreshComments();
        } catch (error) {
          showToast(`Не удалось поставить реакцию: ${error.message}`, "error");
          button.disabled = false;
        }
      })();
    },
    onReply(parentComment, itemNode, mainNode) {
      closeActiveReplyComposer();
      const composerNode = createNodeCommentReplyComposer(parentComment, {
        onClose: () => {
          if (activeReplyComposer === composerNode) activeReplyComposer = null;
        },
        onSubmit: (body, wrap) => {
          void (async () => {
            const submitBtn = wrap.querySelector(".node-comments-submit");
            const field = wrap.querySelector("textarea");
            if (submitBtn) submitBtn.disabled = true;
            if (field) field.disabled = true;
            try {
              const saved = await submitComment(body, parentComment.id);
              if (!saved) return;
              closeActiveReplyComposer();
              await refreshComments();
              showToast("Ответ сохранён", "success");
            } catch (error) {
              showToast(`Не удалось сохранить ответ: ${error.message}`, "error");
              if (submitBtn) submitBtn.disabled = false;
              if (field) field.disabled = false;
            }
          })();
        }
      });
      activeReplyComposer = composerNode;
      mainNode.appendChild(composerNode);
      const replyField = composerNode.querySelector("textarea");
      if (replyField) {
        attachCommentMentionAutocomplete(replyField, () => mentionCandidates);
      }
    }
  };

  const renderComments = (comments) => {
    thread.replaceChildren();
    const items = Array.isArray(comments) ? comments : [];
    count.textContent = String(items.length);
    updateMentionBadge(items);
    const authors = items.map((item) => item.author).filter(Boolean);
    mentionCandidates = collectCommentMentionCandidates({ agentId, authors });
    commentHandlers.mentionLookup = mentionLookup();
    if (items.length === 0) return;
    const tree = buildCommentThreadTree(items);
    for (const comment of tree) {
      thread.appendChild(renderNodeCommentThreadItem(comment, commentHandlers));
    }
  };

  const refreshComments = async () => {
    closeActiveReplyComposer();
    const loading = document.createElement("li");
    loading.className = "node-comments-empty";
    loading.textContent = "Загрузка…";
    thread.replaceChildren(loading);
    try {
      const data = await fetchFileComments(context, agentId);
      renderComments(data.comments);
    } catch (error) {
      loading.textContent = `Не удалось загрузить комментарии: ${error.message}`;
    }
  };

  composerSubmit.addEventListener("click", () => {
    void (async () => {
      const body = String(composerField.value || "").trim();
      if (!body) return;
      closeActiveReplyComposer();
      composerSubmit.disabled = true;
      composerField.disabled = true;
      try {
        const saved = await submitComment(body);
        if (!saved) return;
        composerField.value = "";
        await refreshComments();
        showToast("Комментарий сохранён", "success");
      } catch (error) {
        showToast(`Не удалось сохранить комментарий: ${error.message}`, "error");
      } finally {
        composerField.disabled = false;
        syncSubmitState();
      }
    })();
  });

  composerField.addEventListener("keydown", (event) => {
    if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
      event.preventDefault();
      if (!composerSubmit.disabled) composerSubmit.click();
    }
  });

  await refreshComments();
  return section;
}

