function initAgentRegistryToolbar() {
  if (!agentRegistryBtn) return;
  agentRegistryBtn.replaceChildren();
  const icon = createRegistryMarkerSvg();
  icon.classList.add("agent-registry-btn-icon");
  agentRegistryBtn.appendChild(icon);
  if (agentRegistryBtn.dataset.bound === "1") return;
  agentRegistryBtn.dataset.bound = "1";
  agentRegistryBtn.addEventListener("click", handleAgentRegistryClick);
}

function syncAgentRegistryToolbarUi() {
  agentRegistryBtn?.classList.toggle(
    "is-active",
    agentWorkspaceView === "runtime-registry" && isAgentWorkspaceCanvasVisible()
  );
}

function handleAgentRegistryClick(event) {
  event.preventDefault();
  event.stopPropagation();
  setAgentWorkspaceView("runtime-registry");
}

let agentRuntimeRegistryFilterMode = "sync";

function syncAgentRuntimeRegistryFilterUi() {
  if (!agentRuntimeRegistryFilterNode) return;
  for (const btn of agentRuntimeRegistryFilterNode.querySelectorAll("[data-runtime-filter]")) {
    const mode = btn.getAttribute("data-runtime-filter") || "all";
    const active = mode === agentRuntimeRegistryFilterMode;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-selected", active ? "true" : "false");
  }
}

function initAgentRuntimeRegistryFilter() {
  if (!agentRuntimeRegistryFilterNode || agentRuntimeRegistryFilterNode.dataset.bound === "1") return;
  agentRuntimeRegistryFilterNode.dataset.bound = "1";
  agentRuntimeRegistryFilterNode.addEventListener("click", (event) => {
    const btn = event.target.closest("[data-runtime-filter]");
    if (!btn) return;
    const nextMode = btn.getAttribute("data-runtime-filter") === "all" ? "all" : "sync";
    if (nextMode === agentRuntimeRegistryFilterMode) return;
    agentRuntimeRegistryFilterMode = nextMode;
    syncAgentRuntimeRegistryFilterUi();
    if (agentWorkspaceView === "runtime-registry") {
      void renderAgentRuntimeRegistryView();
    }
  });
  syncAgentRuntimeRegistryFilterUi();
}

async function fetchAgentRuntimeRegistry(filterMode = agentRuntimeRegistryFilterMode) {
  const params = new URLSearchParams();
  if (filterMode === "sync") params.set("sync", "true");
  const query = params.toString();
  const response = await fetch(
    buildApiUrl(`/api/agent/runtime-registry${query ? `?${query}` : ""}`)
  );
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || `HTTP ${response.status}`);
  }
  return response.json();
}

function formatRuntimeRegistryBoolCell(active, detail = "") {
  if (!active) {
    return { text: "—", tone: "off", title: "" };
  }
  const schedule = String(detail || "").trim();
  return {
    text: schedule ? schedule : "да",
    tone: "on",
    title: schedule ? `Cron: ${schedule}` : ""
  };
}

async function renderAgentRuntimeRegistryView() {
  if (!agentRuntimeRegistryContentNode) return;

  agentRuntimeRegistryContentNode.replaceChildren();
  if (agentRuntimeRegistryStatsNode) agentRuntimeRegistryStatsNode.replaceChildren();

  const loading = document.createElement("p");
  loading.className = "agent-runtime-registry-empty";
  loading.textContent = "Загрузка реестра…";
  agentRuntimeRegistryContentNode.appendChild(loading);

  try {
    const data = await fetchAgentRuntimeRegistry();
    agentRuntimeRegistryContentNode.replaceChildren();

    const rows = Array.isArray(data.rows) ? data.rows : [];

    if (agentRuntimeRegistryStatsNode) {
      const syncOnly = agentRuntimeRegistryFilterMode === "sync";
      agentRuntimeRegistryStatsNode.append(
        createAgentWorkspaceStatElement(data.topicCount ?? rows.length, syncOnly ? "sync-тем" : "тем"),
        createAgentWorkspaceStatElement(data.sessionStartCount ?? 0, "при старте", "ok"),
        createAgentWorkspaceStatElement(data.cronCount ?? 0, "cron", "warn"),
        createAgentWorkspaceStatElement(data.heartbeatCount ?? 0, "heartbeat", "ok")
      );
      if (syncOnly && data.totalSyncCount != null) {
        agentRuntimeRegistryStatsNode.append(
          createAgentWorkspaceStatElement(data.totalSyncCount, "из всех", "muted")
        );
      }
    }

    if (!rows.length) {
      const empty = document.createElement("div");
      empty.className = "agent-runtime-registry-empty-state";
      const syncOnly = agentRuntimeRegistryFilterMode === "sync";
      empty.innerHTML = syncOnly
        ? `
        <p class="agent-runtime-registry-empty-title">Нет тем с cron или heartbeat</p>
        <p class="agent-runtime-registry-empty-text">Включите <code>awn-runtime-cron</code> или <code>awn-runtime-heartbeat</code> в manifest темы — она попадёт в карту синхронизации. Или переключитесь на «Все темы».</p>
      `
        : `
        <p class="agent-runtime-registry-empty-title">Тем пока нет</p>
        <p class="agent-runtime-registry-empty-text">Создайте темы в дереве workspace — они появятся в реестре с полями <code>awn-runtime-*</code>.</p>
      `;
      agentRuntimeRegistryContentNode.appendChild(empty);
      return;
    }

    const wrap = document.createElement("div");
    wrap.className = "agent-table-wrap agent-runtime-registry-wrap";

    const table = document.createElement("table");
    table.className = "agent-table agent-runtime-registry-table";
    table.setAttribute("aria-label", "Реестр тем workspace");

    const thead = document.createElement("thead");
    const headRow = document.createElement("tr");
    for (const label of ["Тема", "Загрузка", "Крон", "Сердцебиение"]) {
      const th = document.createElement("th");
      th.scope = "col";
      th.textContent = label;
      headRow.appendChild(th);
    }
    thead.appendChild(headRow);
    table.appendChild(thead);

    const tbody = document.createElement("tbody");
    for (const row of rows) {
      const tr = document.createElement("tr");
      tr.className = "agent-table-row agent-runtime-registry-row";
      tr.tabIndex = 0;
      tr.setAttribute("role", "button");
      tr.title = "Открыть тему";

      const openRow = () => openNodeFromMenu(row.label || getLabelFromPath(row.manifestPath), row.manifestPath);
      tr.addEventListener("click", openRow);
      tr.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          openRow();
        }
      });

      const titleCell = document.createElement("td");
      titleCell.className = "agent-table-cell agent-table-cell--title";
      const titleInner = document.createElement("div");
      titleInner.className = "agent-table-title-inner";
      const titleText = document.createElement("span");
      titleText.className = "agent-table-label";
      titleText.textContent = row.label || row.displayPath || row.manifestPath;
      titleInner.appendChild(titleText);
      if (row.displayPath && row.displayPath !== row.label) {
        const pathHint = document.createElement("span");
        pathHint.className = "agent-runtime-registry-path";
        pathHint.textContent = row.displayPath;
        titleInner.appendChild(pathHint);
      }
      titleCell.appendChild(titleInner);

      const loadCell = document.createElement("td");
      loadCell.className = "agent-table-cell";
      const loadBadge = document.createElement("span");
      loadBadge.className = `agent-runtime-registry-badge is-load${
        row.runtimeLoadAlways ? " is-session-start" : ""
      }`;
      loadBadge.textContent = row.runtimeLoadLabel || "По запросу";
      loadCell.appendChild(loadBadge);

      const cronCell = document.createElement("td");
      cronCell.className = "agent-table-cell agent-table-cell--mono";
      const cronInfo = formatRuntimeRegistryBoolCell(row.runtimeCron, row.runtimeCronSchedule);
      const cronBadge = document.createElement("span");
      cronBadge.className = `agent-runtime-registry-badge is-bool is-${cronInfo.tone}`;
      if (cronInfo.title) cronBadge.title = cronInfo.title;
      cronBadge.textContent = cronInfo.text;
      cronCell.appendChild(cronBadge);

      const heartbeatCell = document.createElement("td");
      heartbeatCell.className = "agent-table-cell";
      const heartbeatInfo = formatRuntimeRegistryBoolCell(row.runtimeHeartbeat);
      const heartbeatBadge = document.createElement("span");
      heartbeatBadge.className = `agent-runtime-registry-badge is-bool is-${heartbeatInfo.tone}`;
      heartbeatBadge.textContent = heartbeatInfo.text;
      heartbeatCell.appendChild(heartbeatBadge);

      tr.append(titleCell, loadCell, cronCell, heartbeatCell);
      tbody.appendChild(tr);
    }

    table.appendChild(tbody);
    wrap.appendChild(table);
    agentRuntimeRegistryContentNode.appendChild(wrap);
  } catch (error) {
    agentRuntimeRegistryContentNode.replaceChildren();
    const errorNode = document.createElement("p");
    errorNode.className = "agent-runtime-registry-empty is-alert";
    errorNode.textContent = error?.message || "Не удалось загрузить реестр";
    agentRuntimeRegistryContentNode.appendChild(errorNode);
    if (agentRuntimeRegistryStatsNode) agentRuntimeRegistryStatsNode.replaceChildren();
  }
}

async function fetchAgentGitStatus() {
  const response = await fetch(buildApiUrl("/api/git/status"));
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || `HTTP ${response.status}`);
  }
  return response.json();
}

function createAgentWorkspaceStatElement(value, label, tone = "") {
  const chip = document.createElement("span");
  chip.className = `agent-workspace-stat${tone ? ` agent-workspace-stat--${tone}` : ""}`;
  chip.innerHTML = `<strong>${escapeHtml(String(value))}</strong> ${escapeHtml(label)}`;
  return chip;
}

function renderAgentGitStatChip(label, value, tone = "") {
  const mappedTone = tone === "clean" ? "ok" : tone === "dirty" ? "warn" : tone;
  return createAgentWorkspaceStatElement(value, label, mappedTone);
}

function appendAgentGitChangeGroup(container, title, items) {
  if (!items.length) return;
  const section = document.createElement("section");
  section.className = "agent-git-group";

  const heading = document.createElement("h3");
  heading.className = "agent-git-group-title";
  heading.textContent = `${title} (${items.length})`;
  section.appendChild(heading);

  const list = document.createElement("ul");
  list.className = "agent-git-change-list";

  for (const item of items) {
    const row = document.createElement("li");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = `agent-git-change-row is-${item.kind || "modified"}`;

    const badge = document.createElement("span");
    badge.className = "agent-git-change-badge";
    badge.textContent = item.label || item.kind || "изменено";

    const pathNode = document.createElement("span");
    pathNode.className = "agent-git-change-path";
    pathNode.textContent = item.oldPath ? `${item.oldPath} → ${item.path}` : item.path;

    btn.append(badge, pathNode);
    btn.title = item.path;
    btn.addEventListener("click", () => {
      void revealWorkspacePath(item.path);
    });
    row.appendChild(btn);
    list.appendChild(row);
  }

  section.appendChild(list);
  container.appendChild(section);
}

async function renderAgentGitView() {
  if (!agentGitContentNode) return;

  agentGitContentNode.replaceChildren();
  if (agentGitStatsNode) agentGitStatsNode.replaceChildren();

  const loading = document.createElement("p");
  loading.className = "agent-git-empty";
  loading.textContent = "Загрузка git status…";
  agentGitContentNode.appendChild(loading);

  try {
    const data = await fetchAgentGitStatus();
    agentGitContentNode.replaceChildren();

    if (agentGitStatsNode) {
      if (data.isRepo) {
        agentGitStatsNode.append(
          renderAgentGitStatChip("изменений", data.counts?.total ?? 0, data.clean ? "clean" : "dirty"),
          renderAgentGitStatChip("ветка", data.branch || "—", "branch")
        );
      }
    }

    if (!data.isRepo) {
      const empty = document.createElement("div");
      empty.className = "agent-git-empty-state";
      empty.innerHTML = `
        <p class="agent-git-empty-title">Отсутствует репозиторий</p>
        <p class="agent-git-empty-text">В корне workspace агента нет каталога <code>.git</code>. Git-проверка не выполняется — инициализируйте репозиторий в корне агента.</p>
      `;
      agentGitContentNode.appendChild(empty);
      return;
    }

    if (data.error) {
      const error = document.createElement("p");
      error.className = "agent-git-empty is-alert";
      error.textContent = `Git: ${data.error}`;
      agentGitContentNode.appendChild(error);
      return;
    }

    const shell = document.createElement("div");
    shell.className = "agent-git-shell";

    const meta = document.createElement("div");
    meta.className = "agent-git-meta";
    const branchLine = document.createElement("p");
    branchLine.className = "agent-git-meta-line";
    const branchParts = [`Ветка: ${data.branch || "—"}`];
    if (data.upstream) branchParts.push(`upstream: ${data.upstream}`);
    if (data.ahead) branchParts.push(`↑${data.ahead}`);
    if (data.behind) branchParts.push(`↓${data.behind}`);
    branchLine.textContent = branchParts.join(" · ");
    meta.appendChild(branchLine);

    if (data.repoRel) {
      const repoLine = document.createElement("p");
      repoLine.className = "agent-git-meta-line is-muted";
      repoLine.textContent = `Корень репозитория: ${data.repoRel}`;
      meta.appendChild(repoLine);
    }

    shell.appendChild(meta);

    if (data.clean) {
      const clean = document.createElement("p");
      clean.className = "agent-git-clean-banner";
      clean.textContent = "Рабочая копия чистая — нет незакоммиченных изменений.";
      shell.appendChild(clean);
    } else {
      const groups = [
        ["В индексе", data.changes.filter((item) => item.kind === "staged")],
        ["Изменено", data.changes.filter((item) => item.kind === "modified")],
        ["Неотслеживаемые", data.changes.filter((item) => item.kind === "untracked")],
        ["Удалено", data.changes.filter((item) => item.kind === "deleted")],
        ["Переименовано", data.changes.filter((item) => item.kind === "renamed")],
        ["Конфликты", data.changes.filter((item) => item.kind === "conflict")]
      ];
      for (const [title, items] of groups) {
        appendAgentGitChangeGroup(shell, title, items);
      }
    }

    if (Array.isArray(data.commits) && data.commits.length) {
      const commitsSection = document.createElement("section");
      commitsSection.className = "agent-git-group agent-git-group--commits";

      const commitsTitle = document.createElement("h3");
      commitsTitle.className = "agent-git-group-title";
      commitsTitle.textContent = "Последние коммиты";
      commitsSection.appendChild(commitsTitle);

      const commitsList = document.createElement("ul");
      commitsList.className = "agent-git-commit-list";
      for (const commit of data.commits) {
        const item = document.createElement("li");
        item.className = "agent-git-commit-row";
        item.innerHTML = `
          <span class="agent-git-commit-hash">${escapeHtml(commit.shortHash || commit.hash || "")}</span>
          <span class="agent-git-commit-subject">${escapeHtml(commit.subject || "")}</span>
          <span class="agent-git-commit-meta">${escapeHtml([commit.when, commit.author].filter(Boolean).join(" · "))}</span>
        `;
        commitsList.appendChild(item);
      }
      commitsSection.appendChild(commitsList);
      shell.appendChild(commitsSection);
    }

    agentGitContentNode.appendChild(shell);
  } catch (error) {
    agentGitContentNode.replaceChildren();
    const errorNode = document.createElement("p");
    errorNode.className = "agent-git-empty is-alert";
    errorNode.textContent = `Не удалось загрузить git status: ${error.message}`;
    agentGitContentNode.appendChild(errorNode);
  }
}

async function fetchAgentLargeFiles() {
  const response = await fetch(buildApiUrl("/api/agent/large-files", { minMb: 45 }));
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || `HTTP ${response.status}`);
  }
  return response.json();
}

function renderAgentLargeFilesStatChip(label, value, tone = "") {
  const mappedTone = tone === "total" ? "warn" : tone;
  return createAgentWorkspaceStatElement(value, label, mappedTone);
}

async function renderAgentLargeFilesView() {
  if (!agentLargeFilesContentNode) return;

  agentLargeFilesContentNode.replaceChildren();
  if (agentLargeFilesStatsNode) agentLargeFilesStatsNode.replaceChildren();

  const loading = document.createElement("p");
  loading.className = "agent-large-files-empty";
  loading.textContent = "Сканирование workspace…";
  agentLargeFilesContentNode.appendChild(loading);

  try {
    const data = await fetchAgentLargeFiles();
    agentLargeFilesContentNode.replaceChildren();

    if (agentLargeFilesStatsNode) {
      agentLargeFilesStatsNode.append(
        renderAgentLargeFilesStatChip("файлов", data.count ?? 0, data.count ? "total" : ""),
        renderAgentLargeFilesStatChip("суммарно", data.totalSizeLabel || formatFileSize(data.totalSize || 0))
      );
    }

    const shell = document.createElement("div");
    shell.className = "agent-large-files-shell";

    const meta = document.createElement("p");
    meta.className = "agent-large-files-meta-line";
    meta.textContent = `Порог: ${data.thresholdMb ?? 45} МБ · сортировка по размеру (убывание)`;
    shell.appendChild(meta);

    const files = Array.isArray(data.files) ? data.files : [];
    if (!files.length) {
      const empty = document.createElement("div");
      empty.className = "agent-large-files-empty-state";
      empty.innerHTML = `
        <p class="agent-large-files-empty-title">Крупных файлов не найдено</p>
        <p class="agent-large-files-empty-text">В workspace нет файлов больше ${data.thresholdMb ?? 45} МБ (кроме служебных каталогов вроде <code>.git</code> и <code>node_modules</code>).</p>
      `;
      shell.appendChild(empty);
    } else {
      const list = document.createElement("ul");
      list.className = "agent-large-files-list";

      for (const item of files) {
        const row = document.createElement("li");
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "agent-large-files-row";
        btn.title = item.path;

        const sizeNode = document.createElement("span");
        sizeNode.className = "agent-large-files-size";
        sizeNode.textContent = item.sizeLabel || formatFileSize(item.size);

        const pathNode = document.createElement("span");
        pathNode.className = "agent-large-files-path";
        pathNode.textContent = item.path;

        btn.append(sizeNode, pathNode);
        btn.addEventListener("click", () => {
          void revealWorkspacePath(item.path);
        });
        row.appendChild(btn);
        list.appendChild(row);
      }

      shell.appendChild(list);
    }

    agentLargeFilesContentNode.appendChild(shell);
  } catch (error) {
    agentLargeFilesContentNode.replaceChildren();
    const errorNode = document.createElement("p");
    errorNode.className = "agent-large-files-empty is-alert";
    errorNode.textContent = `Не удалось просканировать workspace: ${error.message}`;
    agentLargeFilesContentNode.appendChild(errorNode);
  }
}

async function fetchAgentBrokenLinks() {
  const response = await fetch(buildApiUrl("/api/agent/broken-links"));
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || `HTTP ${response.status}`);
  }
  return response.json();
}

function renderAgentBrokenLinksStatChip(label, value, tone = "") {
  const mappedTone = tone === "total" ? "warn" : tone;
  return createAgentWorkspaceStatElement(value, label, mappedTone);
}

function formatBrokenLinkLocation(issue) {
  const parts = [issue.location || "body"];
  if (issue.field) parts.push(issue.field);
  if (issue.line) parts.push(`строка ${issue.line}`);
  return parts.join(" · ");
}

async function renderAgentBrokenLinksView() {
  if (!agentBrokenLinksContentNode) return;

  agentBrokenLinksContentNode.replaceChildren();
  if (agentBrokenLinksStatsNode) agentBrokenLinksStatsNode.replaceChildren();

  const loading = document.createElement("p");
  loading.className = "agent-broken-links-empty";
  loading.textContent = "Проверка ссылок в workspace…";
  agentBrokenLinksContentNode.appendChild(loading);

  try {
    const data = await fetchAgentBrokenLinks();
    agentBrokenLinksContentNode.replaceChildren();

    if (agentBrokenLinksStatsNode) {
      agentBrokenLinksStatsNode.append(
        renderAgentBrokenLinksStatChip("битых", data.count ?? 0, data.count ? "total" : ""),
        renderAgentBrokenLinksStatChip("markdown", data.scanned?.markdown ?? 0),
        renderAgentBrokenLinksStatChip("main.csv", data.scanned?.csv ?? 0)
      );
    }

    const shell = document.createElement("div");
    shell.className = "agent-broken-links-shell";

    const meta = document.createElement("p");
    meta.className = "agent-broken-links-meta-line";
    meta.textContent = `Проверены YAML-шапки, тело .md и main.csv · всего файлов: ${data.scanned?.files ?? 0}`;
    shell.appendChild(meta);

    const issues = Array.isArray(data.issues) ? data.issues : [];
    if (!issues.length) {
      const empty = document.createElement("div");
      empty.className = "agent-broken-links-empty-state";
      empty.innerHTML = `
        <p class="agent-broken-links-empty-title">Битых ссылок не найдено</p>
        <p class="agent-broken-links-empty-text">Ссылки в frontmatter, markdown и <code>main.csv</code> указывают на существующие файлы и wikilink-цели.</p>
      `;
      shell.appendChild(empty);
    } else {
      const list = document.createElement("ul");
      list.className = "agent-broken-links-list";

      for (const issue of issues) {
        const row = document.createElement("li");
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "agent-broken-links-row";
        btn.title = `Открыть ${issue.sourcePath}`;

        const badge = document.createElement("span");
        badge.className = `agent-broken-links-badge is-${issue.kind || "file"}`;
        badge.textContent = issue.kind || "file";

        const main = document.createElement("span");
        main.className = "agent-broken-links-main";

        const linkNode = document.createElement("span");
        linkNode.className = "agent-broken-links-link";
        linkNode.textContent = issue.link;

        const resolvedNode = document.createElement("span");
        resolvedNode.className = "agent-broken-links-resolved";
        resolvedNode.textContent = issue.resolvedPath || issue.message || "не найдено";

        const sourceNode = document.createElement("span");
        sourceNode.className = "agent-broken-links-source";
        sourceNode.textContent = `${issue.sourcePath} · ${formatBrokenLinkLocation(issue)}`;

        main.append(linkNode, resolvedNode, sourceNode);
        btn.append(badge, main);
        btn.addEventListener("click", () => {
          void openWorkspaceInspectorPath(issue.sourcePath);
        });
        row.appendChild(btn);
        list.appendChild(row);
      }

      shell.appendChild(list);
    }

    agentBrokenLinksContentNode.appendChild(shell);
  } catch (error) {
    agentBrokenLinksContentNode.replaceChildren();
    const errorNode = document.createElement("p");
    errorNode.className = "agent-broken-links-empty is-alert";
    errorNode.textContent = `Не удалось проверить ссылки: ${error.message}`;
    agentBrokenLinksContentNode.appendChild(errorNode);
  }
}

async function openWorkspaceInspectorPath(relPath) {
  const normalized = normalizeMenuNodePath(String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, ""));
  if (!normalized) return;

  const label = getLabelFromPath(normalized);

  try {
    if (isGitRepoLooseFilePath(normalized)) {
      await selectRepoLooseFile(label, normalized);
      return;
    }

    if (findMenuNodeInAgentMenu(currentMenuData, normalized)) {
      await openNodeFromMenu(label, normalized);
      return;
    }

    if (isNodeManifestPath(normalized) || isAreaManifestFileName(normalized.split("/").pop() || "")) {
      await openNodeFromMenu(label, normalized);
      return;
    }

    if (/\.md$/i.test(normalized)) {
      await openNodeFromMenu(label, normalized);
      return;
    }

    await selectRepoLooseFile(label, normalized);
  } catch (error) {
    showToast(`Не удалось открыть файл: ${error.message}`, "error");
  }
}

window.showToast = showToast;
window.openWorkspaceInspectorPath = openWorkspaceInspectorPath;

async function revealWorkspacePath(relPath) {
  const normalized = String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return;
  try {
    const response = await fetch(buildApiUrl("/api/reveal"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: normalized, workspace: true, repoFile: true })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `HTTP ${response.status}`);
    }
  } catch (error) {
    showToast(`Не удалось показать в Finder: ${error.message}`, "error");
  }
}

