async function createContainerRoot(options = {}) {
  return createReservedRootFolder("container-root", options);
}

async function createSystemFileScaffold(name, options = {}) {
  const normalizedName = normalizeSystemFileName(name);
  if (!normalizedName || !MENU_TREE_VISIBLE_SYSTEM_MD.has(normalizedName)) return;

  const meta = getSystemFileCacheEntry(normalizedName);
  if (meta?.exists) {
    showToast(`${normalizedName} уже создан`, "error");
    syncCreateNodeRootSystemFilesUi();
    return;
  }

  try {
    const response = await fetch(buildApiUrl("/api/system-file"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: normalizedName,
        content: getDefaultSystemFileScaffoldContent(normalizedName)
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${response.status}`);
    }

    await loadSystemFiles();
    if (currentMenuData) {
      withPreservedMenuScroll(() => renderMenu(currentMenuData));
    } else {
      renderSystemFiles(systemFilesCache);
    }
    syncCreateNodeRootSystemFilesUi();
    syncCreateNodeReservedScaffoldButtonsUi();

    if (options.openAfterCreate !== false) {
      closeCreateNodeModal();
      await selectSystemFile(normalizedName, { edit: true });
    } else {
      showToast(`${normalizedName} создан`, "success");
    }
  } catch (error) {
    showToast(`Не удалось создать ${normalizedName}: ${error.message}`, "error");
  }
}

async function createNode(type, options = {}) {
  const agentId = getCreateModalAgentId();
  if (!agentId || agentId !== activeAgentId) {
    showToast("Агент изменился — откройте «Создать» снова", "error");
    closeCreateNodeModal();
    return;
  }

  if (createModalEmptyFolder && type === "folder") {
    type = isCreateAdoptInsideEstablishedArea() ? "topic-manifest" : "manifest";
  }

  const displayName = createNameInputNode?.value?.trim() ?? "";
  const slug = getCreateSlugInputValue();
  const folderLabel = formatCreateParentLabel(createModalBaseParentPath);
  if (!displayName && type !== "manifest" && type !== "topic-manifest" && type !== "catalog" && type !== "taxonomy" && type !== "service-doc") {
    showToast("Введите название", "error");
    return;
  }
  const isManifestAdopt = type === "manifest" && isCreateAdoptFolderContext();
  const isTopicManifestAdopt = type === "topic-manifest" && isCreateAdoptFolderContext();
  if ((type === "folder" || type === "file" || type === "free-memory-folder" || isManifestAdopt || isTopicManifestAdopt) && !slug) {
    showToast("Введите slug (имя на диске)", "error");
    return;
  }

  try {
    const payload = {
      parentPath: resolveCreateNodeParentPath(type),
      type,
      name: type === "manifest" || type === "topic-manifest" ? folderLabel : displayName || folderLabel,
      displayName: type === "manifest" || type === "topic-manifest" ? displayName || folderLabel : displayName,
      slug:
        type === "folder" ||
        type === "file" ||
        type === "free-memory-folder" ||
        isManifestAdopt ||
        isTopicManifestAdopt
          ? slug
          : ""
    };
    if (type === "catalog" || type === "taxonomy" || type === "service-doc") {
      payload.preset = options.preset || name;
      if (type === "service-doc") {
        payload.parentPath = getActiveAgentKitFolder(agentId) || createTargetParentPath;
      } else {
        const taxonomyFolder = getSharedTaxonomiesFolder(agentId);
        if (!taxonomyFolder || !isSharedTaxonomiesAreaPresent(agentId)) {
          showToast(`Сначала создайте область «${SHARED_TAXONOMIES_LABEL}» в «${SHARED_SECTION_LABEL}»`, "error");
          return;
        }
        payload.parentPath = taxonomyFolder;
        payload.catalogBase = "taxonomy-root";
      }
    }
    if (options.awnType) {
      payload.awnType = String(options.awnType);
    }

    const response = await fetch(buildApiUrl("/api/node/create", {}, agentId), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const reason = errorData.error || `Request failed with ${response.status}`;
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${reason}${details}`);
    }

    const data = await response.json();
    closeCreateNodeModal();
    await applyMenuUpdateAfterCreate({ createdPath: data.createdPath, type, agentId });
    const createdLabel =
      type === "catalog" || type === "taxonomy"
        ? `Справочник «${SERVICE_CATALOG_PRESET_LABELS[data.preset] || data.preset || "catalog"}» создан`
        : type === "service-doc"
          ? `«${SERVICE_DOC_PRESET_LABELS[data.preset] || data.preset}» создан (${SERVICE_DOC_PRESET_FILES[data.preset] || ""}.md)`
          : type === "manifest"
          ? `Область подхвачена (${AREA_MANIFEST_FILE})`
          : type === "topic-manifest"
            ? `Тема подхвачена (${AREA_MANIFEST_FILE})`
          : type === "free-memory-folder"
            ? `${FREE_MEMORY_LABEL} создана`
          : type === "folder"
            ? "Папка-область создана"
            : "Файл (тема) создан";
    if (data.createdPath) {
      try {
        if (type === "free-memory-folder") {
          await openFolderBrowseFromMenu(displayName || getLabelFromPath(data.createdPath), data.createdPath);
        } else {
          await openNodeFromMenu(getLabelFromPath(data.createdPath), data.createdPath);
        }
      } catch (selectError) {
        const selectMessage = selectError instanceof Error ? selectError.message : String(selectError);
        showToast(`${createdLabel} (не удалось открыть: ${selectMessage})`, "success");
        return;
      }
    }
    showToast(createdLabel, "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (/Failed to fetch|NetworkError|Load failed/i.test(message)) {
      showToast("Ошибка соединения — проверьте, что сервер запущен (npm start)", "error");
      return;
    }
    const toastMessage = formatCreateNodeErrorMessage(message);
    showToast(toastMessage, "error");
  }
}

function formatCreateNodeErrorMessage(message) {
  const text = String(message || "");
  if (/Parent folder not found/i.test(text)) {
    return "Родительская папка не найдена";
  }
  if (/No permission to write|EPERM|EACCES/i.test(text)) {
    return "Нет прав на запись в workspace агента";
  }
  if (/Node manifest already exists/i.test(text)) {
    return `В этой папке уже есть ${AREA_MANIFEST_FILE}`;
  }
  if (/Container folder already exists/i.test(text)) {
    return "Контейнер уже создан";
  }
  if (/Agent kit folder already exists/i.test(text)) {
    return "Служебная папка уже создана";
  }
  if (/Failed to create node/i.test(text) && /ENOENT/i.test(text)) {
    if (/agent-kit|awn-agent-kit|service folder|service-doc|catalog|taxonomy/i.test(text)) {
      return "Не удалось создать служебный файл — обновите меню (F5) и повторите";
    }
    return `Папка ${AGENT_KIT_FOLDER_DEFAULT} ещё не создана — обновите меню (F5) и повторите`;
  }
  if (/Catalog node already exists/i.test(text)) {
    return "Такой справочник уже существует";
  }
  if (/Service doc already exists/i.test(text)) {
    return "Этот служебный файл уже создан";
  }
  if (/Folder already exists|Part already exists|Topic already exists|already exists/i.test(text)) {
    return "Область или тема с таким именем уже существует";
  }
  if (/Invalid folder name|Invalid part name|Invalid topic name/i.test(text)) {
    return "Недопустимое имя";
  }
  return text ? `Ошибка создания: ${text}` : "Ошибка создания папки";
}

async function deleteNodeByPath(targetPath, targetLabel = getLabelFromPath(targetPath)) {
  if (!targetPath) return;
  if (isAgentRootIndexPath(targetPath)) return;
  if (isAgentSystemRootIndexPath(targetPath)) return;

  const menuBeforeDelete = currentMenuData;
  const isContainerNode = isNodeManifestPath(targetPath) && !isPartNodePath(targetPath);
  const question = isContainerNode
    ? `Удалить папку "${targetLabel}" целиком?`
    : isPartNodePath(targetPath)
      ? `Удалить тему «${targetLabel}» целиком?`
      : `Удалить файл «${targetLabel}»?`;

  const confirmed = await askConfirm(question);
  if (!confirmed) return;

  try {
    const response = await fetch(buildApiUrl("/api/file", { path: targetPath }), { method: "DELETE" });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const reason = errorData.error || `Request failed with ${response.status}`;
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${reason}${details}`);
    }

    invalidateMenuAgentCache(activeAgentId);
    const menu = await refreshMenu();
    const normalizedActive = normalizeMenuNodePath(getResolvedNodePath(activePath));
    const normalizedDeleted = normalizeMenuNodePath(targetPath);
    if (normalizedActive && normalizedActive === normalizedDeleted) {
      const next = findPreferredNodeAfterDelete(menu, targetPath, menuBeforeDelete);
      if (next) {
        await openNodeFromMenu(next.label, next.path);
      } else {
        clearEditorState(`В ${getAgentTreeTitle()} нет markdown-манифестов`);
      }
    }
    showToast("Удалено", "success");
  } catch (error) {
    showToast(`Ошибка удаления: ${error.message}`, "error");
  }
}

async function promptMoveNodeFromMenu(targetPath) {
  const parentPath = await askMoveTarget({
    title: "Переместить",
    hint: "Укажите родительскую папку (путь от корня workspace).",
    pathLabel: "Родительская папка",
    defaultPath: getNodeParentPathForMove(targetPath)
  });
  if (parentPath == null || parentPath === "") return;

  try {
    const data = await moveNodeByPath(targetPath, parentPath);
    invalidateMenuAgentCache(activeAgentId);
    await refreshMenu();
    if (data.path) {
      await openNodeFromMenu(getLabelFromPath(data.path), data.path);
    }
    notifyMarkdownLinkRewrite(data.linkRewrite);
    showToast("Перемещено", "success");
  } catch (error) {
    showToast(`Ошибка перемещения: ${error.message}`, "error");
  }
}

async function deleteNode() {
  if (!isNodeDeleteAvailable()) return;
  await deleteNodeByPath(getActiveNodeApiPath(), activeLabel || getLabelFromPath(activePath));
}

async function init() {
  const splashStartedAt = Date.now();
  const finishSplash = () => {
    const elapsed = Date.now() - splashStartedAt;
    const wait = Math.max(0, APP_SPLASH_MIN_MS - elapsed);
    window.setTimeout(hideAppSplash, wait);
  };
  const splashFailsafe = window.setTimeout(() => {
    finishSplash();
    if (document.body.classList.contains("app-booting")) {
      showAppLandingView("Загрузка заняла слишком много времени. Проверьте сервер и обновите страницу.");
      setMenuLoading(false);
    }
  }, 20000);

  try {
    if (location.hash === "#graph") {
      history.replaceState(null, "", `${location.pathname}${location.search}`);
    }

    if (window.agentAppLock?.whenUnlocked) {
      await window.agentAppLock.whenUnlocked();
    }

    await loadAgents();
    applyMenuTreeSettingsUi();
    applyAgentGraphSettingsUi();

    const bootRoute = parseAppRoute(location.pathname);
    if (bootRoute.type !== "root" && bootRoute.type !== "legacy" && activeAgentId) {
      setMenuLoading(true, "Загрузка дерева…");
      await Promise.all([loadSystemFiles(), loadAwnTypes(activeAgentId), loadAgentCatalogs(activeAgentId)]);
      await refreshMenu();
    }

    suspendAppRouteSync();
    try {
      await applyAppRouteFromUrl();
    } finally {
      resumeAppRouteSync();
    }

    if (activeAgentId) {
      await loadAgentFocusItems(activeAgentId);
    }

    syncAppRouteToUrl({ replace: true });
  } catch (error) {
    showAppLandingView(`Ошибка загрузки: ${error.message}`);
  } finally {
    window.clearTimeout(splashFailsafe);
    finishSplash();
    setMenuLoading(false);
  }
}

function hideAppSplash() {
  if (!appSplashNode) {
    document.body.classList.remove("app-booting");
    return;
  }
  document.body.classList.remove("app-booting");
  appSplashNode.classList.add("app-splash--hide");
  window.setTimeout(() => {
    appSplashNode.remove();
  }, APP_SPLASH_HIDE_MS);
}

